import React, { useState, useRef, useEffect, useCallback } from 'react';
import type { ChatMessage, ChatPart, SearchResult, UIStyle, ThemeColors, FontSize } from '../types';
import { GoogleGenAI } from "@google/genai";
import { BotIcon, SendIcon, UserIcon, ImageIcon, SpeakerIcon, CopyIcon, SearchIcon } from './Icons';

interface ChatViewProps {
  messages: ChatMessage[];
  setMessages: React.Dispatch<React.SetStateAction<ChatMessage[]>>;
  uiStyle: UIStyle;
  theme: ThemeColors;
  fontSize: FontSize;
  systemInstruction: string;
}

const SourceCard: React.FC<{ result: SearchResult }> = ({ result }) => (
    <a 
        href={result.uri} 
        target="_blank" 
        rel="noopener noreferrer"
        className="flex items-center gap-3 p-2 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl hover:border-blue-500 dark:hover:border-blue-400 transition-all group shrink-0 max-w-[200px]"
    >
        <div className="w-8 h-8 rounded-lg bg-blue-100 dark:bg-blue-900/40 flex items-center justify-center shrink-0">
            <SearchIcon className="w-4 h-4 text-blue-600 dark:text-blue-400" />
        </div>
        <div className="flex-1 min-w-0">
            <p className="text-[10px] font-bold text-slate-900 dark:text-slate-100 truncate">{result.title}</p>
            <p className="text-[8px] text-slate-400 truncate">{new URL(result.uri).hostname}</p>
        </div>
    </a>
);

export const ChatView: React.FC<ChatViewProps> = ({ messages, setMessages, theme, systemInstruction }) => {
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [selectedImage, setSelectedImage] = useState<{ data: string; mimeType: string } | null>(null);

  const chatContainerRef = useRef<HTMLDivElement>(null);
  const textareaRef = useRef<HTMLTextAreaElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (chatContainerRef.current) chatContainerRef.current.scrollTop = chatContainerRef.current.scrollHeight;
  }, [messages, isLoading, selectedImage]);

  const handleSendMessage = useCallback(async (textOverride?: string) => {
    const textInput = (textOverride || input).trim();
    if ((!textInput && !selectedImage) || isLoading) return;

    const userMessageParts: ChatPart[] = [];
    if (selectedImage) userMessageParts.push({ inlineData: { mimeType: selectedImage.mimeType, data: selectedImage.data } });
    if (textInput) userMessageParts.push({ text: textInput });

    const userMessage: ChatMessage = { id: `msg-${Date.now()}`, role: 'user', parts: userMessageParts };
    const modelPlaceholder: ChatMessage = { id: `msg-${Date.now() + 1}`, role: 'model', parts: [{ text: '' }], isSearching: true };

    setMessages(prev => [...prev, userMessage, modelPlaceholder]);
    setInput(''); 
    setSelectedImage(null);
    setIsLoading(true);

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const history = messages.map(msg => ({
        role: msg.role,
        parts: msg.parts.map(p => {
            if (p.text) return { text: p.text };
            if (p.inlineData) return { inlineData: p.inlineData };
            return null;
        }).filter(Boolean) as any[]
      }));

      let stream = await ai.models.generateContentStream({
          model: 'gemini-3-flash-preview',
          contents: [...history, { role: 'user', parts: userMessageParts as any }],
          config: { 
              systemInstruction, 
              tools: [{ googleSearch: {} }],
              temperature: 0.7 
          },
      });

      let fullText = '';
      let searchResults: SearchResult[] = [];

      for await (const chunk of stream) {
        if(chunk.text) {
            fullText += chunk.text;
            setMessages(prev => prev.map(m => m.id === modelPlaceholder.id ? { ...m, parts: [{ text: fullText }], isSearching: false } : m));
        }
        const chunks = chunk.candidates?.[0]?.groundingMetadata?.groundingChunks;
        if (chunks) {
            const results = chunks.map((c: any) => c.web ? { ...c.web, type: 'web' } : null).filter(Boolean);
            searchResults = [...searchResults, ...results];
        }
      }

      if (searchResults.length > 0) {
        const unique = Array.from(new Map(searchResults.map(i => [i.uri, i])).values());
        setMessages(prev => prev.map(m => m.id === modelPlaceholder.id ? { ...m, parts: [{ ...m.parts[0], searchResults: unique }] } : m));
      }
    } catch (error) {
      setMessages(prev => prev.map(m => m.id === modelPlaceholder.id ? { ...m, parts: [{ text: `System Error: ${error instanceof Error ? error.message : "Unknown connectivity issue."}` }], isSearching: false } : m));
    } finally {
      setIsLoading(false);
    }
  }, [input, isLoading, messages, selectedImage, systemInstruction]);

  return (
    <div className="flex flex-col h-full bg-white dark:bg-slate-900">
      <div ref={chatContainerRef} className="flex-1 overflow-y-auto px-4 pb-48 pt-8 custom-scrollbar">
        {messages.length === 0 ? (
            <div className="max-w-3xl mx-auto flex flex-col items-center justify-center min-h-[70vh] text-center px-4">
                 <BotIcon className="w-24 h-24 mb-8 drop-shadow-2xl animate-float" />
                 <h2 className="text-4xl font-extrabold text-slate-900 dark:text-white mb-3 tracking-tight">How can I help you today?</h2>
                 <p className="text-slate-500 dark:text-slate-400 max-w-lg mb-12 text-lg">
                    Welcome back. I'm Cognix AI, your personal intelligence engine. Created by Shashwat Ranjan Jha.
                 </p>

                 <div className="grid grid-cols-1 md:grid-cols-2 gap-4 w-full">
                     {[
                         { t: "Live Web Search", s: "Ask about current events or stock prices", q: "What's the latest tech news from today?" },
                         { t: "Creative Writing", s: "Draft professional emails or stories", q: "Draft a high-end email to a CEO about AI innovation" },
                         { t: "Code Analysis", s: "Solve complex bugs or write features", q: "Explain how React concurrent mode works with examples" },
                         { t: "Plan an Adventure", s: "Custom itineraries for anywhere", q: "Plan a luxury 3-day trip to Tokyo" }
                     ].map((item, i) => (
                        <button 
                            key={i} 
                            onClick={() => handleSendMessage(item.q)}
                            className="text-left p-5 rounded-3xl border border-slate-200 dark:border-slate-800 hover:border-blue-500 dark:hover:border-blue-500/50 hover:bg-slate-50 dark:hover:bg-slate-800/50 transition-all group"
                        >
                            <p className="font-bold text-slate-900 dark:text-white mb-1 group-hover:text-blue-600 transition-colors">{item.t}</p>
                            <p className="text-xs text-slate-400">{item.s}</p>
                        </button>
                     ))}
                 </div>
            </div>
        ) : (
            <div className="max-w-4xl mx-auto space-y-10">
                {messages.map((msg) => (
                    <div key={msg.id} className={`flex gap-5 group ${msg.role === 'user' ? 'flex-row-reverse' : 'flex-row'}`}>
                        <div className={`w-9 h-9 shrink-0 rounded-2xl flex items-center justify-center shadow-md
                            ${msg.role === 'user' ? 'bg-slate-100 dark:bg-slate-800 text-slate-500' : 'bg-gradient-to-tr from-blue-600 to-cyan-500 text-white'}
                        `}>
                             {msg.role === 'user' ? <UserIcon className="w-5 h-5"/> : <BotIcon className="w-6 h-6"/>}
                        </div>

                        <div className={`flex flex-col gap-2 max-w-[85%] ${msg.role === 'user' ? 'items-end' : 'items-start'}`}>
                             {msg.parts.map((part, i) => (
                                 <div key={i} className={`relative leading-relaxed text-base
                                     ${msg.role === 'user' 
                                         ? 'bg-blue-600 text-white px-5 py-3.5 rounded-3xl rounded-tr-sm shadow-lg shadow-blue-500/10' 
                                         : 'text-slate-800 dark:text-slate-200 px-1'}
                                 `}>
                                     {part.inlineData && <img src={`data:${part.inlineData.mimeType};base64,${part.inlineData.data}`} className="rounded-2xl mb-4 max-h-96 shadow-xl border border-slate-200 dark:border-slate-800" alt="Upload"/>}

                                     {msg.isSearching && i === 0 && (
                                         <div className="flex items-center gap-3 text-blue-500 mb-2 animate-pulse-soft">
                                             <div className="w-4 h-4 border-2 border-blue-500 border-t-transparent rounded-full animate-spin"></div>
                                             <span className="text-xs font-bold uppercase tracking-widest">Searching Knowledge Base...</span>
                                         </div>
                                     )}

                                     <div className="whitespace-pre-wrap prose dark:prose-invert max-w-none">{part.text}</div>

                                     {part.searchResults && part.searchResults.length > 0 && (
                                         <div className="mt-6">
                                            <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mb-3 flex items-center gap-2">
                                                Verified Sources <span className="h-px bg-slate-200 dark:bg-slate-800 flex-1"></span>
                                            </p>
                                            <div className="flex gap-3 overflow-x-auto pb-2 no-scrollbar">
                                                {part.searchResults.map((res, idx) => <SourceCard key={idx} result={res} />)}
                                            </div>
                                         </div>
                                     )}

                                     {msg.role === 'model' && part.text && (
                                         <div className="flex gap-2 mt-4 opacity-0 group-hover:opacity-100 transition-opacity">
                                             <button onClick={() => navigator.clipboard.writeText(part.text || '')} className="p-2 hover:bg-slate-100 dark:hover:bg-slate-800 rounded-xl text-slate-400 hover:text-blue-500 transition-all"><CopyIcon className="w-4 h-4"/></button>
                                             <button className="p-2 hover:bg-slate-100 dark:hover:bg-slate-800 rounded-xl text-slate-400 hover:text-blue-500 transition-all"><SpeakerIcon className="w-4 h-4"/></button>
                                         </div>
                                     )}
                                 </div>
                             ))}
                        </div>
                    </div>
                ))}
            </div>
        )}
      </div>

      {/* Floating Input Area */}
      <div className="absolute bottom-0 left-0 right-0 p-6 bg-gradient-to-t from-white dark:from-slate-900 via-white/90 dark:via-slate-900/90 to-transparent">
          <div className="max-w-4xl mx-auto relative">
              <div className="flex items-end gap-3 p-3 bg-white dark:bg-slate-800 rounded-[2rem] shadow-2xl border border-slate-200 dark:border-slate-700 transition-all focus-within:border-blue-500 dark:focus-within:border-blue-500/50">
                   <button 
                        onClick={() => fileInputRef.current?.click()} 
                        className="p-3 mb-0.5 rounded-full text-slate-400 hover:bg-slate-100 dark:hover:bg-slate-700 hover:text-blue-500 transition-all"
                   >
                       <ImageIcon className="w-6 h-6"/>
                       <input type="file" ref={fileInputRef} onChange={(e) => {
                            const file = e.target.files?.[0];
                            if (file) {
                                const reader = new FileReader();
                                reader.onloadend = () => {
                                    setSelectedImage({ data: (reader.result as string).split(',')[1], mimeType: file.type });
                                };
                                reader.readAsDataURL(file);
                            }
                       }} accept="image/*" className="hidden" />
                   </button>

                   <textarea
                       ref={textareaRef}
                       value={input}
                       onChange={e => setInput(e.target.value)}
                       onKeyDown={e => e.key === 'Enter' && !e.shiftKey && (e.preventDefault(), handleSendMessage())}
                       placeholder="Ask Cognix anything..."
                       className="flex-1 bg-transparent border-none outline-none resize-none py-3 max-h-48 text-slate-900 dark:text-white placeholder-slate-400 text-base"
                       rows={1}
                   />

                   <button 
                        onClick={() => handleSendMessage()} 
                        disabled={isLoading || (!input && !selectedImage)} 
                        className={`p-3.5 mb-0.5 rounded-full text-white transition-all transform active:scale-95 disabled:opacity-30
                            ${input || selectedImage ? 'bg-blue-600 shadow-blue-500/30 shadow-lg' : 'bg-slate-300 dark:bg-slate-700'}
                        `}
                   >
                       <SendIcon className="w-5 h-5"/>
                   </button>
              </div>

              {selectedImage && (
                  <div className="absolute -top-24 left-4 p-2 bg-white dark:bg-slate-800 rounded-2xl shadow-2xl border border-slate-200 dark:border-slate-700 flex items-center gap-3 animate-fade-in">
                      <img src={`data:${selectedImage.mimeType};base64,${selectedImage.data}`} className="w-16 h-16 object-cover rounded-xl" />
                      <button onClick={() => setSelectedImage(null)} className="p-1.5 bg-slate-100 dark:bg-slate-700 rounded-full hover:text-red-500 transition-colors">
                          <svg className="w-4 h-4" fill="currentColor" viewBox="0 0 20 20"><path d="M4.293 4.293a1 1 0 011.414 0L10 8.586l4.293-4.293a1 1 0 111.414 1.414L11.414 10l4.293 4.293a1 1 0 01-1.414 1.414L10 11.414l-4.293 4.293a1 1 0 01-1.414-1.414L8.586 10 4.293 5.707a1 1 0 010-1.414z"/></svg>
                      </button>
                  </div>
              )}

              <p className="text-center mt-4 text-[10px] font-bold text-slate-400 uppercase tracking-widest">
                  Powered by Google Gemini 3 Pro • Created by Shashwat Ranjan Jha
              </p>
          </div>
      </div>
    </div>
  );
};

