export type Mode = 'chat' | 'live' | 'friends' | 'video';
export type UIStyle = 'modern' | 'glass' | 'brutal' | 'retro';
export type AccentColor = 'blue' | 'violet' | 'emerald' | 'rose' | 'amber';
export type FontSize = 'small' | 'normal' | 'large';

export interface Friend {
  id: string;
  name: string;
  avatar: string;
  status: 'online' | 'offline' | 'busy' | 'away';
  lastMessage?: string;
}

export interface ThemeColors {
    primary: string;
    primaryHover: string;
    text: string;
    textDark: string;
    bgSoft: string;
    darkBgSoft: string;
    border: string;
    ring: string;
    gradient: string;
}

export interface SearchResult {
  uri: string;
  title: string;
  type?: 'web' | 'map';
}

export interface ChatPart {
  text?: string;
  inlineData?: {
    mimeType: string;
    data: string; // base64 encoded
  };
  functionCall?: {
    name: string;
    args: any;
  };
  searchResults?: SearchResult[];
}

export interface ChatMessage {
  id: string;
  role: 'user' | 'model';
  parts: ChatPart[];
  isSearching?: boolean;
}

export interface ChatSession {
  id:string;
  title: string;
  messages: ChatMessage[];
}

import React, { useState, useEffect, useMemo } from 'react';
import { ChatView } from './components/ChatView';
import { LiveView } from './components/LiveView';
import { Sidebar } from './components/Sidebar';
import { FriendsView } from './components/FriendsView';
import { VideoView } from './components/VideoView';
import { MenuIcon } from './components/Icons';
import { SettingsModal } from './components/SettingsModal';
import type { ChatMessage, ChatSession, Mode, UIStyle, AccentColor, ThemeColors, FontSize, Friend } from './types';

const THEMES: Record<AccentColor, ThemeColors> = {
    blue: { primary: 'bg-blue-600', primaryHover: 'hover:bg-blue-700', text: 'text-blue-600', textDark: 'text-blue-400', bgSoft: 'bg-blue-50', darkBgSoft: 'dark:bg-blue-900/20', border: 'border-blue-600', ring: 'focus:ring-blue-600', gradient: 'bg-gradient-to-r from-blue-500 to-cyan-500' },
    violet: { primary: 'bg-violet-600', primaryHover: 'hover:bg-violet-700', text: 'text-violet-600', textDark: 'text-violet-400', bgSoft: 'bg-violet-50', darkBgSoft: 'dark:bg-violet-900/20', border: 'border-violet-600', ring: 'focus:ring-violet-600', gradient: 'bg-gradient-to-r from-violet-500 to-purple-500' },
    emerald: { primary: 'bg-emerald-600', primaryHover: 'hover:bg-emerald-700', text: 'text-emerald-600', textDark: 'text-emerald-400', bgSoft: 'bg-emerald-50', darkBgSoft: 'dark:bg-emerald-900/20', border: 'border-emerald-600', ring: 'focus:ring-emerald-600', gradient: 'bg-gradient-to-r from-emerald-500 to-teal-500' },
    rose: { primary: 'bg-rose-600', primaryHover: 'hover:bg-rose-700', text: 'text-rose-600', textDark: 'text-rose-400', bgSoft: 'bg-rose-50', darkBgSoft: 'dark:bg-rose-900/20', border: 'border-rose-600', ring: 'focus:ring-rose-600', gradient: 'bg-gradient-to-r from-rose-500 to-pink-500' },
    amber: { primary: 'bg-amber-600', primaryHover: 'hover:bg-amber-700', text: 'text-amber-600', textDark: 'text-amber-400', bgSoft: 'bg-amber-50', darkBgSoft: 'dark:bg-amber-900/20', border: 'border-amber-600', ring: 'focus:ring-amber-600', gradient: 'bg-gradient-to-r from-amber-500 to-orange-500' },
};

const MOCK_FRIENDS: Friend[] = [
    { id: '1', name: 'Alex Thompson', avatar: 'AT', status: 'online', lastMessage: 'That looks great!' },
    { id: '2', name: 'Sarah Miller', avatar: 'SM', status: 'away', lastMessage: 'Talk to you later.' },
    { id: '3', name: 'Jordan Reed', avatar: 'JR', status: 'busy', lastMessage: 'In a meeting...' },
    { id: '4', name: 'Casey Wright', avatar: 'CW', status: 'offline', lastMessage: 'Check this out!' },
];

const App: React.FC = () => {
  const [mode, setMode] = useState<Mode>('chat');
  const [uiStyle, setUiStyle] = useState<UIStyle>('modern');
  const [accentColor, setAccentColor] = useState<AccentColor>('blue');
  const [fontSize, setFontSize] = useState<FontSize>('normal');
  const [systemInstruction, setSystemInstruction] = useState("You are Cognix AI, a highly intelligent and helpful personal assistant created by Shashwat Ranjan Jha. You are professional, witty, and extremely capable. You have access to real-time information via Google Search.");

  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [isDesktopSidebarOpen, setIsDesktopSidebarOpen] = useState(true);
  const [isDarkMode, setIsDarkMode] = useState(false);
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);

  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [chatHistory, setChatHistory] = useState<ChatSession[]>([]);
  const [activeChatId, setActiveChatId] = useState<string | null>(null);
  const [friends] = useState<Friend[]>(MOCK_FRIENDS);

  useEffect(() => {
    const savedHistory = localStorage.getItem('cognix_v2_history');
    if (savedHistory) setChatHistory(JSON.parse(savedHistory));

    const savedTheme = localStorage.getItem('cognix_theme');
    if (savedTheme === 'dark' || (!savedTheme && window.matchMedia('(prefers-color-scheme: dark)').matches)) {
      setIsDarkMode(true);
      document.documentElement.classList.add('dark');
    }
  }, []);

  useEffect(() => localStorage.setItem('cognix_v2_history', JSON.stringify(chatHistory)), [chatHistory]);

  useEffect(() => {
    if (isDarkMode) {
      document.documentElement.classList.add('dark');
      localStorage.setItem('cognix_theme', 'dark');
    } else {
      document.documentElement.classList.remove('dark');
      localStorage.setItem('cognix_theme', 'light');
    }
  }, [isDarkMode]);

  const currentChat = useMemo(() => chatHistory.find(c => c.id === activeChatId), [chatHistory, activeChatId]);
  const activeTheme = useMemo(() => THEMES[accentColor], [accentColor]);

  useEffect(() => {
    setMessages(currentChat ? currentChat.messages : []);
  }, [currentChat?.id]);

  useEffect(() => {
    if (messages.length > 0 && !activeChatId) {
       const firstUserText = messages.find(m => m.role === 'user')?.parts.find(p => p.text)?.text || 'New Chat';
       const newId = Date.now().toString();
       const newSession: ChatSession = {
         id: newId,
         title: firstUserText.slice(0, 30),
         messages: messages
       };
       setChatHistory(prev => [newSession, ...prev]);
       setActiveChatId(newId);
    } else if (activeChatId && messages.length > 0) {
       setChatHistory(prev => prev.map(session => session.id === activeChatId ? { ...session, messages } : session));
    }
  }, [messages, activeChatId]);

  const handleNewChat = () => {
    setActiveChatId(null);
    setMessages([]);
    setMode('chat');
    if (window.innerWidth < 1024) setIsSidebarOpen(false);
  };

  return (
    <div className={`flex h-[100dvh] overflow-hidden bg-slate-50 dark:bg-slate-950 transition-colors duration-300`}>

      {/* Sidebar */}
      <Sidebar 
        chatHistory={chatHistory}
        activeChatId={activeChatId}
        mode={mode}
        onSetMode={(m) => { setMode(m); if(window.innerWidth < 1024) setIsSidebarOpen(false); }}
        onSelectChat={(id) => { setActiveChatId(id); setMode('chat'); if(window.innerWidth < 1024) setIsSidebarOpen(false); }}
        onNewChat={handleNewChat}
        onDeleteChat={(id) => {
            setChatHistory(h => h.filter(c => c.id !== id));
            if (activeChatId === id) { setActiveChatId(null); setMessages([]); }
        }}
        onRenameChat={(id, t) => setChatHistory(h => h.map(c => c.id === id ? { ...c, title: t } : c))}
        onOpenSettings={() => setIsSettingsOpen(true)}
        isSidebarOpen={isSidebarOpen}
        isDesktopSidebarOpen={isDesktopSidebarOpen}
        theme={activeTheme}
        friends={friends}
      />

      {/* Mobile Overlay */}
      {isSidebarOpen && <div className="fixed inset-0 bg-black/40 backdrop-blur-sm z-40 lg:hidden" onClick={() => setIsSidebarOpen(false)} />}

      {/* Main Content */}
      <div className="flex-1 flex flex-col h-full min-w-0 bg-white dark:bg-slate-900 lg:rounded-l-3xl shadow-2xl relative">

        {/* Header */}
        <header className="h-16 flex items-center justify-between px-6 shrink-0 z-30">
             <div className="flex items-center gap-4">
                <button 
                    onClick={() => window.innerWidth >= 1024 ? setIsDesktopSidebarOpen(!isDesktopSidebarOpen) : setIsSidebarOpen(!isSidebarOpen)}
                    className="p-2 -ml-2 text-slate-500 hover:bg-slate-100 dark:hover:bg-slate-800 rounded-xl transition-colors"
                >
                    <MenuIcon className="w-5 h-5"/>
                </button>
                <div className="flex flex-col">
                  <h1 className="text-sm font-bold text-slate-800 dark:text-slate-100 flex items-center gap-2">
                      {mode === 'chat' && (currentChat?.title || 'New Conversation')}
                      {mode === 'live' && 'Live Audio Session'}
                      {mode === 'friends' && 'Friends & Contacts'}
                      {mode === 'video' && 'Video Generation'}
                      {mode === 'chat' && <div className="w-1.5 h-1.5 rounded-full bg-green-500 animate-pulse"></div>}
                  </h1>
                  <span className="text-[10px] text-slate-400 font-medium uppercase tracking-widest">Cognix AI v2.5.0</span>
                </div>
             </div>

             <div className="flex items-center gap-3">
                 <button onClick={() => setIsDarkMode(!isDarkMode)} className="p-2 text-slate-400 hover:text-slate-600 dark:hover:text-slate-200 transition-colors">
                     {isDarkMode ? (
                         <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 20 20" fill="currentColor" className="w-5 h-5"><path fillRule="evenodd" d="M10 2a1 1 0 011 1v1a1 1 0 11-2 0V3a1 1 0 011-1zm4 8a4 4 0 11-8 0 4 4 0 018 0zm-.464 4.95l.707.707a1 1 0 001.414-1.414l-.707-.707a1 1 0 00-1.414 1.414zm2.12-10.607a1 1 0 010 1.414l-.706.707a1 1 0 11-1.414-1.414l.707-.707a1 1 0 011.414 0zM17 11a1 1 0 100-2h-1a1 1 0 100 2h1zm-7 4a1 1 0 011 1v1a1 1 0 11-2 0v-1a1 1 0 011-1zM5.05 6.464A1 1 0 106.465 5.05l-.708-.707a1 1 0 00-1.414 1.414l.707.707zm1.414 8.486l-.707.707a1 1 0 01-1.414-1.414l.707-.707a1 1 0 011.414 1.414zM4 11a1 1 0 100-2H3a1 1 0 000 2h1z" clipRule="evenodd" /></svg>
                     ) : (
                         <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 20 20" fill="currentColor" className="w-5 h-5"><path d="M17.293 13.293A8 8 0 016.707 2.707a8.001 8.001 0 1010.586 10.586z" /></svg>
                     )}
                 </button>
                 <button onClick={() => setIsSettingsOpen(true)} className="p-2 text-slate-400 hover:text-slate-600 dark:hover:text-slate-200 transition-colors">
                    <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 20 20" fill="currentColor" className="w-5 h-5"><path fillRule="evenodd" d="M11.49 3.17c-.38-1.56-2.6-1.56-2.98 0a1.532 1.532 0 01-2.286.948c-1.372-.836-2.942.734-2.106 2.106.54.886.061 2.042-.947 2.287-1.561.379-1.561 2.6 0 2.978a1.532 1.532 0 01.947 2.287c-.836 1.372.734 2.942 2.106 2.106a1.532 1.532 0 012.287.947c.379 1.561 2.6 1.561 2.978 0a1.533 1.533 0 012.287-.947c1.372.836 2.942-.734 2.106-2.106a1.533 1.533 0 01.947-2.287c1.561-.379 1.561-2.6 0-2.978a1.532 1.532 0 01-.947-2.287c.836-1.372-.734-2.942-2.106-2.106a1.532 1.532 0 01-2.287-.947zM10 13a3 3 0 100-6 3 3 0 000 6z" clipRule="evenodd" /></svg>
                 </button>
             </div>
        </header>

        {/* Workspace */}
        <main className="flex-1 relative overflow-hidden">
             {mode === 'chat' && (
                <ChatView 
                    messages={messages} 
                    setMessages={setMessages}
                    uiStyle={uiStyle}
                    theme={activeTheme}
                    fontSize={fontSize}
                    systemInstruction={systemInstruction}
                />
            )}
            {mode === 'live' && <LiveView theme={activeTheme} />}
            {mode === 'friends' && <FriendsView friends={friends} />}
            {mode === 'video' && <VideoView />}
        </main>
      </div>

      <SettingsModal 
        isOpen={isSettingsOpen} 
        onClose={() => setIsSettingsOpen(false)}
        uiStyle={uiStyle}
        setUiStyle={setUiStyle}
        accentColor={accentColor}
        setAccentColor={setAccentColor}
        fontSize={fontSize}
        setFontSize={setFontSize}
        isDarkMode={isDarkMode}
        setIsDarkMode={setIsDarkMode}
        onClearHistory={() => { setChatHistory([]); setMessages([]); setActiveChatId(null); setIsSettingsOpen(false); }}
        systemInstruction={systemInstruction}
        setSystemInstruction={setSystemInstruction}
      />
    </div>
  );
}

export default App;

import React, { useState, useRef, useEffect } from 'react';
import type { ChatSession, Mode, ThemeColors, Friend } from '../types';
import { BotIcon, TrashIcon, PencilIcon, MicrophoneIcon, UsersIcon, VideoIcon } from './Icons';

interface SidebarProps {
  chatHistory: ChatSession[];
  activeChatId: string | null;
  mode: Mode;
  onSetMode: (mode: Mode) => void;
  onSelectChat: (id: string) => void;
  onNewChat: () => void;
  onDeleteChat: (id: string) => void;
  onRenameChat: (id: string, newTitle: string) => void;
  onOpenSettings: () => void;
  isSidebarOpen: boolean;
  isDesktopSidebarOpen: boolean;
  theme: ThemeColors;
  friends: Friend[];
}

export const Sidebar: React.FC<SidebarProps> = ({
  chatHistory,
  activeChatId,
  mode,
  onSetMode,
  onSelectChat,
  onNewChat,
  onDeleteChat,
  onRenameChat,
  isSidebarOpen,
  isDesktopSidebarOpen,
  theme,
  friends,
}) => {
  const [editingChatId, setEditingChatId] = useState<string | null>(null);
  const [newTitle, setNewTitle] = useState('');
  const inputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (editingChatId && inputRef.current) {
        inputRef.current.focus();
        inputRef.current.select();
    }
  }, [editingChatId]);

  const handleRename = () => {
    if (editingChatId && newTitle.trim()) onRenameChat(editingChatId, newTitle.trim());
    setEditingChatId(null);
  };

  const NavItem: React.FC<{ m: Mode, icon: React.ReactNode, label: string }> = ({ m, icon, label }) => (
    <button
        onClick={() => onSetMode(m)}
        className={`w-full flex items-center gap-3 px-3 py-2.5 rounded-xl transition-all duration-200
            ${mode === m 
                ? `${theme.bgSoft} ${theme.text} dark:bg-blue-900/20 dark:text-blue-400 font-semibold shadow-sm` 
                : 'text-slate-600 dark:text-slate-400 hover:bg-slate-100 dark:hover:bg-slate-800'}
        `}
    >
        <span className="shrink-0">{icon}</span>
        <span className="text-sm">{label}</span>
    </button>
  );

  return (
    <aside className={`
      fixed lg:static inset-y-0 left-0 z-50 transition-all duration-300 ease-in-out h-full shrink-0 flex flex-col bg-slate-50 dark:bg-slate-950 border-r border-slate-200 dark:border-slate-800
      ${isSidebarOpen ? 'translate-x-0 w-[280px]' : '-translate-x-full lg:translate-x-0'}
      ${isDesktopSidebarOpen ? 'lg:w-[280px]' : 'lg:w-0 overflow-hidden border-none'}
    `}>
      {/* Header */}
      <div className="p-6">
        <div className="flex items-center gap-3 mb-6">
            <BotIcon className="w-10 h-10 shadow-lg rounded-xl" />
            <div className="flex flex-col">
                <span className="font-bold text-slate-900 dark:text-white tracking-tight text-lg leading-none">Cognix AI</span>
                <span className="text-[10px] text-slate-400 font-bold tracking-widest uppercase mt-1">Intelligent Assistant</span>
            </div>
        </div>

        <button
          onClick={onNewChat}
          className="w-full flex items-center justify-center gap-2 py-3 bg-blue-600 hover:bg-blue-700 text-white rounded-2xl font-bold transition-all shadow-blue-500/20 shadow-lg active:scale-95"
        >
          <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 20 20" fill="currentColor" className="w-4 h-4">
             <path d="M10.75 4.75a.75.75 0 00-1.5 0v4.5h-4.5a.75.75 0 000 1.5h4.5v4.5a.75.75 0 001.5 0v-4.5h4.5a.75.75 0 000-1.5h-4.5v-4.5z" />
          </svg>
          <span className="text-sm">New Session</span>
        </button>
      </div>

      {/* Core Nav */}
      <nav className="px-4 space-y-1 mb-6">
        <NavItem m="chat" icon={<svg className="w-5 h-5" fill="currentColor" viewBox="0 0 20 20"><path d="M2 5a2 2 0 012-2h7a2 2 0 012 2v4a2 2 0 01-2 2H9l-3 3v-3H4a2 2 0 01-2-2V5z"/></svg>} label="Chat Explorer" />
        <NavItem m="live" icon={<MicrophoneIcon className="w-5 h-5" />} label="Live Conversation" />
        <NavItem m="video" icon={<VideoIcon className="w-5 h-5" />} label="Veo Studio" />
        <NavItem m="friends" icon={<UsersIcon className="w-5 h-5" />} label="Friends Network" />
      </nav>

      {/* History & Friends Context */}
      <div className="flex-1 overflow-y-auto px-4 custom-scrollbar pb-6">
        {mode === 'friends' ? (
             <>
                <h3 className="text-[10px] font-bold text-slate-400 uppercase tracking-widest px-3 mb-2">Active Friends</h3>
                <div className="space-y-1">
                    {friends.map(friend => (
                        <div key={friend.id} className="flex items-center gap-3 p-3 rounded-xl hover:bg-slate-100 dark:hover:bg-slate-900 cursor-pointer transition-colors group">
                            <div className="relative w-8 h-8 rounded-full bg-slate-200 dark:bg-slate-800 flex items-center justify-center text-[10px] font-bold text-slate-600 dark:text-slate-400">
                                {friend.avatar}
                                <div className={`absolute -bottom-0.5 -right-0.5 w-2.5 h-2.5 rounded-full border-2 border-slate-50 dark:border-slate-950 ${friend.status === 'online' ? 'bg-green-500' : 'bg-slate-400'}`}></div>
                            </div>
                            <div className="flex-1 min-w-0">
                                <p className="text-xs font-bold text-slate-900 dark:text-slate-100 truncate">{friend.name}</p>
                                <p className="text-[10px] text-slate-400 truncate">{friend.status}</p>
                            </div>
                        </div>
                    ))}
                </div>
             </>
        ) : (
            <>
                <h3 className="text-[10px] font-bold text-slate-400 uppercase tracking-widest px-3 mb-2">Recent Threads</h3>
                <div className="space-y-1">
                    {chatHistory.length === 0 ? (
                        <div className="px-3 py-10 text-center">
                            <p className="text-xs text-slate-400 italic">No history yet</p>
                        </div>
                    ) : (
                        chatHistory.map((chat) => (
                        <div
                            key={chat.id}
                            onClick={() => { if(editingChatId !== chat.id) onSelectChat(chat.id); }}
                            className={`group relative flex items-center justify-between px-3 py-2.5 cursor-pointer rounded-xl transition-all
                            ${activeChatId === chat.id && mode === 'chat'
                                ? 'bg-white dark:bg-slate-900 text-blue-600 dark:text-blue-400 font-semibold shadow-sm border border-slate-200 dark:border-slate-800'
                                : 'text-slate-600 dark:text-slate-400 hover:bg-slate-100 dark:hover:bg-slate-900'}
                            `}
                        >
                            {editingChatId === chat.id ? (
                                <input
                                    ref={inputRef}
                                    type="text"
                                    value={newTitle}
                                    onChange={(e) => setNewTitle(e.target.value)}
                                    onBlur={handleRename}
                                    onKeyDown={(e) => e.key === 'Enter' && handleRename()}
                                    className="bg-transparent border-none w-full outline-none text-xs py-0.5"
                                />
                            ) : (
                                <>
                                <span className="truncate text-xs">{chat.title}</span>
                                <div className="hidden group-hover:flex items-center gap-1 absolute right-2 bg-white dark:bg-slate-800 shadow-xl rounded-lg border border-slate-100 dark:border-slate-700 p-0.5">
                                    <button onClick={(e) => { e.stopPropagation(); setEditingChatId(chat.id); setNewTitle(chat.title); }} className="p-1.5 hover:text-blue-500 transition-colors"><PencilIcon className="w-3.5 h-3.5"/></button>
                                    <button onClick={(e) => { e.stopPropagation(); onDeleteChat(chat.id); }} className="p-1.5 hover:text-red-500 transition-colors"><TrashIcon className="w-3.5 h-3.5"/></button>
                                </div>
                                </>
                            )}
                        </div>
                        ))
                    )}
                </div>
            </>
        )}
      </div>

      {/* Footer */}
      <div className="p-6 border-t border-slate-200 dark:border-slate-800">
          <div className="flex items-center gap-3">
              <div className="w-9 h-9 rounded-xl bg-gradient-to-tr from-blue-600 to-cyan-500 flex items-center justify-center text-white font-bold text-xs shadow-lg">
                  SJ
              </div>
              <div className="flex-1 min-w-0">
                  <p className="text-sm font-bold text-slate-900 dark:text-white truncate">Shashwat R. Jha</p>
                  <p className="text-[10px] text-blue-500 font-bold uppercase tracking-widest">Premium Founder</p>
              </div>
          </div>
      </div>
    </aside>
  );
};

