                ) : (
                    chatHistory.map((chat) => (
                    <div key={chat.id} onClick={() => { if(editingChatId !== chat.id) onSelectChat(chat.id); }}
                        className={`group relative flex items-center justify-between px-3 py-2.5 cursor-pointer rounded-xl transition-all
                        ${activeChatId === chat.id && mode === 'chat'
                            ? 'bg-white dark:bg-slate-900 text-blue-600 dark:text-blue-400 font-semibold shadow-sm border border-slate-200 dark:border-slate-800'
                            : 'text-slate-600 dark:text-slate-400 hover:bg-slate-100 dark:hover:bg-slate-800'}
                        `}
                    >
                        {editingChatId === chat.id ? (
                            <input ref={inputRef} type="text" value={newTitle} onChange={(e) => setNewTitle(e.target.value)} onBlur={handleRename} onKeyDown={(e) => e.key === 'Enter' && handleRename()}
                                className="bg-transparent border-none w-full outline-none text-xs py-0.5" />
                        ) : (
                            <>
                            <span className="truncate text-xs">{chat.title}</span>
                            <div className="hidden group-hover:flex items-center gap-1 absolute right-2 bg-white dark:bg-slate-800 shadow-xl rounded-lg border border-slate-100 dark:border-slate-700 p-0.5">
                                <button onClick={(e) => { e.stopPropagation(); setEditingChatId(chat.id); setNewTitle(chat.title); }} className="p-1.5 hover:text-blue-500 transition-colors"><PencilIcon className="w-3.5 h-3.5"/></button>
                                <button onClick={(e) => { e.stopPropagation(); onDeleteChat(chat.id); }} className="p-1.5 hover:text-red-500 transition-colors"><TrashIcon className="w-3.5 h-3.5"/></button>
                            </div>
                            </>
                        )}
                    </div>
                    ))
                )}
            </div>
      </div>

      <div className="p-6 border-t border-slate-200 dark:border-slate-800">
          <button onClick={() => onSetMode('friends')} className="flex items-center gap-3 w-full hover:bg-slate-100 dark:hover:bg-slate-800 p-2 rounded-xl transition-colors">
              <div className="w-9 h-9 rounded-xl bg-gradient-to-tr from-blue-600 to-cyan-500 flex items-center justify-center text-white font-bold text-xs shadow-lg">SJ</div>
              <div className="flex-1 min-w-0 text-left">
                  <p className="text-sm font-bold text-slate-900 dark:text-white truncate">Shashwat R. Jha</p>
                  <p className="text-[10px] text-blue-500 font-bold uppercase tracking-widest">Founder Profile</p>
              </div>
          </button>
      </div>
    </aside>
  );
};

import React, { useState, useEffect } from 'react';
import { GoogleGenAI } from "@google/genai";
import type { ThemeColors, CommunityPost, ModelType } from '../types';
import { BotIcon, SendIcon, UserIcon, ImageIcon } from './Icons';

export const CommunityView: React.FC<{ theme: ThemeColors, model: ModelType }> = ({ theme, model }) => {
    const [posts, setPosts] = useState<CommunityPost[]>([]);
    const [newPostContent, setNewPostContent] = useState('');
    const [isPublishing, setIsPublishing] = useState(false);
    const [error, setError] = useState<string | null>(null);

    useEffect(() => {
        const saved = localStorage.getItem('cognix_community_posts');
        if (saved) setPosts(JSON.parse(saved));
        else setPosts([
            { id: '1', author: 'System', content: 'Welcome to the Cognix AI Global Feed! Share your thoughts and experiments here.', timestamp: Date.now(), likes: 42, type: 'text' }
        ]);
    }, []);

    useEffect(() => localStorage.setItem('cognix_community_posts', JSON.stringify(posts)), [posts]);

    const handlePublish = async () => {
        if (!newPostContent.trim()) return;
        setIsPublishing(true);
        setError(null);

        try {
            const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
            // AI Moderation Step
            const moderation = await ai.models.generateContent({
                model: 'gemini-3-flash-preview',
                contents: `MODERATION REQUEST: Evaluate if the following post content is appropriate for a professional community. It should not contain hate speech, explicit sexual content, or dangerous instructions. Reply with exactly 'SAFE' or 'INAPPROPRIATE: [reason]'. 

                CONTENT: "${newPostContent}"`,
            });

            const result = moderation.text?.trim();
            if (result?.startsWith('SAFE')) {
                const newPost: CommunityPost = {
                    id: Date.now().toString(),
                    author: 'You',
                    content: newPostContent,
                    timestamp: Date.now(),
                    likes: 0,
                    type: 'text'
                };
                setPosts(prev => [newPost, ...prev]);
                setNewPostContent('');
            } else {
                setError(`AI Blocked Post: ${result?.replace('INAPPROPRIATE:', '') || 'Moderation policy violation'}`);
            }
        } catch (e) {
            setError('Safety check failed. Please check your connection.');
        } finally {
            setIsPublishing(false);
        }
    };

    return (
        <div className="h-full overflow-y-auto bg-slate-50 dark:bg-slate-950 p-6 custom-scrollbar">
            <div className="max-w-3xl mx-auto space-y-8">
                <div className="bg-white dark:bg-slate-900 rounded-3xl p-6 shadow-xl border border-slate-200 dark:border-slate-800">
                    <h2 className="text-xl font-bold text-slate-900 dark:text-white mb-4">What's on your mind?</h2>
                    <textarea 
                        value={newPostContent}
                        onChange={(e) => setNewPostContent(e.target.value)}
                        placeholder="Share a thought, code snippet, or link... (AI Moderated)"
                        className="w-full bg-slate-50 dark:bg-slate-800 border-none rounded-2xl p-4 min-h-[120px] outline-none text-slate-800 dark:text-slate-200 resize-none mb-4"
                    />
                    {error && <p className="text-xs font-bold text-red-500 mb-4 px-2 tracking-wide uppercase">{error}</p>}
                    <div className="flex justify-between items-center">
                        <button className="p-3 text-slate-400 hover:bg-slate-100 dark:hover:bg-slate-800 rounded-xl transition-all"><ImageIcon className="w-5 h-5"/></button>
                        <button 
                            onClick={handlePublish}
                            disabled={isPublishing || !newPostContent.trim()}
                            className={`${theme.primary} text-white px-8 py-2.5 rounded-xl font-bold transition-all disabled:opacity-50 active:scale-95 flex items-center gap-2`}
                        >
                            {isRecording ? 'Publishing...' : 'Publish to Feed'}
                            <SendIcon className="w-4 h-4" />
                        </button>
                    </div>
                </div>

                <div className="space-y-6">
                    {posts.map(post => (
                        <div key={post.id} className="bg-white dark:bg-slate-900 rounded-3xl p-6 shadow-lg border border-slate-100 dark:border-slate-800 group animate-fade-in">
                            <div className="flex items-center gap-4 mb-4">
                                <div className="w-10 h-10 rounded-full bg-blue-100 dark:bg-blue-900/40 flex items-center justify-center font-bold text-blue-600">
                                    {post.author[0]}
                                </div>
                                <div>
                                    <h4 className="font-bold text-slate-900 dark:text-white">{post.author}</h4>
                                    <p className="text-[10px] text-slate-400 font-bold uppercase tracking-widest">{new Date(post.timestamp).toLocaleString()}</p>
                                </div>
                            </div>
                            <p className="text-slate-700 dark:text-slate-300 whitespace-pre-wrap leading-relaxed mb-6">{post.content}</p>
                            <div className="flex gap-6 border-t border-slate-100 dark:border-slate-800 pt-4 text-slate-400">
                                <button className="flex items-center gap-2 hover:text-blue-500 transition-colors"><svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M4.318 6.318a4.5 4.5 0 000 6.364L12 20.364l7.682-7.682a4.5 4.5 0 00-6.364-6.364L12 7.636l-1.318-1.318a4.5 4.5 0 00-6.364 0z"/></svg> {post.likes}</button>
                                <button className="flex items-center gap-2 hover:text-blue-500 transition-colors"><svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M8 12h.01M12 12h.01M16 12h.01M21 12c0 4.418-4.03 8-9 8a9.863 9.863 0 01-4.255-.949L3 20l1.395-3.72C3.512 15.042 3 13.574 3 12c0-4.418 4.03-8 9-8s9 3.582 9 8z"/></svg> Reply</button>
                            </div>
                        </div>
                    ))}
                </div>
            </div>
        </div>
    );
};

