                };
                setPosts(prev => [newPost, ...prev]);
                setNewPostContent('');
            } else {
                setError(`AI Blocked Post: ${result?.replace('INAPPROPRIATE:', '') || 'Moderation policy violation'}`);
            }
        } catch (e) {
            setError('Safety check failed. Please check your connection.');
        } finally {
            setIsPublishing(false);
        }
    };

    return (
        <div className="h-full overflow-y-auto bg-slate-50 dark:bg-slate-950 p-6 custom-scrollbar">
            <div className="max-w-3xl mx-auto space-y-8">
                <div className="bg-white dark:bg-slate-900 rounded-3xl p-6 shadow-xl border border-slate-200 dark:border-slate-800">
                    <h2 className="text-xl font-bold text-slate-900 dark:text-white mb-4">What's on your mind?</h2>
                    <textarea 
                        value={newPostContent}
                        onChange={(e) => setNewPostContent(e.target.value)}
                        placeholder="Share a thought, code snippet, or link... (AI Moderated)"
                        className="w-full bg-slate-50 dark:bg-slate-800 border-none rounded-2xl p-4 min-h-[120px] outline-none text-slate-800 dark:text-slate-200 resize-none mb-4"
                    />
                    {error && <p className="text-xs font-bold text-red-500 mb-4 px-2 tracking-wide uppercase">{error}</p>}
                    <div className="flex justify-between items-center">
                        <button className="p-3 text-slate-400 hover:bg-slate-100 dark:hover:bg-slate-800 rounded-xl transition-all"><ImageIcon className="w-5 h-5"/></button>
                        <button 
                            onClick={handlePublish}
                            disabled={isPublishing || !newPostContent.trim()}
                            className={`${theme.primary} text-white px-8 py-2.5 rounded-xl font-bold transition-all disabled:opacity-50 active:scale-95 flex items-center gap-2`}
                        >
                            {/* FIX: Changed 'isRecording' to 'isPublishing' to resolve 'Cannot find name' error */}
                            {isPublishing ? 'Publishing...' : 'Publish to Feed'}
                            <SendIcon className="w-4 h-4" />
                        </button>
                    </div>
                </div>

                <div className="space-y-6">
                    {posts.map(post => (
                        <div key={post.id} className="bg-white dark:bg-slate-900 rounded-3xl p-6 shadow-lg border border-slate-100 dark:border-slate-800 group animate-fade-in">
                            <div className="flex items-center gap-4 mb-4">
                                <div className="w-10 h-10 rounded-full bg-blue-100 dark:bg-blue-900/40 flex items-center justify-center font-bold text-blue-600">
                                    {post.author[0]}
                                </div>
                                <div>
                                    <h4 className="font-bold text-slate-900 dark:text-white">{post.author}</h4>
                                    <p className="text-[10px] text-slate-400 font-bold uppercase tracking-widest">{new Date(post.timestamp).toLocaleString()}</p>
                                </div>
                            </div>
                            <p className="text-slate-700 dark:text-slate-300 whitespace-pre-wrap leading-relaxed mb-6">{post.content}</p>
                            <div className="flex gap-6 border-t border-slate-100 dark:border-slate-800 pt-4 text-slate-400">
                                <button className="flex items-center gap-2 hover:text-blue-500 transition-colors"><svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M4.318 6.318a4.5 4.5 0 000 6.364L12 20.364l7.682-7.682a4.5 4.5 0 00-6.364-6.364L12 7.636l-1.318-1.318a4.5 4.5 0 00-6.364 0z"/></svg> {post.likes}</button>
                                <button className="flex items-center gap-2 hover:text-blue-500 transition-colors"><svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M8 12h.01M12 12h.01M16 12h.01M21 12c0 4.418-4.03 8-9 8a9.863 9.863 0 01-4.255-.949L3 20l1.395-3.72C3.512 15.042 3 13.574 3 12c0-4.418 4.03-8 9-8s9 3.582 9 8z"/></svg> Reply</button>
                            </div>
                        </div>
                    ))}
                </div>
            </div>
        </div>
    );
};

import React, { useState } from 'react';
import { GoogleGenAI } from "@google/genai";
import type { ThemeColors, ModelType } from '../types';
// FIX: Added 'BotIcon' to the imports to resolve the 'Cannot find name' error on line 91
import { CodeIcon, SparklesIcon, BotIcon } from './Icons';

export const CodingView: React.FC<{ theme: ThemeColors, model: ModelType }> = ({ theme, model }) => {
    const [prompt, setPrompt] = useState('');
    const [code, setCode] = useState('<!-- Website Preview Will Appear Here -->\n<div style="height: 100vh; display: flex; align-items: center; justify-content: center; background: #0f172a; color: white; font-family: sans-serif;">\n  <h1>Ready to Build</h1>\n</div>');
    const [isGenerating, setIsGenerating] = useState(false);
    const [isPublished, setIsPublished] = useState(false);

    const handleGenerate = async () => {
        if (!prompt.trim()) return;
        setIsGenerating(true);
        setIsPublished(false);
        try {
            const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
            const response = await ai.models.generateContent({
                model: 'gemini-3-pro-preview', // Pro is better for code
                contents: `Build a complete, single-file responsive website using HTML, CSS (Tailwind via CDN), and JS based on this description: "${prompt}". Output ONLY the raw code starting with <!DOCTYPE html>. No explanations.`,
            });
            const extractedCode = response.text || '';
            setCode(extractedCode);
        } catch (e) {
            setCode(`<h1>Error</h1><p>${e}</p>`);
        } finally {
            setIsGenerating(false);
        }
    };

    return (
        <div className="h-full flex flex-col md:flex-row bg-slate-50 dark:bg-slate-950 overflow-hidden">
            {/* Editor Sidebar */}
            <div className="w-full md:w-[400px] flex flex-col border-r border-slate-200 dark:border-slate-800 bg-white dark:bg-slate-900 p-6 overflow-y-auto">
                <h2 className="text-xl font-bold text-slate-900 dark:text-white mb-2 flex items-center gap-2">
                    <CodeIcon className="w-5 h-5 text-blue-600" /> DevStudio
                </h2>
                <p className="text-xs text-slate-400 mb-8 font-bold uppercase tracking-widest">Web Engine v1.0</p>

                <div className="space-y-6">
                    <div>
                        <label className="block text-[10px] font-bold text-slate-400 uppercase tracking-widest mb-2 px-1">Concept Architecture</label>
                        <textarea 
                            value={prompt}
                            onChange={(e) => setPrompt(e.target.value)}
                            placeholder="e.g. A luxury portfolio with dark theme, glassmorphism, and smooth scroll animations."
                            className="w-full p-4 h-40 bg-slate-50 dark:bg-slate-800 rounded-2xl border border-slate-100 dark:border-slate-700 outline-none focus:border-blue-500 text-sm transition-all"
                        />
                    </div>

                    <button 
                        onClick={handleGenerate}
                        disabled={isGenerating || !prompt.trim()}
                        className={`w-full py-4 rounded-2xl font-bold text-white shadow-xl flex items-center justify-center gap-3 transition-all active:scale-95 ${theme.primary} disabled:opacity-50`}
                    >
                        {isGenerating ? <div className="w-4 h-4 border-2 border-white border-t-transparent rounded-full animate-spin"></div> : <SparklesIcon className="w-4 h-4" />}
                        {isGenerating ? 'Architecting...' : 'Build Website'}
                    </button>

                    <div className="pt-6 border-t border-slate-100 dark:border-slate-800">
                        <h3 className="text-xs font-bold text-slate-900 dark:text-white mb-4">Output Log</h3>
                        <div className="bg-slate-950 rounded-xl p-4 font-mono text-[10px] text-blue-400 overflow-hidden">
                            <p>> Model: Gemini 3 Pro</p>
                            <p>> Target: Responsive Web Bundle</p>
                            <p>> Status: {isGenerating ? 'Compiling...' : 'Idle'}</p>
                            {isPublished && <p className="text-green-500 font-bold">> Published to Web Successfully!</p>}
                        </div>
                    </div>

                    <button 
                        onClick={() => setIsPublished(true)}
                        disabled={isGenerating || code.includes('Website Preview Will Appear Here')}
                        className="w-full py-3 bg-slate-100 dark:bg-slate-800 text-slate-600 dark:text-slate-400 font-bold rounded-2xl hover:bg-slate-200 dark:hover:bg-slate-700 transition-all disabled:opacity-30"
                    >
                        Publish to Global Web
                    </button>
                </div>
            </div>

            {/* Preview Area */}
            <div className="flex-1 flex flex-col bg-slate-100 dark:bg-slate-950 p-6 overflow-hidden">
                <div className="flex-1 bg-white rounded-3xl shadow-2xl overflow-hidden border border-slate-200 dark:border-slate-800 relative">
                    <iframe 
                        srcDoc={code}
                        title="Web Preview"
                        className="w-full h-full border-none"
                    />
                    {isGenerating && (
                        <div className="absolute inset-0 bg-slate-900/40 backdrop-blur-md flex items-center justify-center">
                            <div className="text-center">
                                <BotIcon className="w-20 h-20 mx-auto mb-4 animate-bounce" />
                                <p className="text-white font-bold tracking-widest uppercase text-xs animate-pulse">Building your interface...</p>
                            </div>
                        </div>
                    )}
                </div>
            </div>
        </div>
    );
};

