                                        <div className="absolute inset-0 bg-blue-500/20 rounded-full animate-ping"></div>
                                        <BotIcon className="relative w-full h-full animate-float" />
                                    </div>
                                    <p className="text-white font-black tracking-[0.2em] uppercase text-xs animate-pulse">Assembling Interface...</p>
                                </div>
                            </div>
                        )}
                        <div className="absolute bottom-6 left-1/2 -translate-x-1/2 bg-black/50 backdrop-blur-md px-4 py-2 rounded-full border border-white/10 opacity-0 group-hover:opacity-100 transition-opacity">
                            <span className="text-[10px] text-white/70 font-bold uppercase tracking-widest">Visual Preview Mode</span>
