export const CommunityView: React.FC<{ theme: ThemeColors, model: ModelType }> = ({ theme, model }) => {
    const [posts, setPosts] = useState<CommunityPost[]>([]);
    const [newPostContent, setNewPostContent] = useState('');
    const [isPublishing, setIsPublishing] = useState(false);
    const [safetyScanner, setSafetyScanner] = useState(false);
    const [error, setError] = useState<string | null>(null);
    const [replyingTo, setReplyingTo] = useState<string | null>(null);
    const [replyText, setReplyText] = useState('');

    useEffect(() => {
        const saved = localStorage.getItem('cognix_community_posts_v2');
        if (saved) setPosts(JSON.parse(saved));
        else setPosts([
            { 
                id: '1', 
                author: 'Cognix System', 
                authorId: 'sys',
                content: 'Welcome to the v2.0 Global Pulse! Share your thoughts, code, and discoveries. Everything is moderated by Cognix Guard.', 
                timestamp: Date.now(), 
                likedBy: ['sys'], 
                replies: [],
                type: 'text' 
            }
        ]);
    }, []);

    useEffect(() => localStorage.setItem('cognix_community_posts_v2', JSON.stringify(posts)), [posts]);

    const handlePublish = async () => {
        if (!newPostContent.trim()) return;
        setIsPublishing(true);
        setSafetyScanner(true);
        setError(null);

        try {
            const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
            const moderation = await ai.models.generateContent({
                model: 'gemini-3-flash-preview',
                contents: `GUARD PROTOCOL: Evaluate content for: Hate Speech, Explicit, Harassment. 
                CONTENT: "${newPostContent}"
                RESPOND WITH: "PASS" OR "FAIL: [REASON]"`,
            });

            const result = moderation.text?.trim() || "";
            if (result.startsWith('PASS')) {
                const newPost: CommunityPost = {
                    id: Date.now().toString(),
                    author: 'User Account',
                    authorId: 'user_1',
                    content: newPostContent,
                    timestamp: Date.now(),
                    likedBy: [],
                    replies: [],
                    type: 'text'
                };
                setPosts(prev => [newPost, ...prev]);
                setNewPostContent('');
            } else {
                setError(`Cognix Guard Block: ${result.replace('FAIL:', '')}`);
            }
        } catch (e) {
            setError('Safety system offline. Please check connectivity.');
        } finally {
            setIsPublishing(false);
            setSafetyScanner(false);
        }
    };

    const toggleLike = (postId: string) => {
        setPosts(prev => prev.map(p => {
            if (p.id === postId) {
                const liked = p.likedBy.includes('user_1');
                return { ...p, likedBy: liked ? p.likedBy.filter(id => id !== 'user_1') : [...p.likedBy, 'user_1'] };
            }
            return p;
        }));
    };

    const addReply = (postId: string) => {
        if (!replyText.trim()) return;
        setPosts(prev => prev.map(p => {
            if (p.id === postId) {
                return { 
                    ...p, 
                    replies: [...p.replies, { id: Date.now().toString(), author: 'You', content: replyText, timestamp: Date.now() }] 
                };
            }
            return p;
        }));
        setReplyText('');
        setReplyingTo(null);
    };

    return (
        <div className="h-full overflow-y-auto bg-slate-50 dark:bg-slate-950 p-6 custom-scrollbar relative">
            <div className="max-w-3xl mx-auto space-y-8 pb-20">
                {/* Posting Area */}
                <div className="bg-white dark:bg-slate-900 rounded-[2.5rem] p-8 shadow-2xl border border-slate-200 dark:border-slate-800 relative overflow-hidden group">
                    {safetyScanner && (
                        <div className="absolute inset-0 bg-blue-600/95 backdrop-blur-xl z-50 flex flex-col items-center justify-center animate-fade-in p-8 text-center">
                            <div className="w-16 h-16 border-4 border-white/20 border-t-white rounded-full animate-spin mb-6"></div>
                            <h3 className="text-white font-black text-xl tracking-tighter uppercase mb-2">Cognix Guard: Scanning</h3>
                            <p className="text-white/70 text-sm max-w-xs">Ensuring content aligns with community safety and professional standards...</p>
                        </div>
                    )}

                    <div className="flex items-center justify-between mb-6">
                        <h2 className="text-2xl font-black text-slate-900 dark:text-white tracking-tighter">Community Pulse</h2>
                        <div className="flex items-center gap-2 px-3 py-1 bg-green-500/10 rounded-full border border-green-500/20">
                            <span className="w-1.5 h-1.5 rounded-full bg-green-500 animate-pulse"></span>
                            <span className="text-[10px] font-bold text-green-500 uppercase tracking-widest">Safe Feed Active</span>
                        </div>
                    </div>

                    <textarea 
                        value={newPostContent}
                        onChange={(e) => setNewPostContent(e.target.value)}
                        placeholder="What's your latest innovation?"
                        className="w-full bg-slate-50 dark:bg-slate-800/50 border-none rounded-3xl p-6 min-h-[140px] outline-none text-slate-800 dark:text-slate-200 resize-none mb-6 text-lg transition-all focus:bg-white dark:focus:bg-slate-800 shadow-inner"
                    />

                    {error && (
                        <div className="mb-6 p-4 bg-red-500/10 border border-red-500/20 rounded-2xl animate-fade-in flex items-center gap-3">
                            <div className="w-8 h-8 rounded-full bg-red-500/20 flex items-center justify-center text-red-500 font-bold text-xs shrink-0">!</div>
                            <p className="text-xs font-bold text-red-500 uppercase tracking-wide">{error}</p>
                        </div>
                    )}

                    <div className="flex justify-between items-center">
                        <div className="flex gap-2">
                            <button className="p-3 text-slate-400 hover:bg-slate-100 dark:hover:bg-slate-800 rounded-2xl transition-all"><ImageIcon className="w-5 h-5"/></button>
                            <button className="p-3 text-slate-400 hover:bg-slate-100 dark:hover:bg-slate-800 rounded-2xl transition-all"><SparklesIcon className="w-5 h-5"/></button>
                        </div>
                        <button 
                            onClick={handlePublish}
                            disabled={isPublishing || !newPostContent.trim()}
                            className={`${theme.primary} text-white px-10 py-3.5 rounded-2xl font-black shadow-xl shadow-blue-500/20 transition-all disabled:opacity-50 active:scale-95 flex items-center gap-3`}
                        >
                            Publish Post
                            <SendIcon className="w-4 h-4" />
                        </button>
                    </div>
                </div>

                {/* Feed */}
                <div className="space-y-6">
                    {posts.map(post => (
                        <div key={post.id} className="bg-white dark:bg-slate-900 rounded-[2.5rem] p-8 shadow-xl border border-slate-100 dark:border-slate-800 group animate-fade-in">
                            <div className="flex items-center justify-between mb-6">
                                <div className="flex items-center gap-4">
                                    <div className="w-12 h-12 rounded-3xl bg-gradient-to-tr from-slate-200 to-slate-100 dark:from-slate-800 dark:to-slate-700 flex items-center justify-center font-black text-slate-500 dark:text-slate-400 shadow-inner">
                                        {post.author[0]}
                                    </div>
                                    <div>
                                        <div className="flex items-center gap-2">
                                            <h4 className="font-black text-slate-900 dark:text-white">{post.author}</h4>
                                            {post.authorId === 'sys' && <BotIcon className="w-3.5 h-3.5 text-blue-500" />}
                                            <button className="text-[10px] font-bold text-blue-500 hover:underline uppercase tracking-widest ml-2">Connect</button>
                                        </div>
                                        <p className="text-[10px] text-slate-400 font-bold uppercase tracking-widest mt-0.5">{new Date(post.timestamp).toLocaleDateString()}</p>
                                    </div>
                                </div>
                            </div>

                            <p className="text-slate-700 dark:text-slate-300 whitespace-pre-wrap leading-relaxed mb-8 text-lg">{post.content}</p>

                            {/* Actions */}
                            <div className="flex items-center gap-8 border-t border-slate-50 dark:border-slate-800 pt-6">
                                <button 
                                    onClick={() => toggleLike(post.id)}
                                    className={`flex items-center gap-2 transition-all font-bold text-sm ${post.likedBy.includes('user_1') ? 'text-rose-500 scale-110' : 'text-slate-400 hover:text-rose-500'}`}
                                >
                                    <svg className={`w-6 h-6 ${post.likedBy.includes('user_1') ? 'fill-current' : 'fill-none stroke-current'}`} viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M4.318 6.318a4.5 4.5 0 000 6.364L12 20.364l7.682-7.682a4.5 4.5 0 00-6.364-6.364L12 7.636l-1.318-1.318a4.5 4.5 0 00-6.364 0z"/></svg>
                                    {post.likedBy.length}
                                </button>
                                <button 
                                    onClick={() => setReplyingTo(replyingTo === post.id ? null : post.id)}
                                    className="flex items-center gap-2 text-slate-400 hover:text-blue-500 transition-colors font-bold text-sm"
                                >
                                    <svg className="w-6 h-6 fill-none stroke-current" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M8 12h.01M12 12h.01M16 12h.01M21 12c0 4.418-4.03 8-9 8a9.863 9.863 0 01-4.255-.949L3 20l1.395-3.72C3.512 15.042 3 13.574 3 12c0-4.418 4.03-8 9-8s9 3.582 9 8z"/></svg>
                                    {post.replies.length}
                                </button>
                                <button className="flex items-center gap-2 text-slate-400 hover:text-emerald-500 transition-colors font-bold text-sm">
                                    <svg className="w-6 h-6 fill-none stroke-current" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M8.684 13.342C8.886 12.938 9 12.482 9 12c0-.482-.114-.938-.316-1.342m0 2.684a3 3 0 110-2.684m0 2.684l6.632 3.316m-6.632-6l6.632-3.316m0 0a3 3 0 105.367-2.684 3 3 0 00-5.367 2.684zm0 9.316a3 3 0 105.368 2.684 3 3 0 00-5.368-2.684z"/></svg>
                                    Share
                                </button>
                            </div>

                            {/* Replies Area */}
                            {(post.replies.length > 0 || replyingTo === post.id) && (
                                <div className="mt-8 space-y-4 pt-6 border-t border-slate-50 dark:border-slate-800">
                                    {post.replies.map(reply => (
                                        <div key={reply.id} className="flex gap-4 p-4 rounded-3xl bg-slate-50 dark:bg-slate-800/30">
                                            <div className="w-8 h-8 rounded-xl bg-slate-200 dark:bg-slate-700 flex items-center justify-center font-bold text-xs">{reply.author[0]}</div>
                                            <div>
                                                <p className="font-bold text-xs text-slate-900 dark:text-white mb-1">{reply.author}</p>
                                                <p className="text-sm text-slate-600 dark:text-slate-400 leading-relaxed">{reply.content}</p>
                                            </div>
                                        </div>
                                    ))}
                                    {replyingTo === post.id && (
                                        <div className="flex gap-3 items-center">
                                            <input 
                                                autoFocus
                                                value={replyText}
                                                onChange={(e) => setReplyText(e.target.value)}
                                                onKeyDown={e => e.key === 'Enter' && addReply(post.id)}
                                                placeholder="Add your reply..."
                                                className="flex-1 bg-slate-100 dark:bg-slate-800 rounded-2xl px-6 py-3 outline-none text-sm transition-all focus:bg-white dark:focus:bg-slate-700"
                                            />
                                            <button onClick={() => addReply(post.id)} className="p-3 bg-blue-600 text-white rounded-2xl hover:bg-blue-700 shadow-lg shadow-blue-500/10">
                                                <SendIcon className="w-4 h-4" />
                                            </button>
                                        </div>
                                    )}
                                </div>
                            )}
                        </div>
                    ))}
                </div>
            </div>
        </div>
    );
};

