import React from 'react';
// Fixed: Removed non-existent icon imports (MoonIcon, PaletteIcon, SunIcon, TypeIcon) and unused ones (BotIcon, CodeIcon) to fix errors.
import { TrashIcon } from './Icons';
import type { UIStyle, AccentColor, FontSize } from '../types';

interface SettingsModalProps {
    isOpen: boolean;
    onClose: () => void;
    uiStyle: UIStyle;
    setUiStyle: (style: UIStyle) => void;
    accentColor: AccentColor;
    setAccentColor: (color: AccentColor) => void;
    fontSize: FontSize;
    setFontSize: (size: FontSize) => void;
    isDarkMode: boolean;
    setIsDarkMode: (isDark: boolean) => void;
    onClearHistory: () => void;
    systemInstruction: string;
    setSystemInstruction: (val: string) => void;
}

const StyleCard: React.FC<{ 
    active: boolean; 
    onClick: () => void; 
    title: string; 
    preview: React.ReactNode;
}> = ({ active, onClick, title, preview }) => (
    <button 
        onClick={onClick}
        className={`flex flex-col items-center gap-3 p-3 rounded-xl transition-all duration-300 w-full group border
            ${active ? 'bg-white/5 border-gold-500 shadow-glow-gold' : 'bg-transparent border-white/10 hover:border-white/30'}
        `}
    >
        <div className="w-full h-16 flex items-center justify-center overflow-hidden rounded-lg bg-black/50">
            {preview}
        </div>
        <span className={`text-xs font-bold uppercase tracking-widest ${active ? 'text-gold-500' : 'text-gray-500'}`}>{title}</span>
    </button>
);

export const SettingsModal: React.FC<SettingsModalProps> = ({ 
    isOpen, onClose, uiStyle, setUiStyle, accentColor, setAccentColor, fontSize, setFontSize, isDarkMode, setIsDarkMode, onClearHistory, systemInstruction, setSystemInstruction
}) => {
    if (!isOpen) return null;

    return (
        <div className="fixed inset-0 bg-black/80 backdrop-blur-md flex items-center justify-center z-[100] animate-fade-in p-4" onClick={onClose}>
            <div className="w-full max-w-2xl bg-obsidian border border-white/10 rounded-sm shadow-2xl max-h-[90vh] flex flex-col overflow-hidden animate-fade-in-up" onClick={e => e.stopPropagation()}>

                {/* Header */}
                <div className="p-8 border-b border-white/10 flex justify-between items-center bg-black/50">
                    <div>
                        <h2 className="text-2xl font-display font-bold text-white uppercase tracking-widest">System Config</h2>
                        <p className="text-xs text-gold-500 font-mono mt-1">v2.5.0 // CUSTOMIZE</p>
                    </div>
                    <button onClick={onClose} className="w-10 h-10 flex items-center justify-center text-white/50 hover:text-white transition-colors text-2xl">&times;</button>
                </div>

                <div className="flex-1 overflow-y-auto p-8 space-y-12 classic-scroll">

                    {/* Theme Engine */}
                    <section>
                        <h3 className="text-xs font-mono font-bold text-cyan-500 mb-6 tracking-widest">INTERFACE_MODE</h3>
                        <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
                            <StyleCard 
                                title="Neo-Classic" 
                                active={uiStyle === 'modern'} 
                                onClick={() => setUiStyle('modern')}
                                preview={<div className="w-12 h-12 bg-black border border-gold-500"></div>}
