  const [systemInstruction, setSystemInstruction] = useState("You are Cognix AI, a highly intelligent personal assistant created by Shashwat Ranjan Jha. You are professional, witty, and extremely capable. You have access to real-time information via Google Search.");

  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [isDesktopSidebarOpen, setIsDesktopSidebarOpen] = useState(true);
  const [isDarkMode, setIsDarkMode] = useState(false);
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);

  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [chatHistory, setChatHistory] = useState<ChatSession[]>([]);
  const [activeChatId, setActiveChatId] = useState<string | null>(null);
  const [friends, setFriends] = useState<Friend[]>([]);

  useEffect(() => {
    const savedHistory = localStorage.getItem('cognix_v2_history');
    if (savedHistory) setChatHistory(JSON.parse(savedHistory));

    const savedFriends = localStorage.getItem('cognix_friends');
    if (savedFriends) setFriends(JSON.parse(savedFriends));

    const savedTheme = localStorage.getItem('cognix_theme');
    if (savedTheme === 'dark' || (!savedTheme && window.matchMedia('(prefers-color-scheme: dark)').matches)) {
      setIsDarkMode(true);
      document.documentElement.classList.add('dark');
    }
  }, []);

  useEffect(() => localStorage.setItem('cognix_v2_history', JSON.stringify(chatHistory)), [chatHistory]);
  useEffect(() => localStorage.setItem('cognix_friends', JSON.stringify(friends)), [friends]);

  useEffect(() => {
    if (isDarkMode) {
      document.documentElement.classList.add('dark');
      localStorage.setItem('cognix_theme', 'dark');
    } else {
      document.documentElement.classList.remove('dark');
      localStorage.setItem('cognix_theme', 'light');
    }
  }, [isDarkMode]);

  const currentChat = useMemo(() => chatHistory.find(c => c.id === activeChatId), [chatHistory, activeChatId]);
  const activeTheme = useMemo(() => THEMES[accentColor], [accentColor]);

  useEffect(() => {
    setMessages(currentChat ? currentChat.messages : []);
  }, [currentChat?.id]);

  // AI powered chat naming
  const generateChatTitle = async (firstMessage: string) => {
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: `Generate a catchy, ultra-short (max 3 words) title for a conversation that starts with: "${firstMessage}". No quotes or period.`,
      });
      return response.text?.trim() || firstMessage.slice(0, 30);
    } catch (e) {
      return firstMessage.slice(0, 30);
    }
  };

  useEffect(() => {
    const updateHistory = async () => {
      if (messages.length === 1 && !activeChatId && messages[0].role === 'user') {
         const firstUserText = messages[0].parts.find(p => p.text)?.text || 'New Chat';
         const newId = Date.now().toString();
         const newTitle = await generateChatTitle(firstUserText);
         const newSession: ChatSession = { id: newId, title: newTitle, messages: messages };
         setChatHistory(prev => [newSession, ...prev]);
         setActiveChatId(newId);
      } else if (activeChatId && messages.length > 0) {
         setChatHistory(prev => prev.map(session => session.id === activeChatId ? { ...session, messages } : session));
      }
    };
    updateHistory();
  }, [messages, activeChatId]);

  const handleNewChat = () => {
    setActiveChatId(null);
    setMessages([]);
    setMode('chat');
    if (window.innerWidth < 1024) setIsSidebarOpen(false);
  };

  return (
    <div className={`flex h-[100dvh] overflow-hidden bg-slate-50 dark:bg-slate-950 transition-colors duration-300`}>

      <Sidebar 
        chatHistory={chatHistory}
        activeChatId={activeChatId}
        mode={mode}
        onSetMode={(m) => { setMode(m); if(window.innerWidth < 1024) setIsSidebarOpen(false); }}
        onSelectChat={(id) => { setActiveChatId(id); setMode('chat'); if(window.innerWidth < 1024) setIsSidebarOpen(false); }}
        onNewChat={handleNewChat}
        onDeleteChat={(id) => {
            setChatHistory(h => h.filter(c => c.id !== id));
            if (activeChatId === id) { setActiveChatId(null); setMessages([]); }
        }}
        onRenameChat={(id, t) => setChatHistory(h => h.map(c => c.id === id ? { ...c, title: t } : c))}
        onOpenSettings={() => setIsSettingsOpen(true)}
        isSidebarOpen={isSidebarOpen}
        isDesktopSidebarOpen={isDesktopSidebarOpen}
        theme={activeTheme}
        friends={friends}
      />

      {isSidebarOpen && <div className="fixed inset-0 bg-black/40 backdrop-blur-sm z-40 lg:hidden" onClick={() => setIsSidebarOpen(false)} />}

      <div className="flex-1 flex flex-col h-full min-w-0 bg-white dark:bg-slate-900 lg:rounded-l-3xl shadow-2xl relative">
        <header className="h-16 flex items-center justify-between px-6 shrink-0 z-30">
             <div className="flex items-center gap-4">
                <button onClick={() => window.innerWidth >= 1024 ? setIsDesktopSidebarOpen(!isDesktopSidebarOpen) : setIsSidebarOpen(!isSidebarOpen)} className="p-2 -ml-2 text-slate-500 hover:bg-slate-100 dark:hover:bg-slate-800 rounded-xl transition-colors">
                    <MenuIcon className="w-5 h-5"/>
                </button>
                <div className="flex flex-col">
                  <h1 className="text-sm font-bold text-slate-800 dark:text-slate-100 flex items-center gap-2">
                      {mode === 'chat' && (currentChat?.title || 'New Conversation')}
                      {mode === 'live' && 'Live Intelligence'}
                      {mode === 'community' && 'Community Pulse'}
                      {mode === 'coding' && 'DevStudio v1.0'}
                      {mode === 'toolbox' && 'Lab Toolbox'}
                      {mode === 'memory' && 'Vault'}
                      {mode === 'chat' && <div className="w-1.5 h-1.5 rounded-full bg-green-500 animate-pulse"></div>}
                  </h1>
                  <span className="text-[10px] text-slate-400 font-medium tracking-widest uppercase">Cognix Pro</span>
                </div>
             </div>

             <div className="flex items-center gap-3">
                 <select 
                    value={activeModel} 
                    onChange={(e) => setActiveModel(e.target.value as ModelType)}
                    className="text-[10px] font-bold bg-slate-100 dark:bg-slate-800 px-3 py-1.5 rounded-lg outline-none border border-slate-200 dark:border-slate-700 text-slate-600 dark:text-slate-300 transition-all hover:bg-slate-200 dark:hover:bg-slate-700 cursor-pointer"
                 >
                     <option value="gemini-2.5-flash-latest">Gemini 2.5 Flash (Default)</option>
                     <option value="cognix-arc-1.0">CognixArc 1.0 (All-Rounder)</option>
                     <option value="gemini-3-flash-preview">Gemini 3 Flash (Fast)</option>
                     <option value="gemini-3-pro-preview">Gemini 3 Pro (Deep Reasoning)</option>
                     <option value="gemini-flash-lite-latest">Gemini Lite (Lightweight)</option>
                 </select>
                 <button onClick={() => setIsDarkMode(!isDarkMode)} className="p-2 text-slate-400 hover:text-slate-600 dark:hover:text-slate-200 transition-colors">
                     {isDarkMode ? <svg className="w-5 h-5" fill="currentColor" viewBox="0 0 20 20"><path d="M10 2a1 1 0 011 1v1a1 1 0 11-2 0V3a1 1 0 011-1zm4 8a4 4 0 11-8 0 4 4 0 018 0zm-.464 4.95l.707.707a1 1 0 001.414-1.414l-.707-.707a1 1 0 00-1.414 1.414zm2.12-10.607a1 1 0 010 1.414l-.706.707a1 1 0 11-1.414-1.414l.707-.707a1 1 0 011.414 0zM17 11a1 1 0 100-2h-1a1 1 0 100 2h1zm-7 4a1 1 0 011 1v1a1 1 0 11-2 0v-1a1 1 0 011-1zM5.05 6.464A1 1 0 106.465 5.05l-.708-.707a1 1 0 00-1.414 1.414l.707.707zm1.414 8.486l-.707.707a1 1 0 01-1.414-1.414l.707-.707a1 1 0 011.414 1.414zM4 11a1 1 0 100-2H3a1 1 0 000 2h1z"/></svg> : <svg className="w-5 h-5" fill="currentColor" viewBox="0 0 20 20"><path d="M17.293 13.293A8 8 0 016.707 2.707a8.001 8.001 0 1010.586 10.586z"/></svg>}
                 </button>
             </div>
        </header>

        <main className="flex-1 relative overflow-hidden">
             {mode === 'chat' && (
                <ChatView 
                    messages={messages} 
                    setMessages={setMessages}
                    uiStyle={uiStyle}
                    theme={activeTheme}
                    fontSize={fontSize}
                    systemInstruction={systemInstruction}
                    model={activeModel}
                    setActiveModel={setActiveModel}
                />
            )}
            {mode === 'live' && <LiveView theme={activeTheme} />}
            {mode === 'friends' && <FriendsView friends={friends} setFriends={setFriends} />}
            {mode === 'community' && <CommunityView theme={activeTheme} model={activeModel} />}
            {mode === 'coding' && <CodingView theme={activeTheme} model={activeModel} />}
            {mode === 'toolbox' && <ToolboxView theme={activeTheme} model={activeModel} />}
            {mode === 'memory' && <MemoryView theme={activeTheme} />}
        </main>
      </div>

      <SettingsModal 
        isOpen={isSettingsOpen} onClose={() => setIsSettingsOpen(false)}
        uiStyle={uiStyle} setUiStyle={setUiStyle}
        accentColor={accentColor} setAccentColor={setAccentColor}
        fontSize={fontSize} setFontSize={setFontSize}
        isDarkMode={isDarkMode} setIsDarkMode={setIsDarkMode}
        onClearHistory={() => { setChatHistory([]); setMessages([]); setActiveChatId(null); setIsSettingsOpen(false); }}
        systemInstruction={systemInstruction} setSystemInstruction={setSystemInstruction}
      />
    </div>
  );
}

export default App;

import React, { useState, useRef, useEffect, useCallback } from 'react';
import type { ChatMessage, ChatPart, SearchResult, UIStyle, ThemeColors, FontSize, ModelType } from '../types';
import { GoogleGenAI } from "@google/genai";
import { BotIcon, SendIcon, UserIcon, ImageIcon, SpeakerIcon, CopyIcon, SearchIcon, SparklesIcon } from './Icons';

interface ChatViewProps {
  messages: ChatMessage[];
  setMessages: React.Dispatch<React.SetStateAction<ChatMessage[]>>;
  uiStyle: UIStyle;
  theme: ThemeColors;
  fontSize: FontSize;
  systemInstruction: string;
  model: ModelType;
  setActiveModel: (m: ModelType) => void;
}

const SourceCard: React.FC<{ result: SearchResult }> = ({ result }) => (
    <a 
        href={result.uri} 
        target="_blank" 
        rel="noopener noreferrer"
        className="flex items-center gap-3 p-3 bg-white/50 dark:bg-slate-800/50 backdrop-blur-sm border border-slate-200 dark:border-slate-700 rounded-2xl hover:border-blue-500 dark:hover:border-blue-400 transition-all group shrink-0 max-w-[220px] shadow-sm"
    >
        <div className="w-10 h-10 rounded-xl bg-blue-100 dark:bg-blue-900/40 flex items-center justify-center shrink-0">
            <SearchIcon className="w-5 h-5 text-blue-600 dark:text-blue-400" />
        </div>
        <div className="flex-1 min-w-0">
            <p className="text-xs font-bold text-slate-900 dark:text-slate-100 truncate">{result.title}</p>
            <p className="text-[10px] text-slate-400 truncate uppercase tracking-tight">{new URL(result.uri).hostname}</p>
        </div>
    </a>
);

export const ChatView: React.FC<ChatViewProps> = ({ messages, setMessages, theme, systemInstruction, model, setActiveModel }) => {
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [selectedImage, setSelectedImage] = useState<{ data: string; mimeType: string } | null>(null);
  const [webSearchEnabled, setWebSearchEnabled] = useState(true);

  const chatContainerRef = useRef<HTMLDivElement>(null);
  const textareaRef = useRef<HTMLTextAreaElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (chatContainerRef.current) chatContainerRef.current.scrollTop = chatContainerRef.current.scrollHeight;
  }, [messages, isLoading, selectedImage]);

  // Strip asterisks for the user as requested
  const formatOutput = (text: string) => {
    return text.replace(/\*/g, '');
  };

  const handleSendMessage = useCallback(async (textOverride?: string) => {
    const textInput = (textOverride || input).trim();
    if ((!textInput && !selectedImage) || isLoading) return;

    const userMessageParts: ChatPart[] = [];
    if (selectedImage) userMessageParts.push({ inlineData: { mimeType: selectedImage.mimeType, data: selectedImage.data } });
    if (textInput) userMessageParts.push({ text: textInput });

    const userMessage: ChatMessage = { id: `msg-${Date.now()}`, role: 'user', parts: userMessageParts };
    const modelPlaceholder: ChatMessage = { id: `msg-${Date.now() + 1}`, role: 'model', parts: [{ text: '' }], isSearching: webSearchEnabled };

    setMessages(prev => [...prev, userMessage, modelPlaceholder]);
    setInput(''); 
    setSelectedImage(null);
    setIsLoading(true);

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const history = messages.map(msg => ({
        role: msg.role,
        parts: msg.parts.map(p => {
            if (p.text) return { text: p.text };
            if (p.inlineData) return { inlineData: p.inlineData };
            return null;
        }).filter(Boolean) as any[]
      }));

      let finalModelName = model === 'cognix-arc-1.0' ? 'gemini-3-pro-preview' : model;
      let modelSpecificInstruction = systemInstruction;

      // Add specific logic for models
      if (model === 'gemini-2.5-flash-latest') {
          modelSpecificInstruction += " IMPORTANT: Use relevant emojis to make your responses engaging and friendly. NEVER use asterisks (*) for formatting (no bolding or italics with asterisks). Always respond in clear, professional paragraphs.";
      } else if (model === 'cognix-arc-1.0') {
          modelSpecificInstruction = "You are CognixArc 1.0, an advanced all-rounder AI node. You are efficient, creative, and highly accurate. Do not use asterisks (*) for formatting. Use emojis sparingly but effectively.";
      } else {
          modelSpecificInstruction += " Do not use asterisks (*) for formatting.";
      }

      let stream = await ai.models.generateContentStream({
          model: finalModelName as any,
          contents: [...history, { role: 'user', parts: userMessageParts as any }],
          config: { 
              systemInstruction: modelSpecificInstruction, 
              tools: webSearchEnabled ? [{ googleSearch: {} }] : [],
              temperature: model === 'gemini-2.5-flash-latest' ? 0.9 : 0.7 
          },
      });

      let fullText = '';
      let searchResults: SearchResult[] = [];

      for await (const chunk of stream) {
        if(chunk.text) {
            fullText += chunk.text;
            // Cleaning output text as it streams
            const cleanText = formatOutput(fullText);
            setMessages(prev => prev.map(m => m.id === modelPlaceholder.id ? { ...m, parts: [{ text: cleanText }], isSearching: false } : m));
        }
        const chunks = chunk.candidates?.[0]?.groundingMetadata?.groundingChunks;
        if (chunks) {
            const results = chunks.map((c: any) => c.web ? { ...c.web, type: 'web' } : null).filter(Boolean);
            searchResults = [...searchResults, ...results];
        }
      }

      if (searchResults.length > 0) {
        const unique = Array.from(new Map(searchResults.map(i => [i.uri, i])).values());
        setMessages(prev => prev.map(m => m.id === modelPlaceholder.id ? { ...m, parts: [{ ...m.parts[0], searchResults: unique }] } : m));
      }
    } catch (error) {
      setMessages(prev => prev.map(m => m.id === modelPlaceholder.id ? { ...m, parts: [{ text: `System Error: ${error instanceof Error ? error.message : "Unknown connectivity issue."}` }], isSearching: false } : m));
    } finally {
      setIsLoading(false);
    }
  }, [input, isLoading, messages, selectedImage, systemInstruction, model, webSearchEnabled]);

  return (
    <div className="flex flex-col h-full bg-white dark:bg-slate-900 relative">
      <div ref={chatContainerRef} className="flex-1 overflow-y-auto px-4 pb-48 pt-8 custom-scrollbar">
        {messages.length === 0 ? (
            <div className="max-w-3xl mx-auto flex flex-col items-center justify-center min-h-[70vh] text-center px-4">
                 <div className="relative mb-12">
                     <div className="absolute inset-0 bg-blue-500/10 rounded-full blur-3xl animate-pulse"></div>
                     <BotIcon className="relative w-28 h-28 drop-shadow-2xl animate-float" />
                 </div>
                 <h2 className="text-5xl font-black text-slate-900 dark:text-white mb-4 tracking-tighter">Initiate Cognix Engine.</h2>
                 <p className="text-slate-500 dark:text-slate-400 max-w-lg mb-16 text-xl font-medium leading-relaxed">
                    Personal intelligence at your fingertips. Built by Shashwat Ranjan Jha.
                 </p>

                 <div className="grid grid-cols-1 md:grid-cols-2 gap-5 w-full">
                     {[
                         { t: "Live Intelligence", s: "Browse the live web for current facts", q: "What are the top 3 tech breakthroughs from this month?", icon: <SearchIcon className="w-5 h-5"/> },
                         { t: "Neural Creation", s: "Generate unique imagery and art", q: "Generate a hyper-realistic 8k image of a futuristic floating city at sunset", icon: <ImageIcon className="w-5 h-5"/> },
                         { t: "Dev Architect", s: "Build and debug professional web code", q: "Architect a responsive React dashboard layout with dark mode using Tailwind", icon: <SparklesIcon className="w-5 h-5"/> },
                         { t: "Deep Reasoning", s: "Solve complex logical architectures", q: "Explain quantum entanglement through a coffee shop analogy", icon: <BotIcon className="w-5 h-5"/> }
                     ].map((item, i) => (
                        <button 
                            key={i} 
                            onClick={() => handleSendMessage(item.q)}
                            className="text-left p-6 rounded-[2rem] border border-slate-200 dark:border-slate-800 hover:border-blue-500 dark:hover:border-blue-500/50 hover:bg-slate-50 dark:hover:bg-slate-800/50 transition-all group flex gap-5 items-start"
                        >
                            <div className="w-12 h-12 rounded-2xl bg-slate-100 dark:bg-slate-800 flex items-center justify-center shrink-0 group-hover:bg-blue-600 group-hover:text-white transition-all">
                                {item.icon}
                            </div>
                            <div>
                                <p className="font-black text-slate-900 dark:text-white mb-1 group-hover:text-blue-600 dark:group-hover:text-blue-400 transition-colors">{item.t}</p>
                                <p className="text-xs text-slate-400 font-medium">{item.s}</p>
                            </div>
                        </button>
                     ))}
                 </div>
            </div>
        ) : (
            <div className="max-w-4xl mx-auto space-y-12">
                {messages.map((msg) => (
                    <div key={msg.id} className={`flex gap-6 group ${msg.role === 'user' ? 'flex-row-reverse' : 'flex-row'}`}>
                        <div className={`w-10 h-10 shrink-0 rounded-[1.2rem] flex items-center justify-center shadow-xl
                            ${msg.role === 'user' ? 'bg-slate-100 dark:bg-slate-800 text-slate-500 border border-slate-200 dark:border-slate-700' : 'bg-gradient-to-tr from-blue-600 to-indigo-600 text-white'}
                        `}>
                             {msg.role === 'user' ? <UserIcon className="w-6 h-6"/> : <BotIcon className="w-7 h-7"/>}
                        </div>

                        <div className={`flex flex-col gap-3 max-w-[85%] ${msg.role === 'user' ? 'items-end' : 'items-start'}`}>
                             {msg.parts.map((part, i) => (
                                 <div key={i} className={`relative leading-relaxed text-base transition-all
                                     ${msg.role === 'user' 
                                         ? 'bg-blue-600 text-white px-6 py-4 rounded-[2rem] rounded-tr-sm shadow-xl shadow-blue-500/20 font-medium' 
                                         : 'text-slate-800 dark:text-slate-100 px-1'}
                                 `}>
                                     {part.inlineData && <img src={`data:${part.inlineData.mimeType};base64,${part.inlineData.data}`} className="rounded-[2rem] mb-6 max-h-[500px] shadow-2xl border border-slate-200 dark:border-slate-800 object-contain" alt="Upload"/>}

                                     {msg.isSearching && i === 0 && (
                                         <div className="flex items-center gap-3 text-blue-500 mb-4 animate-pulse-soft bg-blue-50 dark:bg-blue-900/20 px-4 py-2 rounded-full border border-blue-500/20 w-fit">
                                             <div className="w-4 h-4 border-2 border-blue-500 border-t-transparent rounded-full animate-spin"></div>
                                             <span className="text-[10px] font-black uppercase tracking-[0.2em]">Navigating Live Web...</span>
                                         </div>
                                     )}

                                     <div className="whitespace-pre-wrap prose dark:prose-invert max-w-none text-lg leading-relaxed">{part.text}</div>

                                     {part.searchResults && part.searchResults.length > 0 && (
                                         <div className="mt-8">
                                            <p className="text-[10px] font-black text-slate-400 uppercase tracking-[0.3em] mb-4 flex items-center gap-3">
                                                Grounding Sources <span className="h-px bg-slate-200 dark:bg-slate-800 flex-1"></span>
                                            </p>
                                            <div className="flex gap-4 overflow-x-auto pb-4 no-scrollbar">
                                                {part.searchResults.map((res, idx) => <SourceCard key={idx} result={res} />)}
                                            </div>
                                         </div>
                                     )}

                                     {msg.role === 'model' && part.text && (
                                         <div className="flex gap-3 mt-6 opacity-0 group-hover:opacity-100 transition-all translate-y-2 group-hover:translate-y-0">
                                             <button onClick={() => navigator.clipboard.writeText(part.text || '')} className="p-2.5 hover:bg-slate-100 dark:hover:bg-slate-800 rounded-2xl text-slate-400 hover:text-blue-500 transition-all border border-transparent hover:border-slate-200 dark:hover:border-slate-700 shadow-sm"><CopyIcon className="w-5 h-5"/></button>
                                             <button className="p-2.5 hover:bg-slate-100 dark:hover:bg-slate-800 rounded-2xl text-slate-400 hover:text-blue-500 transition-all border border-transparent hover:border-slate-200 dark:hover:border-slate-700 shadow-sm"><SpeakerIcon className="w-5 h-5"/></button>
                                         </div>
                                     )}
                                 </div>
                             ))}
                        </div>
                    </div>
                ))}
            </div>
        )}
      </div>

      {/* Advanced Premium Input Bar */}
      <div className="absolute bottom-0 left-0 right-0 px-6 pb-10 pt-10 bg-gradient-to-t from-white dark:from-slate-900 via-white/95 dark:via-slate-900/95 to-transparent pointer-events-none">
          <div className="max-w-4xl mx-auto relative group pointer-events-auto">
              {/* Upper Actions Toolbar */}
              <div className="flex justify-between items-center px-6 mb-4">
                  <div className="flex gap-4 items-center">
                      <div className="flex bg-slate-100 dark:bg-slate-800 p-1 rounded-2xl border border-slate-200 dark:border-slate-700">
                          {(['gemini-2.5-flash-latest', 'cognix-arc-1.0'] as ModelType[]).map(m => (
                              <button 
                                  key={m}
                                  onClick={() => setActiveModel(m)}
                                  className={`px-4 py-1.5 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${model === m ? 'bg-white dark:bg-slate-900 text-blue-600 shadow-sm' : 'text-slate-400 hover:text-slate-600 dark:hover:text-slate-200'}`}
                              >
                                  {m === 'gemini-2.5-flash-latest' ? 'Flash 2.5' : 'Arc 1.0'}
                              </button>
                          ))}
                      </div>

                      <button 
                          onClick={() => setWebSearchEnabled(!webSearchEnabled)}
                          className={`flex items-center gap-2 px-4 py-2 rounded-2xl border transition-all ${webSearchEnabled ? 'bg-blue-50 dark:bg-blue-900/30 border-blue-200 dark:border-blue-800 text-blue-600 dark:text-blue-400' : 'bg-slate-50 dark:bg-slate-800 border-slate-200 dark:border-slate-700 text-slate-400'}`}
                      >
                          <SearchIcon className="w-4 h-4" />
                          <span className="text-[10px] font-black uppercase tracking-widest">Web Grounding</span>
                          <div className={`w-2 h-2 rounded-full ${webSearchEnabled ? 'bg-blue-500 animate-pulse' : 'bg-slate-300 dark:bg-slate-600'}`}></div>
                      </button>
                  </div>
              </div>

              {/* Main Input Box */}
              <div className="flex items-end gap-3 p-2.5 bg-white/80 dark:bg-slate-800/80 backdrop-blur-3xl rounded-[3rem] shadow-[0_30px_60px_-12px_rgba(0,0,0,0.15)] dark:shadow-[0_30px_60px_-12px_rgba(0,0,0,0.4)] border border-slate-200/50 dark:border-slate-700/50 transition-all focus-within:ring-8 ring-blue-500/5 focus-within:border-blue-500 dark:focus-within:border-blue-400/50">
                   <button 
                        onClick={() => fileInputRef.current?.click()} 
                        className="p-4 mb-0.5 rounded-full text-slate-400 hover:bg-blue-50 dark:hover:bg-blue-900/20 hover:text-blue-600 transition-all duration-300 hover:scale-110 active:scale-90"
                        title="Upload Cognitive Asset"
                   >
                       <ImageIcon className="w-7 h-7"/>
                       <input type="file" ref={fileInputRef} onChange={(e) => {
                            const file = e.target.files?.[0];
                            if (file) {
                                const reader = new FileReader();
                                reader.onloadend = () => {
                                    setSelectedImage({ data: (reader.result as string).split(',')[1], mimeType: file.type });
                                };
                                reader.readAsDataURL(file);
                            }
                       }} accept="image/*" className="hidden" />
                   </button>

                   <textarea
                       ref={textareaRef}
                       value={input}
                       onChange={e => setInput(e.target.value)}
                       onKeyDown={e => e.key === 'Enter' && !e.shiftKey && (e.preventDefault(), handleSendMessage())}
                       placeholder="Ask Cognix anything..."
                       className="flex-1 bg-transparent border-none outline-none resize-none py-4 px-2 max-h-48 text-slate-900 dark:text-white placeholder-slate-400 dark:placeholder-slate-500 text-lg font-medium leading-normal"
                       rows={1}
                   />

                   <button 
                        onClick={() => handleSendMessage()} 
                        disabled={isLoading || (!input && !selectedImage)} 
                        className={`p-5 mb-0.5 rounded-full text-white transition-all duration-500 transform active:scale-90 disabled:opacity-20 flex items-center justify-center
                            ${input || selectedImage ? 'bg-gradient-to-r from-blue-600 to-indigo-600 shadow-2xl shadow-blue-500/30' : 'bg-slate-200 dark:bg-slate-700 text-slate-400'}
                        `}
                   >
                       {isLoading ? (
                           <div className="w-6 h-6 border-2 border-white border-t-transparent rounded-full animate-spin"></div>
                       ) : (
                           <SendIcon className="w-6 h-6"/>
                       )}
                   </button>
              </div>

              {selectedImage && (
                  <div className="absolute -top-32 left-4 p-3 bg-white/90 dark:bg-slate-800/90 backdrop-blur-xl rounded-[2.5rem] shadow-2xl border border-slate-200/50 dark:border-slate-700/50 flex items-center gap-5 animate-fade-in group">
                      <div className="relative overflow-hidden rounded-[1.5rem] w-24 h-24 shadow-inner border border-slate-100 dark:border-slate-700">
                        <img src={`data:${selectedImage.mimeType};base64,${selectedImage.data}`} className="w-full h-full object-cover" />
                        <div className="absolute inset-0 bg-black/10 transition-opacity opacity-0 group-hover:opacity-100"></div>
                      </div>
                      <div className="pr-2">
                        <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2">Cognitive Link</p>
                        <button onClick={() => setSelectedImage(null)} className="px-4 py-2 bg-red-500 text-white rounded-xl hover:bg-red-600 transition-all shadow-lg shadow-red-500/20 text-[10px] font-black uppercase tracking-widest">
                            Detach
                        </button>
                      </div>
                  </div>
              )}
          </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { GoogleGenAI } from "@google/genai";
import type { ThemeColors, CommunityPost, ModelType } from '../types';
import { BotIcon, SendIcon, UserIcon, ImageIcon, SparklesIcon } from './Icons';

export const CommunityView: React.FC<{ theme: ThemeColors, model: ModelType }> = ({ theme, model }) => {
    const [posts, setPosts] = useState<CommunityPost[]>([]);
    const [newPostContent, setNewPostContent] = useState('');
    const [isPublishing, setIsPublishing] = useState(false);
    const [safetyScanner, setSafetyScanner] = useState(false);
    const [error, setError] = useState<string | null>(null);
    const [replyingTo, setReplyingTo] = useState<string | null>(null);
    const [replyText, setReplyText] = useState('');
    const [following, setFollowing] = useState<string[]>([]);
    const [shareToast, setShareToast] = useState(false);

    useEffect(() => {
        const saved = localStorage.getItem('cognix_community_posts_v2');
        if (saved) setPosts(JSON.parse(saved));
        else setPosts([
            { 
                id: '1', 
                author: 'Cognix System', 
                authorId: 'sys',
                content: 'Welcome to the v2.0 Global Pulse! Share your thoughts, code, and discoveries. Everything is moderated by Cognix Guard.', 
                timestamp: Date.now(), 
                likedBy: ['sys'], 
                replies: [],
                type: 'text' 
            }
        ]);

        const savedFollows = localStorage.getItem('cognix_following');
        if (savedFollows) setFollowing(JSON.parse(savedFollows));
    }, []);

    useEffect(() => localStorage.setItem('cognix_community_posts_v2', JSON.stringify(posts)), [posts]);
    useEffect(() => localStorage.setItem('cognix_following', JSON.stringify(following)), [following]);

    const handlePublish = async () => {
        if (!newPostContent.trim()) return;
        setIsPublishing(true);
        setSafetyScanner(true);
        setError(null);

        try {
            const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
            const moderation = await ai.models.generateContent({
                model: 'gemini-3-flash-preview',
                contents: `GUARD PROTOCOL: Evaluate content for: Hate Speech, Explicit, Harassment. 
                CONTENT: "${newPostContent}"
                RESPOND WITH: "PASS" OR "FAIL: [REASON]"`,
            });

            const result = moderation.text?.trim() || "";
            if (result.startsWith('PASS')) {
                const newPost: CommunityPost = {
                    id: Date.now().toString(),
                    author: 'Neural User',
                    authorId: 'user_1',
                    content: newPostContent,
                    timestamp: Date.now(),
                    likedBy: [],
                    replies: [],
                    type: 'text'
                };
                setPosts(prev => [newPost, ...prev]);
                setNewPostContent('');
            } else {
                setError(`Cognix Guard Block: ${result.replace('FAIL:', '')}`);
            }
        } catch (e) {
            setError('Safety system offline. Check connectivity.');
        } finally {
            setIsPublishing(false);
            setSafetyScanner(false);
        }
    };

    const toggleLike = (postId: string) => {
        setPosts(prev => prev.map(p => {
            if (p.id === postId) {
                const liked = p.likedBy.includes('user_1');
                return { ...p, likedBy: liked ? p.likedBy.filter(id => id !== 'user_1') : [...p.likedBy, 'user_1'] };
            }
            return p;
        }));
    };

    const addReply = (postId: string) => {
        if (!replyText.trim()) return;
        setPosts(prev => prev.map(p => {
            if (p.id === postId) {
                return { 
                    ...p, 
                    replies: [...p.replies, { id: Date.now().toString(), author: 'You', content: replyText, timestamp: Date.now() }] 
                };
            }
            return p;
        }));
        setReplyText('');
        setReplyingTo(null);
    };

    const toggleFollow = (authorId: string) => {
        if (authorId === 'user_1') return;
        setFollowing(prev => prev.includes(authorId) ? prev.filter(id => id !== authorId) : [...prev, authorId]);
    };

    const handleShare = (postId: string) => {
        navigator.clipboard.writeText(`https://cognix.ai/pulse/${postId}`);
        setShareToast(true);
        setTimeout(() => setShareToast(false), 2000);
    };

    return (
        <div className="h-full overflow-y-auto bg-slate-50 dark:bg-slate-950 p-6 custom-scrollbar relative">
            <div className="max-w-3xl mx-auto space-y-10 pb-24">

                {/* AI Guard Scanner & Post Area */}
                <div className="bg-white dark:bg-slate-900 rounded-[3rem] p-10 shadow-2xl border border-slate-200 dark:border-slate-800 relative overflow-hidden group">
                    {safetyScanner && (
                        <div className="absolute inset-0 bg-blue-600 z-50 flex flex-col items-center justify-center animate-fade-in p-10 text-center">
                            <div className="relative w-20 h-20 mb-8">
                                <div className="absolute inset-0 bg-white/20 rounded-full animate-ping"></div>
                                <div className="absolute inset-2 border-4 border-white border-t-transparent rounded-full animate-spin"></div>
                                <BotIcon className="absolute inset-4 w-12 h-12 text-white" />
                            </div>
                            <h3 className="text-white font-black text-2xl tracking-tighter uppercase mb-3">Guard: Scanning</h3>
                            <p className="text-white/80 text-sm max-w-xs font-medium leading-relaxed">Cognix Intelligence is analyzing your content for community standards and neural safety.</p>
                        </div>
                    )}

                    <div className="flex items-center justify-between mb-8">
                        <div>
                            <h2 className="text-3xl font-black text-slate-900 dark:text-white tracking-tighter">Global Pulse.</h2>
                            <p className="text-xs font-bold text-slate-400 uppercase tracking-widest mt-1">Broadcast to the Neural Network</p>
                        </div>
                        <div className="flex flex-col items-end gap-1">
                            <div className="flex items-center gap-2 px-3 py-1 bg-green-500/10 rounded-full border border-green-500/20">
                                <span className="w-1.5 h-1.5 rounded-full bg-green-500 animate-pulse"></span>
                                <span className="text-[10px] font-bold text-green-500 uppercase tracking-[0.2em]">Scanner: Ready</span>
                            </div>
                        </div>
                    </div>

                    <textarea 
                        value={newPostContent}
                        onChange={(e) => setNewPostContent(e.target.value)}
                        placeholder="Broadcast your innovation or thoughts..."
                        className="w-full bg-slate-50 dark:bg-slate-800/40 border-none rounded-[2rem] p-8 min-h-[160px] outline-none text-slate-800 dark:text-slate-100 resize-none mb-8 text-xl font-medium transition-all focus:bg-white dark:focus:bg-slate-800 shadow-inner"
                    />

                    {error && (
                        <div className="mb-8 p-5 bg-red-500/10 border border-red-500/20 rounded-2xl animate-fade-in flex items-center gap-4">
                            <div className="w-10 h-10 rounded-full bg-red-500/20 flex items-center justify-center text-red-500 font-black text-lg shrink-0">!</div>
                            <div>
                                <p className="text-xs font-black text-red-500 uppercase tracking-widest mb-0.5">Publishing Inhibited</p>
                                <p className="text-xs text-red-500/80 font-medium">{error}</p>
                            </div>
                        </div>
                    )}

                    <div className="flex justify-between items-center">
                        <div className="flex gap-3">
                            <button className="p-4 text-slate-400 hover:bg-slate-100 dark:hover:bg-slate-800 rounded-2xl transition-all hover:scale-110"><ImageIcon className="w-6 h-6"/></button>
                            <button className="p-4 text-slate-400 hover:bg-slate-100 dark:hover:bg-slate-800 rounded-2xl transition-all hover:scale-110"><SparklesIcon className="w-6 h-6"/></button>
                        </div>
                        <button 
                            onClick={handlePublish}
                            disabled={isPublishing || !newPostContent.trim()}
                            className={`bg-gradient-to-r from-blue-600 to-indigo-600 text-white px-12 py-4 rounded-[2rem] font-black shadow-2xl shadow-blue-500/30 transition-all disabled:opacity-50 active:scale-95 flex items-center gap-4 hover:translate-y-[-2px]`}
                        >
                            Publish Broadcast
                            <SendIcon className="w-5 h-5" />
                        </button>
                    </div>
                </div>

                {/* Feed Section */}
                <div className="space-y-8">
                    {posts.map(post => (
                        <div key={post.id} className="bg-white dark:bg-slate-900 rounded-[3rem] p-10 shadow-2xl border border-slate-100 dark:border-slate-800 group animate-fade-in hover:border-blue-500/20 transition-all">
                            <div className="flex items-center justify-between mb-8">
                                <div className="flex items-center gap-5">
                                    <div className="w-14 h-14 rounded-3xl bg-gradient-to-tr from-slate-200 to-slate-100 dark:from-slate-800 dark:to-slate-700 flex items-center justify-center font-black text-slate-500 dark:text-slate-400 shadow-inner text-xl">
                                        {post.author[0]}
                                    </div>
                                    <div>
                                        <div className="flex items-center gap-3">
                                            <h4 className="font-black text-lg text-slate-900 dark:text-white tracking-tight">{post.author}</h4>
                                            {post.authorId === 'sys' && <div className="flex items-center gap-1.5 bg-blue-50 dark:bg-blue-900/30 text-blue-600 dark:text-blue-400 px-2 py-0.5 rounded-full text-[8px] font-black uppercase tracking-widest"><BotIcon className="w-3 h-3"/> Core</div>}
                                            {post.authorId !== 'user_1' && (
                                                <button 
                                                    onClick={() => toggleFollow(post.authorId)}
                                                    className={`text-[10px] font-black uppercase tracking-widest ml-2 px-3 py-1 rounded-full transition-all ${following.includes(post.authorId) ? 'bg-slate-100 dark:bg-slate-800 text-slate-500' : 'bg-blue-600 text-white shadow-lg shadow-blue-500/20'}`}
                                                >
                                                    {following.includes(post.authorId) ? 'Connected' : 'Connect'}
                                                </button>
                                            )}
                                        </div>
                                        <p className="text-[10px] text-slate-400 font-bold uppercase tracking-[0.2em] mt-1">{new Date(post.timestamp).toLocaleTimeString()} • Live Node</p>
                                    </div>
                                </div>
                            </div>

                            <p className="text-slate-800 dark:text-slate-200 whitespace-pre-wrap leading-relaxed mb-10 text-xl font-medium">{post.content}</p>

                            {/* Engagement Hub */}
                            <div className="flex items-center gap-10 border-t border-slate-50 dark:border-slate-800 pt-8">
                                <button 
                                    onClick={() => toggleLike(post.id)}
                                    className={`flex items-center gap-2.5 transition-all font-black text-sm ${post.likedBy.includes('user_1') ? 'text-rose-500' : 'text-slate-400 hover:text-rose-500'}`}
                                >
                                    <svg className={`w-7 h-7 transition-transform ${post.likedBy.includes('user_1') ? 'fill-current scale-110' : 'fill-none stroke-current'}`} viewBox="0 0 24 24" strokeWidth="2.5"><path strokeLinecap="round" strokeLinejoin="round" d="M4.318 6.318a4.5 4.5 0 000 6.364L12 20.364l7.682-7.682a4.5 4.5 0 00-6.364-6.364L12 7.636l-1.318-1.318a4.5 4.5 0 00-6.364 0z"/></svg>
                                    <span>{post.likedBy.length}</span>
                                </button>
                                <button 
                                    onClick={() => setReplyingTo(replyingTo === post.id ? null : post.id)}
                                    className={`flex items-center gap-2.5 transition-colors font-black text-sm ${replyingTo === post.id ? 'text-blue-500' : 'text-slate-400 hover:text-blue-500'}`}
                                >
                                    <svg className="w-7 h-7 fill-none stroke-current" strokeWidth="2.5" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" d="M8 12h.01M12 12h.01M16 12h.01M21 12c0 4.418-4.03 8-9 8a9.863 9.863 0 01-4.255-.949L3 20l1.395-3.72C3.512 15.042 3 13.574 3 12c0-4.418 4.03-8 9-8s9 3.582 9 8z"/></svg>
                                    <span>{post.replies.length}</span>
                                </button>
                                <button 
                                    onClick={() => handleShare(post.id)}
                                    className="flex items-center gap-2.5 text-slate-400 hover:text-emerald-500 transition-colors font-black text-sm"
                                >
                                    <svg className="w-7 h-7 fill-none stroke-current" strokeWidth="2.5" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" d="M8.684 13.342C8.886 12.938 9 12.482 9 12c0-.482-.114-.938-.316-1.342m0 2.684a3 3 0 110-2.684m0 2.684l6.632 3.316m-6.632-6l6.632-3.316m0 0a3 3 0 105.367-2.684 3 3 0 00-5.367 2.684zm0 9.316a3 3 0 105.368 2.684 3 3 0 00-5.368-2.684z"/></svg>
                                    <span>Share</span>
                                </button>
                            </div>

                            {/* Interactive Reply Area */}
                            {(post.replies.length > 0 || replyingTo === post.id) && (
                                <div className="mt-10 space-y-5 pt-8 border-t border-slate-50 dark:border-slate-800">
                                    {post.replies.map(reply => (
                                        <div key={reply.id} className="flex gap-5 p-5 rounded-[2rem] bg-slate-50 dark:bg-slate-800/40 border border-slate-100 dark:border-slate-700/50">
                                            <div className="w-10 h-10 rounded-2xl bg-slate-200 dark:bg-slate-700 flex items-center justify-center font-black text-sm text-slate-500 shrink-0">{reply.author[0]}</div>
                                            <div>
                                                <p className="font-black text-xs text-slate-900 dark:text-white mb-1.5 uppercase tracking-widest">{reply.author}</p>
                                                <p className="text-base text-slate-600 dark:text-slate-400 font-medium leading-relaxed">{reply.content}</p>
                                            </div>
                                        </div>
                                    ))}
                                    {replyingTo === post.id && (
                                        <div className="flex gap-4 items-center bg-slate-100 dark:bg-slate-800/80 p-2 rounded-[2rem] border border-slate-200 dark:border-slate-700">
                                            <input 
                                                autoFocus
                                                value={replyText}
                                                onChange={(e) => setReplyText(e.target.value)}
                                                onKeyDown={e => e.key === 'Enter' && addReply(post.id)}
                                                placeholder="Inject your perspective..."
                                                className="flex-1 bg-transparent px-6 py-4 outline-none text-base font-medium"
                                            />
                                            <button onClick={() => addReply(post.id)} className="w-12 h-12 bg-blue-600 text-white rounded-full flex items-center justify-center hover:bg-blue-700 shadow-xl shadow-blue-500/20 transition-all hover:scale-105 active:scale-95">
                                                <SendIcon className="w-5 h-5" />
                                            </button>
                                        </div>
                                    )}
                                </div>
                            )}
                        </div>
                    ))}
                </div>
            </div>

            {/* Notification Toast */}
            {shareToast && (
                <div className="fixed bottom-10 left-1/2 -translate-x-1/2 bg-emerald-600 text-white px-8 py-4 rounded-full font-black uppercase tracking-widest text-xs shadow-2xl animate-fade-in-up z-[100] flex items-center gap-3">
                    <div className="w-2 h-2 bg-white rounded-full animate-ping"></div>
                    Broadcast Link Decoupled to Clipboard
                </div>
            )}
        </div>
    );
};

import React, { useState, useEffect, useMemo } from 'react';
import { ChatView } from './components/ChatView';
import { LiveView } from './components/LiveView';
import { Sidebar } from './components/Sidebar';
import { FriendsView } from './components/FriendsView';
import { ToolboxView } from './components/ToolboxView';
import { MemoryView } from './components/MemoryView';
import { CommunityView } from './components/CommunityView';
import { CodingView } from './components/CodingView';
import { MenuIcon, UserIcon } from './components/Icons';
import { SettingsModal } from './components/SettingsModal';
import { GoogleGenAI } from "@google/genai";
import type { ChatMessage, ChatSession, Mode, UIStyle, AccentColor, ThemeColors, FontSize, Friend, ModelType } from './types';

const THEMES: Record<AccentColor, ThemeColors> = {
    blue: { primary: 'bg-blue-600', primaryHover: 'hover:bg-blue-700', text: 'text-blue-600', textDark: 'text-blue-400', bgSoft: 'bg-blue-50', darkBgSoft: 'dark:bg-blue-900/20', border: 'border-blue-600', ring: 'focus:ring-blue-600', gradient: 'bg-gradient-to-r from-blue-500 to-cyan-500' },
    violet: { primary: 'bg-violet-600', primaryHover: 'hover:bg-violet-700', text: 'text-violet-600', textDark: 'text-violet-400', bgSoft: 'bg-violet-50', darkBgSoft: 'dark:bg-violet-900/20', border: 'border-violet-600', ring: 'focus:ring-violet-600', gradient: 'bg-gradient-to-r from-violet-500 to-purple-500' },
    emerald: { primary: 'bg-emerald-600', primaryHover: 'hover:bg-emerald-700', text: 'text-emerald-600', textDark: 'text-emerald-400', bgSoft: 'bg-emerald-50', darkBgSoft: 'dark:bg-emerald-900/20', border: 'border-emerald-600', ring: 'focus:ring-emerald-600', gradient: 'bg-gradient-to-r from-emerald-500 to-teal-500' },
    rose: { primary: 'bg-rose-600', primaryHover: 'hover:bg-rose-700', text: 'text-rose-600', textDark: 'text-rose-400', bgSoft: 'bg-rose-50', darkBgSoft: 'dark:bg-rose-900/20', border: 'border-rose-600', ring: 'focus:ring-rose-600', gradient: 'bg-gradient-to-r from-rose-500 to-pink-500' },
    amber: { primary: 'bg-amber-600', primaryHover: 'hover:bg-amber-700', text: 'text-amber-600', textDark: 'text-amber-400', bgSoft: 'bg-amber-50', darkBgSoft: 'dark:bg-amber-900/20', border: 'border-amber-600', ring: 'focus:ring-amber-600', gradient: 'bg-gradient-to-r from-amber-500 to-orange-500' },
};

const App: React.FC = () => {
  const [mode, setMode] = useState<Mode>('chat');
  const [uiStyle, setUiStyle] = useState<UIStyle>('modern');
  const [accentColor, setAccentColor] = useState<AccentColor>('blue');
  const [fontSize, setFontSize] = useState<FontSize>('normal');
  const [activeModel, setActiveModel] = useState<ModelType>('gemini-2.5-flash-latest');
  const [systemInstruction, setSystemInstruction] = useState("You are Cognix AI, a highly intelligent personal assistant created by Shashwat Ranjan Jha. You are professional, witty, and extremely capable. You have access to real-time information via Google Search.");

  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [isDesktopSidebarOpen, setIsDesktopSidebarOpen] = useState(true);
  const [isDarkMode, setIsDarkMode] = useState(false);
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);

  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [chatHistory, setChatHistory] = useState<ChatSession[]>([]);
  const [activeChatId, setActiveChatId] = useState<string | null>(null);
  const [friends, setFriends] = useState<Friend[]>([]);

  useEffect(() => {
    const savedHistory = localStorage.getItem('cognix_v2_history');
    if (savedHistory) setChatHistory(JSON.parse(savedHistory));

    const savedFriends = localStorage.getItem('cognix_friends');
    if (savedFriends) setFriends(JSON.parse(savedFriends));

    const savedTheme = localStorage.getItem('cognix_theme');
    if (savedTheme === 'dark' || (!savedTheme && window.matchMedia('(prefers-color-scheme: dark)').matches)) {
      setIsDarkMode(true);
      document.documentElement.classList.add('dark');
    }
  }, []);

  useEffect(() => localStorage.setItem('cognix_v2_history', JSON.stringify(chatHistory)), [chatHistory]);
  useEffect(() => localStorage.setItem('cognix_friends', JSON.stringify(friends)), [friends]);

  useEffect(() => {
    if (isDarkMode) {
      document.documentElement.classList.add('dark');
      localStorage.setItem('cognix_theme', 'dark');
    } else {
      document.documentElement.classList.remove('dark');
      localStorage.setItem('cognix_theme', 'light');
    }
  }, [isDarkMode]);

  const currentChat = useMemo(() => chatHistory.find(c => c.id === activeChatId), [chatHistory, activeChatId]);
  const activeTheme = useMemo(() => THEMES[accentColor], [accentColor]);

  useEffect(() => {
    setMessages(currentChat ? currentChat.messages : []);
  }, [currentChat?.id]);

  const generateChatTitle = async (firstMessage: string) => {
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: `Generate a catchy, ultra-short (max 3 words) title for a conversation that starts with: "${firstMessage}". No quotes or period.`,
      });
      return response.text?.trim() || firstMessage.slice(0, 30);
    } catch (e) {
      return firstMessage.slice(0, 30);
    }
  };

  useEffect(() => {
    const updateHistory = async () => {
      if (messages.length === 1 && !activeChatId && messages[0].role === 'user') {
         const firstUserText = messages[0].parts.find(p => p.text)?.text || 'New Chat';
         const newId = Date.now().toString();
         const newTitle = await generateChatTitle(firstUserText);
         const newSession: ChatSession = { id: newId, title: newTitle, messages: messages };
         setChatHistory(prev => [newSession, ...prev]);
         setActiveChatId(newId);
      } else if (activeChatId && messages.length > 0) {
         setChatHistory(prev => prev.map(session => session.id === activeChatId ? { ...session, messages } : session));
      }
    };
    updateHistory();
  }, [messages, activeChatId]);

  const handleNewChat = () => {
    setActiveChatId(null);
    setMessages([]);
    setMode('chat');
    if (window.innerWidth < 1024) setIsSidebarOpen(false);
  };

  return (
    <div className={`flex h-[100dvh] overflow-hidden bg-slate-50 dark:bg-slate-950 transition-colors duration-300`}>

      <Sidebar 
        chatHistory={chatHistory}
        activeChatId={activeChatId}
        mode={mode}
        onSetMode={(m) => { setMode(m); if(window.innerWidth < 1024) setIsSidebarOpen(false); }}
        onSelectChat={(id) => { setActiveChatId(id); setMode('chat'); if(window.innerWidth < 1024) setIsSidebarOpen(false); }}
        onNewChat={handleNewChat}
        onDeleteChat={(id) => {
            setChatHistory(h => h.filter(c => c.id !== id));
            if (activeChatId === id) { setActiveChatId(null); setMessages([]); }
        }}
        onRenameChat={(id, t) => setChatHistory(h => h.map(c => c.id === id ? { ...c, title: t } : c))}
        onOpenSettings={() => setIsSettingsOpen(true)}
        isSidebarOpen={isSidebarOpen}
        isDesktopSidebarOpen={isDesktopSidebarOpen}
        theme={activeTheme}
        friends={friends}
      />

      {isSidebarOpen && <div className="fixed inset-0 bg-black/40 backdrop-blur-sm z-40 lg:hidden" onClick={() => setIsSidebarOpen(false)} />}

      <div className="flex-1 flex flex-col h-full min-w-0 bg-white dark:bg-slate-900 lg:rounded-l-[2.5rem] shadow-2xl relative">
        <header className="h-16 flex items-center justify-between px-8 shrink-0 z-30">
             <div className="flex items-center gap-4">
                <button onClick={() => window.innerWidth >= 1024 ? setIsDesktopSidebarOpen(!isDesktopSidebarOpen) : setIsSidebarOpen(!isSidebarOpen)} className="p-2 -ml-2 text-slate-500 hover:bg-slate-100 dark:hover:bg-slate-800 rounded-xl transition-colors">
                    <MenuIcon className="w-5 h-5"/>
                </button>
                <div className="flex flex-col">
                  <h1 className="text-sm font-black text-slate-800 dark:text-slate-100 flex items-center gap-2 tracking-tight">
                      {mode === 'chat' && (currentChat?.title || 'New Session')}
                      {mode === 'live' && 'Live Intelligence'}
                      {mode === 'community' && 'Global Pulse'}
                      {mode === 'coding' && 'DevStudio v1.0'}
                      {mode === 'toolbox' && 'Lab Toolbox'}
                      {mode === 'memory' && 'Vault'}
                      <div className="w-1.5 h-1.5 rounded-full bg-blue-500 animate-pulse"></div>
                  </h1>
                  <span className="text-[9px] text-slate-400 font-bold tracking-[0.2em] uppercase">Cognix Neural Engine</span>
                </div>
             </div>

             <div className="flex items-center gap-4">
                 <button onClick={() => setIsDarkMode(!isDarkMode)} className="p-2 text-slate-400 hover:text-slate-600 dark:hover:text-slate-200 transition-colors">
                     {isDarkMode ? <svg className="w-5 h-5" fill="currentColor" viewBox="0 0 20 20"><path d="M10 2a1 1 0 011 1v1a1 1 0 11-2 0V3a1 1 0 011-1zm4 8a4 4 0 11-8 0 4 4 0 018 0zm-.464 4.95l.707.707a1 1 0 001.414-1.414l-.707-.707a1 1 0 00-1.414 1.414zm2.12-10.607a1 1 0 010 1.414l-.706.707a1 1 0 11-1.414-1.414l.707-.707a1 1 0 011.414 0zM17 11a1 1 0 100-2h-1a1 1 0 100 2h1zm-7 4a1 1 0 011 1v1a1 1 0 11-2 0v-1a1 1 0 011-1zM5.05 6.464A1 1 0 106.465 5.05l-.708-.707a1 1 0 00-1.414 1.414l.707.707zm1.414 8.486l-.707.707a1 1 0 01-1.414-1.414l.707-.707a1 1 0 011.414 1.414zM4 11a1 1 0 100-2H3a1 1 0 000 2h1z"/></svg> : <svg className="w-5 h-5" fill="currentColor" viewBox="0 0 20 20"><path d="M17.293 13.293A8 8 0 016.707 2.707a8.001 8.001 0 1010.586 10.586z"/></svg>}
                 </button>
                 <button 
                    onClick={() => setIsSettingsOpen(true)}
                    className="flex items-center gap-2 p-1 pl-3 bg-slate-100 dark:bg-slate-800 rounded-full border border-slate-200 dark:border-slate-700 hover:border-blue-500 transition-all group"
                 >
                     <span className="text-[10px] font-black text-slate-500 group-hover:text-blue-500 transition-colors uppercase tracking-widest">Profile</span>
                     <div className="w-8 h-8 rounded-full bg-gradient-to-tr from-blue-600 to-indigo-600 flex items-center justify-center text-white">
                         <UserIcon className="w-5 h-5"/>
                     </div>
                 </button>
             </div>
        </header>

        <main className="flex-1 relative overflow-hidden">
             {mode === 'chat' && (
                <ChatView 
                    messages={messages} 
                    setMessages={setMessages}
                    uiStyle={uiStyle}
                    theme={activeTheme}
                    fontSize={fontSize}
                    systemInstruction={systemInstruction}
                    model={activeModel}
                    setActiveModel={setActiveModel}
                />
            )}
            {mode === 'live' && <LiveView theme={activeTheme} />}
            {mode === 'friends' && <FriendsView friends={friends} setFriends={setFriends} />}
            {mode === 'community' && <CommunityView theme={activeTheme} model={activeModel} />}
            {mode === 'coding' && <CodingView theme={activeTheme} model={activeModel} />}
            {mode === 'toolbox' && <ToolboxView theme={activeTheme} model={activeModel} />}
            {mode === 'memory' && <MemoryView theme={activeTheme} />}
        </main>
      </div>

      <SettingsModal 
        isOpen={isSettingsOpen} onClose={() => setIsSettingsOpen(false)}
        uiStyle={uiStyle} setUiStyle={setUiStyle}
        accentColor={accentColor} setAccentColor={setAccentColor}
        fontSize={fontSize} setFontSize={setFontSize}
        isDarkMode={isDarkMode} setIsDarkMode={setIsDarkMode}
        onClearHistory={() => { setChatHistory([]); setMessages([]); setActiveChatId(null); setIsSettingsOpen(false); }}
        systemInstruction={systemInstruction} setSystemInstruction={setSystemInstruction}
      />
    </div>
  );
}

export default App;

import React, { useState, useRef, useEffect, useCallback } from 'react';
import type { ChatMessage, ChatPart, SearchResult, UIStyle, ThemeColors, FontSize, ModelType } from '../types';
import { GoogleGenAI } from "@google/genai";
import { BotIcon, SendIcon, UserIcon, ImageIcon, SpeakerIcon, CopyIcon, SearchIcon, SparklesIcon } from './Icons';

interface ChatViewProps {
  messages: ChatMessage[];
  setMessages: React.Dispatch<React.SetStateAction<ChatMessage[]>>;
  uiStyle: UIStyle;
  theme: ThemeColors;
  fontSize: FontSize;
  systemInstruction: string;
  model: ModelType;
  setActiveModel: (m: ModelType) => void;
}

const SourceCard: React.FC<{ result: SearchResult }> = ({ result }) => (
    <a 
        href={result.uri} 
        target="_blank" 
        rel="noopener noreferrer"
        className="flex items-center gap-3 p-3 bg-white/50 dark:bg-slate-800/50 backdrop-blur-sm border border-slate-200 dark:border-slate-700 rounded-2xl hover:border-blue-500 dark:hover:border-blue-400 transition-all group shrink-0 max-w-[220px] shadow-sm"
    >
        <div className="w-10 h-10 rounded-xl bg-blue-100 dark:bg-blue-900/40 flex items-center justify-center shrink-0">
            <SearchIcon className="w-5 h-5 text-blue-600 dark:text-blue-400" />
        </div>
        <div className="flex-1 min-w-0">
            <p className="text-xs font-bold text-slate-900 dark:text-slate-100 truncate">{result.title}</p>
            <p className="text-[10px] text-slate-400 truncate uppercase tracking-tight">{new URL(result.uri).hostname}</p>
        </div>
    </a>
);

export const ChatView: React.FC<ChatViewProps> = ({ messages, setMessages, theme, systemInstruction, model, setActiveModel }) => {
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [selectedImage, setSelectedImage] = useState<{ data: string; mimeType: string } | null>(null);
  const [webSearchEnabled, setWebSearchEnabled] = useState(true);
  const [isModelDropdownOpen, setIsModelDropdownOpen] = useState(false);

  const chatContainerRef = useRef<HTMLDivElement>(null);
  const textareaRef = useRef<HTMLTextAreaElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (chatContainerRef.current) chatContainerRef.current.scrollTop = chatContainerRef.current.scrollHeight;
  }, [messages, isLoading, selectedImage]);

  const formatOutput = (text: string) => {
    return text.replace(/\*/g, '');
  };

  const handleSendMessage = useCallback(async (textOverride?: string) => {
    const textInput = (textOverride || input).trim();
    if ((!textInput && !selectedImage) || isLoading) return;

    const userMessageParts: ChatPart[] = [];
    if (selectedImage) userMessageParts.push({ inlineData: { mimeType: selectedImage.mimeType, data: selectedImage.data } });
    if (textInput) userMessageParts.push({ text: textInput });

    const userMessage: ChatMessage = { id: `msg-${Date.now()}`, role: 'user', parts: userMessageParts };
    const modelPlaceholder: ChatMessage = { id: `msg-${Date.now() + 1}`, role: 'model', parts: [{ text: '' }], isSearching: webSearchEnabled };

    setMessages(prev => [...prev, userMessage, modelPlaceholder]);
    setInput(''); 
    setSelectedImage(null);
    setIsLoading(true);

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const history = messages.map(msg => ({
        role: msg.role,
        parts: msg.parts.map(p => {
            if (p.text) return { text: p.text };
            if (p.inlineData) return { inlineData: p.inlineData };
            return null;
        }).filter(Boolean) as any[]
      }));

      let finalModelName = model === 'cognix-arc-1.0' ? 'gemini-3-pro-preview' : model;
      let modelSpecificInstruction = systemInstruction;

      if (model === 'gemini-2.5-flash-latest') {
          modelSpecificInstruction += " IMPORTANT: Use relevant emojis to make your responses engaging and friendly. NEVER use asterisks (*) for formatting. Always respond in clear, professional paragraphs.";
      } else if (model === 'cognix-arc-1.0') {
          modelSpecificInstruction = "You are CognixArc 1.0, an advanced high-reasoning engine. You are efficient, creative, and highly accurate. Do not use asterisks (*) for formatting. Use emojis sparingly.";
      } else {
          modelSpecificInstruction += " Do not use asterisks (*) for formatting.";
      }

      let stream = await ai.models.generateContentStream({
          model: finalModelName as any,
          contents: [...history, { role: 'user', parts: userMessageParts as any }],
          config: { 
              systemInstruction: modelSpecificInstruction, 
              tools: webSearchEnabled ? [{ googleSearch: {} }] : [],
              temperature: model === 'gemini-2.5-flash-latest' ? 0.9 : 0.7 
          },
      });

      let fullText = '';
      let searchResults: SearchResult[] = [];

      for await (const chunk of stream) {
        if(chunk.text) {
            fullText += chunk.text;
            const cleanText = formatOutput(fullText);
            setMessages(prev => prev.map(m => m.id === modelPlaceholder.id ? { ...m, parts: [{ text: cleanText }], isSearching: false } : m));
        }
        const chunks = chunk.candidates?.[0]?.groundingMetadata?.groundingChunks;
        if (chunks) {
            const results = chunks.map((c: any) => c.web ? { ...c.web, type: 'web' } : null).filter(Boolean);
            searchResults = [...searchResults, ...results];
        }
      }

      if (searchResults.length > 0) {
        const unique = Array.from(new Map(searchResults.map(i => [i.uri, i])).values());
        setMessages(prev => prev.map(m => m.id === modelPlaceholder.id ? { ...m, parts: [{ ...m.parts[0], searchResults: unique }] } : m));
      }
    } catch (error) {
      setMessages(prev => prev.map(m => m.id === modelPlaceholder.id ? { ...m, parts: [{ text: `System Error: ${error instanceof Error ? error.message : "Unknown connectivity issue."}` }], isSearching: false } : m));
    } finally {
      setIsLoading(false);
    }
  }, [input, isLoading, messages, selectedImage, systemInstruction, model, webSearchEnabled]);

  const adjustTextareaHeight = () => {
    if (textareaRef.current) {
      textareaRef.current.style.height = 'auto';
      textareaRef.current.style.height = `${Math.min(textareaRef.current.scrollHeight, 240)}px`;
    }
  };

  useEffect(() => {
    adjustTextareaHeight();
  }, [input]);

  return (
    <div className="flex flex-col h-full bg-white dark:bg-slate-900 relative">
      <div ref={chatContainerRef} className="flex-1 overflow-y-auto px-4 pb-64 pt-8 custom-scrollbar">
        {messages.length === 0 ? (
            <div className="max-w-4xl mx-auto flex flex-col items-center justify-center min-h-[60vh] text-center px-4">
                 <div className="relative mb-10">
                     <div className="absolute inset-0 bg-blue-500/10 rounded-full blur-3xl animate-pulse"></div>
                     <BotIcon className="relative w-24 h-24 drop-shadow-2xl animate-float" />
                 </div>
                 <h2 className="text-5xl font-black text-slate-900 dark:text-white mb-4 tracking-tighter">Command Intelligence.</h2>
                 <p className="text-slate-500 dark:text-slate-400 max-w-lg mb-12 text-xl font-medium leading-relaxed">
                    Personalized high-bandwidth AI built by Shashwat Ranjan Jha.
                 </p>

                 <div className="grid grid-cols-1 md:grid-cols-2 gap-4 w-full">
                     {[
                         { t: "Neural Creation", q: "Generate a hyper-realistic image of a cybernetic tiger in a neon rainforest", icon: <ImageIcon className="w-5 h-5"/> },
                         { t: "Deep Synthesis", q: "Explain the philosophy of simulated realities through modern physics", icon: <SparklesIcon className="w-5 h-5"/> }
                     ].map((item, i) => (
                        <button 
                            key={i} 
                            onClick={() => handleSendMessage(item.q)}
                            className="text-left p-6 rounded-[2rem] border border-slate-200 dark:border-slate-800 hover:border-blue-500 dark:hover:border-blue-500/50 hover:bg-slate-50 dark:hover:bg-slate-800/50 transition-all group flex gap-5 items-center"
                        >
                            <div className="w-12 h-12 rounded-2xl bg-slate-100 dark:bg-slate-800 flex items-center justify-center shrink-0 group-hover:bg-blue-600 group-hover:text-white transition-all">
                                {item.icon}
                            </div>
                            <div>
                                <p className="font-black text-slate-900 dark:text-white group-hover:text-blue-600 transition-colors text-base">{item.t}</p>
                                <p className="text-[10px] text-slate-400 font-bold uppercase tracking-widest mt-0.5">Quick Command</p>
                            </div>
                        </button>
                     ))}
                 </div>
            </div>
        ) : (
            <div className="max-w-4xl mx-auto space-y-12">
                {messages.map((msg) => (
                    <div key={msg.id} className={`flex gap-6 group ${msg.role === 'user' ? 'flex-row-reverse' : 'flex-row'}`}>
                        <div className={`w-10 h-10 shrink-0 rounded-2xl flex items-center justify-center shadow-xl
                            ${msg.role === 'user' ? 'bg-slate-100 dark:bg-slate-800 text-slate-500 border border-slate-200 dark:border-slate-700' : 'bg-gradient-to-tr from-blue-600 to-indigo-600 text-white'}
                        `}>
                             {msg.role === 'user' ? <UserIcon className="w-6 h-6"/> : <BotIcon className="w-7 h-7"/>}
                        </div>

                        <div className={`flex flex-col gap-3 max-w-[85%] ${msg.role === 'user' ? 'items-end' : 'items-start'}`}>
                             {msg.parts.map((part, i) => (
                                 <div key={i} className={`relative leading-relaxed text-base transition-all
                                     ${msg.role === 'user' 
                                         ? 'bg-blue-600 text-white px-6 py-4 rounded-[2rem] rounded-tr-sm shadow-xl shadow-blue-500/20 font-medium' 
                                         : 'text-slate-800 dark:text-slate-100 px-1'}
                                 `}>
                                     {part.inlineData && <img src={`data:${part.inlineData.mimeType};base64,${part.inlineData.data}`} className="rounded-[2rem] mb-6 max-h-[500px] shadow-2xl border border-slate-200 dark:border-slate-800 object-contain" alt="Upload"/>}

                                     {msg.isSearching && i === 0 && (
                                         <div className="flex items-center gap-3 text-blue-500 mb-6 animate-pulse-soft bg-blue-50 dark:bg-blue-900/20 px-4 py-2 rounded-full border border-blue-500/20 w-fit">
                                             <div className="w-4 h-4 border-2 border-blue-500 border-t-transparent rounded-full animate-spin"></div>
                                             <span className="text-[10px] font-black uppercase tracking-[0.2em]">Synchronizing Web Data...</span>
                                         </div>
                                     )}

                                     <div className="whitespace-pre-wrap prose dark:prose-invert max-w-none text-lg leading-relaxed">{part.text}</div>

                                     {part.searchResults && part.searchResults.length > 0 && (
                                         <div className="mt-10">
                                            <p className="text-[10px] font-black text-slate-400 uppercase tracking-[0.3em] mb-4 flex items-center gap-3">
                                                Grounding Node <span className="h-px bg-slate-200 dark:bg-slate-800 flex-1"></span>
                                            </p>
                                            <div className="flex gap-4 overflow-x-auto pb-4 no-scrollbar">
                                                {part.searchResults.map((res, idx) => <SourceCard key={idx} result={res} />)}
                                            </div>
                                         </div>
                                     )}
                                 </div>
                             ))}
                        </div>
                    </div>
                ))}
            </div>
        )}
      </div>

      {/* RE-DESIGNED PREMIUM INPUT BAR */}
      <div className="absolute bottom-0 left-0 right-0 px-6 pb-12 pt-10 bg-gradient-to-t from-white dark:from-slate-900 via-white/95 dark:via-slate-900/95 to-transparent pointer-events-none">
          <div className="max-w-4xl mx-auto relative group pointer-events-auto">

              {/* Outer Input Container */}
              <div className="bg-white dark:bg-slate-800/80 backdrop-blur-3xl rounded-[2.5rem] shadow-[0_30px_70px_-15px_rgba(0,0,0,0.2)] dark:shadow-[0_40px_100px_-20px_rgba(0,0,0,0.6)] border border-slate-200/50 dark:border-slate-700/50 transition-all focus-within:ring-4 ring-blue-500/10 overflow-hidden">

                   {/* Top Control Bar inside Input */}
                   <div className="flex items-center justify-between px-6 pt-4 pb-2 border-b border-slate-100/50 dark:border-slate-700/30">
                       <div className="flex items-center gap-4 relative">
                           {/* Model Pill Selection - Matching Image Request */}
                           <div className="relative">
                                <button 
                                    onClick={() => setIsModelDropdownOpen(!isModelDropdownOpen)}
                                    className="flex items-center gap-2.5 px-4 py-2 bg-slate-900 dark:bg-slate-950 text-white rounded-full hover:bg-black transition-all shadow-md active:scale-95"
                                >
                                    <span className="text-[11px] font-black tracking-tight uppercase">
                                        {model === 'gemini-2.5-flash-latest' ? 'Smart' : 'Arc 1.0'}
                                    </span>
                                    <svg className={`w-3.5 h-3.5 transition-transform ${isModelDropdownOpen ? 'rotate-180' : ''}`} fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M19 9l-7 7-7-7"/></svg>
                                </button>

                                {isModelDropdownOpen && (
                                    <div className="absolute top-full left-0 mt-2 w-48 bg-slate-900 text-white rounded-2xl shadow-2xl border border-white/10 z-[100] overflow-hidden animate-fade-in">
                                        {[
                                            { id: 'gemini-2.5-flash-latest', label: 'Smart', desc: 'Fast, emoji-friendly' },
                                            { id: 'cognix-arc-1.0', label: 'Arc 1.0', desc: 'Complex reasoning' }
                                        ].map(m => (
                                            <button 
                                                key={m.id}
                                                onClick={() => { setActiveModel(m.id as any); setIsModelDropdownOpen(false); }}
                                                className="w-full text-left px-5 py-3.5 hover:bg-white/10 transition-colors border-b border-white/5 last:border-none"
                                            >
                                                <p className="text-xs font-black tracking-widest uppercase">{m.label}</p>
                                                <p className="text-[9px] text-white/50 font-medium uppercase tracking-tighter mt-0.5">{m.desc}</p>
                                            </button>
                                        ))}
                                    </div>
                                )}
                           </div>

                           <button 
                                onClick={() => setWebSearchEnabled(!webSearchEnabled)}
                                className={`flex items-center gap-2 px-4 py-2 rounded-full border transition-all ${webSearchEnabled ? 'bg-blue-600 border-blue-600 text-white shadow-lg' : 'bg-slate-50 dark:bg-slate-900 border-slate-200 dark:border-slate-700 text-slate-400'}`}
                            >
                                <SearchIcon className="w-3.5 h-3.5" />
                                <span className="text-[10px] font-black uppercase tracking-widest">Web Grounding</span>
                            </button>
                       </div>

                       <div className="flex gap-2">
                           <button className="p-2 text-slate-400 hover:text-blue-500 transition-colors"><SparklesIcon className="w-4 h-4"/></button>
                       </div>
                   </div>

                   {/* Main Textarea Area */}
                   <div className="p-4 flex items-end gap-3">
                        <button 
                            onClick={() => fileInputRef.current?.click()} 
                            className="p-3.5 mb-1 rounded-2xl text-slate-400 hover:bg-blue-50 dark:hover:bg-blue-900/20 hover:text-blue-600 transition-all group"
                        >
                            <ImageIcon className="w-6 h-6"/>
                            <input type="file" ref={fileInputRef} onChange={(e) => {
                                    const file = e.target.files?.[0];
                                    if (file) {
                                        const reader = new FileReader();
                                        reader.onloadend = () => {
                                            setSelectedImage({ data: (reader.result as string).split(',')[1], mimeType: file.type });
                                        };
                                        reader.readAsDataURL(file);
                                    }
                            }} accept="image/*" className="hidden" />
                        </button>

                        <textarea
                            ref={textareaRef}
                            value={input}
                            onChange={e => setInput(e.target.value)}
                            onKeyDown={e => e.key === 'Enter' && !e.shiftKey && (e.preventDefault(), handleSendMessage())}
                            placeholder="Ask Cognix anything..."
                            className="flex-1 bg-transparent border-none outline-none resize-none py-4 px-2 text-slate-900 dark:text-white placeholder-slate-400 dark:placeholder-slate-500 text-lg font-medium leading-relaxed max-h-60"
                            rows={1}
                        />

                        <button 
                            onClick={() => handleSendMessage()} 
                            disabled={isLoading || (!input && !selectedImage)} 
                            className={`p-5 mb-1 rounded-3xl text-white transition-all duration-500 transform active:scale-95 disabled:opacity-30 flex items-center justify-center
                                ${input || selectedImage ? 'bg-blue-600 shadow-xl shadow-blue-500/20 hover:bg-blue-700' : 'bg-slate-100 dark:bg-slate-700 text-slate-300'}
                            `}
                        >
                            {isLoading ? (
                                <div className="w-6 h-6 border-2 border-white border-t-transparent rounded-full animate-spin"></div>
                            ) : (
                                <SendIcon className="w-6 h-6"/>
                            )}
