                   </div>
              </div>

              {selectedImage && (
                  <div className="absolute -top-28 left-4 p-3 bg-white dark:bg-slate-800 rounded-[2rem] shadow-2xl border border-slate-200 dark:border-slate-700 flex items-center gap-4 animate-fade-in group pointer-events-auto">
                      <div className="relative overflow-hidden rounded-2xl w-20 h-20">
                        <img src={`data:${selectedImage.mimeType};base64,${selectedImage.data}`} className="w-full h-full object-cover" />
                      </div>
                      <button onClick={() => setSelectedImage(null)} className="p-2 bg-red-500 text-white rounded-full hover:bg-red-600 transition-all shadow-lg">
                          <svg className="w-4 h-4" fill="currentColor" viewBox="0 0 20 20"><path d="M4.293 4.293a1 1 0 011.414 0L10 8.586l4.293-4.293a1 1 0 111.414 1.414L11.414 10l4.293 4.293a1 1 0 01-1.414 1.414L10 11.414l-4.293 4.293a1 1 0 01-1.414-1.414L8.586 10 4.293 5.707a1 1 0 010-1.414z"/></svg>
                      </button>
                  </div>
              )}
          </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { GoogleGenAI } from "@google/genai";
import type { ThemeColors, CommunityPost, ModelType } from '../types';
import { BotIcon, SendIcon, UserIcon, ImageIcon, SparklesIcon } from './Icons';

export const CommunityView: React.FC<{ theme: ThemeColors, model: ModelType }> = ({ theme, model }) => {
    const [posts, setPosts] = useState<CommunityPost[]>([]);
    const [newPostContent, setNewPostContent] = useState('');
    const [isPublishing, setIsPublishing] = useState(false);
    const [safetyScanner, setSafetyScanner] = useState(false);
    const [error, setError] = useState<string | null>(null);
    const [replyingTo, setReplyingTo] = useState<string | null>(null);
    const [replyText, setReplyText] = useState('');
    const [following, setFollowing] = useState<string[]>([]);
    const [shareToast, setShareToast] = useState(false);

    useEffect(() => {
        const saved = localStorage.getItem('cognix_community_posts_v2');
        if (saved) setPosts(JSON.parse(saved));
        else setPosts([
            { 
                id: '1', 
                author: 'Cognix System', 
                authorId: 'sys',
                content: 'Welcome to the v2.5 Neural Feed! Share your research, code, and discoveries. Moderated by Cognix Neural Guard.', 
                timestamp: Date.now(), 
                likedBy: ['sys', '123'], 
                replies: [],
                type: 'text' 
            }
        ]);

        const savedFollows = localStorage.getItem('cognix_following');
        if (savedFollows) setFollowing(JSON.parse(savedFollows));
    }, []);

    useEffect(() => localStorage.setItem('cognix_community_posts_v2', JSON.stringify(posts)), [posts]);
    useEffect(() => localStorage.setItem('cognix_following', JSON.stringify(following)), [following]);

    const handlePublish = async () => {
        if (!newPostContent.trim()) return;
        setIsPublishing(true);
        setSafetyScanner(true);
        setError(null);

        try {
            const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
            const moderation = await ai.models.generateContent({
                model: 'gemini-3-flash-preview',
                contents: `GUARD PROTOCOL: Evaluate content for: Hate Speech, Explicit, Harassment. 
                CONTENT: "${newPostContent}"
                RESPOND WITH: "PASS" OR "FAIL: [REASON]"`,
            });

            const result = moderation.text?.trim() || "";
            if (result.startsWith('PASS')) {
                const newPost: CommunityPost = {
                    id: Date.now().toString(),
                    author: 'Neural User',
                    authorId: 'user_1',
                    content: newPostContent,
                    timestamp: Date.now(),
                    likedBy: [],
                    replies: [],
                    type: 'text'
                };
                setPosts(prev => [newPost, ...prev]);
                setNewPostContent('');
            } else {
                setError(`Cognix Guard Block: ${result.replace('FAIL:', '')}`);
            }
        } catch (e) {
            setError('Safety system offline.');
        } finally {
            setIsPublishing(false);
            setSafetyScanner(false);
        }
    };

    const toggleLike = (postId: string) => {
        setPosts(prev => prev.map(p => {
            if (p.id === postId) {
                const liked = p.likedBy.includes('user_1');
                return { ...p, likedBy: liked ? p.likedBy.filter(id => id !== 'user_1') : [...p.likedBy, 'user_1'] };
            }
            return p;
        }));
    };

    const addReply = (postId: string) => {
        if (!replyText.trim()) return;
        setPosts(prev => prev.map(p => {
            if (p.id === postId) {
                return { 
                    ...p, 
                    replies: [...p.replies, { id: Date.now().toString(), author: 'You', content: replyText, timestamp: Date.now() }] 
                };
            }
            return p;
        }));
        setReplyText('');
        setReplyingTo(null);
    };

    const toggleFollow = (authorId: string) => {
        if (authorId === 'user_1') return;
        setFollowing(prev => prev.includes(authorId) ? prev.filter(id => id !== authorId) : [...prev, authorId]);
    };

    const handleShare = (postId: string) => {
        navigator.clipboard.writeText(`https://cognix.ai/pulse/${postId}`);
        setShareToast(true);
        setTimeout(() => setShareToast(false), 2000);
    };

    return (
        <div className="h-full overflow-y-auto bg-slate-50 dark:bg-slate-950 p-6 custom-scrollbar relative">
            <div className="max-w-4xl mx-auto space-y-6 pb-32">

                {/* Compact Posting Area */}
                <div className="bg-white dark:bg-slate-900 rounded-2xl p-6 shadow-lg border border-slate-200 dark:border-slate-800 relative overflow-hidden">
                    {safetyScanner && (
                        <div className="absolute inset-0 bg-blue-600/90 backdrop-blur-sm z-50 flex items-center justify-center animate-fade-in p-6 text-center">
                            <BotIcon className="w-10 h-10 text-white animate-spin-slow mr-4" />
                            <h3 className="text-white font-black text-lg tracking-tight uppercase">Neural Scanning...</h3>
                        </div>
                    )}

                    <div className="flex gap-4">
                         <div className="w-10 h-10 rounded-full bg-slate-100 dark:bg-slate-800 flex items-center justify-center font-black text-slate-500">U</div>
                         <textarea 
                            value={newPostContent}
                            onChange={(e) => setNewPostContent(e.target.value)}
                            placeholder="Create a new broadcast..."
                            className="flex-1 bg-slate-50 dark:bg-slate-800/50 border border-slate-200 dark:border-slate-700 rounded-xl p-4 min-h-[100px] outline-none text-slate-800 dark:text-slate-100 resize-none font-medium"
                        />
                    </div>

                    {error && <p className="mt-3 text-xs font-bold text-red-500 uppercase tracking-widest">{error}</p>}

                    <div className="flex justify-end items-center mt-4 gap-4">
                        <button className="text-slate-400 hover:text-blue-500"><ImageIcon className="w-5 h-5"/></button>
                        <button 
                            onClick={handlePublish}
                            disabled={isPublishing || !newPostContent.trim()}
                            className="bg-blue-600 text-white px-8 py-2.5 rounded-full font-black text-xs uppercase tracking-[0.2em] shadow-lg shadow-blue-500/20 active:scale-95 disabled:opacity-50"
                        >
                            Publish
                        </button>
                    </div>
                </div>

                {/* Reddit Style Feed */}
                <div className="space-y-4">
                    {posts.map(post => (
                        <div key={post.id} className="flex bg-white dark:bg-slate-900 rounded-xl border border-slate-200 dark:border-slate-800 hover:border-slate-300 dark:hover:border-slate-700 transition-colors shadow-sm overflow-hidden group">

                            {/* Vote Column */}
                            <div className="w-12 bg-slate-50 dark:bg-slate-900/50 flex flex-col items-center py-4 gap-1">
                                <button onClick={() => toggleLike(post.id)} className={`p-1 rounded hover:bg-slate-200 dark:hover:bg-slate-800 ${post.likedBy.includes('user_1') ? 'text-blue-600' : 'text-slate-400'}`}>
                                    <svg className="w-5 h-5" fill="none" stroke="currentColor" strokeWidth="3" viewBox="0 0 24 24"><path d="M5 15l7-7 7 7"/></svg>
                                </button>
                                <span className={`text-[11px] font-black ${post.likedBy.includes('user_1') ? 'text-blue-600' : 'text-slate-500'}`}>{post.likedBy.length}</span>
                                <button className="p-1 rounded hover:bg-slate-200 dark:hover:bg-slate-800 text-slate-400">
                                    <svg className="w-5 h-5" fill="none" stroke="currentColor" strokeWidth="3" viewBox="0 0 24 24"><path d="M19 9l-7 7-7-7"/></svg>
                                </button>
                            </div>

                            {/* Content Column */}
                            <div className="flex-1 p-4">
                                <div className="flex items-center gap-2 mb-2">
                                    <span className="text-[10px] font-black text-slate-900 dark:text-white uppercase tracking-widest">c/NeuralNetwork</span>
                                    <span className="text-[10px] text-slate-400">•</span>
                                    <span className="text-[10px] text-slate-400 font-bold">Posted by {post.author}</span>
                                    {post.authorId !== 'user_1' && (
                                        <button onClick={() => toggleFollow(post.authorId)} className="text-[10px] font-bold text-blue-500 hover:underline">Connect</button>
                                    )}
                                    <span className="text-[10px] text-slate-400 font-bold ml-auto">{new Date(post.timestamp).toLocaleTimeString()}</span>
                                </div>

                                <p className="text-slate-800 dark:text-slate-200 text-lg font-medium leading-relaxed mb-6">{post.content}</p>

                                <div className="flex items-center gap-6">
                                    <button 
                                        onClick={() => setReplyingTo(replyingTo === post.id ? null : post.id)}
                                        className="flex items-center gap-1.5 text-[10px] font-black uppercase text-slate-400 hover:bg-slate-100 dark:hover:bg-slate-800 px-2 py-1.5 rounded-md transition-all"
                                    >
                                        <svg className="w-4 h-4" fill="none" stroke="currentColor" strokeWidth="2.5" viewBox="0 0 24 24"><path d="M8 12h.01M12 12h.01M16 12h.01M21 12c0 4.418-4.03 8-9 8a9.863 9.863 0 01-4.255-.949L3 20l1.395-3.72C3.512 15.042 3 13.574 3 12c0-4.418 4.03-8 9-8s9 3.582 9 8z"/></svg>
                                        {post.replies.length} Perspectives
                                    </button>
                                    <button onClick={() => handleShare(post.id)} className="flex items-center gap-1.5 text-[10px] font-black uppercase text-slate-400 hover:bg-slate-100 dark:hover:bg-slate-800 px-2 py-1.5 rounded-md transition-all">
                                        <svg className="w-4 h-4" fill="none" stroke="currentColor" strokeWidth="2.5" viewBox="0 0 24 24"><path d="M8.684 13.342C8.886 12.938 9 12.482 9 12c0-.482-.114-.938-.316-1.342m0 2.684a3 3 0 110-2.684m0 2.684l6.632 3.316m-6.632-6l6.632-3.316m0 0a3 3 0 105.367-2.684 3 3 0 00-5.367 2.684zm0 9.316a3 3 0 105.368 2.684 3 3 0 00-5.368-2.684z"/></svg>
                                        Share Broadcast
                                    </button>
                                </div>

                                {/* Replies - Simple Thread Style */}
                                {(post.replies.length > 0 || replyingTo === post.id) && (
                                    <div className="mt-6 pl-4 border-l-2 border-slate-100 dark:border-slate-800 space-y-4">
                                        {post.replies.map(reply => (
                                            <div key={reply.id} className="text-xs">
                                                <p className="font-black text-slate-400 uppercase tracking-tighter mb-1">{reply.author} • <span className="font-bold opacity-50">Just now</span></p>
                                                <p className="text-slate-600 dark:text-slate-400 font-medium leading-relaxed">{reply.content}</p>
                                            </div>
                                        ))}
                                        {replyingTo === post.id && (
                                            <div className="flex gap-2">
                                                <input 
                                                    autoFocus
                                                    value={replyText}
                                                    onChange={(e) => setReplyText(e.target.value)}
                                                    onKeyDown={e => e.key === 'Enter' && addReply(post.id)}
                                                    placeholder="Inject perspective..."
                                                    className="flex-1 bg-slate-50 dark:bg-slate-800 rounded-lg px-4 py-2 text-xs outline-none border border-slate-200 dark:border-slate-700"
                                                />
                                                <button onClick={() => addReply(post.id)} className="bg-blue-600 text-white px-4 py-2 rounded-lg text-[10px] font-black uppercase">Send</button>
                                            </div>
                                        )}
                                    </div>
                                )}
                            </div>
                        </div>
                    ))}
                </div>
            </div>

            {shareToast && (
                <div className="fixed bottom-10 left-1/2 -translate-x-1/2 bg-emerald-600 text-white px-8 py-3 rounded-full font-black uppercase tracking-widest text-[10px] shadow-2xl animate-fade-in-up z-[100]">
                    Broadcast Link Synchronized to Clipboard
                </div>
            )}
        </div>
    );
};

import React, { useState, useRef, useEffect, useCallback } from 'react';
import type { ChatMessage, ChatPart, SearchResult, UIStyle, ThemeColors, FontSize, ModelType } from '../types';
import { GoogleGenAI } from "@google/genai";
import { BotIcon, SendIcon, UserIcon, ImageIcon, SpeakerIcon, CopyIcon, SearchIcon, SparklesIcon } from './Icons';

interface ChatViewProps {
  messages: ChatMessage[];
  setMessages: React.Dispatch<React.SetStateAction<ChatMessage[]>>;
  uiStyle: UIStyle;
  theme: ThemeColors;
  fontSize: FontSize;
  systemInstruction: string;
  model: ModelType;
  setActiveModel: (m: ModelType) => void;
}

const SourceCard: React.FC<{ result: SearchResult }> = ({ result }) => (
    <a 
        href={result.uri} 
        target="_blank" 
        rel="noopener noreferrer"
        className="flex items-center gap-3 p-3 bg-white/50 dark:bg-slate-800/50 backdrop-blur-sm border border-slate-200 dark:border-slate-700 rounded-2xl hover:border-blue-500 dark:hover:border-blue-400 transition-all group shrink-0 max-w-[200px] shadow-sm"
    >
        <div className="w-8 h-8 rounded-lg bg-blue-100 dark:bg-blue-900/40 flex items-center justify-center shrink-0">
            <SearchIcon className="w-4 h-4 text-blue-600 dark:text-blue-400" />
        </div>
        <div className="flex-1 min-w-0">
            <p className="text-[11px] font-bold text-slate-900 dark:text-slate-100 truncate">{result.title}</p>
            <p className="text-[9px] text-slate-400 truncate uppercase tracking-tight">{new URL(result.uri).hostname}</p>
        </div>
    </a>
);

export const ChatView: React.FC<ChatViewProps> = ({ messages, setMessages, theme, systemInstruction, model, setActiveModel }) => {
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [selectedImage, setSelectedImage] = useState<{ data: string; mimeType: string } | null>(null);
  const [webSearchEnabled, setWebSearchEnabled] = useState(true);
  const [isModelDropdownOpen, setIsModelDropdownOpen] = useState(false);

  const chatContainerRef = useRef<HTMLDivElement>(null);
  const textareaRef = useRef<HTMLTextAreaElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (chatContainerRef.current) {
      chatContainerRef.current.scrollTo({
        top: chatContainerRef.current.scrollHeight,
        behavior: 'smooth'
      });
    }
  }, [messages, isLoading]);

  const formatOutput = (text: string) => {
    return text.replace(/\*/g, '');
  };

  const handleSendMessage = useCallback(async (textOverride?: string) => {
    const textInput = (textOverride || input).trim();
    if ((!textInput && !selectedImage) || isLoading) return;

    const userMessageParts: ChatPart[] = [];
    if (selectedImage) userMessageParts.push({ inlineData: { mimeType: selectedImage.mimeType, data: selectedImage.data } });
    if (textInput) userMessageParts.push({ text: textInput });

    const userMessage: ChatMessage = { id: `msg-${Date.now()}`, role: 'user', parts: userMessageParts };
    const modelPlaceholder: ChatMessage = { id: `msg-${Date.now() + 1}`, role: 'model', parts: [{ text: '' }], isSearching: webSearchEnabled };

    setMessages(prev => [...prev, userMessage, modelPlaceholder]);
    setInput(''); 
    setSelectedImage(null);
    setIsLoading(true);

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const history = messages.map(msg => ({
        role: msg.role,
        parts: msg.parts.map(p => {
            if (p.text) return { text: p.text };
            if (p.inlineData) return { inlineData: p.inlineData };
            return null;
        }).filter(Boolean) as any[]
      }));

      let finalModelName = model === 'cognix-arc-1.0' ? 'gemini-3-pro-preview' : model;
      let modelSpecificInstruction = systemInstruction;

      if (model === 'gemini-2.5-flash-latest') {
          modelSpecificInstruction += " IMPORTANT: Use relevant emojis to make your responses engaging and friendly. NEVER use asterisks (*) for formatting. Always respond in clear, professional paragraphs.";
      } else if (model === 'cognix-arc-1.0') {
          modelSpecificInstruction = "You are CognixArc 1.0. High-reasoning engine. Professional, creative, accurate. Do not use asterisks (*) for formatting.";
      }

      let stream = await ai.models.generateContentStream({
          model: finalModelName as any,
          contents: [...history, { role: 'user', parts: userMessageParts as any }],
          config: { 
              systemInstruction: modelSpecificInstruction, 
              tools: webSearchEnabled ? [{ googleSearch: {} }] : [],
              temperature: 0.8 
          },
      });

      let fullText = '';
      let searchResults: SearchResult[] = [];

      for await (const chunk of stream) {
        if(chunk.text) {
            fullText += chunk.text;
            const cleanText = formatOutput(fullText);
            setMessages(prev => prev.map(m => m.id === modelPlaceholder.id ? { ...m, parts: [{ text: cleanText }], isSearching: false } : m));
        }
        const chunks = chunk.candidates?.[0]?.groundingMetadata?.groundingChunks;
        if (chunks) {
            const results = chunks.map((c: any) => c.web ? { ...c.web, type: 'web' } : null).filter(Boolean);
            searchResults = [...searchResults, ...results];
        }
      }

      if (searchResults.length > 0) {
        const unique = Array.from(new Map(searchResults.map(i => [i.uri, i])).values());
        setMessages(prev => prev.map(m => m.id === modelPlaceholder.id ? { ...m, parts: [{ ...m.parts[0], searchResults: unique }] } : m));
      }
    } catch (error) {
      setMessages(prev => prev.map(m => m.id === modelPlaceholder.id ? { ...m, parts: [{ text: `Error: ${error instanceof Error ? error.message : "Connection failed."}` }], isSearching: false } : m));
    } finally {
      setIsLoading(false);
    }
  }, [input, isLoading, messages, selectedImage, systemInstruction, model, webSearchEnabled, setMessages]);

  const adjustTextareaHeight = () => {
    if (textareaRef.current) {
      textareaRef.current.style.height = 'auto';
      textareaRef.current.style.height = `${Math.min(textareaRef.current.scrollHeight, 180)}px`;
    }
  };

  useEffect(() => {
    adjustTextareaHeight();
  }, [input]);

  const hasMessages = messages.length > 0;

  return (
    <div className="flex flex-col h-full bg-white dark:bg-slate-900 relative">
      {/* Messages / Hero Section */}
      <div ref={chatContainerRef} className="flex-1 overflow-y-auto px-4 sm:px-6 md:px-8 pb-48 pt-6 custom-scrollbar scroll-smooth">
        {!hasMessages ? (
            <div className="max-w-4xl mx-auto flex flex-col items-center justify-center min-h-[70vh] text-center px-4 animate-fade-in transition-all duration-700 ease-out">
                 <div className="relative mb-6 transform hover:scale-105 transition-transform cursor-pointer">
                     <div className="absolute inset-0 bg-blue-500/10 rounded-full blur-3xl animate-pulse"></div>
                     <BotIcon className="relative w-20 h-20 sm:w-28 sm:h-28 drop-shadow-2xl" />
                 </div>
                 <h2 className="text-3xl sm:text-4xl md:text-5xl font-black text-slate-900 dark:text-white mb-2 tracking-tighter">
                   Ask Cognix anything.
                 </h2>
                 <p className="text-slate-500 dark:text-slate-400 max-w-lg mb-10 text-lg sm:text-xl font-medium leading-relaxed">
                    Advanced multimodal intelligence at your command.
                 </p>

                 <div className="grid grid-cols-1 sm:grid-cols-2 gap-3 w-full max-w-2xl">
                     {[
                         { t: "Generate Image", q: "Create a cyberpunk portrait of a samurai in neon Tokyo", icon: <ImageIcon className="w-5 h-5"/> },
                         { t: "Live Search", q: "What are the latest updates in space exploration this week?", icon: <SearchIcon className="w-5 h-5"/> },
                         { t: "Deep Logic", q: "Explain quantum computing to a 5-year-old using Legos", icon: <SparklesIcon className="w-5 h-5"/> },
                         { t: "Code Architect", q: "Write a responsive React component for a data dashboard", icon: <BotIcon className="w-5 h-5"/> }
                     ].map((item, i) => (
                        <button 
                            key={i} 
                            onClick={() => handleSendMessage(item.q)}
                            className="text-left p-4 rounded-2xl border border-slate-200 dark:border-slate-800 hover:border-blue-500 dark:hover:border-blue-500/50 hover:bg-slate-50 dark:hover:bg-slate-800/50 transition-all group flex gap-4 items-center"
                        >
                            <div className="w-10 h-10 rounded-xl bg-slate-100 dark:bg-slate-800 flex items-center justify-center shrink-0 group-hover:bg-blue-600 group-hover:text-white transition-all">
                                {item.icon}
                            </div>
                            <div className="min-w-0">
                                <p className="font-bold text-slate-900 dark:text-white text-sm truncate">{item.t}</p>
                                <p className="text-[10px] text-slate-400 font-bold uppercase truncate tracking-widest">Try this command</p>
                            </div>
                        </button>
                     ))}
                 </div>
            </div>
        ) : (
            <div className="max-w-3xl mx-auto space-y-10 animate-fade-in-up pb-10">
                {messages.map((msg) => (
                    <div key={msg.id} className={`flex gap-4 sm:gap-6 group ${msg.role === 'user' ? 'flex-row-reverse' : 'flex-row'}`}>
                        <div className={`w-8 h-8 sm:w-10 sm:h-10 shrink-0 rounded-xl flex items-center justify-center shadow-lg
                            ${msg.role === 'user' ? 'bg-slate-100 dark:bg-slate-800 text-slate-500 border border-slate-200 dark:border-slate-700' : 'bg-gradient-to-tr from-blue-600 to-indigo-600 text-white'}
                        `}>
                             {msg.role === 'user' ? <UserIcon className="w-5 h-5 sm:w-6 sm:h-6"/> : <BotIcon className="w-6 h-6 sm:w-8 sm:h-8"/>}
                        </div>

                        <div className={`flex flex-col gap-2 max-w-[90%] sm:max-w-[85%] ${msg.role === 'user' ? 'items-end' : 'items-start'}`}>
                             {msg.parts.map((part, i) => (
                                 <div key={i} className={`relative leading-relaxed transition-all
                                     ${msg.role === 'user' 
                                         ? 'bg-blue-600 text-white px-5 py-3 rounded-2xl rounded-tr-sm shadow-md font-medium text-sm sm:text-base' 
                                         : 'text-slate-800 dark:text-slate-100 text-sm sm:text-base'}
                                 `}>
                                     {part.inlineData && <img src={`data:${part.inlineData.mimeType};base64,${part.inlineData.data}`} className="rounded-2xl mb-4 max-h-[400px] shadow-lg border border-slate-200 dark:border-slate-800 object-contain" alt="Upload"/>}

                                     {msg.isSearching && i === 0 && (
                                         <div className="flex items-center gap-3 text-blue-500 mb-4 animate-pulse-soft bg-blue-50 dark:bg-blue-900/20 px-3 py-1.5 rounded-full border border-blue-500/20 w-fit">
                                             <div className="w-3 h-3 border-2 border-blue-500 border-t-transparent rounded-full animate-spin"></div>
                                             <span className="text-[10px] font-black uppercase tracking-wider">Syncing Neural Link...</span>
                                         </div>
                                     )}

                                     <div className="whitespace-pre-wrap prose prose-sm sm:prose-base dark:prose-invert max-w-none">{part.text}</div>

                                     {part.searchResults && part.searchResults.length > 0 && (
                                         <div className="mt-6">
                                            <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-3 flex items-center gap-2">
                                                Grounding Node <span className="h-px bg-slate-100 dark:bg-slate-800 flex-1"></span>
                                            </p>
                                            <div className="flex gap-3 overflow-x-auto pb-3 no-scrollbar scroll-smooth">
                                                {part.searchResults.map((res, idx) => <SourceCard key={idx} result={res} />)}
                                            </div>
                                         </div>
                                     )}
                                 </div>
                             ))}
                        </div>
                    </div>
                ))}
                {isLoading && (
                  <div className="flex gap-4 sm:gap-6 items-center">
                    <div className="w-8 h-8 sm:w-10 sm:h-10 shrink-0 rounded-xl bg-gradient-to-tr from-blue-600 to-indigo-600 flex items-center justify-center shadow-lg">
                      <BotIcon className="w-6 h-6 sm:w-8 sm:h-8 animate-pulse" />
                    </div>
                    <div className="flex gap-1">
                      <div className="w-1.5 h-1.5 bg-blue-500 rounded-full animate-bounce [animation-delay:-0.3s]"></div>
                      <div className="w-1.5 h-1.5 bg-blue-500 rounded-full animate-bounce [animation-delay:-0.15s]"></div>
                      <div className="w-1.5 h-1.5 bg-blue-500 rounded-full animate-bounce"></div>
                    </div>
                  </div>
                )}
            </div>
        )}
      </div>

      {/* Input Section - Optimized for Responsiveness */}
      <div className={`absolute bottom-0 left-0 right-0 px-4 sm:px-6 md:px-12 pb-6 pt-10 transition-all duration-500 ${hasMessages ? 'bg-gradient-to-t from-white dark:from-slate-900 via-white/95 dark:via-slate-900/95 to-transparent' : 'translate-y-0'}`}>
          <div className="max-w-3xl mx-auto relative group pointer-events-auto">

              <div className="bg-white dark:bg-slate-800/90 backdrop-blur-2xl rounded-[1.8rem] sm:rounded-[2.5rem] shadow-2xl border border-slate-200/60 dark:border-slate-700/60 transition-all focus-within:ring-4 ring-blue-500/10 overflow-hidden">

                   {/* Tool Bar */}
                   <div className="flex items-center justify-between px-5 sm:px-7 pt-3 pb-1 border-b border-slate-100 dark:border-slate-700/40">
                       <div className="flex items-center gap-3 relative">
                           {/* Model Switcher Pill */}
                           <div className="relative">
                                <button 
                                    onClick={() => setIsModelDropdownOpen(!isModelDropdownOpen)}
                                    className="flex items-center gap-2 px-3 sm:px-4 py-1.5 bg-slate-900 dark:bg-slate-950 text-white rounded-full hover:bg-black transition-all shadow-md active:scale-95"
                                >
                                    <span className="text-[10px] font-black tracking-tighter uppercase whitespace-nowrap">
                                        {model === 'gemini-2.5-flash-latest' ? 'Smart' : 'Arc 1.0'}
                                    </span>
                                    <svg className={`w-3 h-3 transition-transform ${isModelDropdownOpen ? 'rotate-180' : ''}`} fill="none" stroke="currentColor" viewBox="0 0 24 24" strokeWidth="3"><path strokeLinecap="round" strokeLinejoin="round" d="M19 9l-7 7-7-7"/></svg>
                                </button>

                                {isModelDropdownOpen && (
                                    <div className="absolute top-full left-0 mt-2 w-40 bg-slate-900 text-white rounded-2xl shadow-2xl border border-white/10 z-[100] overflow-hidden animate-fade-in">
                                        {[
                                            { id: 'gemini-2.5-flash-latest', label: 'Smart' },
                                            { id: 'cognix-arc-1.0', label: 'Arc 1.0' }
                                        ].map(m => (
                                            <button 
                                                key={m.id}
                                                onClick={() => { setActiveModel(m.id as any); setIsModelDropdownOpen(false); }}
                                                className="w-full text-left px-4 py-2.5 hover:bg-white/10 transition-colors border-b border-white/5 last:border-none text-[10px] font-black uppercase tracking-widest"
                                            >
                                                {m.label}
                                            </button>
                                        ))}
                                    </div>
                                )}
                           </div>

                           <button 
                                onClick={() => setWebSearchEnabled(!webSearchEnabled)}
                                className={`flex items-center gap-2 px-3 sm:px-4 py-1.5 rounded-full border transition-all ${webSearchEnabled ? 'bg-blue-600 border-blue-600 text-white shadow-md' : 'bg-slate-50 dark:bg-slate-900 border-slate-200 dark:border-slate-700 text-slate-400'}`}
                            >
                                <SearchIcon className="w-3 h-3" />
                                <span className="text-[9px] font-black uppercase tracking-tighter hidden sm:inline">Grounding</span>
                            </button>
                       </div>

                       <div className="flex gap-2 text-slate-400">
                           <SparklesIcon className="w-4 h-4"/>
                       </div>
                   </div>

                   {/* Main Input */}
                   <div className="p-3 sm:p-4 flex items-end gap-2">
                        <button 
                            onClick={() => fileInputRef.current?.click()} 
                            className="p-3 rounded-2xl text-slate-400 hover:bg-slate-100 dark:hover:bg-slate-700 hover:text-blue-500 transition-all shrink-0"
                        >
                            <ImageIcon className="w-5 h-5 sm:w-6 sm:h-6"/>
                            <input type="file" ref={fileInputRef} onChange={(e) => {
                                    const file = e.target.files?.[0];
                                    if (file) {
                                        const reader = new FileReader();
                                        reader.onloadend = () => {
                                            setSelectedImage({ data: (reader.result as string).split(',')[1], mimeType: file.type });
                                        };
                                        reader.readAsDataURL(file);
                                    }
                            }} accept="image/*" className="hidden" />
                        </button>

                        <textarea
                            ref={textareaRef}
                            value={input}
                            onChange={e => setInput(e.target.value)}
                            onKeyDown={e => e.key === 'Enter' && !e.shiftKey && (e.preventDefault(), handleSendMessage())}
                            placeholder="Ask Cognix anything..."
                            className="flex-1 bg-transparent border-none outline-none resize-none py-3 px-2 text-slate-900 dark:text-white placeholder-slate-400 dark:placeholder-slate-500 text-base sm:text-lg font-medium leading-relaxed max-h-[180px] min-h-[40px]"
                            rows={1}
                        />

                        <button 
                            onClick={() => handleSendMessage()} 
                            disabled={isLoading || (!input && !selectedImage)} 
                            className={`w-12 h-12 rounded-[1.2rem] text-white transition-all duration-300 transform active:scale-90 disabled:opacity-30 flex items-center justify-center shrink-0
                                ${input || selectedImage ? 'bg-blue-600 shadow-xl shadow-blue-500/20 hover:scale-105' : 'bg-slate-100 dark:bg-slate-700 text-slate-300'}
                            `}
                        >
                             <SendIcon className="w-5 h-5 sm:w-6 sm:h-6"/>
                        </button>
                   </div>
              </div>

              {selectedImage && (
                  <div className="absolute -top-24 left-4 p-2 bg-white dark:bg-slate-800 rounded-2xl shadow-xl border border-slate-200 dark:border-slate-700 flex items-center gap-3 animate-fade-in group pointer-events-auto">
                      <div className="relative overflow-hidden rounded-xl w-14 h-14">
                        <img src={`data:${selectedImage.mimeType};base64,${selectedImage.data}`} className="w-full h-full object-cover" />
                      </div>
                      <button onClick={() => setSelectedImage(null)} className="p-1.5 bg-red-500 text-white rounded-full hover:bg-red-600 transition-all shadow-md">
                          <svg className="w-3 h-3" fill="currentColor" viewBox="0 0 20 20"><path d="M4.293 4.293a1 1 0 011.414 0L10 8.586l4.293-4.293a1 1 0 111.414 1.414L11.414 10l4.293 4.293a1 1 0 01-1.414 1.414L10 11.414l-4.293 4.293a1 1 0 01-1.414-1.414L8.586 10 4.293 5.707a1 1 0 010-1.414z"/></svg>
                      </button>
                  </div>
              )}
          </div>
          <p className="max-w-xl mx-auto text-center mt-3 text-[9px] text-slate-400 font-bold uppercase tracking-widest hidden sm:block">
            Cognix can make mistakes. Built by Shashwat Ranjan Jha
          </p>
      </div>
    </div>
  );
};

import React, { useState, useEffect, useMemo } from 'react';
import { ChatView } from './components/ChatView';
import { LiveView } from './components/LiveView';
import { Sidebar } from './components/Sidebar';
import { FriendsView } from './components/FriendsView';
import { ToolboxView } from './components/ToolboxView';
import { MemoryView } from './components/MemoryView';
import { CommunityView } from './components/CommunityView';
import { CodingView } from './components/CodingView';
import { MenuIcon, UserIcon } from './components/Icons';
import { SettingsModal } from './components/SettingsModal';
import { GoogleGenAI } from "@google/genai";
import type { ChatMessage, ChatSession, Mode, UIStyle, AccentColor, ThemeColors, FontSize, Friend, ModelType } from './types';

const THEMES: Record<AccentColor, ThemeColors> = {
    blue: { primary: 'bg-blue-600', primaryHover: 'hover:bg-blue-700', text: 'text-blue-600', textDark: 'text-blue-400', bgSoft: 'bg-blue-50', darkBgSoft: 'dark:bg-blue-900/20', border: 'border-blue-600', ring: 'focus:ring-blue-600', gradient: 'bg-gradient-to-r from-blue-500 to-cyan-500' },
    violet: { primary: 'bg-violet-600', primaryHover: 'hover:bg-violet-700', text: 'text-violet-600', textDark: 'text-violet-400', bgSoft: 'bg-violet-50', darkBgSoft: 'dark:bg-violet-900/20', border: 'border-violet-600', ring: 'focus:ring-violet-600', gradient: 'bg-gradient-to-r from-violet-500 to-purple-500' },
    emerald: { primary: 'bg-emerald-600', primaryHover: 'hover:bg-emerald-700', text: 'text-emerald-600', textDark: 'text-emerald-400', bgSoft: 'bg-emerald-50', darkBgSoft: 'dark:bg-emerald-900/20', border: 'border-emerald-600', ring: 'focus:ring-emerald-600', gradient: 'bg-gradient-to-r from-emerald-500 to-teal-500' },
    rose: { primary: 'bg-rose-600', primaryHover: 'hover:bg-rose-700', text: 'text-rose-600', textDark: 'text-rose-400', bgSoft: 'bg-rose-50', darkBgSoft: 'dark:bg-rose-900/20', border: 'border-rose-600', ring: 'focus:ring-rose-600', gradient: 'bg-gradient-to-r from-rose-500 to-pink-500' },
    amber: { primary: 'bg-amber-600', primaryHover: 'hover:bg-amber-700', text: 'text-amber-600', textDark: 'text-amber-400', bgSoft: 'bg-amber-50', darkBgSoft: 'dark:bg-amber-900/20', border: 'border-amber-600', ring: 'focus:ring-amber-600', gradient: 'bg-gradient-to-r from-amber-500 to-orange-500' },
};

const App: React.FC = () => {
  const [mode, setMode] = useState<Mode>('chat');
  const [uiStyle, setUiStyle] = useState<UIStyle>('modern');
  const [accentColor, setAccentColor] = useState<AccentColor>('blue');
  const [fontSize, setFontSize] = useState<FontSize>('normal');
  const [activeModel, setActiveModel] = useState<ModelType>('gemini-2.5-flash-latest');
  const [systemInstruction, setSystemInstruction] = useState("You are Cognix AI, a highly intelligent personal assistant created by Shashwat Ranjan Jha. You are professional, witty, and extremely capable. You have access to real-time information via Google Search.");

  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [isDesktopSidebarOpen, setIsDesktopSidebarOpen] = useState(true);
  const [isDarkMode, setIsDarkMode] = useState(false);
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);

  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [chatHistory, setChatHistory] = useState<ChatSession[]>([]);
  const [activeChatId, setActiveChatId] = useState<string | null>(null);
  const [friends, setFriends] = useState<Friend[]>([]);

  useEffect(() => {
    const savedHistory = localStorage.getItem('cognix_v2_history');
    if (savedHistory) setChatHistory(JSON.parse(savedHistory));

    const savedFriends = localStorage.getItem('cognix_friends');
    if (savedFriends) setFriends(JSON.parse(savedFriends));

    const savedTheme = localStorage.getItem('cognix_theme');
    if (savedTheme === 'dark' || (!savedTheme && window.matchMedia('(prefers-color-scheme: dark)').matches)) {
      setIsDarkMode(true);
      document.documentElement.classList.add('dark');
    }
  }, []);

  useEffect(() => localStorage.setItem('cognix_v2_history', JSON.stringify(chatHistory)), [chatHistory]);
  useEffect(() => localStorage.setItem('cognix_friends', JSON.stringify(friends)), [friends]);

  useEffect(() => {
    if (isDarkMode) {
      document.documentElement.classList.add('dark');
      localStorage.setItem('cognix_theme', 'dark');
    } else {
      document.documentElement.classList.remove('dark');
      localStorage.setItem('cognix_theme', 'light');
    }
  }, [isDarkMode]);

  const currentChat = useMemo(() => chatHistory.find(c => c.id === activeChatId), [chatHistory, activeChatId]);
  const activeTheme = useMemo(() => THEMES[accentColor], [accentColor]);

  useEffect(() => {
    setMessages(currentChat ? currentChat.messages : []);
  }, [currentChat?.id]);

  const generateChatTitle = async (firstMessage: string) => {
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: `Generate a catchy, ultra-short (max 3 words) title for a conversation that starts with: "${firstMessage}". No quotes or period.`,
      });
      return response.text?.trim() || firstMessage.slice(0, 30);
    } catch (e) {
      return firstMessage.slice(0, 30);
    }
  };

  useEffect(() => {
    const updateHistory = async () => {
      if (messages.length === 1 && !activeChatId && messages[0].role === 'user') {
         const firstUserText = messages[0].parts.find(p => p.text)?.text || 'New Chat';
         const newId = Date.now().toString();
         const newTitle = await generateChatTitle(firstUserText);
         const newSession: ChatSession = { id: newId, title: newTitle, messages: messages };
         setChatHistory(prev => [newSession, ...prev]);
         setActiveChatId(newId);
      } else if (activeChatId && messages.length > 0) {
         setChatHistory(prev => prev.map(session => session.id === activeChatId ? { ...session, messages } : session));
      }
    };
    updateHistory();
  }, [messages, activeChatId]);

  const handleNewChat = () => {
    setActiveChatId(null);
    setMessages([]);
    setMode('chat');
    if (window.innerWidth < 1024) setIsSidebarOpen(false);
  };

  return (
    <div className={`flex h-[100dvh] overflow-hidden bg-slate-50 dark:bg-slate-950 transition-colors duration-300`}>

      <Sidebar 
        chatHistory={chatHistory}
        activeChatId={activeChatId}
        mode={mode}
        onSetMode={(m) => { setMode(m); if(window.innerWidth < 1024) setIsSidebarOpen(false); }}
        onSelectChat={(id) => { setActiveChatId(id); setMode('chat'); if(window.innerWidth < 1024) setIsSidebarOpen(false); }}
        onNewChat={handleNewChat}
        onDeleteChat={(id) => {
            setChatHistory(h => h.filter(c => c.id !== id));
            if (activeChatId === id) { setActiveChatId(null); setMessages([]); }
        }}
        onRenameChat={(id, t) => setChatHistory(h => h.map(c => c.id === id ? { ...c, title: t } : c))}
        onOpenSettings={() => setIsSettingsOpen(true)}
        isSidebarOpen={isSidebarOpen}
        isDesktopSidebarOpen={isDesktopSidebarOpen}
        theme={activeTheme}
        friends={friends}
      />

      {isSidebarOpen && <div className="fixed inset-0 bg-black/40 backdrop-blur-sm z-40 lg:hidden" onClick={() => setIsSidebarOpen(false)} />}

      <div className="flex-1 flex flex-col h-full min-w-0 bg-white dark:bg-slate-900 lg:rounded-l-[2.5rem] shadow-2xl relative">
        <header className="h-16 flex items-center justify-between px-4 sm:px-8 shrink-0 z-30 border-b border-slate-50 dark:border-slate-800 lg:border-none">
             <div className="flex items-center gap-2 sm:gap-4">
                <button onClick={() => window.innerWidth >= 1024 ? setIsDesktopSidebarOpen(!isDesktopSidebarOpen) : setIsSidebarOpen(!isSidebarOpen)} className="p-2 -ml-2 text-slate-500 hover:bg-slate-100 dark:hover:bg-slate-800 rounded-xl transition-colors">
                    <MenuIcon className="w-5 h-5"/>
                </button>
                <div className="flex flex-col">
                  <h1 className="text-xs sm:text-sm font-black text-slate-800 dark:text-slate-100 flex items-center gap-2 tracking-tight truncate max-w-[150px] sm:max-w-none">
                      {mode === 'chat' && (currentChat?.title || 'New Session')}
                      {mode === 'live' && 'Live Intelligence'}
                      {mode === 'community' && 'Global Pulse'}
                      {mode === 'coding' && 'DevStudio v1.0'}
                      {mode === 'toolbox' && 'Lab Toolbox'}
                      {mode === 'memory' && 'Vault'}
                      <div className="w-1.5 h-1.5 rounded-full bg-blue-500 animate-pulse shrink-0"></div>
                  </h1>
                  <span className="text-[8px] sm:text-[9px] text-slate-400 font-bold tracking-[0.2em] uppercase">Cognix Neural Engine</span>
                </div>
             </div>

             <div className="flex items-center gap-2 sm:gap-4">
                 <button onClick={() => setIsDarkMode(!isDarkMode)} className="p-2 text-slate-400 hover:text-slate-600 dark:hover:text-slate-200 transition-colors">
                     {isDarkMode ? <svg className="w-5 h-5" fill="currentColor" viewBox="0 0 20 20"><path d="M10 2a1 1 0 011 1v1a1 1 0 11-2 0V3a1 1 0 011-1zm4 8a4 4 0 11-8 0 4 4 0 018 0zm-.464 4.95l.707.707a1 1 0 001.414-1.414l-.707-.707a1 1 0 00-1.414 1.414zm2.12-10.607a1 1 0 010 1.414l-.706.707a1 1 0 11-1.414-1.414l.707-.707a1 1 0 011.414 0zM17 11a1 1 0 100-2h-1a1 1 0 100 2h1zm-7 4a1 1 0 011 1v1a1 1 0 11-2 0v-1a1 1 0 011-1zM5.05 6.464A1 1 0 106.465 5.05l-.708-.707a1 1 0 00-1.414 1.414l.707.707zm1.414 8.486l-.707.707a1 1 0 01-1.414-1.414l.707-.707a1 1 0 011.414 1.414zM4 11a1 1 0 100-2H3a1 1 0 000 2h1z"/></svg> : <svg className="w-5 h-5" fill="currentColor" viewBox="0 0 20 20"><path d="M17.293 13.293A8 8 0 016.707 2.707a8.001 8.001 0 1010.586 10.586z"/></svg>}
                 </button>
                 <button 
                    onClick={() => setIsSettingsOpen(true)}
                    className="flex items-center gap-2 p-1 pl-2 sm:pl-3 bg-slate-100 dark:bg-slate-800 rounded-full border border-slate-200 dark:border-slate-700 hover:border-blue-500 transition-all group"
                 >
                     <span className="text-[8px] sm:text-[10px] font-black text-slate-500 group-hover:text-blue-500 transition-colors uppercase tracking-widest hidden xs:inline">Profile</span>
                     <div className="w-7 h-7 sm:w-8 sm:h-8 rounded-full bg-gradient-to-tr from-blue-600 to-indigo-600 flex items-center justify-center text-white">
                         <UserIcon className="w-4 h-4 sm:w-5 sm:h-5"/>
                     </div>
                 </button>
             </div>
        </header>

        <main className="flex-1 relative overflow-hidden">
             {mode === 'chat' && (
                <ChatView 
                    messages={messages} 
                    setMessages={setMessages}
                    uiStyle={uiStyle}
                    theme={activeTheme}
                    fontSize={fontSize}
                    systemInstruction={systemInstruction}
                    model={activeModel}
                    setActiveModel={setActiveModel}
                />
            )}
            {mode === 'live' && <LiveView theme={activeTheme} />}
            {mode === 'friends' && <FriendsView friends={friends} setFriends={setFriends} />}
            {mode === 'community' && <CommunityView theme={activeTheme} model={activeModel} />}
            {mode === 'coding' && <CodingView theme={activeTheme} model={activeModel} />}
            {mode === 'toolbox' && <ToolboxView theme={activeTheme} model={activeModel} />}
            {mode === 'memory' && <MemoryView theme={activeTheme} />}
        </main>
      </div>

      <SettingsModal 
        isOpen={isSettingsOpen} onClose={() => setIsSettingsOpen(false)}
        uiStyle={uiStyle} setUiStyle={setUiStyle}
        accentColor={accentColor} setAccentColor={setAccentColor}
        fontSize={fontSize} setFontSize={setFontSize}
        isDarkMode={isDarkMode} setIsDarkMode={setIsDarkMode}
        onClearHistory={() => { setChatHistory([]); setMessages([]); setActiveChatId(null); setIsSettingsOpen(false); }}
        systemInstruction={systemInstruction} setSystemInstruction={setSystemInstruction}
      />
    </div>
  );
}

export default App;

import React, { useState, useEffect, useMemo } from 'react';
import { ChatView } from './components/ChatView';
import { LiveView } from './components/LiveView';
import { Sidebar } from './components/Sidebar';
import { FriendsView } from './components/FriendsView';
import { ToolboxView } from './components/ToolboxView';
import { MemoryView } from './components/MemoryView';
import { CommunityView } from './components/CommunityView';
import { CodingView } from './components/CodingView';
import { MenuIcon, UserIcon } from './components/Icons';
import { SettingsModal } from './components/SettingsModal';
import { GoogleGenAI } from "@google/genai";
import type { ChatMessage, ChatSession, Mode, UIStyle, AccentColor, ThemeColors, FontSize, Friend, ModelType } from './types';

const THEMES: Record<AccentColor, ThemeColors> = {
    blue: { primary: 'bg-blue-600', primaryHover: 'hover:bg-blue-700', text: 'text-blue-600', textDark: 'text-blue-400', bgSoft: 'bg-blue-50', darkBgSoft: 'dark:bg-blue-900/20', border: 'border-blue-600', ring: 'focus:ring-blue-600', gradient: 'bg-gradient-to-r from-blue-500 to-cyan-500' },
    violet: { primary: 'bg-violet-600', primaryHover: 'hover:bg-violet-700', text: 'text-violet-600', textDark: 'text-violet-400', bgSoft: 'bg-violet-50', darkBgSoft: 'dark:bg-violet-900/20', border: 'border-violet-600', ring: 'focus:ring-violet-600', gradient: 'bg-gradient-to-r from-violet-500 to-purple-500' },
    emerald: { primary: 'bg-emerald-600', primaryHover: 'hover:bg-emerald-700', text: 'text-emerald-600', textDark: 'text-emerald-400', bgSoft: 'bg-emerald-50', darkBgSoft: 'dark:bg-emerald-900/20', border: 'border-emerald-600', ring: 'focus:ring-emerald-600', gradient: 'bg-gradient-to-r from-emerald-500 to-teal-500' },
    rose: { primary: 'bg-rose-600', primaryHover: 'hover:bg-rose-700', text: 'text-rose-600', textDark: 'text-rose-400', bgSoft: 'bg-rose-50', darkBgSoft: 'dark:bg-rose-900/20', border: 'border-rose-600', ring: 'focus:ring-rose-600', gradient: 'bg-gradient-to-r from-rose-500 to-pink-500' },
    amber: { primary: 'bg-amber-600', primaryHover: 'hover:bg-amber-700', text: 'text-amber-600', textDark: 'text-amber-400', bgSoft: 'bg-amber-50', darkBgSoft: 'dark:bg-amber-900/20', border: 'border-amber-600', ring: 'focus:ring-amber-600', gradient: 'bg-gradient-to-r from-amber-500 to-orange-500' },
};

const App: React.FC = () => {
  const [mode, setMode] = useState<Mode>('chat');
  const [uiStyle, setUiStyle] = useState<UIStyle>('modern');
  const [accentColor, setAccentColor] = useState<AccentColor>('blue');
  const [fontSize, setFontSize] = useState<FontSize>('normal');
  const [activeModel, setActiveModel] = useState<ModelType>('gemini-3-flash-preview');
  const [systemInstruction, setSystemInstruction] = useState("You are Nexzi AI, a highly intelligent and helpful personal assistant created by Shashwat Ranjan Jha. You are professional, friendly, and efficient. You use emojis to make conversations engaging. You have access to real-time information via Google Search.");

  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [isDesktopSidebarOpen, setIsDesktopSidebarOpen] = useState(true);
  const [isDarkMode, setIsDarkMode] = useState(false);
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);

  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [chatHistory, setChatHistory] = useState<ChatSession[]>([]);
  const [activeChatId, setActiveChatId] = useState<string | null>(null);
  const [friends, setFriends] = useState<Friend[]>([]);

  useEffect(() => {
    const savedHistory = localStorage.getItem('nexzi_history');
    if (savedHistory) setChatHistory(JSON.parse(savedHistory));

    const savedFriends = localStorage.getItem('nexzi_friends');
    if (savedFriends) setFriends(JSON.parse(savedFriends));

    const savedTheme = localStorage.getItem('nexzi_theme');
    if (savedTheme === 'dark' || (!savedTheme && window.matchMedia('(prefers-color-scheme: dark)').matches)) {
      setIsDarkMode(true);
      document.documentElement.classList.add('dark');
    }
  }, []);

  useEffect(() => localStorage.setItem('nexzi_history', JSON.stringify(chatHistory)), [chatHistory]);
  useEffect(() => localStorage.setItem('nexzi_friends', JSON.stringify(friends)), [friends]);

  useEffect(() => {
    if (isDarkMode) {
      document.documentElement.classList.add('dark');
      localStorage.setItem('nexzi_theme', 'dark');
    } else {
      document.documentElement.classList.remove('dark');
      localStorage.setItem('nexzi_theme', 'light');
    }
  }, [isDarkMode]);

  const currentChat = useMemo(() => chatHistory.find(c => c.id === activeChatId), [chatHistory, activeChatId]);
  const activeTheme = useMemo(() => THEMES[accentColor], [accentColor]);

  useEffect(() => {
    setMessages(currentChat ? currentChat.messages : []);
  }, [currentChat?.id]);

  const generateChatTitle = async (firstMessage: string) => {
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: `Generate a ultra-short (max 3 words) title for: "${firstMessage}". Output ONLY the title.`,
      });
      return response.text?.trim() || firstMessage.slice(0, 30);
    } catch (e) {
      return firstMessage.slice(0, 30);
    }
  };

  useEffect(() => {
    const updateHistory = async () => {
      if (messages.length === 1 && !activeChatId && messages[0].role === 'user') {
         const firstUserText = messages[0].parts.find(p => p.text)?.text || 'New Chat';
         const newId = Date.now().toString();
         const newTitle = await generateChatTitle(firstUserText);
         const newSession: ChatSession = { id: newId, title: newTitle, messages: messages };
         setChatHistory(prev => [newSession, ...prev]);
         setActiveChatId(newId);
      } else if (activeChatId && messages.length > 0) {
         setChatHistory(prev => prev.map(session => session.id === activeChatId ? { ...session, messages } : session));
      }
    };
    updateHistory();
  }, [messages, activeChatId]);

  const handleNewChat = () => {
    setActiveChatId(null);
    setMessages([]);
    setMode('chat');
    if (window.innerWidth < 1024) setIsSidebarOpen(false);
  };

  return (
    <div className="flex h-[100dvh] overflow-hidden bg-slate-50 dark:bg-slate-950 transition-colors duration-300">
      <Sidebar 
        chatHistory={chatHistory}
        activeChatId={activeChatId}
        mode={mode}
        onSetMode={(m) => { setMode(m); if(window.innerWidth < 1024) setIsSidebarOpen(false); }}
        onSelectChat={(id) => { setActiveChatId(id); setMode('chat'); if(window.innerWidth < 1024) setIsSidebarOpen(false); }}
        onNewChat={handleNewChat}
        onDeleteChat={(id) => {
            setChatHistory(h => h.filter(c => c.id !== id));
            if (activeChatId === id) { setActiveChatId(null); setMessages([]); }
        }}
        onRenameChat={(id, t) => setChatHistory(h => h.map(c => c.id === id ? { ...c, title: t } : c))}
        onOpenSettings={() => setIsSettingsOpen(true)}
        isSidebarOpen={isSidebarOpen}
        isDesktopSidebarOpen={isDesktopSidebarOpen}
        theme={activeTheme}
        friends={friends}
      />

      {isSidebarOpen && <div className="fixed inset-0 bg-black/40 backdrop-blur-sm z-40 lg:hidden" onClick={() => setIsSidebarOpen(false)} />}

      <div className="flex-1 flex flex-col h-full min-w-0 bg-white dark:bg-slate-900 lg:rounded-l-[2.5rem] shadow-2xl relative transition-all duration-500">
        <header className="h-16 flex items-center justify-between px-4 sm:px-8 shrink-0 z-30 border-b border-slate-50 dark:border-slate-800 lg:border-none">
             <div className="flex items-center gap-2 sm:gap-4">
                <button onClick={() => window.innerWidth >= 1024 ? setIsDesktopSidebarOpen(!isDesktopSidebarOpen) : setIsSidebarOpen(!isSidebarOpen)} className="p-2 -ml-2 text-slate-500 hover:bg-slate-100 dark:hover:bg-slate-800 rounded-xl transition-colors">
                    <MenuIcon className="w-5 h-5"/>
                </button>
                <div className="flex flex-col">
                  <h1 className="text-xs sm:text-sm font-black text-slate-800 dark:text-slate-100 flex items-center gap-2 tracking-tight truncate max-w-[150px] sm:max-w-none">
                      {mode === 'chat' && (currentChat?.title || 'Nexzi AI')}
                      {mode === 'live' && 'Nexzi Live'}
                      {mode === 'community' && 'Global Pulse'}
                      {mode === 'coding' && 'DevStudio'}
                      {mode === 'toolbox' && 'Lab Toolbox'}
                      {mode === 'memory' && 'Vault'}
                      <div className="w-1.5 h-1.5 rounded-full bg-blue-500 animate-pulse shrink-0"></div>
                  </h1>
                  <span className="text-[8px] sm:text-[9px] text-slate-400 font-bold tracking-[0.2em] uppercase">Intelligence Node</span>
                </div>
             </div>

             <div className="flex items-center gap-2 sm:gap-4">
                 <button onClick={() => setIsDarkMode(!isDarkMode)} className="p-2 text-slate-400 hover:text-slate-600 dark:hover:text-slate-200 transition-colors">
                     {isDarkMode ? <svg className="w-5 h-5" fill="currentColor" viewBox="0 0 20 20"><path d="M10 2a1 1 0 011 1v1a1 1 0 11-2 0V3a1 1 0 011-1zm4 8a4 4 0 11-8 0 4 4 0 018 0zm-.464 4.95l.707.707a1 1 0 001.414-1.414l-.707-.707a1 1 0 00-1.414 1.414zm2.12-10.607a1 1 0 010 1.414l-.706.707a1 1 0 11-1.414-1.414l.707-.707a1 1 0 011.414 0zM17 11a1 1 0 100-2h-1a1 1 0 100 2h1zm-7 4a1 1 0 011 1v1a1 1 0 11-2 0v-1a1 1 0 011-1zM5.05 6.464A1 1 0 106.465 5.05l-.708-.707a1 1 0 00-1.414 1.414l.707.707zm1.414 8.486l-.707.707a1 1 0 01-1.414-1.414l.707-.707a1 1 0 011.414 1.414zM4 11a1 1 0 100-2H3a1 1 0 000 2h1z"/></svg> : <svg className="w-5 h-5" fill="currentColor" viewBox="0 0 20 20"><path d="M17.293 13.293A8 8 0 016.707 2.707a8.001 8.001 0 1010.586 10.586z"/></svg>}
                 </button>
                 <button 
                    onClick={() => setIsSettingsOpen(true)}
                    className="flex items-center gap-2 p-1 pl-2 sm:pl-3 bg-slate-100 dark:bg-slate-800 rounded-full border border-slate-200 dark:border-slate-700 hover:border-blue-500 transition-all group"
                 >
                     <span className="text-[8px] sm:text-[10px] font-black text-slate-500 group-hover:text-blue-500 transition-colors uppercase tracking-widest hidden xs:inline">Config</span>
                     <div className="w-7 h-7 sm:w-8 sm:h-8 rounded-full bg-gradient-to-tr from-blue-600 to-indigo-600 flex items-center justify-center text-white">
                         <UserIcon className="w-4 h-4 sm:w-5 sm:h-5"/>
                     </div>
                 </button>
             </div>
        </header>

        <main className="flex-1 relative overflow-hidden">
             {mode === 'chat' && (
                <ChatView 
                    messages={messages} 
                    setMessages={setMessages}
                    uiStyle={uiStyle}
                    theme={activeTheme}
                    fontSize={fontSize}
                    systemInstruction={systemInstruction}
                    model={activeModel}
                    setActiveModel={setActiveModel}
                />
            )}
            {mode === 'live' && <LiveView theme={activeTheme} />}
            {mode === 'friends' && <FriendsView friends={friends} setFriends={setFriends} />}
            {mode === 'community' && <CommunityView theme={activeTheme} model={activeModel} />}
            {mode === 'coding' && <CodingView theme={activeTheme} model={activeModel} />}
            {mode === 'toolbox' && <ToolboxView theme={activeTheme} model={activeModel} />}
            {mode === 'memory' && <MemoryView theme={activeTheme} />}
        </main>
      </div>

      <SettingsModal 
        isOpen={isSettingsOpen} onClose={() => setIsSettingsOpen(false)}
        uiStyle={uiStyle} setUiStyle={setUiStyle}
        accentColor={accentColor} setAccentColor={setAccentColor}
        fontSize={fontSize} setFontSize={setFontSize}
        isDarkMode={isDarkMode} setIsDarkMode={setIsDarkMode}
        onClearHistory={() => { setChatHistory([]); setMessages([]); setActiveChatId(null); setIsSettingsOpen(false); }}
        systemInstruction={systemInstruction} setSystemInstruction={setSystemInstruction}
      />
    </div>
  );
}

export default App;

import React, { useState, useRef, useEffect, useCallback } from 'react';
import type { ChatMessage, ChatPart, SearchResult, UIStyle, ThemeColors, FontSize, ModelType } from '../types';
import { GoogleGenAI } from "@google/genai";
import { BotIcon, SendIcon, UserIcon, ImageIcon, SpeakerIcon, CopyIcon, SearchIcon, SparklesIcon } from './Icons';

interface ChatViewProps {
  messages: ChatMessage[];
  setMessages: React.Dispatch<React.SetStateAction<ChatMessage[]>>;
  uiStyle: UIStyle;
  theme: ThemeColors;
  fontSize: FontSize;
  systemInstruction: string;
  model: ModelType;
  setActiveModel: (m: ModelType) => void;
}

const SourceCard: React.FC<{ result: SearchResult }> = ({ result }) => (
    <a 
        href={result.uri} 
        target="_blank" 
        rel="noopener noreferrer"
        className="flex items-center gap-3 p-3 bg-white/50 dark:bg-slate-800/50 backdrop-blur-sm border border-slate-200 dark:border-slate-700 rounded-2xl hover:border-blue-500 dark:hover:border-blue-400 transition-all group shrink-0 max-w-[200px] shadow-sm"
    >
        <div className="w-8 h-8 rounded-lg bg-blue-100 dark:bg-blue-900/40 flex items-center justify-center shrink-0">
            <SearchIcon className="w-4 h-4 text-blue-600 dark:text-blue-400" />
        </div>
        <div className="flex-1 min-w-0">
            <p className="text-[11px] font-bold text-slate-900 dark:text-slate-100 truncate">{result.title}</p>
            <p className="text-[9px] text-slate-400 truncate uppercase tracking-tight">{new URL(result.uri).hostname}</p>
        </div>
    </a>
);

export const ChatView: React.FC<ChatViewProps> = ({ messages, setMessages, theme, systemInstruction, model, setActiveModel }) => {
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [selectedImage, setSelectedImage] = useState<{ data: string; mimeType: string } | null>(null);
  const [webSearchEnabled, setWebSearchEnabled] = useState(true);
  const [isModelDropdownOpen, setIsModelDropdownOpen] = useState(false);
  const [isFirstMessageSent, setIsFirstMessageSent] = useState(messages.length > 0);

  const chatContainerRef = useRef<HTMLDivElement>(null);
  const textareaRef = useRef<HTMLTextAreaElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (chatContainerRef.current) {
      chatContainerRef.current.scrollTo({
        top: chatContainerRef.current.scrollHeight,
        behavior: 'smooth'
      });
    }
  }, [messages, isLoading]);

  useEffect(() => {
    if (messages.length > 0 && !isFirstMessageSent) {
      setIsFirstMessageSent(true);
    }
  }, [messages.length, isFirstMessageSent]);

  const formatOutput = (text: string) => {
    return text.replace(/\*/g, '');
  };

  const handleSendMessage = useCallback(async (textOverride?: string) => {
    const textInput = (textOverride || input).trim();
    if ((!textInput && !selectedImage) || isLoading) return;

    const userMessageParts: ChatPart[] = [];
    if (selectedImage) userMessageParts.push({ inlineData: { mimeType: selectedImage.mimeType, data: selectedImage.data } });
    if (textInput) userMessageParts.push({ text: textInput });

    const userMessage: ChatMessage = { id: `msg-${Date.now()}`, role: 'user', parts: userMessageParts };
    const modelPlaceholder: ChatMessage = { id: `msg-${Date.now() + 1}`, role: 'model', parts: [{ text: '' }], isSearching: webSearchEnabled };

    setMessages(prev => [...prev, userMessage, modelPlaceholder]);
    setInput(''); 
    setSelectedImage(null);
    setIsLoading(true);

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const history = messages.map(msg => ({
        role: msg.role,
        parts: msg.parts.map(p => {
            if (p.text) return { text: p.text };
            if (p.inlineData) return { inlineData: p.inlineData };
            return null;
        }).filter(Boolean) as any[]
      }));

      const stream = await ai.models.generateContentStream({
          model: model as any,
          contents: [...history, { role: 'user', parts: userMessageParts as any }],
          config: { 
              systemInstruction: systemInstruction, 
              tools: webSearchEnabled ? [{ googleSearch: {} }] : [],
              temperature: 0.8 
          },
      });

      let fullText = '';
      let searchResults: SearchResult[] = [];

      for await (const chunk of stream) {
        if(chunk.text) {
            fullText += chunk.text;
            const cleanText = formatOutput(fullText);
            setMessages(prev => prev.map(m => m.id === modelPlaceholder.id ? { ...m, parts: [{ text: cleanText }], isSearching: false } : m));
        }
        const chunks = chunk.candidates?.[0]?.groundingMetadata?.groundingChunks;
        if (chunks) {
            const results = chunks.map((c: any) => c.web ? { ...c.web, type: 'web' } : null).filter(Boolean);
            searchResults = [...searchResults, ...results];
        }
      }

      if (searchResults.length > 0) {
        const unique = Array.from(new Map(searchResults.map(i => [i.uri, i])).values());
        setMessages(prev => prev.map(m => m.id === modelPlaceholder.id ? { ...m, parts: [{ ...m.parts[0], searchResults: unique }] } : m));
      }
    } catch (error) {
      setMessages(prev => prev.map(m => m.id === modelPlaceholder.id ? { ...m, parts: [{ text: `Error: ${error instanceof Error ? error.message : "Connection failed."}` }], isSearching: false } : m));
    } finally {
      setIsLoading(false);
    }
  }, [input, isLoading, messages, selectedImage, systemInstruction, model, webSearchEnabled, setMessages]);

  const adjustTextareaHeight = () => {
    if (textareaRef.current) {
      textareaRef.current.style.height = 'auto';
      textareaRef.current.style.height = `${Math.min(textareaRef.current.scrollHeight, 180)}px`;
    }
  };

  useEffect(() => {
    adjustTextareaHeight();
  }, [input]);

  return (
    <div className="flex flex-col h-full bg-white dark:bg-slate-900 relative">
      {/* Messages / Hero Section */}
      <div ref={chatContainerRef} className="flex-1 overflow-y-auto px-4 sm:px-6 md:px-8 pb-48 pt-6 custom-scrollbar scroll-smooth">
        {!isFirstMessageSent ? (
            <div className="max-w-4xl mx-auto flex flex-col items-center justify-center min-h-[70vh] text-center px-4 animate-fade-in transition-all duration-700 ease-out">
                 <div className="relative mb-6 transform hover:scale-110 transition-transform cursor-pointer">
                     <div className="absolute inset-0 bg-blue-500/10 rounded-full blur-3xl animate-pulse"></div>
                     <BotIcon className="relative w-24 h-24 sm:w-32 sm:h-32 drop-shadow-2xl" />
                 </div>
                 <h2 className="text-4xl sm:text-5xl md:text-6xl font-black text-slate-900 dark:text-white mb-4 tracking-tighter">
                   Ask Nexzi anything.
                 </h2>
                 <p className="text-slate-500 dark:text-slate-400 max-w-lg mb-12 text-lg sm:text-xl font-medium leading-relaxed">
                    Powered by Gemini 3 Flash. Built for the modern workspace.
                 </p>

                 <div className="grid grid-cols-1 sm:grid-cols-2 gap-4 w-full max-w-2xl px-2">
                     {[
                         { t: "Personal Summary", q: "Summarize my day as if you were a supportive coach", icon: <SparklesIcon className="w-5 h-5"/> },
                         { t: "Live Research", q: "Search for the latest breakthroughs in renewable energy this month", icon: <SearchIcon className="w-5 h-5"/> },
                         { t: "Code Review", q: "Explain the difference between useMemo and useCallback with code examples", icon: <BotIcon className="w-5 h-5"/> },
                         { t: "Creative Writing", q: "Write a short sci-fi story about an AI discovering music for the first time", icon: <SparklesIcon className="w-5 h-5"/> }
                     ].map((item, i) => (
                        <button 
                            key={i} 
                            onClick={() => handleSendMessage(item.q)}
                            className="text-left p-5 rounded-3xl border border-slate-200 dark:border-slate-800 hover:border-blue-500 dark:hover:border-blue-500/50 hover:bg-slate-50 dark:hover:bg-slate-800/50 transition-all group flex gap-5 items-center bg-white dark:bg-slate-900 shadow-sm"
                        >
                            <div className="w-12 h-12 rounded-2xl bg-slate-100 dark:bg-slate-800 flex items-center justify-center shrink-0 group-hover:bg-blue-600 group-hover:text-white transition-all">
                                {item.icon}
                            </div>
                            <div className="min-w-0">
                                <p className="font-bold text-slate-900 dark:text-white text-sm sm:text-base truncate">{item.t}</p>
                                <p className="text-[10px] text-slate-400 font-bold uppercase truncate tracking-widest mt-0.5">Quick Prompt</p>
                            </div>
                        </button>
                     ))}
                 </div>
            </div>
        ) : (
            <div className="max-w-3xl mx-auto space-y-12 animate-fade-in-up pb-10">
                {messages.map((msg) => (
                    <div key={msg.id} className={`flex gap-4 sm:gap-6 group ${msg.role === 'user' ? 'flex-row-reverse' : 'flex-row'}`}>
                        <div className={`w-9 h-9 sm:w-11 sm:h-11 shrink-0 rounded-2xl flex items-center justify-center shadow-lg
                            ${msg.role === 'user' ? 'bg-slate-100 dark:bg-slate-800 text-slate-500 border border-slate-200 dark:border-slate-700' : 'bg-gradient-to-tr from-blue-600 to-indigo-600 text-white'}
                        `}>
                             {msg.role === 'user' ? <UserIcon className="w-6 h-6"/> : <BotIcon className="w-7 h-7 sm:w-9 sm:h-9"/>}
                        </div>

                        <div className={`flex flex-col gap-3 max-w-[90%] sm:max-w-[85%] ${msg.role === 'user' ? 'items-end' : 'items-start'}`}>
                             {msg.parts.map((part, i) => (
                                 <div key={i} className={`relative leading-relaxed transition-all
                                     ${msg.role === 'user' 
                                         ? 'bg-blue-600 text-white px-6 py-4 rounded-[2rem] rounded-tr-sm shadow-xl font-medium text-sm sm:text-base' 
                                         : 'text-slate-800 dark:text-slate-100 text-base sm:text-lg'}
                                 `}>
                                     {part.inlineData && <img src={`data:${part.inlineData.mimeType};base64,${part.inlineData.data}`} className="rounded-2xl mb-6 max-h-[500px] shadow-2xl border border-slate-200 dark:border-slate-800 object-contain" alt="Context"/>}

                                     {msg.isSearching && i === 0 && (
                                         <div className="flex items-center gap-3 text-blue-500 mb-6 animate-pulse-soft bg-blue-50 dark:bg-blue-900/20 px-4 py-2 rounded-full border border-blue-500/20 w-fit">
                                             <div className="w-4 h-4 border-2 border-blue-500 border-t-transparent rounded-full animate-spin"></div>
                                             <span className="text-[10px] font-black uppercase tracking-[0.2em]">Neural Research Link Active</span>
                                         </div>
                                     )}

                                     <div className="whitespace-pre-wrap prose prose-sm sm:prose-base md:prose-lg dark:prose-invert max-w-none font-medium leading-relaxed">{part.text}</div>

                                     {part.searchResults && part.searchResults.length > 0 && (
                                         <div className="mt-8 pt-8 border-t border-slate-100 dark:border-slate-800">
                                            <p className="text-[10px] font-black text-slate-400 uppercase tracking-[0.3em] mb-4 flex items-center gap-2">
                                                Verified Grounding Nodes <span className="h-px bg-slate-100 dark:bg-slate-800 flex-1"></span>
                                            </p>
                                            <div className="flex gap-4 overflow-x-auto pb-4 no-scrollbar scroll-smooth">
                                                {part.searchResults.map((res, idx) => <SourceCard key={idx} result={res} />)}
                                            </div>
                                         </div>
                                     )}
                                 </div>
                             ))}
                        </div>
                    </div>
                ))}
                {isLoading && (
                  <div className="flex gap-4 sm:gap-6 items-center">
                    <div className="w-9 h-9 sm:w-11 sm:h-11 shrink-0 rounded-2xl bg-gradient-to-tr from-blue-600 to-indigo-600 flex items-center justify-center shadow-lg">
                      <BotIcon className="w-7 h-7 sm:w-9 sm:h-9 animate-pulse" />
                    </div>
                    <div className="flex gap-1.5 p-4 bg-slate-50 dark:bg-slate-800/50 rounded-2xl">
                      <div className="w-2 h-2 bg-blue-500 rounded-full animate-bounce [animation-delay:-0.3s]"></div>
                      <div className="w-2 h-2 bg-blue-500 rounded-full animate-bounce [animation-delay:-0.15s]"></div>
                      <div className="w-2 h-2 bg-blue-500 rounded-full animate-bounce"></div>
                    </div>
                  </div>
                )}
            </div>
        )}
      </div>

      {/* Input Section - Optimized for Responsiveness */}
      <div className={`absolute bottom-0 left-0 right-0 px-4 sm:px-6 md:px-12 pb-8 pt-12 transition-all duration-700 ${!isFirstMessageSent ? 'translate-y-0 sm:-translate-y-12' : 'bg-gradient-to-t from-white dark:from-slate-900 via-white/95 dark:via-slate-900/95 to-transparent'}`}>
          <div className="max-w-3xl mx-auto relative group pointer-events-auto">

              <div className="bg-white dark:bg-slate-800/90 backdrop-blur-3xl rounded-[2rem] sm:rounded-[3rem] shadow-[0_20px_60px_-15px_rgba(0,0,0,0.15)] dark:shadow-[0_40px_100px_-20px_rgba(0,0,0,0.5)] border border-slate-200/60 dark:border-slate-700/60 transition-all focus-within:ring-8 ring-blue-500/5 overflow-hidden">

                   {/* Tool Bar */}
                   <div className="flex items-center justify-between px-6 sm:px-8 pt-4 pb-2 border-b border-slate-100 dark:border-slate-700/40">
                       <div className="flex items-center gap-4 relative">
                           {/* Model Switcher Pill */}
                           <div className="relative">
                                <button 
                                    onClick={() => setIsModelDropdownOpen(!isModelDropdownOpen)}
                                    className="flex items-center gap-3 px-4 py-2 bg-slate-900 dark:bg-slate-950 text-white rounded-full hover:bg-black transition-all shadow-md active:scale-95"
                                >
                                    <span className="text-[10px] font-black tracking-widest uppercase whitespace-nowrap">
                                        {model === 'gemini-3-flash-preview' ? 'Flash 3' : 'Pro 3'}
                                    </span>
                                    <svg className={`w-3.5 h-3.5 transition-transform ${isModelDropdownOpen ? 'rotate-180' : ''}`} fill="none" stroke="currentColor" viewBox="0 0 24 24" strokeWidth="3"><path strokeLinecap="round" strokeLinejoin="round" d="M19 9l-7 7-7-7"/></svg>
                                </button>

                                {isModelDropdownOpen && (
                                    <div className="absolute top-full left-0 mt-3 w-44 bg-slate-900 text-white rounded-3xl shadow-2xl border border-white/10 z-[100] overflow-hidden animate-fade-in">
                                        {[
                                            { id: 'gemini-3-flash-preview', label: 'Flash 3 (Fast)' },
                                            { id: 'gemini-3-pro-preview', label: 'Pro 3 (Deep)' }
                                        ].map(m => (
                                            <button 
                                                key={m.id}
                                                onClick={() => { setActiveModel(m.id as any); setIsModelDropdownOpen(false); }}
                                                className="w-full text-left px-5 py-3.5 hover:bg-white/10 transition-colors border-b border-white/5 last:border-none text-[11px] font-black uppercase tracking-widest"
                                            >
                                                {m.label}
                                            </button>
                                        ))}
                                    </div>
                                )}
                           </div>

                           <button 
                                onClick={() => setWebSearchEnabled(!webSearchEnabled)}
                                className={`flex items-center gap-2 px-4 py-2 rounded-full border transition-all ${webSearchEnabled ? 'bg-blue-600 border-blue-600 text-white shadow-lg' : 'bg-slate-50 dark:bg-slate-900 border-slate-200 dark:border-slate-700 text-slate-400'}`}
                            >
                                <SearchIcon className="w-4 h-4" />
                                <span className="text-[10px] font-black uppercase tracking-widest hidden sm:inline">Grounding</span>
                            </button>
                       </div>

                       <div className="flex gap-2 text-slate-400">
                           <SparklesIcon className="w-4 h-4 hidden xs:block"/>
                       </div>
                   </div>

                   {/* Main Input */}
                   <div className="p-4 sm:p-5 flex items-end gap-3">
                        <button 
                            onClick={() => fileInputRef.current?.click()} 
                            className="p-4 rounded-3xl text-slate-400 hover:bg-slate-100 dark:hover:bg-slate-800 hover:text-blue-500 transition-all shrink-0"
                            title="Context Link"
                        >
                            <ImageIcon className="w-6 h-6 sm:w-7 sm:h-7"/>
                            <input type="file" ref={fileInputRef} onChange={(e) => {
                                    const file = e.target.files?.[0];
                                    if (file) {
                                        const reader = new FileReader();
                                        reader.onloadend = () => {
                                            setSelectedImage({ data: (reader.result as string).split(',')[1], mimeType: file.type });
                                        };
                                        reader.readAsDataURL(file);
                                    }
                            }} accept="image/*" className="hidden" />
                        </button>

                        <textarea
                            ref={textareaRef}
                            value={input}
                            onChange={e => setInput(e.target.value)}
                            onKeyDown={e => e.key === 'Enter' && !e.shiftKey && (e.preventDefault(), handleSendMessage())}
                            placeholder="Ask Nexzi anything..."
                            className="flex-1 bg-transparent border-none outline-none resize-none py-4 px-2 text-slate-900 dark:text-white placeholder-slate-400 dark:placeholder-slate-500 text-lg sm:text-xl font-medium leading-relaxed max-h-[180px] min-h-[48px]"
                            rows={1}
                        />

                        <button 
                            onClick={() => handleSendMessage()} 
                            disabled={isLoading || (!input && !selectedImage)} 
                            className={`w-14 h-14 rounded-3xl text-white transition-all duration-500 transform active:scale-90 disabled:opacity-30 flex items-center justify-center shrink-0
                                ${input || selectedImage ? 'bg-blue-600 shadow-2xl shadow-blue-500/30 hover:scale-105 active:bg-blue-700' : 'bg-slate-100 dark:bg-slate-700 text-slate-300'}
                            `}
                        >
                             <SendIcon className="w-7 h-7 sm:w-8 sm:h-8"/>
                        </button>
                   </div>
              </div>

              {selectedImage && (
                  <div className="absolute -top-28 left-6 p-3 bg-white dark:bg-slate-800 rounded-3xl shadow-2xl border border-slate-200 dark:border-slate-700 flex items-center gap-4 animate-fade-in group pointer-events-auto">
                      <div className="relative overflow-hidden rounded-2xl w-20 h-20">
                        <img src={`data:${selectedImage.mimeType};base64,${selectedImage.data}`} className="w-full h-full object-cover" />
                        <div className="absolute inset-0 bg-black/10"></div>
                      </div>
                      <button onClick={() => setSelectedImage(null)} className="p-2 bg-red-500 text-white rounded-full hover:bg-red-600 transition-all shadow-xl hover:scale-110">
                          <svg className="w-4 h-4" fill="currentColor" viewBox="0 0 20 20"><path d="M4.293 4.293a1 1 0 011.414 0L10 8.586l4.293-4.293a1 1 0 111.414 1.414L11.414 10l4.293 4.293a1 1 0 01-1.414 1.414L10 11.414l-4.293 4.293a1 1 0 01-1.414-1.414L8.586 10 4.293 5.707a1 1 0 010-1.414z"/></svg>
                      </button>
                  </div>
              )}
          </div>
          <p className="max-w-xl mx-auto text-center mt-5 text-[9px] text-slate-400 font-bold uppercase tracking-[0.3em] hidden sm:block opacity-60">
            Powered by Gemini 3 Flash • NEXZI Neural Node v2.5
          </p>
      </div>
    </div>
  );
};

export type Mode = 'chat' | 'live' | 'friends' | 'toolbox' | 'memory' | 'community' | 'coding';
export type UIStyle = 'modern' | 'glass' | 'brutal' | 'retro';
export type AccentColor = 'blue' | 'violet' | 'emerald' | 'rose' | 'amber';
export type FontSize = 'small' | 'normal' | 'large';
export type ModelType = 'gemini-3-flash-preview' | 'gemini-3-pro-preview';

export interface Friend {
  id: string;
  name: string;
  avatar: string;
  status: 'online' | 'offline' | 'busy' | 'away';
  isFollowing?: boolean;
}

export interface CommunityReply {
    id: string;
    author: string;
    content: string;
    timestamp: number;
}

export interface CommunityPost {
    id: string;
    author: string;
    authorId: string;
    content: string;
    timestamp: number;
    likedBy: string[]; // User IDs who liked
    replies: CommunityReply[];
    type: 'text' | 'image' | 'code';
    mediaUrl?: string;
}

export interface MemoryFact {
    id: string;
    category: 'preference' | 'project' | 'personal' | 'work';
    content: string;
    timestamp: string;
}

export interface ThemeColors {
    primary: string;
    primaryHover: string;
    text: string;
    textDark: string;
    bgSoft: string;
    darkBgSoft: string;
    border: string;
    ring: string;
    gradient: string;
}

export interface SearchResult {
  uri: string;
  title: string;
  type?: 'web' | 'map';
}

export interface ChatPart {
  text?: string;
  inlineData?: {
    mimeType: string;
    data: string; // base64 encoded
  };
  functionCall?: {
    name: string;
    args: any;
  };
  searchResults?: SearchResult[];
}

export interface ChatMessage {
  id: string;
  role: 'user' | 'model';
  parts: ChatPart[];
  isSearching?: boolean;
}

export interface ChatSession {
  id:string;
  title: string;
  messages: ChatMessage[];
}

import React, { useState, useRef, useEffect, useCallback } from 'react';
import type { ChatMessage, ChatPart, SearchResult, UIStyle, ThemeColors, FontSize, ModelType } from '../types';
import { GoogleGenAI } from "@google/genai";
import { BotIcon, SendIcon, UserIcon, ImageIcon, SpeakerIcon, CopyIcon, SearchIcon, SparklesIcon } from './Icons';

interface ChatViewProps {
  messages: ChatMessage[];
  setMessages: React.Dispatch<React.SetStateAction<ChatMessage[]>>;
  uiStyle: UIStyle;
  theme: ThemeColors;
  fontSize: FontSize;
  systemInstruction: string;
  model: ModelType;
  setActiveModel: (m: ModelType) => void;
}

const SourceCard: React.FC<{ result: SearchResult }> = ({ result }) => (
    <a 
        href={result.uri} 
        target="_blank" 
        rel="noopener noreferrer"
        className="flex items-center gap-3 p-3 bg-white/50 dark:bg-slate-800/50 backdrop-blur-sm border border-slate-200 dark:border-slate-700 rounded-2xl hover:border-blue-500 dark:hover:border-blue-400 transition-all group shrink-0 max-w-[180px] shadow-sm"
    >
        <div className="w-8 h-8 rounded-lg bg-blue-100 dark:bg-blue-900/40 flex items-center justify-center shrink-0">
            <SearchIcon className="w-4 h-4 text-blue-600 dark:text-blue-400" />
        </div>
        <div className="flex-1 min-w-0">
            <p className="text-[11px] font-bold text-slate-900 dark:text-slate-100 truncate">{result.title}</p>
            <p className="text-[9px] text-slate-400 truncate uppercase tracking-tight">{new URL(result.uri).hostname}</p>
        </div>
    </a>
);

export const ChatView: React.FC<ChatViewProps> = ({ messages, setMessages, theme, systemInstruction, model, setActiveModel }) => {
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [selectedImage, setSelectedImage] = useState<{ data: string; mimeType: string } | null>(null);
  const [webSearchEnabled, setWebSearchEnabled] = useState(true);
  const [isModelDropdownOpen, setIsModelDropdownOpen] = useState(false);
  const [isFirstMessageSent, setIsFirstMessageSent] = useState(messages.length > 0);

  const chatContainerRef = useRef<HTMLDivElement>(null);
  const textareaRef = useRef<HTMLTextAreaElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (chatContainerRef.current) {
      chatContainerRef.current.scrollTo({
        top: chatContainerRef.current.scrollHeight,
        behavior: 'smooth'
      });
    }
  }, [messages, isLoading]);

  useEffect(() => {
    if (messages.length > 0 && !isFirstMessageSent) {
      setIsFirstMessageSent(true);
    }
  }, [messages.length, isFirstMessageSent]);

  const formatOutput = (text: string) => {
    return text.replace(/\*/g, '');
  };

  const handleSendMessage = useCallback(async (textOverride?: string) => {
    const textInput = (textOverride || input).trim();
    if ((!textInput && !selectedImage) || isLoading) return;

    const userMessageParts: ChatPart[] = [];
    if (selectedImage) userMessageParts.push({ inlineData: { mimeType: selectedImage.mimeType, data: selectedImage.data } });
    if (textInput) userMessageParts.push({ text: textInput });

    const userMessage: ChatMessage = { id: `msg-${Date.now()}`, role: 'user', parts: userMessageParts };
    const modelPlaceholder: ChatMessage = { id: `msg-${Date.now() + 1}`, role: 'model', parts: [{ text: '' }], isSearching: webSearchEnabled };

    setMessages(prev => [...prev, userMessage, modelPlaceholder]);
    setInput(''); 
    setSelectedImage(null);
    setIsLoading(true);

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const history = messages.map(msg => ({
        role: msg.role,
        parts: msg.parts.map(p => {
            if (p.text) return { text: p.text };
            if (p.inlineData) return { inlineData: p.inlineData };
            return null;
        }).filter(Boolean) as any[]
      }));

      const stream = await ai.models.generateContentStream({
          model: model as any,
          contents: [...history, { role: 'user', parts: userMessageParts as any }],
          config: { 
              systemInstruction: systemInstruction, 
              tools: webSearchEnabled ? [{ googleSearch: {} }] : [],
              temperature: 0.8 
          },
      });

      let fullText = '';
      let searchResults: SearchResult[] = [];

      for await (const chunk of stream) {
        if(chunk.text) {
            fullText += chunk.text;
            const cleanText = formatOutput(fullText);
            setMessages(prev => prev.map(m => m.id === modelPlaceholder.id ? { ...m, parts: [{ text: cleanText }], isSearching: false } : m));
        }
        const chunks = chunk.candidates?.[0]?.groundingMetadata?.groundingChunks;
        if (chunks) {
            const results = chunks.map((c: any) => c.web ? { ...c.web, type: 'web' } : null).filter(Boolean);
            searchResults = [...searchResults, ...results];
        }
      }

      if (searchResults.length > 0) {
        const unique = Array.from(new Map(searchResults.map(i => [i.uri, i])).values());
        setMessages(prev => prev.map(m => m.id === modelPlaceholder.id ? { ...m, parts: [{ ...m.parts[0], searchResults: unique }] } : m));
      }
    } catch (error) {
      setMessages(prev => prev.map(m => m.id === modelPlaceholder.id ? { ...m, parts: [{ text: `Error: ${error instanceof Error ? error.message : "Connection failed."}` }], isSearching: false } : m));
    } finally {
      setIsLoading(false);
    }
  }, [input, isLoading, messages, selectedImage, systemInstruction, model, webSearchEnabled, setMessages]);

  const adjustTextareaHeight = () => {
    if (textareaRef.current) {
      textareaRef.current.style.height = 'auto';
      textareaRef.current.style.height = `${Math.min(textareaRef.current.scrollHeight, 180)}px`;
    }
  };

  useEffect(() => {
    adjustTextareaHeight();
  }, [input]);

  const modelLabels: Record<string, string> = {
    'gemini-3-flash-preview': 'Flash 3',
    'gemini-3-pro-preview': 'Pro 3',
    'gemini-2.5-flash-latest': 'Flash 2.5',
    'gemini-2.5-flash-lite-latest': 'Lite 2.5'
  };

  return (
    <div className="flex flex-col h-full bg-white dark:bg-slate-900 relative">
      {/* Messages / Hero Section */}
      <div ref={chatContainerRef} className="flex-1 overflow-y-auto px-4 sm:px-6 md:px-8 pb-48 pt-6 custom-scrollbar scroll-smooth">
        {!isFirstMessageSent ? (
            <div className="max-w-4xl mx-auto flex flex-col items-center justify-center min-h-[70vh] text-center px-4 animate-fade-in transition-all duration-700 ease-out">
                 <div className="relative mb-6 transform hover:scale-110 transition-transform cursor-pointer">
                     <div className="absolute inset-0 bg-blue-500/10 rounded-full blur-3xl animate-pulse"></div>
                     <BotIcon className="relative w-20 h-20 sm:w-32 sm:h-32 drop-shadow-2xl" />
                 </div>
                 <h2 className="text-3xl sm:text-5xl md:text-6xl font-black text-slate-900 dark:text-white mb-4 tracking-tighter">
                   Ask Nexzi anything.
                 </h2>
                 <p className="text-slate-500 dark:text-slate-400 max-w-lg mb-12 text-base sm:text-lg md:text-xl font-medium leading-relaxed">
                    Personal intelligence for the modern world. Powered by Gemini.
                 </p>

                 <div className="grid grid-cols-1 sm:grid-cols-2 gap-4 w-full max-w-2xl px-2">
                     {[
                         { t: "Code Review", q: "Explain the difference between useMemo and useCallback with code examples", icon: <BotIcon className="w-5 h-5"/> },
                         { t: "Creative Writing", q: "Write a short sci-fi story about an AI discovering music for the first time", icon: <SparklesIcon className="w-5 h-5"/> }
                     ].map((item, i) => (
                        <button 
                            key={i} 
                            onClick={() => handleSendMessage(item.q)}
                            className="text-left p-5 rounded-3xl border border-slate-200 dark:border-slate-800 hover:border-blue-500 dark:hover:border-blue-500/50 hover:bg-slate-50 dark:hover:bg-slate-800/50 transition-all group flex gap-5 items-center bg-white dark:bg-slate-900 shadow-sm"
                        >
                            <div className="w-10 h-10 sm:w-12 sm:h-12 rounded-2xl bg-slate-100 dark:bg-slate-800 flex items-center justify-center shrink-0 group-hover:bg-blue-600 group-hover:text-white transition-all">
                                {item.icon}
                            </div>
                            <div className="min-w-0">
                                <p className="font-bold text-slate-900 dark:text-white text-sm sm:text-base truncate">{item.t}</p>
                                <p className="text-[10px] text-slate-400 font-bold uppercase truncate tracking-widest mt-0.5">Quick Prompt</p>
                            </div>
                        </button>
                     ))}
                 </div>
            </div>
        ) : (
            <div className="max-w-3xl mx-auto space-y-12 animate-fade-in-up pb-10">
                {messages.map((msg) => (
                    <div key={msg.id} className={`flex gap-4 sm:gap-6 group ${msg.role === 'user' ? 'flex-row-reverse' : 'flex-row'}`}>
                        <div className={`w-8 h-8 sm:w-10 sm:h-10 shrink-0 rounded-2xl flex items-center justify-center shadow-lg
                            ${msg.role === 'user' ? 'bg-slate-100 dark:bg-slate-800 text-slate-500 border border-slate-200 dark:border-slate-700' : 'bg-gradient-to-tr from-blue-600 to-indigo-600 text-white'}
                        `}>
                             {msg.role === 'user' ? <UserIcon className="w-5 h-5 sm:w-6 sm:h-6"/> : <BotIcon className="w-6 h-6 sm:w-8 sm:h-8"/>}
                        </div>

                        <div className={`flex flex-col gap-3 max-w-[90%] sm:max-w-[85%] ${msg.role === 'user' ? 'items-end' : 'items-start'}`}>
                             {msg.parts.map((part, i) => (
                                 <div key={i} className={`relative leading-relaxed transition-all
                                     ${msg.role === 'user' 
                                         ? 'bg-blue-600 text-white px-5 py-3 rounded-2xl rounded-tr-sm shadow-xl font-medium text-sm sm:text-base' 
                                         : 'text-slate-800 dark:text-slate-100 text-base sm:text-lg'}
                                 `}>
                                     {part.inlineData && <img src={`data:${part.inlineData.mimeType};base64,${part.inlineData.data}`} className="rounded-2xl mb-6 max-h-[500px] shadow-2xl border border-slate-200 dark:border-slate-800 object-contain" alt="Context"/>}

                                     {msg.isSearching && i === 0 && (
                                         <div className="flex items-center gap-3 text-blue-500 mb-6 animate-pulse-soft bg-blue-50 dark:bg-blue-900/20 px-4 py-2 rounded-full border border-blue-500/20 w-fit">
                                             <div className="w-4 h-4 border-2 border-blue-500 border-t-transparent rounded-full animate-spin"></div>
                                             <span className="text-[10px] font-black uppercase tracking-[0.2em]">Neural Research Active</span>
                                         </div>
                                     )}

                                     <div className="whitespace-pre-wrap prose prose-sm sm:prose-base dark:prose-invert max-w-none font-medium leading-relaxed">{part.text}</div>

                                     {part.searchResults && part.searchResults.length > 0 && (
                                         <div className="mt-8 pt-8 border-t border-slate-100 dark:border-slate-800">
                                            <p className="text-[10px] font-black text-slate-400 uppercase tracking-[0.3em] mb-4 flex items-center gap-2">
                                                Grounding Nodes <span className="h-px bg-slate-100 dark:bg-slate-800 flex-1"></span>
                                            </p>
                                            <div className="flex gap-4 overflow-x-auto pb-4 no-scrollbar scroll-smooth">
                                                {part.searchResults.map((res, idx) => <SourceCard key={idx} result={res} />)}
                                            </div>
                                         </div>
                                     )}
                                 </div>
                             ))}
                        </div>
                    </div>
                ))}
                {isLoading && (
                  <div className="flex gap-4 sm:gap-6 items-center">
                    <div className="w-8 h-8 sm:w-10 sm:h-10 shrink-0 rounded-2xl bg-gradient-to-tr from-blue-600 to-indigo-600 flex items-center justify-center shadow-lg">
                      <BotIcon className="w-6 h-6 sm:w-8 sm:h-8 animate-pulse" />
                    </div>
                    <div className="flex gap-1.5 p-3 sm:p-4 bg-slate-50 dark:bg-slate-800/50 rounded-2xl">
                      <div className="w-1.5 h-1.5 bg-blue-500 rounded-full animate-bounce [animation-delay:-0.3s]"></div>
                      <div className="w-1.5 h-1.5 bg-blue-500 rounded-full animate-bounce [animation-delay:-0.15s]"></div>
                      <div className="w-1.5 h-1.5 bg-blue-500 rounded-full animate-bounce"></div>
                    </div>
                  </div>
                )}
            </div>
        )}
      </div>

      {/* Input Section - Refined UX and Responsiveness */}
      <div className={`absolute bottom-0 left-0 right-0 px-4 sm:px-6 md:px-12 pb-6 sm:pb-8 pt-12 transition-all duration-700 ${!isFirstMessageSent ? 'translate-y-0 sm:-translate-y-12' : 'bg-gradient-to-t from-white dark:from-slate-900 via-white/95 dark:via-slate-900/95 to-transparent'}`}>
          <div className="max-w-3xl mx-auto relative group pointer-events-auto">

              <div className="bg-white dark:bg-slate-800/90 backdrop-blur-3xl rounded-[2rem] sm:rounded-[3rem] shadow-[0_15px_45px_-10px_rgba(0,0,0,0.1)] dark:shadow-[0_40px_100px_-20px_rgba(0,0,0,0.5)] border border-slate-200/60 dark:border-slate-700/60 transition-all focus-within:ring-4 sm:focus-within:ring-8 ring-blue-500/5 overflow-hidden">

                   {/* Tool Bar */}
                   <div className="flex items-center justify-between px-5 sm:px-8 pt-3 sm:pt-4 pb-2 border-b border-slate-100 dark:border-slate-700/40">
                       <div className="flex items-center gap-3 sm:gap-4 relative">
                           {/* Model Switcher Pill */}
                           <div className="relative">
                                <button 
                                    onClick={() => setIsModelDropdownOpen(!isModelDropdownOpen)}
                                    className="flex items-center gap-2 sm:gap-3 px-3 sm:px-4 py-1.5 bg-slate-900 dark:bg-slate-950 text-white rounded-full hover:bg-black transition-all shadow-md active:scale-95"
                                >
                                    <span className="text-[9px] sm:text-[10px] font-black tracking-widest uppercase whitespace-nowrap">
                                        {modelLabels[model] || 'Gemini'}
                                    </span>
                                    <svg className={`w-3 h-3 transition-transform ${isModelDropdownOpen ? 'rotate-180' : ''}`} fill="none" stroke="currentColor" viewBox="0 0 24 24" strokeWidth="3"><path strokeLinecap="round" strokeLinejoin="round" d="M19 9l-7 7-7-7"/></svg>
                                </button>

                                {isModelDropdownOpen && (
                                    <div className="absolute top-full left-0 mt-3 w-48 bg-slate-900 text-white rounded-3xl shadow-2xl border border-white/10 z-[100] overflow-hidden animate-fade-in">
                                        {[
                                            { id: 'gemini-3-flash-preview', label: 'Flash 3 (Ultra-Fast)' },
                                            { id: 'gemini-3-pro-preview', label: 'Pro 3 (Deep Reasoning)' },
                                            { id: 'gemini-2.5-flash-latest', label: 'Flash 2.5 (Stable)' },
                                            { id: 'gemini-2.5-flash-lite-latest', label: 'Lite 2.5 (Efficient)' }
                                        ].map(m => (
                                            <button 
                                                key={m.id}
                                                onClick={() => { setActiveModel(m.id as any); setIsModelDropdownOpen(false); }}
                                                className={`w-full text-left px-5 py-3.5 hover:bg-white/10 transition-colors border-b border-white/5 last:border-none text-[10px] font-black uppercase tracking-widest ${model === m.id ? 'text-blue-400' : 'text-white'}`}
                                            >
                                                {m.label}
                                            </button>
                                        ))}
                                    </div>
                                )}
                           </div>

                           <button 
                                onClick={() => setWebSearchEnabled(!webSearchEnabled)}
                                className={`flex items-center gap-2 px-3 sm:px-4 py-1.5 rounded-full border transition-all ${webSearchEnabled ? 'bg-blue-600 border-blue-600 text-white shadow-md' : 'bg-slate-50 dark:bg-slate-900 border-slate-200 dark:border-slate-700 text-slate-400'}`}
                            >
                                <SearchIcon className="w-3.5 h-3.5" />
                                <span className="text-[9px] font-black uppercase tracking-widest hidden xs:inline">Grounding</span>
                            </button>
                       </div>

                       <div className="flex gap-2 text-slate-400">
                           <SparklesIcon className="w-4 h-4 hidden sm:block"/>
                       </div>
                   </div>

                   {/* Main Input */}
                   <div className="p-3 sm:p-5 flex items-end gap-2 sm:gap-3">
                        <button 
                            onClick={() => fileInputRef.current?.click()} 
                            className="p-3 sm:p-4 rounded-2xl sm:rounded-3xl text-slate-500 bg-slate-50 dark:bg-slate-900/40 hover:bg-blue-50 dark:hover:bg-blue-900/20 hover:text-blue-600 transition-all shrink-0 border border-transparent hover:border-blue-500/20 shadow-sm"
                            title="Add File"
                        >
                            <ImageIcon className="w-5 h-5 sm:w-7 sm:h-7"/>
                            <input type="file" ref={fileInputRef} onChange={(e) => {
                                    const file = e.target.files?.[0];
                                    if (file) {
                                        const reader = new FileReader();
                                        reader.onloadend = () => {
                                            setSelectedImage({ data: (reader.result as string).split(',')[1], mimeType: file.type });
                                        };
                                        reader.readAsDataURL(file);
                                    }
                            }} accept="image/*" className="hidden" />
                        </button>

                        <textarea
                            ref={textareaRef}
                            value={input}
                            onChange={e => setInput(e.target.value)}
                            onKeyDown={e => e.key === 'Enter' && !e.shiftKey && (e.preventDefault(), handleSendMessage())}
                            placeholder="Ask Nexzi anything..."
                            className="flex-1 bg-transparent border-none outline-none resize-none py-3 sm:py-4 px-2 text-slate-900 dark:text-white placeholder-slate-400 dark:placeholder-slate-500 text-base sm:text-lg md:text-xl font-medium leading-relaxed max-h-[160px] min-h-[44px]"
                            rows={1}
                        />

                        <button 
                            onClick={() => handleSendMessage()} 
                            disabled={isLoading || (!input && !selectedImage)} 
                            className={`w-11 h-11 sm:w-14 sm:h-14 rounded-2xl sm:rounded-3xl text-white transition-all duration-300 transform active:scale-90 disabled:opacity-30 flex items-center justify-center shrink-0
                                ${input || selectedImage ? 'bg-blue-600 shadow-xl shadow-blue-500/20 hover:scale-105 active:bg-blue-700' : 'bg-slate-100 dark:bg-slate-700 text-slate-300'}
                            `}
                        >
                             <SendIcon className="w-6 h-6 sm:w-7 sm:h-7"/>
                        </button>
                   </div>
              </div>

              {selectedImage && (
                  <div className="absolute -top-24 left-4 p-2 bg-white dark:bg-slate-800 rounded-2xl shadow-2xl border border-slate-200 dark:border-slate-700 flex items-center gap-3 animate-fade-in group pointer-events-auto">
                      <div className="relative overflow-hidden rounded-xl w-14 h-14">
                        <img src={`data:${selectedImage.mimeType};base64,${selectedImage.data}`} className="w-full h-full object-cover" />
                        <div className="absolute inset-0 bg-black/10"></div>
                      </div>
                      <button onClick={() => setSelectedImage(null)} className="p-1.5 bg-red-500 text-white rounded-full hover:bg-red-600 transition-all shadow-md">
                          <svg className="w-3 h-3" fill="currentColor" viewBox="0 0 20 20"><path d="M4.293 4.293a1 1 0 011.414 0L10 8.586l4.293-4.293a1 1 0 111.414 1.414L11.414 10l4.293 4.293a1 1 0 01-1.414 1.414L10 11.414l-4.293 4.293a1 1 0 01-1.414-1.414L8.586 10 4.293 5.707a1 1 0 010-1.414z"/></svg>
                      </button>
                  </div>
              )}
          </div>
          <p className="max-w-xl mx-auto text-center mt-4 text-[9px] text-slate-400 font-bold uppercase tracking-[0.2em] hidden sm:block opacity-60">
            NEXZI Neural v2.5 • Gemini Intelligence Node
          </p>
      </div>
    </div>
  );
};

