                                            </p>
                                            <div className="flex gap-4 overflow-x-auto pb-4 no-scrollbar scroll-smooth">
                                                {part.searchResults.map((res, idx) => <SourceCard key={idx} result={res} />)}
                                            </div>
                                         </div>
                                     )}
                                 </div>
                             ))}
                        </div>
                    </div>
                ))}
                {isLoading && (
                  <div className="flex gap-4 sm:gap-6 items-center animate-fade-in">
                    <div className="w-8 h-8 sm:w-10 sm:h-10 shrink-0 rounded-2xl bg-gradient-to-tr from-blue-600 to-indigo-600 flex items-center justify-center shadow-lg">
                      <BotIcon className="w-6 h-6 sm:w-8 sm:h-8 animate-pulse" />
                    </div>
                    <div className="flex gap-1.5 p-3 sm:p-4 bg-slate-50 dark:bg-slate-800/50 rounded-2xl shadow-inner">
                      <div className="w-2 h-2 bg-blue-500 rounded-full animate-bounce [animation-delay:-0.3s]"></div>
                      <div className="w-2 h-2 bg-blue-500 rounded-full animate-bounce [animation-delay:-0.15s]"></div>
                      <div className="w-2 h-2 bg-blue-500 rounded-full animate-bounce"></div>
                    </div>
                  </div>
                )}
            </div>
        )}
      </div>

      {/* Input Section - Refined UX and Responsiveness */}
      <div className={`absolute bottom-0 left-0 right-0 px-4 sm:px-6 md:px-12 pb-6 sm:pb-10 pt-12 transition-all duration-700 ease-in-out ${!isFirstMessageSent ? 'translate-y-0' : 'bg-gradient-to-t from-white dark:from-slate-900 via-white/95 dark:via-slate-900/95 to-transparent'}`}>
          <div className="max-w-3xl mx-auto relative group pointer-events-auto">

              <div className="bg-white dark:bg-slate-800/95 backdrop-blur-3xl rounded-[2rem] sm:rounded-[2.5rem] shadow-[0_25px_50px_-12px_rgba(0,0,0,0.15)] dark:shadow-[0_40px_100px_-20px_rgba(0,0,0,0.6)] border border-slate-200/60 dark:border-slate-700/60 transition-all focus-within:ring-4 sm:focus-within:ring-[12px] ring-blue-500/5 overflow-hidden">

                   {/* Tool Bar */}
                   <div className="flex items-center justify-between px-5 sm:px-8 pt-4 pb-2 border-b border-slate-100 dark:border-slate-700/40">
                       <div className="flex items-center gap-3 sm:gap-5 relative">
                           {/* Model Switcher Pill */}
