                            `}
                        >
                             <SendIcon className="w-6 h-6 sm:w-8 sm:h-8"/>
                        </button>
                   </div>
              </div>

              {selectedImage && (
                  <div className="absolute -top-28 left-4 p-3 bg-white dark:bg-slate-800 rounded-[2rem] shadow-2xl border border-slate-200 dark:border-slate-700 flex items-center gap-4 animate-fade-in-up group pointer-events-auto">
                      <div className="relative overflow-hidden rounded-2xl w-16 h-16 sm:w-20 sm:h-20 border border-slate-100 dark:border-slate-700">
