                      </div>
                      <button onClick={() => setSelectedImage(null)} className="p-2 bg-red-500 text-white rounded-full hover:bg-red-600 transition-all shadow-lg active:scale-90">
                          <svg className="w-4 h-4" fill="currentColor" viewBox="0 0 20 20"><path d="M4.293 4.293a1 1 0 011.414 0L10 8.586l4.293-4.293a1 1 0 111.414 1.414L11.414 10l4.293 4.293a1 1 0 01-1.414 1.414L10 11.414l-4.293 4.293a1 1 0 01-1.414-1.414L8.586 10 4.293 5.707a1 1 0 010-1.414z"/></svg>
                      </button>
                  </div>
              )}
          </div>
          <p className="max-w-xl mx-auto text-center mt-5 text-[9px] text-slate-400 font-bold uppercase tracking-[0.3em] hidden sm:block opacity-40">
            NEXZI Intelligence • Node v2.5.1 • Gemini Neural Engine
          </p>
      </div>
    </div>
  );
};

