                            <input type="file" ref={fileInputRef} onChange={(e) => {
                                    const file = e.target.files?.[0];
                                    if (file) {
                                        const reader = new FileReader();
                                        reader.onloadend = () => {
                                            setSelectedImage({ data: (reader.result as string).split(',')[1], mimeType: file.type });
                                        };
                                        reader.readAsDataURL(file);
                                    }
                            }} accept="image/*" className="hidden" />
                        </button>

                        <textarea
                            ref={textareaRef}
                            value={input}
                            onChange={e => setInput(e.target.value)}
                            onKeyDown={e => e.key === 'Enter' && !e.shiftKey && (e.preventDefault(), handleSendMessage())}
                            placeholder="Type a command or ask Nexzi..."
                            className="flex-1 bg-transparent border-none outline-none resize-none py-4 px-2 text-slate-900 dark:text-white placeholder-slate-400 dark:placeholder-slate-500 text-lg sm:text-xl md:text-2xl font-medium leading-relaxed max-h-[160px] min-h-[48px]"
                            rows={1}
                        />

                        <button 
                            onClick={() => handleSendMessage()} 
                            disabled={isLoading || (!input && !selectedImage)} 
                            className={`w-14 h-14 sm:w-18 sm:h-18 rounded-[1.5rem] sm:rounded-[2rem] text-white transition-all duration-500 transform active:scale-90 disabled:opacity-30 flex items-center justify-center shrink-0
                                ${input || selectedImage ? 'bg-blue-600 shadow-2xl shadow-blue-500/30 hover:scale-105 active:bg-blue-700' : 'bg-slate-100 dark:bg-slate-700 text-slate-300'}
                            `}
                        >
                             <SendIcon className="w-8 h-8 sm:w-10 sm:h-10"/>
                        </button>
                   </div>
              </div>

              {selectedImage && (
                  <div className="absolute -top-32 left-4 p-4 bg-white dark:bg-slate-800 rounded-[2.5rem] shadow-2xl border border-slate-200 dark:border-slate-700 flex items-center gap-5 animate-fade-in-up group pointer-events-auto">
                      <div className="relative overflow-hidden rounded-2xl w-20 h-20 sm:w-24 sm:h-24 border border-slate-100 dark:border-slate-700 shadow-inner">
                        <img src={`data:${selectedImage.mimeType};base64,${selectedImage.data}`} className="w-full h-full object-cover" />
                        <div className="absolute inset-0 bg-black/5"></div>
                      </div>
                      <button onClick={() => setSelectedImage(null)} className="p-2.5 bg-red-500 text-white rounded-full hover:bg-red-600 transition-all shadow-lg active:scale-90">
                          <svg className="w-5 h-5" fill="currentColor" viewBox="0 0 20 20"><path d="M4.293 4.293a1 1 0 011.414 0L10 8.586l4.293-4.293a1 1 0 111.414 1.414L11.414 10l4.293 4.293a1 1 0 01-1.414 1.414L10 11.414l-4.293 4.293a1 1 0 01-1.414-1.414L8.586 10 4.293 5.707a1 1 0 010-1.414z"/></svg>
                      </button>
