import React, { useState, useRef, useEffect, useCallback } from 'react';
import type { ChatMessage, ChatPart, SearchResult, UIStyle, ThemeColors, FontSize, ModelType } from '../types';
import { GoogleGenAI } from "@google/genai";
import { BotIcon, SendIcon, UserIcon, ImageIcon, SearchIcon, SparklesIcon } from './Icons';

interface ChatViewProps {
  messages: ChatMessage[];
  setMessages: React.Dispatch<React.SetStateAction<ChatMessage[]>>;
  uiStyle: UIStyle;
  theme: ThemeColors;
  fontSize: FontSize;
  systemInstruction: string;
  model: ModelType;
  setActiveModel: (m: ModelType) => void;
}

const SourceCard: React.FC<{ result: SearchResult }> = ({ result }) => (
    <a 
        href={result.uri} 
        target="_blank" 
        rel="noopener noreferrer"
        className="flex items-center gap-2 p-2 bg-white/50 dark:bg-slate-800/50 backdrop-blur-sm border border-slate-200 dark:border-slate-700 rounded-xl hover:border-blue-500 transition-all shrink-0 max-w-[160px] shadow-sm"
    >
        <div className="w-6 h-6 rounded bg-blue-100 dark:bg-blue-900/40 flex items-center justify-center shrink-0">
            <SearchIcon className="w-3 h-3 text-blue-600" />
        </div>
        <div className="flex-1 min-w-0">
            <p className="text-[10px] font-bold text-slate-900 dark:text-slate-100 truncate">{result.title}</p>
        </div>
    </a>
);

export const ChatView: React.FC<ChatViewProps> = ({ messages, setMessages, theme, systemInstruction, model, setActiveModel }) => {
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [selectedImage, setSelectedImage] = useState<{ data: string; mimeType: string } | null>(null);
  const [webSearchEnabled, setWebSearchEnabled] = useState(true);
  const [isModelDropdownOpen, setIsModelDropdownOpen] = useState(false);
  const [isFirstMessageSent, setIsFirstMessageSent] = useState(messages.length > 0);

  const chatContainerRef = useRef<HTMLDivElement>(null);
  const textareaRef = useRef<HTMLTextAreaElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (chatContainerRef.current) {
      chatContainerRef.current.scrollTo({
        top: chatContainerRef.current.scrollHeight,
        behavior: 'smooth'
      });
    }
  }, [messages, isLoading]);

  useEffect(() => {
    if (messages.length > 0 && !isFirstMessageSent) {
      setIsFirstMessageSent(true);
    }
  }, [messages.length, isFirstMessageSent]);

  const handleSendMessage = useCallback(async (textOverride?: string) => {
    const textInput = (textOverride || input).trim();
    if ((!textInput && !selectedImage) || isLoading) return;

    const userMessageParts: ChatPart[] = [];
    if (selectedImage) userMessageParts.push({ inlineData: { mimeType: selectedImage.mimeType, data: selectedImage.data } });
    if (textInput) userMessageParts.push({ text: textInput });

    const userMessage: ChatMessage = { id: `msg-${Date.now()}`, role: 'user', parts: userMessageParts };
    const modelPlaceholder: ChatMessage = { id: `msg-${Date.now() + 1}`, role: 'model', parts: [{ text: '' }], isSearching: webSearchEnabled };

    setMessages(prev => [...prev, userMessage, modelPlaceholder]);
    setInput(''); 
    setSelectedImage(null);
    setIsLoading(true);

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const history = messages.map(msg => ({
        role: msg.role,
        parts: msg.parts.map(p => {
            if (p.text) return { text: p.text };
            if (p.inlineData) return { inlineData: p.inlineData };
            return null;
        }).filter(Boolean) as any[]
      }));

      const realModel = model === 'cognix-arc-1.0' ? 'gemini-3-flash-preview' : model;

      const stream = await ai.models.generateContentStream({
          model: realModel as any,
          contents: [...history, { role: 'user', parts: userMessageParts as any }],
          config: { 
              systemInstruction: systemInstruction, 
              tools: webSearchEnabled ? [{ googleSearch: {} }] : [],
              temperature: 0.8 
          },
      });

      let fullText = '';
      let searchResults: SearchResult[] = [];

      for await (const chunk of stream) {
        if(chunk.text) {
            fullText += chunk.text;
            setMessages(prev => prev.map(m => m.id === modelPlaceholder.id ? { ...m, parts: [{ text: fullText.replace(/\*/g, '') }], isSearching: false } : m));
        }
        const chunks = chunk.candidates?.[0]?.groundingMetadata?.groundingChunks;
        if (chunks) {
            const results = chunks.map((c: any) => c.web ? { ...c.web, type: 'web' } : null).filter(Boolean);
            searchResults = [...searchResults, ...results];
        }
      }

      if (searchResults.length > 0) {
        const unique = Array.from(new Map(searchResults.map(i => [i.uri, i])).values());
        setMessages(prev => prev.map(m => m.id === modelPlaceholder.id ? { ...m, parts: [{ ...m.parts[0], searchResults: unique }] } : m));
      }
    } catch (error) {
      setMessages(prev => prev.map(m => m.id === modelPlaceholder.id ? { ...m, parts: [{ text: `Error: ${error instanceof Error ? error.message : "Request failed."}` }], isSearching: false } : m));
    } finally {
      setIsLoading(false);
    }
  }, [input, isLoading, messages, selectedImage, systemInstruction, model, webSearchEnabled, setMessages]);

  const adjustTextareaHeight = () => {
    if (textareaRef.current) {
      textareaRef.current.style.height = 'auto';
      textareaRef.current.style.height = `${Math.min(textareaRef.current.scrollHeight, 180)}px`;
    }
  };

  useEffect(() => {
    adjustTextareaHeight();
  }, [input]);

  const modelOptions = [
    { id: 'cognix-arc-1.0', label: 'CognixArc 1.0', desc: 'Default friendly' },
    { id: 'gemini-3-flash-preview', label: 'Gemini 3 Flash', desc: 'Fast reasoning' },
    { id: 'gemini-3-pro-preview', label: 'Gemini 3 Pro', desc: 'Deep complex logic' },
    { id: 'gemini-2.5-flash-latest', label: 'Gemini 2.5 Flash', desc: 'Standard AI' },
    { id: 'gemini-2.5-flash-lite-latest', label: 'Gemini 2.5 Lite', desc: 'Efficient' }
  ];

  return (
    <div className="flex flex-col h-full bg-white dark:bg-slate-900 relative">
      <div ref={chatContainerRef} className="flex-1 overflow-y-auto px-4 sm:px-6 md:px-8 pb-48 pt-6 custom-scrollbar scroll-smooth">
        {!isFirstMessageSent ? (
            <div className="max-w-2xl mx-auto flex flex-col items-center justify-center min-h-[60vh] text-center px-4 animate-fade-in transition-all">
                 <div className="relative mb-6">
                     <div className="absolute inset-0 bg-blue-500/10 rounded-full blur-2xl animate-pulse"></div>
                     <BotIcon className="relative w-16 h-16 sm:w-20 sm:h-20 drop-shadow-xl" />
                 </div>
                 <h2 className="text-2xl sm:text-4xl font-black text-slate-900 dark:text-white mb-2 tracking-tight">
                   Ask Nexzi anything.
                 </h2>
                 <p className="text-slate-500 dark:text-slate-400 max-w-md mb-8 text-sm sm:text-base font-medium leading-relaxed">
                    Intelligent. Fast. Versatile.
                 </p>

                 <div className="grid grid-cols-1 sm:grid-cols-2 gap-3 w-full">
                     {[
                         { t: "Logic Problem", q: "Solve for x: 2x + 5 = 15. Explain each step.", icon: <SparklesIcon className="w-4 h-4"/> },
                         { t: "Quick Code", q: "Write a React hook for managing localStorage.", icon: <BotIcon className="w-4 h-4"/> }
                     ].map((item, i) => (
                        <button 
                            key={i} 
                            onClick={() => handleSendMessage(item.q)}
                            className="text-left p-4 rounded-2xl border border-slate-200 dark:border-slate-800 hover:border-blue-500 hover:bg-slate-50 dark:hover:bg-slate-800/50 transition-all group flex gap-4 items-center bg-white dark:bg-slate-900 shadow-sm active:scale-[0.98]"
                        >
                            <div className="w-8 h-8 rounded-xl bg-slate-100 dark:bg-slate-800 flex items-center justify-center shrink-0 group-hover:bg-blue-600 group-hover:text-white transition-all">
                                {item.icon}
                            </div>
                            <div className="min-w-0">
                                <p className="font-bold text-slate-900 dark:text-white text-xs sm:text-sm truncate">{item.t}</p>
                            </div>
                        </button>
                     ))}
                 </div>
            </div>
        ) : (
            <div className="max-w-3xl mx-auto space-y-8 animate-fade-in-up pb-10">
                {messages.map((msg) => (
                    <div key={msg.id} className={`flex gap-3 sm:gap-4 ${msg.role === 'user' ? 'flex-row-reverse' : 'flex-row'}`}>
                        <div className={`w-8 h-8 sm:w-10 sm:h-10 shrink-0 rounded-xl flex items-center justify-center shadow-md
                            ${msg.role === 'user' ? 'bg-slate-100 dark:bg-slate-800 text-slate-500 border border-slate-200 dark:border-slate-700' : 'bg-gradient-to-tr from-blue-600 to-indigo-600 text-white'}
                        `}>
                             {msg.role === 'user' ? <UserIcon className="w-5 h-5"/> : <BotIcon className="w-6 h-6 sm:w-7 sm:h-7"/>}
                        </div>

                        <div className={`flex flex-col gap-2 max-w-[85%] ${msg.role === 'user' ? 'items-end' : 'items-start'}`}>
                             {msg.parts.map((part, i) => (
                                 <div key={i} className={`relative leading-relaxed transition-all
                                     ${msg.role === 'user' 
                                         ? 'bg-blue-600 text-white px-4 py-2.5 rounded-2xl rounded-tr-sm shadow-md font-medium text-sm' 
                                         : 'text-slate-800 dark:text-slate-100 text-sm sm:text-base'}
                                 `}>
                                     {part.inlineData && <img src={`data:${part.inlineData.mimeType};base64,${part.inlineData.data}`} className="rounded-xl mb-4 max-h-64 shadow-md border border-slate-200 dark:border-slate-800 object-contain" alt="Context"/>}
                                     {msg.isSearching && i === 0 && (
                                         <div className="flex items-center gap-2 text-blue-500 mb-3 animate-pulse bg-blue-50 dark:bg-blue-900/20 px-3 py-1 rounded-full border border-blue-500/20 w-fit">
                                             <div className="w-2.5 h-2.5 border-2 border-blue-500 border-t-transparent rounded-full animate-spin"></div>
                                             <span className="text-[9px] font-black uppercase">Thinking...</span>
                                         </div>
                                     )}
                                     <div className="whitespace-pre-wrap prose prose-sm dark:prose-invert max-w-none">{part.text}</div>
                                     {part.searchResults && part.searchResults.length > 0 && (
                                         <div className="mt-4 pt-4 border-t border-slate-100 dark:border-slate-800">
                                            <div className="flex gap-2 overflow-x-auto pb-2 no-scrollbar">
                                                {part.searchResults.map((res, idx) => <SourceCard key={idx} result={res} />)}
                                            </div>
                                         </div>
                                     )}
                                 </div>
                             ))}
                        </div>
                    </div>
                ))}
                {isLoading && (
                  <div className="flex gap-3 sm:gap-4 items-center animate-fade-in">
                    <div className="w-8 h-8 sm:w-10 sm:h-10 shrink-0 rounded-xl bg-gradient-to-tr from-blue-600 to-indigo-600 flex items-center justify-center shadow-md">
                      <BotIcon className="w-6 h-6 animate-pulse" />
                    </div>
                    <div className="flex gap-1 p-3 bg-slate-50 dark:bg-slate-800/50 rounded-xl">
                      <div className="w-1.5 h-1.5 bg-blue-500 rounded-full animate-bounce [animation-delay:-0.3s]"></div>
                      <div className="w-1.5 h-1.5 bg-blue-500 rounded-full animate-bounce [animation-delay:-0.15s]"></div>
                      <div className="w-1.5 h-1.5 bg-blue-500 rounded-full animate-bounce"></div>
                    </div>
                  </div>
                )}
            </div>
        )}
      </div>

      {/* Re-designed Input Section */}
      <div className={`absolute bottom-0 left-0 right-0 px-4 sm:px-6 md:px-12 pb-6 pt-10 transition-all duration-700 ${!isFirstMessageSent ? '' : 'bg-gradient-to-t from-white dark:from-slate-900 via-white/95 dark:via-slate-900/95 to-transparent'}`}>
          <div className="max-w-3xl mx-auto relative pointer-events-auto">
              <div className="bg-white dark:bg-slate-800/95 backdrop-blur-2xl rounded-[1.8rem] sm:rounded-[2.5rem] shadow-2xl border border-slate-200/60 dark:border-slate-700/60 focus-within:ring-4 ring-blue-500/5 transition-all overflow-hidden">
                   <div className="flex items-center justify-between px-5 sm:px-8 pt-3 pb-1 border-b border-slate-100 dark:border-slate-700/40">
                       <div className="flex items-center gap-2 sm:gap-4 relative">
                           <div className="relative">
                                <button onClick={() => setIsModelDropdownOpen(!isModelDropdownOpen)} className="flex items-center gap-2 px-3 py-1.5 bg-slate-900 dark:bg-slate-950 text-white rounded-full hover:bg-black transition-all shadow-md active:scale-95">
                                    <span className="text-[9px] font-black uppercase whitespace-nowrap">
                                        {modelOptions.find(o => o.id === model)?.label || 'Model'}
                                    </span>
                                    <svg className={`w-3 h-3 transition-transform ${isModelDropdownOpen ? 'rotate-180' : ''}`} fill="none" stroke="currentColor" viewBox="0 0 24 24" strokeWidth="3"><path d="M19 9l-7 7-7-7"/></svg>
                                </button>
                                {isModelDropdownOpen && (
                                    <div className="absolute top-full left-0 mt-2 w-56 bg-slate-900 text-white rounded-2xl shadow-2xl border border-white/10 z-[100] max-h-60 overflow-y-auto custom-scrollbar p-1">
                                        {modelOptions.map(m => (
                                            <button key={m.id} onClick={() => { setActiveModel(m.id as any); setIsModelDropdownOpen(false); }}
                                                className={`w-full text-left px-4 py-3 hover:bg-white/10 transition-all rounded-xl flex flex-col ${model === m.id ? 'bg-white/5 text-blue-400' : 'text-white'}`}>
                                                <span className="text-[10px] font-black uppercase">{m.label}</span>
                                                <span className="text-[8px] opacity-50 uppercase">{m.desc}</span>
                                            </button>
                                        ))}
                                    </div>
                                )}
                           </div>
                           <button onClick={() => setWebSearchEnabled(!webSearchEnabled)} className={`flex items-center gap-1.5 px-3 py-1.5 rounded-full border transition-all ${webSearchEnabled ? 'bg-blue-600 border-blue-600 text-white shadow-md' : 'bg-slate-50 dark:bg-slate-900 border-slate-200 dark:border-slate-700 text-slate-400'}`}>
                                <SearchIcon className="w-3.5 h-3.5" />
                                <span className="text-[8px] font-black uppercase hidden sm:inline">Grounding</span>
                            </button>
                       </div>
                       <SparklesIcon className="w-4 h-4 text-slate-300 hidden sm:block"/>
                   </div>

                   <div className="p-3 sm:p-5 flex items-end gap-2 sm:gap-4">
                        <button onClick={() => fileInputRef.current?.click()} className="p-3 sm:p-4 rounded-2xl text-blue-600 bg-blue-50 dark:bg-blue-900/30 hover:bg-blue-600 hover:text-white transition-all shrink-0 active:scale-90 flex items-center justify-center border border-blue-100 dark:border-blue-800">
                            <ImageIcon className="w-5 h-5 sm:w-6 sm:h-6"/>
                            <input type="file" ref={fileInputRef} onChange={(e) => {
                                    const file = e.target.files?.[0];
                                    if (file) {
                                        const reader = new FileReader();
                                        reader.onloadend = () => setSelectedImage({ data: (reader.result as string).split(',')[1], mimeType: file.type });
                                        reader.readAsDataURL(file);
                                    }
                            }} accept="image/*" className="hidden" />
                        </button>
                        <textarea ref={textareaRef} value={input} onChange={e => setInput(e.target.value)}
                            onKeyDown={e => e.key === 'Enter' && !e.shiftKey && (e.preventDefault(), handleSendMessage())}
                            placeholder="Type a message..."
                            className="flex-1 bg-transparent border-none outline-none resize-none py-3 px-1 text-slate-900 dark:text-white placeholder-slate-400 text-base sm:text-lg font-medium max-h-40 min-h-[44px]"
                            rows={1} />
                        <button onClick={() => handleSendMessage()} disabled={isLoading || (!input && !selectedImage)} 
                            className={`w-11 h-11 sm:w-14 sm:h-14 rounded-2xl text-white transition-all active:scale-90 flex items-center justify-center shrink-0
                                ${input || selectedImage ? 'bg-blue-600 shadow-lg' : 'bg-slate-100 dark:bg-slate-700 text-slate-300'}
                            `}
                        >
                             <SendIcon className="w-6 h-6"/>
                        </button>
                   </div>
              </div>
              {selectedImage && (
                  <div className="absolute -top-20 left-4 p-2 bg-white dark:bg-slate-800 rounded-2xl shadow-xl border border-slate-200 dark:border-slate-700 flex items-center gap-2 animate-fade-in-up">
                      <img src={`data:${selectedImage.mimeType};base64,${selectedImage.data}`} className="w-12 h-12 rounded-lg object-cover" />
                      <button onClick={() => setSelectedImage(null)} className="p-1 bg-red-500 text-white rounded-full hover:bg-red-600 transition-all shadow-md">
                          <svg className="w-3 h-3" fill="currentColor" viewBox="0 0 20 20"><path d="M4.293 4.293a1 1 0 011.414 0L10 8.586l4.293-4.293a1 1 0 111.414 1.414L11.414 10l4.293 4.293a1 1 0 01-1.414 1.414L10 11.414l-4.293 4.293a1 1 0 01-1.414-1.414L8.586 10 4.293 5.707a1 1 0 010-1.414z"/></svg>
                      </button>
                  </div>
              )}
          </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { GoogleGenAI } from "@google/genai";
import type { ThemeColors, CommunityPost, ModelType } from '../types';
import { BotIcon, SendIcon, ImageIcon } from './Icons';

export const CommunityView: React.FC<{ theme: ThemeColors, model: ModelType }> = ({ theme, model }) => {
    const [posts, setPosts] = useState<CommunityPost[]>([]);
    const [newPostContent, setNewPostContent] = useState('');
    const [username, setUsername] = useState(localStorage.getItem('cognix_user_name') || '');
    const [isPublishing, setIsPublishing] = useState(false);
    const [safetyScanner, setSafetyScanner] = useState(false);
    const [error, setError] = useState<string | null>(null);
    const [replyingTo, setReplyingTo] = useState<string | null>(null);
    const [replyText, setReplyText] = useState('');

    useEffect(() => {
        const saved = localStorage.getItem('cognix_community_posts_v2');
        if (saved) setPosts(JSON.parse(saved));
        else setPosts([
            { 
                id: '1', 
                author: 'System Admin', 
                authorId: 'sys',
                content: 'Welcome to the Nexzi Community! Post your thoughts, code, or ideas here.', 
                timestamp: Date.now(), 
                likedBy: ['sys'], 
                replies: [],
                type: 'text' 
            }
        ]);
    }, []);

    useEffect(() => localStorage.setItem('cognix_community_posts_v2', JSON.stringify(posts)), [posts]);
    useEffect(() => { if(username) localStorage.setItem('cognix_user_name', username); }, [username]);

    const handlePublish = async () => {
        if (!newPostContent.trim() || !username.trim()) {
            setError('Both username and content are required.');
            return;
        }
        setIsPublishing(true);
        setSafetyScanner(true);
        setError(null);

        try {
            const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
            const moderation = await ai.models.generateContent({
                model: 'gemini-3-flash-preview',
                contents: `Evaluate for safety (No hate/harassment): "${newPostContent}". Respond ONLY "PASS" or "FAIL: [REASON]".`,
            });

            const result = moderation.text?.trim() || "";
            if (result.startsWith('PASS')) {
                const newPost: CommunityPost = {
                    id: Date.now().toString(),
                    author: username,
                    authorId: 'user_local',
                    content: newPostContent,
                    timestamp: Date.now(),
                    likedBy: [],
                    replies: [],
                    type: 'text'
                };
                setPosts(prev => [newPost, ...prev]);
                setNewPostContent('');
            } else {
                setError(`Guard: ${result.replace('FAIL:', '')}`);
            }
        } catch (e) {
            setError('System offline.');
        } finally {
            setIsPublishing(false);
            setSafetyScanner(false);
        }
    };

    const toggleLike = (postId: string) => {
        setPosts(prev => prev.map(p => {
            if (p.id === postId) {
                const liked = p.likedBy.includes('user_local');
                return { ...p, likedBy: liked ? p.likedBy.filter(id => id !== 'user_local') : [...p.likedBy, 'user_local'] };
            }
            return p;
        }));
    };

    const addReply = (postId: string) => {
        if (!replyText.trim() || !username.trim()) return;
        setPosts(prev => prev.map(p => {
            if (p.id === postId) {
                return { 
                    ...p, 
                    replies: [...p.replies, { id: Date.now().toString(), author: username, content: replyText, timestamp: Date.now() }] 
                };
            }
            return p;
        }));
        setReplyText('');
        setReplyingTo(null);
    };

    return (
        <div className="h-full overflow-y-auto bg-slate-50 dark:bg-slate-950 p-4 sm:p-6 custom-scrollbar">
            <div className="max-w-2xl mx-auto space-y-6 pb-20">
                <div className="bg-white dark:bg-slate-900 rounded-2xl p-4 sm:p-6 shadow-md border border-slate-200 dark:border-slate-800 relative">
                    {safetyScanner && <div className="absolute inset-0 bg-white/80 dark:bg-slate-900/80 backdrop-blur-sm z-10 flex items-center justify-center rounded-2xl font-bold uppercase tracking-widest text-blue-600">Analyzing...</div>}
                    <div className="flex flex-col gap-4">
                        <input 
                            value={username}
                            onChange={(e) => setUsername(e.target.value)}
                            placeholder="Set your username..."
                            className="bg-slate-50 dark:bg-slate-800/50 border border-slate-200 dark:border-slate-700 rounded-xl px-4 py-2 text-sm font-bold text-blue-600 outline-none w-fit min-w-[150px]"
                        />
                         <textarea 
                            value={newPostContent}
                            onChange={(e) => setNewPostContent(e.target.value)}
                            placeholder="What's on your mind?"
                            className="bg-slate-50 dark:bg-slate-800/50 border border-slate-200 dark:border-slate-700 rounded-xl p-4 min-h-[100px] outline-none text-slate-800 dark:text-slate-100 resize-none text-sm"
                        />
                    </div>
                    {error && <p className="mt-2 text-[10px] font-bold text-red-500 uppercase">{error}</p>}
                    <div className="flex justify-end mt-4">
                        <button 
                            onClick={handlePublish}
                            disabled={isPublishing || !newPostContent.trim() || !username.trim()}
                            className="bg-blue-600 text-white px-6 py-2 rounded-full font-black text-xs uppercase tracking-widest disabled:opacity-50 active:scale-95 transition-all"
                        >
                            Publish Broadcast
                        </button>
                    </div>
                </div>

                <div className="space-y-4">
                    {posts.map(post => (
                        <div key={post.id} className="bg-white dark:bg-slate-900 rounded-2xl p-4 sm:p-5 shadow-sm border border-slate-200 dark:border-slate-800">
                            <div className="flex items-center gap-2 mb-3">
                                <div className="w-8 h-8 rounded-full bg-blue-100 dark:bg-blue-900 flex items-center justify-center font-bold text-blue-600 text-xs">{post.author[0]}</div>
                                <div className="flex flex-col">
                                    <span className="text-sm font-bold text-slate-900 dark:text-white">@{post.author.toLowerCase().replace(/\s+/g, '')}</span>
                                    <span className="text-[10px] text-slate-400 font-medium">{new Date(post.timestamp).toLocaleDateString()}</span>
                                </div>
                            </div>
                            <p className="text-slate-800 dark:text-slate-200 text-sm sm:text-base leading-relaxed mb-4">{post.content}</p>
                            <div className="flex items-center gap-4 text-slate-400">
                                <button onClick={() => toggleLike(post.id)} className={`flex items-center gap-1 text-[10px] font-bold uppercase transition-colors ${post.likedBy.includes('user_local') ? 'text-blue-600' : 'hover:text-slate-600'}`}>
                                    <svg className="w-4 h-4" fill={post.likedBy.includes('user_local') ? 'currentColor' : 'none'} stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M4.318 6.318a4.5 4.5 0 000 6.364L12 20.364l7.682-7.682a4.5 4.5 0 00-6.364-6.364L12 7.636l-1.318-1.318a4.5 4.5 0 00-6.364 0z"/></svg>
                                    {post.likedBy.length} Pulse
                                </button>
                                <button onClick={() => setReplyingTo(replyingTo === post.id ? null : post.id)} className="flex items-center gap-1 text-[10px] font-bold uppercase hover:text-slate-600">
                                    <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M8 12h.01M12 12h.01M16 12h.01M21 12c0 4.418-4.03 8-9 8a9.863 9.863 0 01-4.255-.949L3 20l1.395-3.72C3.512 15.042 3 13.574 3 12c0-4.418 4.03-8 9-8s9 3.582 9 8z"/></svg>
                                    {post.replies.length} Perspective
                                </button>
                            </div>
                            {(post.replies.length > 0 || replyingTo === post.id) && (
                                <div className="mt-4 pt-4 border-t border-slate-100 dark:border-slate-800 space-y-3">
                                    {post.replies.map(reply => (
                                        <div key={reply.id} className="text-xs">
                                            <span className="font-bold text-blue-500">@{reply.author.toLowerCase().replace(/\s+/g, '')}</span>
                                            <p className="text-slate-600 dark:text-slate-400 mt-1">{reply.content}</p>
                                        </div>
                                    ))}
                                    {replyingTo === post.id && (
                                        <div className="flex gap-2">
                                            <input value={replyText} onChange={(e) => setReplyText(e.target.value)} onKeyDown={e => e.key === 'Enter' && addReply(post.id)} placeholder="Reply..." className="flex-1 bg-slate-50 dark:bg-slate-800 rounded-lg px-3 py-1.5 text-xs outline-none border border-slate-200 dark:border-slate-700" />
                                            <button onClick={() => addReply(post.id)} className="bg-blue-600 text-white px-3 rounded-lg text-[10px] font-bold uppercase">Inject</button>
                                        </div>
                                    )}
                                </div>
                            )}
                        </div>
                    ))}
                </div>
            </div>
        </div>
    );
};

export type Mode = 'chat' | 'live' | 'friends' | 'toolbox' | 'memory' | 'community' | 'coding';
export type UIStyle = 'modern' | 'glass' | 'brutal' | 'retro';
export type AccentColor = 'blue' | 'violet' | 'emerald' | 'rose' | 'amber';
export type FontSize = 'small' | 'normal' | 'large';
export type ModelType = 
  | 'cognix-arc-1.0'
  | 'gemini-3-flash-preview' 
  | 'gemini-3-pro-preview' 
  | 'gemini-2.5-flash'
  | 'gemini-2.5-pro'
  | 'gemini-2.5-flash-latest' 
  | 'gemini-2.5-flash-lite-latest';

export interface Friend {
  id: string;
  name: string;
  avatar: string;
  status: 'online' | 'offline' | 'busy' | 'away';
  isFollowing?: boolean;
}

export interface CommunityReply {
    id: string;
    author: string;
    content: string;
    timestamp: number;
}

export interface CommunityPost {
    id: string;
    author: string;
    authorId: string;
    content: string;
    timestamp: number;
    likedBy: string[]; // User IDs who liked
    replies: CommunityReply[];
    type: 'text' | 'image' | 'code';
    mediaUrl?: string;
}

export interface MemoryFact {
    id: string;
    category: 'preference' | 'project' | 'personal' | 'work';
    content: string;
    timestamp: string;
}

export interface ThemeColors {
    primary: string;
    primaryHover: string;
    text: string;
    textDark: string;
    bgSoft: string;
    darkBgSoft: string;
    border: string;
    ring: string;
    gradient: string;
}

export interface SearchResult {
  uri: string;
  title: string;
  type?: 'web' | 'map';
}

export interface ChatPart {
  text?: string;
  inlineData?: {
    mimeType: string;
    data: string; // base64 encoded
  };
  functionCall?: {
    name: string;
    args: any;
  };
  searchResults?: SearchResult[];
}

export interface ChatMessage {
  id: string;
  role: 'user' | 'model';
  parts: ChatPart[];
  isSearching?: boolean;
}

export interface ChatSession {
  id:string;
  title: string;
  messages: ChatMessage[];
}

import React, { useState, useRef, useEffect, useCallback } from 'react';
import type { ChatMessage, ChatPart, SearchResult, UIStyle, ThemeColors, FontSize, ModelType } from '../types';
import { GoogleGenAI } from "@google/genai";
import { BotIcon, SendIcon, UserIcon, ImageIcon, SearchIcon, SparklesIcon } from './Icons';

interface ChatViewProps {
  messages: ChatMessage[];
  setMessages: React.Dispatch<React.SetStateAction<ChatMessage[]>>;
  uiStyle: UIStyle;
  theme: ThemeColors;
  fontSize: FontSize;
  systemInstruction: string;
  model: ModelType;
  setActiveModel: (m: ModelType) => void;
}

const SourceCard: React.FC<{ result: SearchResult }> = ({ result }) => (
    <a 
        href={result.uri} 
        target="_blank" 
        rel="noopener noreferrer"
        className="flex items-center gap-2 p-2 bg-white/50 dark:bg-slate-800/50 backdrop-blur-sm border border-slate-200 dark:border-slate-700 rounded-xl hover:border-blue-500 transition-all shrink-0 max-w-[160px] shadow-sm"
    >
        <div className="w-6 h-6 rounded bg-blue-100 dark:bg-blue-900/40 flex items-center justify-center shrink-0">
            <SearchIcon className="w-3 h-3 text-blue-600" />
        </div>
        <div className="flex-1 min-w-0">
            <p className="text-[10px] font-bold text-slate-900 dark:text-slate-100 truncate">{result.title}</p>
        </div>
    </a>
);

export const ChatView: React.FC<ChatViewProps> = ({ messages, setMessages, theme, systemInstruction, model, setActiveModel }) => {
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [selectedImage, setSelectedImage] = useState<{ data: string; mimeType: string } | null>(null);
  const [webSearchEnabled, setWebSearchEnabled] = useState(true);
  const [isModelDropdownOpen, setIsModelDropdownOpen] = useState(false);
  const [isFirstMessageSent, setIsFirstMessageSent] = useState(messages.length > 0);

  const chatContainerRef = useRef<HTMLDivElement>(null);
  const textareaRef = useRef<HTMLTextAreaElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (chatContainerRef.current) {
      chatContainerRef.current.scrollTo({
        top: chatContainerRef.current.scrollHeight,
        behavior: 'smooth'
      });
    }
  }, [messages, isLoading]);

  useEffect(() => {
    if (messages.length > 0 && !isFirstMessageSent) {
      setIsFirstMessageSent(true);
    }
  }, [messages.length, isFirstMessageSent]);

  const handleSendMessage = useCallback(async (textOverride?: string) => {
    const textInput = (textOverride || input).trim();
    if ((!textInput && !selectedImage) || isLoading) return;

    const userMessageParts: ChatPart[] = [];
    if (selectedImage) userMessageParts.push({ inlineData: { mimeType: selectedImage.mimeType, data: selectedImage.data } });
    if (textInput) userMessageParts.push({ text: textInput });

    const userMessage: ChatMessage = { id: `msg-${Date.now()}`, role: 'user', parts: userMessageParts };
    const modelPlaceholder: ChatMessage = { id: `msg-${Date.now() + 1}`, role: 'model', parts: [{ text: '' }], isSearching: webSearchEnabled };

    setMessages(prev => [...prev, userMessage, modelPlaceholder]);
    setInput(''); 
    setSelectedImage(null);
    setIsLoading(true);

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const history = messages.map(msg => ({
        role: msg.role,
        parts: msg.parts.map(p => {
            if (p.text) return { text: p.text };
            if (p.inlineData) return { inlineData: p.inlineData };
            return null;
        }).filter(Boolean) as any[]
      }));

      const realModelMapping: Record<string, string> = {
        'cognix-arc-1.0': 'gemini-3-flash-preview',
        'gemini-2.5-flash': 'gemini-2.5-flash',
        'gemini-2.5-pro': 'gemini-2.5-pro'
      };

      const realModel = realModelMapping[model] || model;

      const stream = await ai.models.generateContentStream({
          model: realModel as any,
          contents: [...history, { role: 'user', parts: userMessageParts as any }],
          config: { 
              systemInstruction: systemInstruction, 
              tools: webSearchEnabled ? [{ googleSearch: {} }] : [],
              temperature: 0.8 
          },
      });

      let fullText = '';
      let searchResults: SearchResult[] = [];

      for await (const chunk of stream) {
        if(chunk.text) {
            fullText += chunk.text;
            setMessages(prev => prev.map(m => m.id === modelPlaceholder.id ? { ...m, parts: [{ text: fullText.replace(/\*/g, '') }], isSearching: false } : m));
        }
        const chunks = chunk.candidates?.[0]?.groundingMetadata?.groundingChunks;
        if (chunks) {
            const results = chunks.map((c: any) => c.web ? { ...c.web, type: 'web' } : null).filter(Boolean);
            searchResults = [...searchResults, ...results];
        }
      }

      if (searchResults.length > 0) {
        const unique = Array.from(new Map(searchResults.map(i => [i.uri, i])).values());
        setMessages(prev => prev.map(m => m.id === modelPlaceholder.id ? { ...m, parts: [{ ...m.parts[0], searchResults: unique }] } : m));
      }
    } catch (error) {
      setMessages(prev => prev.map(m => m.id === modelPlaceholder.id ? { ...m, parts: [{ text: `Error: ${error instanceof Error ? error.message : "Request failed."}` }], isSearching: false } : m));
    } finally {
      setIsLoading(false);
    }
  }, [input, isLoading, messages, selectedImage, systemInstruction, model, webSearchEnabled, setMessages]);

  const adjustTextareaHeight = () => {
    if (textareaRef.current) {
      textareaRef.current.style.height = 'auto';
      textareaRef.current.style.height = `${Math.min(textareaRef.current.scrollHeight, 180)}px`;
    }
  };

  useEffect(() => {
    adjustTextareaHeight();
  }, [input]);

  const modelOptions = [
    { id: 'cognix-arc-1.0', label: 'CognixArc 1.0', desc: 'Default friendly' },
    { id: 'gemini-3-flash-preview', label: 'Gemini 3 Flash', desc: 'Next-gen reasoning' },
    { id: 'gemini-3-pro-preview', label: 'Gemini 3 Pro', desc: 'Complex reasoning' },
    { id: 'gemini-2.5-flash', label: 'Gemini 2.5 Flash', desc: 'Standard speed' },
    { id: 'gemini-2.5-pro', label: 'Gemini 2.5 Pro', desc: 'Balanced reasoning' },
    { id: 'gemini-2.5-flash-lite-latest', label: 'Gemini 2.5 Lite', desc: 'Ultra efficient' }
  ];

  return (
    <div className="flex flex-col h-full bg-white dark:bg-slate-900 relative">
      <div ref={chatContainerRef} className="flex-1 overflow-y-auto px-4 sm:px-6 md:px-8 pb-48 pt-6 custom-scrollbar scroll-smooth">
        {!isFirstMessageSent ? (
            <div className="max-w-xl mx-auto flex flex-col items-center justify-center min-h-[60vh] text-center px-4 animate-fade-in transition-all">
                 <div className="relative mb-4 group cursor-pointer">
                     <div className="absolute inset-0 bg-blue-500/20 rounded-full blur-3xl animate-pulse group-hover:bg-blue-500/30 transition-all duration-500"></div>
                     <BotIcon className="relative w-16 h-16 sm:w-20 sm:h-20 drop-shadow-2xl animate-float transition-transform duration-700" />
                 </div>
                 <h2 className="text-2xl sm:text-3xl md:text-4xl font-black text-slate-900 dark:text-white mb-2 tracking-tight animate-fade-in-up">
                   Ask Nexzi anything.
                 </h2>
                 <p className="text-slate-500 dark:text-slate-400 max-w-sm mb-6 text-sm sm:text-base font-medium leading-relaxed opacity-0 animate-fade-in-up [animation-delay:200ms] [animation-fill-mode:forwards]">
                    Your personalized intelligence node. Fast, focused, and secure.
                 </p>

                 <div className="grid grid-cols-1 sm:grid-cols-2 gap-2.5 w-full opacity-0 animate-fade-in-up [animation-delay:400ms] [animation-fill-mode:forwards]">
                     {[
                         { t: "Logic Puzzle", q: "A man has 5 apples and eats 2. How many does he have?", icon: <SparklesIcon className="w-4 h-4"/> },
                         { t: "Code Assist", q: "Write a clean JavaScript function for debouncing.", icon: <BotIcon className="w-4 h-4"/> }
                     ].map((item, i) => (
                        <button 
                            key={i} 
                            onClick={() => handleSendMessage(item.q)}
                            className="text-left p-3.5 rounded-2xl border border-slate-100 dark:border-slate-800 hover:border-blue-500 hover:bg-slate-50 dark:hover:bg-slate-800/50 transition-all group flex gap-3.5 items-center bg-white dark:bg-slate-900 shadow-sm active:scale-[0.97]"
                        >
                            <div className="w-8 h-8 rounded-xl bg-slate-100 dark:bg-slate-800 flex items-center justify-center shrink-0 group-hover:bg-blue-600 group-hover:text-white transition-all shadow-inner">
                                {item.icon}
                            </div>
                            <div className="min-w-0">
                                <p className="font-bold text-slate-900 dark:text-white text-xs sm:text-sm truncate">{item.t}</p>
                                <p className="text-[8px] text-slate-400 font-bold uppercase tracking-widest mt-0.5">Quick Start</p>
                            </div>
                        </button>
                     ))}
                 </div>
            </div>
        ) : (
            <div className="max-w-3xl mx-auto space-y-8 animate-fade-in-up pb-10">
                {messages.map((msg) => (
                    <div key={msg.id} className={`flex gap-3 sm:gap-4 ${msg.role === 'user' ? 'flex-row-reverse' : 'flex-row'}`}>
                        <div className={`w-8 h-8 sm:w-10 sm:h-10 shrink-0 rounded-xl flex items-center justify-center shadow-md
                            ${msg.role === 'user' ? 'bg-slate-100 dark:bg-slate-800 text-slate-500 border border-slate-200 dark:border-slate-700' : 'bg-gradient-to-tr from-blue-600 to-indigo-600 text-white'}
                        `}>
                             {msg.role === 'user' ? <UserIcon className="w-5 h-5"/> : <BotIcon className="w-6 h-6 sm:w-7 sm:h-7"/>}
                        </div>

                        <div className={`flex flex-col gap-2 max-w-[85%] ${msg.role === 'user' ? 'items-end' : 'items-start'}`}>
                             {msg.parts.map((part, i) => (
                                 <div key={i} className={`relative leading-relaxed transition-all
                                     ${msg.role === 'user' 
                                         ? 'bg-blue-600 text-white px-4 py-2.5 rounded-2xl rounded-tr-sm shadow-md font-medium text-sm' 
                                         : 'text-slate-800 dark:text-slate-100 text-sm sm:text-base'}
                                 `}>
                                     {part.inlineData && <img src={`data:${part.inlineData.mimeType};base64,${part.inlineData.data}`} className="rounded-xl mb-4 max-h-64 shadow-md border border-slate-200 dark:border-slate-800 object-contain" alt="Context"/>}
                                     {msg.isSearching && i === 0 && (
                                         <div className="flex items-center gap-2 text-blue-500 mb-3 animate-pulse bg-blue-50 dark:bg-blue-900/20 px-3 py-1 rounded-full border border-blue-500/20 w-fit">
                                             <div className="w-2.5 h-2.5 border-2 border-blue-500 border-t-transparent rounded-full animate-spin"></div>
                                             <span className="text-[9px] font-black uppercase tracking-widest">Researching</span>
                                         </div>
                                     )}
                                     <div className="whitespace-pre-wrap prose prose-sm dark:prose-invert max-w-none">{part.text}</div>
                                     {part.searchResults && part.searchResults.length > 0 && (
                                         <div className="mt-4 pt-4 border-t border-slate-100 dark:border-slate-800">
                                            <div className="flex gap-2 overflow-x-auto pb-2 no-scrollbar">
                                                {part.searchResults.map((res, idx) => <SourceCard key={idx} result={res} />)}
                                            </div>
                                         </div>
                                     )}
                                 </div>
                             ))}
                        </div>
                    </div>
                ))}
                {isLoading && (
                  <div className="flex gap-3 sm:gap-4 items-center animate-fade-in">
                    <div className="w-8 h-8 sm:w-10 sm:h-10 shrink-0 rounded-xl bg-gradient-to-tr from-blue-600 to-indigo-600 flex items-center justify-center shadow-md">
                      <BotIcon className="w-6 h-6 animate-pulse" />
                    </div>
                    <div className="flex gap-1 p-2.5 bg-slate-50 dark:bg-slate-800/50 rounded-xl">
                      <div className="w-1.5 h-1.5 bg-blue-500 rounded-full animate-bounce [animation-delay:-0.3s]"></div>
                      <div className="w-1.5 h-1.5 bg-blue-500 rounded-full animate-bounce [animation-delay:-0.15s]"></div>
                      <div className="w-1.5 h-1.5 bg-blue-500 rounded-full animate-bounce"></div>
                    </div>
                  </div>
                )}
            </div>
        )}
      </div>

      {/* Input Section - Optimized upward dropdown */}
      <div className={`absolute bottom-0 left-0 right-0 px-4 sm:px-6 md:px-12 pb-6 pt-10 transition-all duration-700 ${!isFirstMessageSent ? '' : 'bg-gradient-to-t from-white dark:from-slate-900 via-white/95 dark:via-slate-900/95 to-transparent'}`}>
          <div className="max-w-2xl mx-auto relative pointer-events-auto">
              <div className="bg-white dark:bg-slate-800/95 backdrop-blur-2xl rounded-[1.5rem] sm:rounded-[2rem] shadow-2xl border border-slate-200/60 dark:border-slate-700/60 focus-within:ring-4 ring-blue-500/5 transition-all overflow-visible">

                   <div className="flex items-center justify-between px-5 sm:px-8 pt-3 pb-1 border-b border-slate-100 dark:border-slate-700/40">
                       <div className="flex items-center gap-2 sm:gap-4 relative">
                           {/* Model Switcher - Upward Opening */}
                           <div className="relative">
                                {isModelDropdownOpen && (
                                    <div className="absolute bottom-full left-0 mb-3 w-60 bg-slate-900 dark:bg-black text-white rounded-2xl shadow-2xl border border-white/10 z-[100] max-h-64 overflow-y-auto custom-scrollbar p-1.5 animate-fade-in-up">
                                        <p className="text-[9px] font-black uppercase text-slate-500 px-3 py-2 border-b border-white/5 mb-1 tracking-widest">Select Intelligence Engine</p>
                                        {modelOptions.map(m => (
                                            <button key={m.id} onClick={() => { setActiveModel(m.id as any); setIsModelDropdownOpen(false); }}
                                                className={`w-full text-left px-4 py-3 hover:bg-white/10 transition-all rounded-xl flex flex-col gap-0.5 ${model === m.id ? 'bg-white/10 text-blue-400' : 'text-white'}`}>
                                                <span className="text-[10px] font-black uppercase tracking-tight">{m.label}</span>
                                                <span className="text-[8px] opacity-40 uppercase font-bold">{m.desc}</span>
                                            </button>
                                        ))}
                                    </div>
                                )}
                                <button onClick={() => setIsModelDropdownOpen(!isModelDropdownOpen)} className="flex items-center gap-2 px-3 py-1.5 bg-slate-900 dark:bg-slate-950 text-white rounded-full hover:bg-black transition-all shadow-md active:scale-95 border border-white/10">
                                    <span className="text-[9px] font-black uppercase whitespace-nowrap tracking-tighter">
                                        {modelOptions.find(o => o.id === model)?.label || 'Model'}
                                    </span>
                                    <svg className={`w-3 h-3 transition-transform ${isModelDropdownOpen ? 'rotate-180' : ''}`} fill="none" stroke="currentColor" viewBox="0 0 24 24" strokeWidth="3"><path d="M19 9l-7 7-7-7"/></svg>
                                </button>
                           </div>

                           <button onClick={() => setWebSearchEnabled(!webSearchEnabled)} className={`flex items-center gap-1.5 px-3 py-1.5 rounded-full border transition-all ${webSearchEnabled ? 'bg-blue-600 border-blue-600 text-white shadow-md' : 'bg-slate-50 dark:bg-slate-900 border-slate-200 dark:border-slate-700 text-slate-400'}`}>
                                <SearchIcon className="w-3.5 h-3.5" />
                                <span className="text-[8px] font-black uppercase hidden sm:inline tracking-widest">Grounding</span>
                            </button>
                       </div>
                       <SparklesIcon className="w-4 h-4 text-slate-300 hidden sm:block animate-pulse-soft"/>
