export type Mode = 'chat' | 'live' | 'friends' | 'toolbox' | 'memory' | 'community' | 'coding';
export type UIStyle = 'modern' | 'glass' | 'brutal' | 'retro';
export type AccentColor = 'blue' | 'violet' | 'emerald' | 'rose' | 'amber';
export type FontSize = 'small' | 'normal' | 'large';
export type ModelType = 
  | 'cognix-arc-1.0'
  | 'gemini-3-flash-preview' 
  | 'gemini-3-pro-preview' 
  | 'gemini-2.5-flash-native-audio-preview-09-2025'
  | 'gemini-2.5-flash-preview-tts';

export interface Friend {
  id: string;
  name: string;
  avatar: string;
  status: 'online' | 'offline' | 'busy' | 'away';
  isFollowing?: boolean;
}

export interface Deployment {
  id: string;
  title: string;
  code: string;
  timestamp: number;
}

export interface CommunityReply {
    id: string;
    author: string;
    content: string;
    timestamp: number;
}

export interface CommunityPost {
    id: string;
    author: string;
    authorId: string;
    content: string;
    timestamp: number;
    likedBy: string[]; // User IDs who liked
    replies: CommunityReply[];
    type: 'text' | 'image' | 'code';
    mediaUrl?: string;
}

export interface MemoryFact {
    id: string;
    category: 'preference' | 'project' | 'personal' | 'work';
    content: string;
    timestamp: string;
}

export interface ThemeColors {
    primary: string;
    primaryHover: string;
    text: string;
    textDark: string;
    bgSoft: string;
    darkBgSoft: string;
    border: string;
    ring: string;
    gradient: string;
}

export interface SearchResult {
  uri: string;
  title: string;
  type?: 'web' | 'map';
}

export interface ChatPart {
  text?: string;
  inlineData?: {
    mimeType: string;
    data: string; // base64 encoded
  };
  functionCall?: {
    name: string;
    args: any;
  };
  searchResults?: SearchResult[];
}

export interface ChatMessage {
  id: string;
  role: 'user' | 'model';
  parts: ChatPart[];
  isSearching?: boolean;
}

export interface ChatSession {
  id:string;
  title: string;
  messages: ChatMessage[];
  participants?: string[]; // Friend IDs
}

import React, { useState, useRef, useEffect, useCallback } from 'react';
import type { ChatMessage, ChatPart, SearchResult, UIStyle, ThemeColors, FontSize, ModelType, Friend } from '../types';
import { GoogleGenAI } from "@google/genai";
import { BotIcon, SendIcon, UserIcon, ImageIcon, SearchIcon, SparklesIcon, UsersIcon } from './Icons';

interface ChatViewProps {
  messages: ChatMessage[];
  setMessages: React.Dispatch<React.SetStateAction<ChatMessage[]>>;
  uiStyle: UIStyle;
  theme: ThemeColors;
  fontSize: FontSize;
  systemInstruction: string;
  model: ModelType;
  setActiveModel: (m: ModelType) => void;
  friends?: Friend[];
}

const SourceCard: React.FC<{ result: SearchResult }> = ({ result }) => (
    <a 
        href={result.uri} 
        target="_blank" 
        rel="noopener noreferrer"
        className="flex items-center gap-2 p-2 bg-white/50 dark:bg-slate-800/50 backdrop-blur-sm border border-slate-200 dark:border-slate-700 rounded-xl hover:border-blue-500 transition-all shrink-0 max-w-[160px] shadow-sm"
    >
        <div className="w-6 h-6 rounded bg-blue-100 dark:bg-blue-900/40 flex items-center justify-center shrink-0">
            <SearchIcon className="w-3 h-3 text-blue-600" />
        </div>
        <div className="flex-1 min-w-0">
            <p className="text-[10px] font-bold text-slate-900 dark:text-slate-100 truncate">{result.title}</p>
        </div>
    </a>
);

export const ChatView: React.FC<ChatViewProps> = ({ messages, setMessages, theme, systemInstruction, model, setActiveModel, friends = [] }) => {
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [selectedImage, setSelectedImage] = useState<{ data: string; mimeType: string } | null>(null);
  const [webSearchEnabled, setWebSearchEnabled] = useState(true);
  const [isModelDropdownOpen, setIsModelDropdownOpen] = useState(false);
  const [isFriendDropdownOpen, setIsFriendDropdownOpen] = useState(false);
  const [isFirstMessageSent, setIsFirstMessageSent] = useState(messages.length > 0);
  const [activeParticipants, setActiveParticipants] = useState<string[]>([]);

  const chatContainerRef = useRef<HTMLDivElement>(null);
  const textareaRef = useRef<HTMLTextAreaElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (chatContainerRef.current) {
      chatContainerRef.current.scrollTo({
        top: chatContainerRef.current.scrollHeight,
        behavior: 'smooth'
      });
    }
  }, [messages, isLoading]);

  useEffect(() => {
    if (messages.length > 0 && !isFirstMessageSent) {
      setIsFirstMessageSent(true);
    }
  }, [messages.length, isFirstMessageSent]);

  const handleSendMessage = useCallback(async (textOverride?: string) => {
    const textInput = (textOverride || input).trim();
    if ((!textInput && !selectedImage) || isLoading) return;

    const userMessageParts: ChatPart[] = [];
    if (selectedImage) userMessageParts.push({ inlineData: { mimeType: selectedImage.mimeType, data: selectedImage.data } });

    // Include participant mentions if any
    const participantPrefix = activeParticipants.length > 0 
        ? `[Conversation with: ${activeParticipants.map(id => friends.find(f => f.id === id)?.name).join(', ')}] ` 
        : '';

    if (textInput) userMessageParts.push({ text: participantPrefix + textInput });

    const userMessage: ChatMessage = { id: `msg-${Date.now()}`, role: 'user', parts: userMessageParts };
    const modelPlaceholderId = `msg-${Date.now() + 1}`;
    const modelPlaceholder: ChatMessage = { id: modelPlaceholderId, role: 'model', parts: [{ text: '' }], isSearching: webSearchEnabled };

    setMessages(prev => [...prev, userMessage, modelPlaceholder]);
    setInput(''); 
    setSelectedImage(null);
    setIsLoading(true);
    if (!isFirstMessageSent) setIsFirstMessageSent(true);

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const history = messages.map(msg => ({
        role: msg.role,
        parts: msg.parts.map(p => {
            if (p.text) return { text: p.text };
            if (p.inlineData) return { inlineData: p.inlineData };
            return null;
        }).filter(Boolean) as any[]
      }));

      // FIX: Correcting model mappings to prevent 404 errors.
      // Use 'gemini-3-flash-preview' for general flash tasks.
      const realModelMapping: Record<string, string> = {
        'cognix-arc-1.0': 'gemini-3-flash-preview',
        'gemini-3-flash-preview': 'gemini-3-flash-preview',
        'gemini-3-pro-preview': 'gemini-3-pro-preview',
        'gemini-2.5-flash-native-audio-preview-09-2025': 'gemini-2.5-flash-native-audio-preview-09-2025'
      };

      const realModel = realModelMapping[model] || 'gemini-3-flash-preview';

      const stream = await ai.models.generateContentStream({
          model: realModel as any,
          contents: [...history, { role: 'user', parts: userMessageParts as any }],
          config: { 
              systemInstruction: systemInstruction, 
              tools: webSearchEnabled ? [{ googleSearch: {} }] : [],
              temperature: 0.7 
          },
      });

      let fullText = '';
      let searchResults: SearchResult[] = [];

      for await (const chunk of stream) {
        if(chunk.text) {
            fullText += chunk.text;
            setMessages(prev => prev.map(m => m.id === modelPlaceholderId ? { ...m, parts: [{ ...m.parts[0], text: fullText.replace(/\*/g, '') }], isSearching: false } : m));
        }
        const chunks = chunk.candidates?.[0]?.groundingMetadata?.groundingChunks;
        if (chunks) {
            const results = chunks.map((c: any) => c.web ? { ...c.web, type: 'web' } : null).filter(Boolean);
            searchResults = [...searchResults, ...results];
        }
      }

      if (searchResults.length > 0) {
        const unique = Array.from(new Map(searchResults.map(i => [i.uri, i])).values());
        setMessages(prev => prev.map(m => m.id === modelPlaceholderId ? { ...m, parts: [{ ...m.parts[0], searchResults: unique }] } : m));
      }
    } catch (error) {
      setMessages(prev => prev.map(m => m.id === modelPlaceholderId ? { ...m, parts: [{ text: `Engine Error: The requested configuration failed. Reverting to backup protocols.` }], isSearching: false } : m));
    } finally {
      setIsLoading(false);
    }
  }, [input, isLoading, messages, selectedImage, systemInstruction, model, webSearchEnabled, setMessages, isFirstMessageSent, activeParticipants, friends]);

  const toggleParticipant = (friendId: string) => {
    setActiveParticipants(prev => prev.includes(friendId) ? prev.filter(id => id !== friendId) : [...prev, friendId]);
  };

  const adjustTextareaHeight = () => {
    if (textareaRef.current) {
      textareaRef.current.style.height = 'auto';
      textareaRef.current.style.height = `${Math.min(textareaRef.current.scrollHeight, 180)}px`;
    }
  };

  useEffect(() => { adjustTextareaHeight(); }, [input]);

  const modelOptions = [
    { id: 'cognix-arc-1.0', label: 'CognixArc 1.0', desc: 'Optimized Standard' },
    { id: 'gemini-3-flash-preview', label: 'Flash 3', desc: 'Real-time Logic' },
    { id: 'gemini-3-pro-preview', label: 'Pro 3', desc: 'Advanced Reasoning' },
    { id: 'gemini-2.5-flash-native-audio-preview-09-2025', label: 'Flash 2.5 Audio', desc: 'Native Multimodal' }
  ];

  return (
    <div className="flex flex-col h-full bg-white dark:bg-slate-900 relative">
      {/* Header Participants Display */}
      {activeParticipants.length > 0 && (
          <div className="absolute top-4 left-1/2 -translate-x-1/2 z-20 flex items-center gap-1.5 px-3 py-1.5 bg-blue-600 rounded-full shadow-lg animate-fade-in">
              <div className="flex -space-x-2">
                  {activeParticipants.map(id => (
                      <div key={id} className="w-6 h-6 rounded-full bg-white border-2 border-blue-600 flex items-center justify-center text-[8px] font-black text-blue-600 uppercase">
                          {friends.find(f => f.id === id)?.name[0]}
                      </div>
                  ))}
              </div>
              <span className="text-[9px] font-bold text-white uppercase tracking-wider">{activeParticipants.length} Connected</span>
          </div>
      )}

      <div ref={chatContainerRef} className="flex-1 overflow-y-auto px-4 sm:px-6 md:px-8 pb-48 pt-6 custom-scrollbar scroll-smooth">
        {!isFirstMessageSent ? (
            <div className="max-w-xl mx-auto flex flex-col items-center justify-center min-h-[60vh] text-center px-4 animate-fade-in">
                 <div className="relative mb-4 group animate-float">
                     <div className="absolute inset-0 bg-blue-500/10 rounded-full blur-2xl group-hover:bg-blue-500/20 transition-all duration-700"></div>
                     <BotIcon className="relative w-12 h-12 sm:w-16 sm:h-16 md:w-20 md:h-20 drop-shadow-xl" />
                 </div>
                 <h2 className="text-2xl sm:text-3xl md:text-4xl font-black text-slate-900 dark:text-white mb-2 tracking-tight">
                   Cognix Intelligence
                 </h2>
                 <p className="text-slate-500 dark:text-slate-400 max-w-sm mb-6 text-sm sm:text-base font-medium opacity-80">
                    High-performance neural node for modern work.
                 </p>

                 <div className="grid grid-cols-1 sm:grid-cols-2 gap-3 w-full max-w-lg">
                     {[
                         { t: "Logic Problem", q: "Compare the efficiency of binary search vs linear search.", icon: <SparklesIcon className="w-4 h-4"/> },
                         { t: "React Setup", q: "Generate a Tailwind card component for a blog.", icon: <BotIcon className="w-4 h-4"/> }
                     ].map((item, i) => (
                        <button key={i} onClick={() => handleSendMessage(item.q)} className="text-left p-4 rounded-2xl border border-slate-100 dark:border-slate-800/50 hover:border-blue-500 hover:bg-slate-50 dark:hover:bg-slate-800 transition-all group flex gap-3 items-center bg-white dark:bg-slate-900 shadow-sm">
                            <div className="w-8 h-8 rounded-xl bg-slate-100 dark:bg-slate-800 flex items-center justify-center group-hover:bg-blue-600 group-hover:text-white transition-all">
                                {item.icon}
                            </div>
                            <span className="font-bold text-slate-900 dark:text-white text-xs sm:text-sm truncate">{item.t}</span>
                        </button>
                     ))}
                 </div>
            </div>
        ) : (
            <div className="max-w-3xl mx-auto space-y-10 animate-fade-in-up pb-10">
                {messages.map((msg) => (
                    <div key={msg.id} className={`flex gap-3 sm:gap-4 ${msg.role === 'user' ? 'flex-row-reverse' : 'flex-row'}`}>
                        <div className={`w-8 h-8 sm:w-10 sm:h-10 shrink-0 rounded-xl flex items-center justify-center shadow-md
                            ${msg.role === 'user' ? 'bg-slate-100 dark:bg-slate-800 text-slate-500 border border-slate-200 dark:border-slate-700' : 'bg-gradient-to-tr from-blue-600 to-indigo-600 text-white'}
                        `}>
                             {msg.role === 'user' ? <UserIcon className="w-5 h-5"/> : <BotIcon className="w-6 h-6 sm:w-7 sm:h-7"/>}
                        </div>

                        <div className={`flex flex-col gap-2 max-w-[85%] ${msg.role === 'user' ? 'items-end' : 'items-start'}`}>
                             {msg.parts.map((part, i) => (
                                 <div key={i} className={`relative leading-relaxed transition-all
                                     ${msg.role === 'user' 
                                         ? 'bg-blue-600 text-white px-4 py-2.5 rounded-2xl rounded-tr-sm shadow-md font-medium text-sm' 
                                         : 'text-slate-800 dark:text-slate-100 text-sm sm:text-base'}
                                 `}>
                                     {part.inlineData && <img src={`data:${part.inlineData.mimeType};base64,${part.inlineData.data}`} className="rounded-xl mb-4 max-h-64 shadow-md border border-slate-200 dark:border-slate-800 object-contain" alt="Context"/>}

                                     {msg.isSearching && i === 0 && (
                                         <div className="flex items-center gap-2 text-blue-500 mb-3 bg-blue-50 dark:bg-blue-900/20 px-3 py-1.5 rounded-full border border-blue-500/20 w-fit">
                                             <div className="flex gap-1">
                                                <div className="w-1.5 h-1.5 bg-blue-500 rounded-full animate-bounce [animation-delay:-0.3s]"></div>
                                                <div className="w-1.5 h-1.5 bg-blue-500 rounded-full animate-bounce [animation-delay:-0.15s]"></div>
                                                <div className="w-1.5 h-1.5 bg-blue-500 rounded-full animate-bounce"></div>
                                             </div>
                                             <span className="text-[9px] font-black uppercase tracking-widest ml-1">Web Search</span>
                                         </div>
                                     )}

                                     <div className="whitespace-pre-wrap prose prose-sm dark:prose-invert max-w-none">{part.text}</div>

                                     {part.searchResults && part.searchResults.length > 0 && (
                                         <div className="mt-4 pt-4 border-t border-slate-100 dark:border-slate-800">
                                            <div className="flex gap-2 overflow-x-auto pb-2 no-scrollbar scroll-smooth">
                                                {part.searchResults.map((res, idx) => <SourceCard key={idx} result={res} />)}
                                            </div>
                                         </div>
                                     )}
                                 </div>
                             ))}
                        </div>
                    </div>
                ))}
                {isLoading && (
                  <div className="flex gap-3 sm:gap-4 items-center animate-fade-in">
                    <div className="w-8 h-8 sm:w-10 sm:h-10 shrink-0 rounded-xl bg-gradient-to-tr from-blue-600 to-indigo-600 flex items-center justify-center shadow-md">
                      <BotIcon className="w-6 h-6 animate-pulse" />
                    </div>
                    <div className="flex gap-1.5 p-3 bg-slate-50 dark:bg-slate-800/50 rounded-xl shadow-inner">
                      <div className="w-1.5 h-1.5 bg-blue-500 rounded-full animate-bounce [animation-delay:-0.3s]"></div>
                      <div className="w-1.5 h-1.5 bg-blue-500 rounded-full animate-bounce [animation-delay:-0.15s]"></div>
                      <div className="w-1.5 h-1.5 bg-blue-500 rounded-full animate-bounce"></div>
                    </div>
                  </div>
                )}
            </div>
        )}
      </div>

      <div className={`absolute bottom-0 left-0 right-0 px-4 sm:px-6 md:px-12 pb-6 pt-10 transition-all duration-700 ${!isFirstMessageSent ? '' : 'bg-gradient-to-t from-white dark:from-slate-900 via-white/95 dark:via-slate-900/95 to-transparent'}`}>
          <div className="max-w-2xl mx-auto relative pointer-events-auto">
              <div className="bg-white dark:bg-slate-800/95 backdrop-blur-2xl rounded-[1.5rem] sm:rounded-[2rem] shadow-2xl border border-slate-200/60 dark:border-slate-700/60 focus-within:ring-4 ring-blue-500/5 transition-all overflow-visible">

                   <div className="flex items-center justify-between px-5 sm:px-8 pt-3 pb-1 border-b border-slate-100 dark:border-slate-700/40">
                       <div className="flex items-center gap-2 sm:gap-4 relative">
                           {/* Model Switcher - Upward */}
                           <div className="relative">
                                {isModelDropdownOpen && (
                                    <div className="absolute bottom-full left-0 mb-3 w-56 bg-slate-900 text-white rounded-2xl shadow-2xl border border-white/10 z-[100] p-1.5 animate-fade-in-up">
                                        {modelOptions.map(m => (
                                            <button key={m.id} onClick={() => { setActiveModel(m.id as any); setIsModelDropdownOpen(false); }}
                                                className={`w-full text-left px-3 py-2.5 hover:bg-white/10 transition-all rounded-xl flex flex-col gap-0.5 ${model === m.id ? 'bg-white/10 text-blue-400' : 'text-white'}`}>
                                                <span className="text-[10px] font-black uppercase tracking-tight">{m.label}</span>
                                                <span className="text-[8px] opacity-40 uppercase font-bold">{m.desc}</span>
                                            </button>
                                        ))}
                                    </div>
                                )}
                                <button onClick={() => { setIsModelDropdownOpen(!isModelDropdownOpen); setIsFriendDropdownOpen(false); }} className="flex items-center gap-2 px-3 py-1.5 bg-slate-900 dark:bg-slate-950 text-white rounded-full hover:bg-black transition-all border border-white/10 active:scale-95">
                                    <span className="text-[9px] font-black uppercase whitespace-nowrap">{modelOptions.find(o => o.id === model)?.label || 'Core'}</span>
                                    <svg className={`w-3 h-3 transition-transform ${isModelDropdownOpen ? 'rotate-180' : ''}`} fill="none" stroke="currentColor" viewBox="0 0 24 24" strokeWidth="3"><path d="M19 9l-7 7-7-7"/></svg>
                                </button>
                           </div>

                           <button onClick={() => setWebSearchEnabled(!webSearchEnabled)} className={`flex items-center gap-1.5 px-3 py-1.5 rounded-full border transition-all ${webSearchEnabled ? 'bg-blue-600 border-blue-600 text-white shadow-md' : 'bg-slate-50 dark:bg-slate-900 border-slate-200 dark:border-slate-700 text-slate-400'}`}>
                                <SearchIcon className="w-3.5 h-3.5" />
                                <span className="text-[8px] font-black uppercase hidden sm:inline tracking-widest">Web Search</span>
                            </button>

                           {/* Friend Injector */}
                           <div className="relative">
                                <button onClick={() => { setIsFriendDropdownOpen(!isFriendDropdownOpen); setIsModelDropdownOpen(false); }} className={`flex items-center gap-1.5 px-3 py-1.5 rounded-full border transition-all ${activeParticipants.length > 0 ? 'bg-indigo-600 border-indigo-600 text-white shadow-md' : 'bg-slate-50 dark:bg-slate-900 border-slate-200 dark:border-slate-700 text-slate-400'}`}>
                                    <UsersIcon className="w-3.5 h-3.5" />
                                    <span className="text-[8px] font-black uppercase hidden sm:inline tracking-widest">Friends</span>
                                </button>
                                {isFriendDropdownOpen && (
                                    <div className="absolute bottom-full left-0 mb-3 w-48 bg-slate-900 text-white rounded-2xl shadow-2xl border border-white/10 z-[100] p-1.5 animate-fade-in-up">
                                        <p className="text-[8px] font-black text-slate-500 p-2 uppercase border-b border-white/5 mb-1">Invite to chat</p>
                                        {friends.length === 0 ? (
                                            <p className="text-[10px] p-3 text-slate-400 italic">No connections</p>
                                        ) : (
                                            friends.map(f => (
                                                <button key={f.id} onClick={() => toggleParticipant(f.id)} className={`w-full flex items-center justify-between px-3 py-2 rounded-xl transition-all ${activeParticipants.includes(f.id) ? 'bg-indigo-600/20 text-indigo-400' : 'hover:bg-white/10'}`}>
                                                    <span className="text-[10px] font-bold">{f.name}</span>
                                                    {activeParticipants.includes(f.id) && <div className="w-1.5 h-1.5 rounded-full bg-indigo-500 animate-pulse"></div>}
                                                </button>
                                            ))
                                        )}
                                    </div>
                                )}
                           </div>
                       </div>
                       <SparklesIcon className="w-4 h-4 text-slate-300 hidden sm:block"/>
                   </div>

                   <div className="p-3 sm:p-4 flex items-end gap-2 sm:gap-4">
                        <button onClick={() => fileInputRef.current?.click()} className="p-3 rounded-xl text-blue-600 bg-blue-50 dark:bg-blue-900/30 hover:bg-blue-600 hover:text-white transition-all shrink-0 active:scale-90 border border-blue-100/50 dark:border-blue-800/50">
                            <ImageIcon className="w-5 h-5 sm:w-6 h-6"/>
                            <input type="file" ref={fileInputRef} onChange={(e) => {
                                    const file = e.target.files?.[0];
                                    if (file) {
                                        const reader = new FileReader();
                                        reader.onloadend = () => setSelectedImage({ data: (reader.result as string).split(',')[1], mimeType: file.type });
                                        reader.readAsDataURL(file);
                                    }
                            }} accept="image/*" className="hidden" />
                        </button>
                        <textarea ref={textareaRef} value={input} onChange={e => setInput(e.target.value)}
                            onKeyDown={e => e.key === 'Enter' && !e.shiftKey && (e.preventDefault(), handleSendMessage())}
                            placeholder="Type a message..."
                            className="flex-1 bg-transparent border-none outline-none resize-none py-3 px-1 text-slate-900 dark:text-white placeholder-slate-400 text-sm sm:text-base font-medium max-h-40 min-h-[44px]"
                            rows={1} />
                        <button onClick={() => handleSendMessage()} disabled={isLoading || (!input && !selectedImage)} 
                            className={`w-11 h-11 sm:w-12 sm:h-12 rounded-xl text-white transition-all active:scale-90 flex items-center justify-center shrink-0
                                ${input || selectedImage ? 'bg-blue-600 shadow-lg' : 'bg-slate-100 dark:bg-slate-700 text-slate-300'}
                            `}
                        >
                             <SendIcon className="w-5 h-5 sm:w-6 sm:h-6"/>
                        </button>
                   </div>
              </div>
              {selectedImage && (
                  <div className="absolute -top-20 left-4 p-2 bg-white dark:bg-slate-800 rounded-2xl shadow-xl border border-slate-200 dark:border-slate-700 flex items-center gap-2 animate-fade-in-up">
                      <img src={`data:${selectedImage.mimeType};base64,${selectedImage.data}`} className="w-12 h-12 rounded-lg object-cover" />
                      <button onClick={() => setSelectedImage(null)} className="p-1.5 bg-red-500 text-white rounded-full hover:bg-red-600 transition-all active:scale-90">
                          <svg className="w-3 h-3" fill="currentColor" viewBox="0 0 20 20"><path d="M4.293 4.293a1 1 0 011.414 0L10 8.586l4.293-4.293a1 1 0 111.414 1.414L11.414 10l4.293 4.293a1 1 0 01-1.414 1.414L10 11.414l-4.293 4.293a1 1 0 01-1.414-1.414L8.586 10 4.293 5.707a1 1 0 010-1.414z"/></svg>
                      </button>
                  </div>
              )}
          </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { GoogleGenAI } from "@google/genai";
import type { ThemeColors, ModelType, Deployment } from '../types';
import { CodeIcon, SparklesIcon, BotIcon, CopyIcon, DownloadIcon, TrashIcon } from './Icons';

export const CodingView: React.FC<{ theme: ThemeColors, model: ModelType }> = ({ theme, model }) => {
    const [prompt, setPrompt] = useState('');
    const [code, setCode] = useState('<!DOCTYPE html>\n<html>\n<head>\n<script src="https://cdn.tailwindcss.com"></script>\n</head>\n<body class="bg-slate-900 text-white flex items-center justify-center min-h-screen font-sans">\n  <div class="text-center p-8 border border-white/10 rounded-3xl bg-white/5 backdrop-blur-xl shadow-2xl">\n    <h1 class="text-5xl font-black mb-4 bg-gradient-to-r from-blue-400 to-emerald-400 bg-clip-text text-transparent">Cognix DevStudio</h1>\n    <p class="text-slate-400">Ready for persistent deployment.</p>\n  </div>\n</body>\n</html>');
    const [isGenerating, setIsGenerating] = useState(false);
    const [showCode, setShowCode] = useState(false);
    const [deployments, setDeployments] = useState<Deployment[]>([]);
    const [activeDeploymentId, setActiveDeploymentId] = useState<string | null>(null);

    useEffect(() => {
        const saved = localStorage.getItem('cognix_deployments');
        if (saved) setDeployments(JSON.parse(saved));
    }, []);

    useEffect(() => {
        localStorage.setItem('cognix_deployments', JSON.stringify(deployments));
    }, [deployments]);

    const handleGenerate = async () => {
        if (!prompt.trim()) return;
        setIsGenerating(true);
        try {
            const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
            const response = await ai.models.generateContent({
                model: 'gemini-3-pro-preview',
                contents: `ACT AS A SENIOR FRONTEND ENGINEER. Build a high-fidelity, single-file responsive website. 
                USE: Tailwind CSS (via CDN), Google Fonts.
                REQUIREMENT: "${prompt}".
                OUTPUT: Raw HTML only. Start with <!DOCTYPE html>. No commentary.`,
            });
            const extractedCode = response.text || '';
            setCode(extractedCode);
            setActiveDeploymentId(null);
        } catch (e) {
            setCode(`<h1>Build Failed</h1><p>${e}</p>`);
        } finally {
            setIsGenerating(false);
        }
    };

    const handlePublish = () => {
        const newDeployment: Deployment = {
            id: Date.now().toString(),
            title: prompt.slice(0, 30) || 'Untitled Deployment',
            code: code,
            timestamp: Date.now()
        };
        setDeployments(prev => [newDeployment, ...prev]);
        setActiveDeploymentId(newDeployment.id);

        const blob = new Blob([code], { type: 'text/html' });
        const url = URL.createObjectURL(blob);
        window.open(url, '_blank');
    };

    const deleteDeployment = (id: string, e: React.MouseEvent) => {
        e.stopPropagation();
        setDeployments(prev => prev.filter(d => d.id !== id));
        if (activeDeploymentId === id) setActiveDeploymentId(null);
    };

    const viewDeployment = (d: Deployment) => {
        setCode(d.code);
        setActiveDeploymentId(d.id);
    };

    return (
        <div className="h-full flex flex-col md:flex-row bg-slate-50 dark:bg-slate-950 overflow-hidden">
            <div className="w-full md:w-[380px] flex flex-col border-r border-slate-200 dark:border-slate-800 bg-white dark:bg-slate-900 p-6 overflow-y-auto custom-scrollbar">
                <div className="flex items-center justify-between mb-8">
                    <h2 className="text-xl font-bold text-slate-900 dark:text-white flex items-center gap-2">
                        <CodeIcon className="w-5 h-5 text-blue-600" /> DevStudio
                    </h2>
                    <span className="text-[10px] font-black bg-blue-100 dark:bg-blue-900/40 text-blue-600 dark:text-blue-400 px-2 py-1 rounded-full uppercase">Persistent</span>
                </div>

                <div className="space-y-6">
                    <div>
                        <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-3 px-1">Describe Requirements</label>
                        <textarea 
                            value={prompt}
                            onChange={(e) => setPrompt(e.target.value)}
                            placeholder="Describe the application architecture..."
                            className="w-full p-4 h-32 bg-slate-50 dark:bg-slate-800 rounded-2xl border border-slate-100 dark:border-slate-700 outline-none focus:border-blue-500 text-sm transition-all resize-none shadow-sm"
                        />
                    </div>

                    <div className="grid grid-cols-2 gap-3">
                        <button 
                            onClick={handleGenerate}
                            disabled={isGenerating || !prompt.trim()}
                            className={`col-span-2 py-3.5 rounded-2xl font-bold text-white shadow-lg flex items-center justify-center gap-3 transition-all active:scale-95 ${theme.primary} disabled:opacity-50`}
                        >
                            {isGenerating ? <div className="w-4 h-4 border-2 border-white border-t-transparent rounded-full animate-spin"></div> : <SparklesIcon className="w-4 h-4" />}
                            {isGenerating ? 'Synthesizing...' : 'Architect Interface'}
                        </button>

                        <button onClick={() => setShowCode(!showCode)} className="py-2.5 bg-slate-100 dark:bg-slate-800 text-slate-700 dark:text-slate-300 rounded-xl font-bold text-[10px] uppercase tracking-wider hover:bg-slate-200 transition-all">
                            {showCode ? 'Preview' : 'View Code'}
                        </button>

                        <button onClick={handlePublish} disabled={isGenerating || code.length < 50} className="py-2.5 bg-emerald-600 text-white rounded-xl font-bold text-[10px] uppercase tracking-wider hover:bg-emerald-700 transition-all shadow-md">
                            Deploy Live
                        </button>
                    </div>

                    <div className="pt-6 border-t border-slate-100 dark:border-slate-800">
                        <h4 className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] mb-4 px-1">Persistent Deployments</h4>
                        <div className="space-y-2">
                            {deployments.length === 0 ? (
                                <p className="text-[10px] text-slate-400 italic px-1">No sites deployed yet.</p>
                            ) : (
                                deployments.map(d => (
                                    <div key={d.id} onClick={() => viewDeployment(d)} className={`group p-3 rounded-xl border transition-all cursor-pointer relative ${activeDeploymentId === d.id ? 'bg-blue-50 dark:bg-blue-900/20 border-blue-500' : 'bg-slate-50 dark:bg-slate-800/50 border-transparent hover:border-slate-300 dark:hover:border-slate-600'}`}>
                                        <div className="flex justify-between items-start pr-8">
                                            <p className="text-[11px] font-bold text-slate-900 dark:text-white truncate">{d.title}</p>
                                        </div>
                                        <p className="text-[8px] text-slate-400 mt-1 uppercase font-bold tracking-widest">{new Date(d.timestamp).toLocaleDateString()}</p>
                                        <button onClick={(e) => deleteDeployment(d.id, e)} className="absolute right-2 top-3 p-1.5 text-slate-400 hover:text-red-500 opacity-0 group-hover:opacity-100 transition-all">
                                            <TrashIcon className="w-3.5 h-3.5" />
                                        </button>
                                    </div>
                                ))
                            )}
                        </div>
                    </div>
                </div>
            </div>

            <div className="flex-1 flex flex-col bg-slate-100 dark:bg-slate-950 p-4 md:p-6 overflow-hidden relative">
                {showCode ? (
                    <div className="flex-1 bg-slate-950 rounded-2xl shadow-2xl border border-white/5 overflow-hidden flex flex-col">
                        <div className="h-10 bg-slate-900 border-b border-white/5 flex items-center justify-between px-5">
                            <span className="text-[9px] font-black text-slate-500 uppercase tracking-widest">Source Pulse</span>
                            <button onClick={() => navigator.clipboard.writeText(code)} className="p-1.5 text-slate-500 hover:text-white transition-colors"><CopyIcon className="w-3.5 h-3.5"/></button>
                        </div>
                        <textarea value={code} onChange={(e) => setCode(e.target.value)} className="flex-1 bg-transparent p-6 font-mono text-xs text-blue-400 outline-none resize-none custom-scrollbar" />
                    </div>
                ) : (
                    <div className="flex-1 bg-white rounded-2xl shadow-2xl overflow-hidden border border-slate-200 dark:border-slate-800 relative">
                        <iframe srcDoc={code} title="Web Preview" className="w-full h-full border-none" />
                        {isGenerating && (
                            <div className="absolute inset-0 bg-slate-900/60 backdrop-blur-md flex items-center justify-center z-50 animate-fade-in">
                                <div className="text-center">
                                    <div className="flex gap-2 justify-center mb-4">
                                        <div className="w-3 h-3 bg-blue-500 rounded-full animate-bounce [animation-delay:-0.3s]"></div>
                                        <div className="w-3 h-3 bg-blue-500 rounded-full animate-bounce [animation-delay:-0.15s]"></div>
                                        <div className="w-3 h-3 bg-blue-500 rounded-full animate-bounce"></div>
                                    </div>
                                    <p className="text-white font-black tracking-[0.2em] uppercase text-[10px]">Assembling Component Architecture</p>
                                </div>
                            </div>
                        )}
                    </div>
                )}
            </div>
        </div>
    );
};

import React, { useState, useEffect, useMemo } from 'react';
import { ChatView } from './components/ChatView';
import { LiveView } from './components/LiveView';
import { Sidebar } from './components/Sidebar';
import { FriendsView } from './components/FriendsView';
import { ToolboxView } from './components/ToolboxView';
import { MemoryView } from './components/MemoryView';
import { CommunityView } from './components/CommunityView';
import { CodingView } from './components/CodingView';
import { MenuIcon, UserIcon } from './components/Icons';
import { SettingsModal } from './components/SettingsModal';
import { GoogleGenAI } from "@google/genai";
import type { ChatMessage, ChatSession, Mode, UIStyle, AccentColor, ThemeColors, FontSize, Friend, ModelType } from './types';

const THEMES: Record<AccentColor, ThemeColors> = {
    blue: { primary: 'bg-blue-600', primaryHover: 'hover:bg-blue-700', text: 'text-blue-600', textDark: 'text-blue-400', bgSoft: 'bg-blue-50', darkBgSoft: 'dark:bg-blue-900/20', border: 'border-blue-600', ring: 'focus:ring-blue-600', gradient: 'bg-gradient-to-r from-blue-500 to-cyan-500' },
    violet: { primary: 'bg-violet-600', primaryHover: 'hover:bg-violet-700', text: 'text-violet-600', textDark: 'text-violet-400', bgSoft: 'bg-violet-50', darkBgSoft: 'dark:bg-violet-900/20', border: 'border-violet-600', ring: 'focus:ring-violet-600', gradient: 'bg-gradient-to-r from-violet-500 to-purple-500' },
    emerald: { primary: 'bg-emerald-600', primaryHover: 'hover:bg-emerald-700', text: 'text-emerald-600', textDark: 'text-emerald-400', bgSoft: 'bg-emerald-50', darkBgSoft: 'dark:bg-emerald-900/20', border: 'border-emerald-600', ring: 'focus:ring-emerald-600', gradient: 'bg-gradient-to-r from-emerald-500 to-teal-500' },
    rose: { primary: 'bg-rose-600', primaryHover: 'hover:bg-rose-700', text: 'text-rose-600', textDark: 'text-rose-400', bgSoft: 'bg-rose-50', darkBgSoft: 'dark:bg-violet-900/20', border: 'border-rose-600', ring: 'focus:ring-rose-600', gradient: 'bg-gradient-to-r from-rose-500 to-pink-500' },
    amber: { primary: 'bg-amber-600', primaryHover: 'hover:bg-amber-700', text: 'text-amber-600', textDark: 'text-amber-400', bgSoft: 'bg-amber-50', darkBgSoft: 'dark:bg-amber-900/20', border: 'border-amber-600', ring: 'focus:ring-amber-600', gradient: 'bg-gradient-to-r from-amber-500 to-orange-500' },
};

const App: React.FC = () => {
  const [mode, setMode] = useState<Mode>('chat');
  const [uiStyle, setUiStyle] = useState<UIStyle>('modern');
  const [accentColor, setAccentColor] = useState<AccentColor>('blue');
  const [fontSize, setFontSize] = useState<FontSize>('normal');
  const [activeModel, setActiveModel] = useState<ModelType>('cognix-arc-1.0');
  const [systemInstruction, setSystemInstruction] = useState("You are Nexzi AI, a highly intelligent and helpful personal assistant created by Shashwat Ranjan Jha. You are professional, friendly, and efficient. You use emojis to make conversations engaging. You have access to real-time information via Google Search.");

  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [isDesktopSidebarOpen, setIsDesktopSidebarOpen] = useState(true);
  const [isDarkMode, setIsDarkMode] = useState(false);
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);

  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [chatHistory, setChatHistory] = useState<ChatSession[]>([]);
  const [activeChatId, setActiveChatId] = useState<string | null>(null);
  const [friends, setFriends] = useState<Friend[]>([]);

  useEffect(() => {
    const savedHistory = localStorage.getItem('nexzi_history');
    if (savedHistory) setChatHistory(JSON.parse(savedHistory));

    const savedFriends = localStorage.getItem('nexzi_friends');
    if (savedFriends) setFriends(JSON.parse(savedFriends));

    const savedTheme = localStorage.getItem('nexzi_theme');
    if (savedTheme === 'dark' || (!savedTheme && window.matchMedia('(prefers-color-scheme: dark)').matches)) {
      setIsDarkMode(true);
      document.documentElement.classList.add('dark');
    }
  }, []);

  useEffect(() => localStorage.setItem('nexzi_history', JSON.stringify(chatHistory)), [chatHistory]);
  useEffect(() => localStorage.setItem('nexzi_friends', JSON.stringify(friends)), [friends]);

  useEffect(() => {
    if (isDarkMode) {
      document.documentElement.classList.add('dark');
      localStorage.setItem('nexzi_theme', 'dark');
    } else {
      document.documentElement.classList.remove('dark');
      localStorage.setItem('nexzi_theme', 'light');
    }
  }, [isDarkMode]);

  const currentChat = useMemo(() => chatHistory.find(c => c.id === activeChatId), [chatHistory, activeChatId]);
  const activeTheme = useMemo(() => THEMES[accentColor], [accentColor]);

  useEffect(() => {
    setMessages(currentChat ? currentChat.messages : []);
  }, [currentChat?.id]);

  const generateChatTitle = async (firstMessage: string) => {
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: `Generate a ultra-short (max 3 words) title for: "${firstMessage}". Output ONLY the title.`,
      });
      return response.text?.trim() || firstMessage.slice(0, 30);
    } catch (e) {
      return firstMessage.slice(0, 30);
    }
  };

  useEffect(() => {
    const updateHistory = async () => {
      if (messages.length === 1 && !activeChatId && messages[0].role === 'user') {
         const firstUserText = messages[0].parts.find(p => p.text)?.text || 'New Chat';
         const newId = Date.now().toString();
         const newTitle = await generateChatTitle(firstUserText);
         const newSession: ChatSession = { id: newId, title: newTitle, messages: messages };
         setChatHistory(prev => [newSession, ...prev]);
         setActiveChatId(newId);
      } else if (activeChatId && messages.length > 0) {
         setChatHistory(prev => prev.map(session => session.id === activeChatId ? { ...session, messages } : session));
      }
    };
    updateHistory();
  }, [messages, activeChatId]);

  const handleNewChat = () => {
    setActiveChatId(null);
    setMessages([]);
    setMode('chat');
    if (window.innerWidth < 1024) setIsSidebarOpen(false);
  };

  return (
    <div className="flex h-[100dvh] overflow-hidden bg-slate-50 dark:bg-slate-950 transition-colors duration-300">
      <Sidebar 
        chatHistory={chatHistory}
        activeChatId={activeChatId}
        mode={mode}
        onSetMode={(m) => { setMode(m); if(window.innerWidth < 1024) setIsSidebarOpen(false); }}
        onSelectChat={(id) => { setActiveChatId(id); setMode('chat'); if(window.innerWidth < 1024) setIsSidebarOpen(false); }}
        onNewChat={handleNewChat}
        onDeleteChat={(id) => {
            setChatHistory(h => h.filter(c => c.id !== id));
            if (activeChatId === id) { setActiveChatId(null); setMessages([]); }
        }}
        onRenameChat={(id, t) => setChatHistory(h => h.map(c => c.id === id ? { ...c, title: t } : c))}
        onOpenSettings={() => setIsSettingsOpen(true)}
        isSidebarOpen={isSidebarOpen}
        isDesktopSidebarOpen={isDesktopSidebarOpen}
        theme={activeTheme}
        friends={friends}
      />

      {isSidebarOpen && <div className="fixed inset-0 bg-black/40 backdrop-blur-sm z-40 lg:hidden" onClick={() => setIsSidebarOpen(false)} />}

      <div className="flex-1 flex flex-col h-full min-w-0 bg-white dark:bg-slate-900 lg:rounded-l-[2.5rem] shadow-2xl relative transition-all duration-500">
        <header className="h-16 flex items-center justify-between px-4 sm:px-8 shrink-0 z-30 border-b border-slate-50 dark:border-slate-800 lg:border-none">
             <div className="flex items-center gap-2 sm:gap-4">
                <button onClick={() => window.innerWidth >= 1024 ? setIsDesktopSidebarOpen(!isDesktopSidebarOpen) : setIsSidebarOpen(!isSidebarOpen)} className="p-2 -ml-2 text-slate-500 hover:bg-slate-100 dark:hover:bg-slate-800 rounded-xl transition-colors">
                    <MenuIcon className="w-5 h-5"/>
                </button>
                <div className="flex flex-col">
                  <h1 className="text-xs sm:text-sm font-black text-slate-800 dark:text-slate-100 flex items-center gap-2 tracking-tight truncate max-w-[150px] sm:max-w-none">
                      {mode === 'chat' && (currentChat?.title || 'Nexzi AI')}
                      {mode === 'live' && 'Nexzi Live'}
                      {mode === 'community' && 'Global Pulse'}
                      {mode === 'coding' && 'DevStudio'}
                      {mode === 'toolbox' && 'Lab Toolbox'}
                      {mode === 'memory' && 'Vault'}
                      <div className="w-1.5 h-1.5 rounded-full bg-blue-500 animate-pulse shrink-0"></div>
                  </h1>
                  <span className="text-[8px] sm:text-[9px] text-slate-400 font-bold tracking-[0.2em] uppercase">Intelligence Node</span>
                </div>
             </div>

             <div className="flex items-center gap-2 sm:gap-4">
                 <button onClick={() => setIsDarkMode(!isDarkMode)} className="p-2 text-slate-400 hover:text-slate-600 dark:hover:text-slate-200 transition-colors">
                     {isDarkMode ? <svg className="w-5 h-5" fill="currentColor" viewBox="0 0 20 20"><path d="M10 2a1 1 0 011 1v1a1 1 0 11-2 0V3a1 1 0 011-1zm4 8a4 4 0 11-8 0 4 4 0 018 0zm-.464 4.95l.707.707a1 1 0 001.414-1.414l-.707-.707a1 1 0 00-1.414 1.414zm2.12-10.607a1 1 0 010 1.414l-.706.707a1 1 0 11-1.414-1.414l.707-.707a1 1 0 011.414 0zM17 11a1 1 0 100-2h-1a1 1 0 100 2h1zm-7 4a1 1 0 011 1v1a1 1 0 11-2 0v-1a1 1 0 011-1zM5.05 6.464A1 1 0 106.465 5.05l-.708-.707a1 1 0 00-1.414 1.414l.707.707zm1.414 8.486l-.707.707a1 1 0 01-1.414-1.414l.707-.707a1 1 0 011.414 1.414zM4 11a1 1 0 100-2H3a1 1 0 000 2h1z"/></svg> : <svg className="w-5 h-5" fill="currentColor" viewBox="0 0 20 20"><path d="M17.293 13.293A8 8 0 016.707 2.707a8.001 8.001 0 1010.586 10.586z"/></svg>}
                 </button>
                 <button 
                    onClick={() => setIsSettingsOpen(true)}
                    className="flex items-center gap-2 p-1 pl-2 sm:pl-3 bg-slate-100 dark:bg-slate-800 rounded-full border border-slate-200 dark:border-slate-700 hover:border-blue-500 transition-all group"
                 >
                     <span className="text-[8px] sm:text-[10px] font-black text-slate-500 group-hover:text-blue-500 transition-colors uppercase tracking-widest hidden xs:inline">Config</span>
                     <div className="w-7 h-7 sm:w-8 sm:h-8 rounded-full bg-gradient-to-tr from-blue-600 to-indigo-600 flex items-center justify-center text-white">
                         <UserIcon className="w-4 h-4 sm:w-5 sm:h-5"/>
                     </div>
                 </button>
             </div>
        </header>

        <main className="flex-1 relative overflow-hidden">
             {mode === 'chat' && (
                <ChatView 
                    messages={messages} 
                    setMessages={setMessages}
                    uiStyle={uiStyle}
                    theme={activeTheme}
                    fontSize={fontSize}
                    systemInstruction={systemInstruction}
                    model={activeModel}
                    setActiveModel={setActiveModel}
                    friends={friends}
                />
            )}
            {mode === 'live' && <LiveView theme={activeTheme} />}
            {mode === 'friends' && <FriendsView friends={friends} setFriends={setFriends} />}
            {mode === 'community' && <CommunityView theme={activeTheme} model={activeModel} />}
            {mode === 'coding' && <CodingView theme={activeTheme} model={activeModel} />}
            {mode === 'toolbox' && <ToolboxView theme={activeTheme} model={activeModel} />}
            {mode === 'memory' && <MemoryView theme={activeTheme} />}
        </main>
      </div>

      <SettingsModal 
        isOpen={isSettingsOpen} onClose={() => setIsSettingsOpen(false)}
        uiStyle={uiStyle} setUiStyle={setUiStyle}
        accentColor={accentColor} setAccentColor={setAccentColor}
        fontSize={fontSize} setFontSize={setFontSize}
        isDarkMode={isDarkMode} setIsDarkMode={setIsDarkMode}
        onClearHistory={() => { setChatHistory([]); setMessages([]); setActiveChatId(null); setIsSettingsOpen(false); }}
        systemInstruction={systemInstruction} setSystemInstruction={setSystemInstruction}
      />
    </div>
  );
}

export default App;

import React, { useState, useRef, useEffect, useCallback } from 'react';
import type { ChatMessage, ChatPart, SearchResult, UIStyle, ThemeColors, FontSize, ModelType, Friend } from '../types';
import { GoogleGenAI } from "@google/genai";
import { BotIcon, SendIcon, UserIcon, ImageIcon, SearchIcon, SparklesIcon, UsersIcon, CodeIcon } from './Icons';

interface ChatViewProps {
  messages: ChatMessage[];
  setMessages: React.Dispatch<React.SetStateAction<ChatMessage[]>>;
  uiStyle: UIStyle;
  theme: ThemeColors;
  fontSize: FontSize;
  systemInstruction: string;
  model: ModelType;
  setActiveModel: (m: ModelType) => void;
  friends?: Friend[];
}

const SourceCard: React.FC<{ result: SearchResult }> = ({ result }) => (
    <a 
        href={result.uri} 
        target="_blank" 
        rel="noopener noreferrer"
        className="flex items-center gap-2 p-2 bg-white/50 dark:bg-slate-800/50 backdrop-blur-sm border border-slate-200 dark:border-slate-700 rounded-xl hover:border-blue-500 transition-all shrink-0 max-w-[160px] shadow-sm"
    >
        <div className="w-6 h-6 rounded bg-blue-100 dark:bg-blue-900/40 flex items-center justify-center shrink-0">
            <SearchIcon className="w-3 h-3 text-blue-600" />
        </div>
        <div className="flex-1 min-w-0">
            <p className="text-[10px] font-bold text-slate-900 dark:text-slate-100 truncate">{result.title}</p>
        </div>
    </a>
);

export const ChatView: React.FC<ChatViewProps> = ({ messages, setMessages, theme, systemInstruction, model, setActiveModel, friends = [] }) => {
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [selectedImage, setSelectedImage] = useState<{ data: string; mimeType: string } | null>(null);
  const [webSearchEnabled, setWebSearchEnabled] = useState(true);
  const [isModelDropdownOpen, setIsModelDropdownOpen] = useState(false);
  const [isFriendDropdownOpen, setIsFriendDropdownOpen] = useState(false);
  const [isFirstMessageSent, setIsFirstMessageSent] = useState(messages.length > 0);
  const [activeParticipants, setActiveParticipants] = useState<string[]>([]);

  const chatContainerRef = useRef<HTMLDivElement>(null);
  const textareaRef = useRef<HTMLTextAreaElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (chatContainerRef.current) {
      chatContainerRef.current.scrollTo({
        top: chatContainerRef.current.scrollHeight,
        behavior: 'smooth'
      });
    }
  }, [messages, isLoading]);

  useEffect(() => {
    if (messages.length > 0 && !isFirstMessageSent) {
      setIsFirstMessageSent(true);
    }
  }, [messages.length, isFirstMessageSent]);

  const handleSendMessage = useCallback(async (textOverride?: string) => {
    const textInput = (textOverride || input).trim();
    if ((!textInput && !selectedImage) || isLoading) return;

    const userMessageParts: ChatPart[] = [];
    if (selectedImage) userMessageParts.push({ inlineData: { mimeType: selectedImage.mimeType, data: selectedImage.data } });

    const participantPrefix = activeParticipants.length > 0 
        ? `[Involving Cognates: ${activeParticipants.map(id => friends.find(f => f.id === id)?.name).join(', ')}] ` 
        : '';

    if (textInput) userMessageParts.push({ text: participantPrefix + textInput });

    const userMessage: ChatMessage = { id: `msg-${Date.now()}`, role: 'user', parts: userMessageParts };
    const modelPlaceholderId = `msg-${Date.now() + 1}`;
    const modelPlaceholder: ChatMessage = { id: modelPlaceholderId, role: 'model', parts: [{ text: '' }], isSearching: webSearchEnabled };

    setMessages(prev => [...prev, userMessage, modelPlaceholder]);
    setInput(''); 
    setSelectedImage(null);
    setIsLoading(true);
    if (!isFirstMessageSent) setIsFirstMessageSent(true);

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const history = messages.map(msg => ({
        role: msg.role,
        parts: msg.parts.map(p => {
            if (p.text) return { text: p.text };
            if (p.inlineData) return { inlineData: p.inlineData };
            return null;
        }).filter(Boolean) as any[]
      }));

      const realModelMapping: Record<string, string> = {
        'cognix-arc-1.0': 'gemini-3-flash-preview',
        'gemini-3-flash-preview': 'gemini-3-flash-preview',
        'gemini-3-pro-preview': 'gemini-3-pro-preview',
        'gemini-2.5-flash-native-audio-preview-09-2025': 'gemini-2.5-flash-native-audio-preview-09-2025'
      };

      const realModel = realModelMapping[model] || 'gemini-3-flash-preview';

      const stream = await ai.models.generateContentStream({
          model: realModel as any,
          contents: [...history, { role: 'user', parts: userMessageParts as any }],
          config: { 
              systemInstruction: systemInstruction, 
              tools: webSearchEnabled ? [{ googleSearch: {} }] : [],
              temperature: 0.7 
          },
      });

      let fullText = '';
      let searchResults: SearchResult[] = [];

      for await (const chunk of stream) {
        if(chunk.text) {
            fullText += chunk.text;
            setMessages(prev => prev.map(m => m.id === modelPlaceholderId ? { ...m, parts: [{ ...m.parts[0], text: fullText.replace(/\*/g, '') }], isSearching: false } : m));
        }
        const chunks = chunk.candidates?.[0]?.groundingMetadata?.groundingChunks;
        if (chunks) {
            const results = chunks.map((c: any) => c.web ? { ...c.web, type: 'web' } : null).filter(Boolean);
            searchResults = [...searchResults, ...results];
        }
      }

      if (searchResults.length > 0) {
        const unique = Array.from(new Map(searchResults.map(i => [i.uri, i])).values());
        setMessages(prev => prev.map(m => m.id === modelPlaceholderId ? { ...m, parts: [{ ...m.parts[0], searchResults: unique }] } : m));
      }
    } catch (error) {
      setMessages(prev => prev.map(m => m.id === modelPlaceholderId ? { ...m, parts: [{ text: `Interface Sync Failure: Retrying with legacy protocol.` }], isSearching: false } : m));
    } finally {
      setIsLoading(false);
    }
  }, [input, isLoading, messages, selectedImage, systemInstruction, model, webSearchEnabled, setMessages, isFirstMessageSent, activeParticipants, friends]);

  const toggleParticipant = (friendId: string) => {
    if (activeParticipants.length >= 10 && !activeParticipants.includes(friendId)) return;
