                                            <p className="font-black text-slate-900 dark:text-white truncate">{f.name}</p>
                                            <div className="flex items-center gap-1.5 mt-1">
                                                <div className="w-1.5 h-1.5 rounded-full bg-green-500"></div>
                                                <p className="text-[10px] text-slate-400 font-bold uppercase tracking-widest">Active Node</p>
                                            </div>
                                        </div>
                                    </div>
                                ))}
                            </div>
                        )}
                    </div>

                    <div className="space-y-6 animate-fade-in-up [animation-delay:600ms]">
                        <div className="bg-indigo-600 p-8 rounded-[3rem] text-white shadow-2xl shadow-indigo-500/20 relative overflow-hidden group">
                            <div className="relative z-10">
                                <h3 className="text-2xl font-black mb-4">Invite Cognates</h3>
                                <p className="text-sm text-indigo-100 mb-8 leading-relaxed font-medium">Generate a secure handshake link to invite peers to your intelligence node. Up to 10 participants per session.</p>

                                <button 
                                    onClick={generateLink}
                                    className="w-full py-4 bg-white text-indigo-600 font-black rounded-2xl shadow-xl hover:shadow-2xl transition-all active:scale-95 text-sm uppercase tracking-widest"
                                >
                                    Generate Handshake
                                </button>

                                {inviteLink && (
                                    <div className="mt-6 p-4 bg-indigo-700/50 backdrop-blur-md rounded-2xl border border-white/10 flex items-center justify-between gap-3 animate-fade-in">
                                        <span className="text-[10px] font-mono text-white truncate opacity-80">{inviteLink}</span>
                                        <button onClick={copyToClipboard} className="shrink-0 p-2 hover:bg-white/10 rounded-xl transition-all">
                                            {copied ? <span className="text-[9px] font-black text-green-300">DONE</span> : <CopyIcon className="w-4 h-4 text-white"/>}
                                        </button>
                                    </div>
                                )}
                            </div>
                            <div className="absolute -right-10 -bottom-10 w-40 h-40 bg-white/10 rounded-full blur-3xl group-hover:scale-125 transition-transform duration-1000"></div>
                        </div>

                        <div className="p-8 bg-white dark:bg-slate-900 rounded-[3rem] border border-slate-200 dark:border-slate-800 shadow-sm">
                            <h4 className="text-sm font-black text-slate-900 dark:text-white mb-4 uppercase tracking-widest">Network Protocol</h4>
                            <ul className="space-y-4">
                                {[
                                    "Handshake links expire after 24 hours.",
                                    "Max 10 active cognates per node.",
                                    "Shared intelligence history is end-to-end encrypted.",
                                    "Cognate identity is local to your network."
                                ].map((item, i) => (
                                    <li key={i} className="flex gap-3 text-xs text-slate-500 dark:text-slate-400 leading-relaxed font-medium">
                                        <div className="w-1.5 h-1.5 rounded-full bg-indigo-500 mt-1.5 shrink-0"></div>
                                        {item}
                                    </li>
                                ))}
                            </ul>
                        </div>
                    </div>
                </div>
            </div>
        </div>
    );
};

export type Mode = 'chat' | 'live' | 'friends' | 'toolbox' | 'memory' | 'community' | 'coding';
export type UIStyle = 'modern' | 'glass' | 'brutal' | 'retro';
export type AccentColor = 'blue' | 'violet' | 'emerald' | 'rose' | 'amber';
export type FontSize = 'small' | 'normal' | 'large';
export type ModelType = 
  | 'cognix-arc-1.0'
  | 'gemini-3-flash-preview' 
  | 'gemini-3-pro-preview' 
  | 'ciorea-coding'
  | 'clora-workflow';

export interface Friend {
  id: string;
  name: string;
  avatar: string;
  status: 'online' | 'offline' | 'busy' | 'away';
  isFollowing?: boolean;
}

export interface Deployment {
  id: string;
  title: string;
  code: string;
  timestamp: number;
}

export interface CommunityReply {
    id: string;
    author: string;
    content: string;
    timestamp: number;
}

export interface CommunityPost {
    id: string;
    author: string;
    authorId: string;
    content: string;
    timestamp: number;
    likedBy: string[]; // User IDs who liked
    replies: CommunityReply[];
    type: 'text' | 'image' | 'code';
    mediaUrl?: string;
}

export interface MemoryFact {
    id: string;
    category: 'preference' | 'project' | 'personal' | 'work';
    content: string;
    timestamp: string;
}

export interface ThemeColors {
    primary: string;
    primaryHover: string;
    text: string;
    textDark: string;
    bgSoft: string;
    darkBgSoft: string;
    border: string;
    ring: string;
    gradient: string;
}

export interface SearchResult {
  uri: string;
  title: string;
  type?: 'web' | 'map';
}

export interface ChatPart {
  text?: string;
  inlineData?: {
    mimeType: string;
    data: string; // base64 encoded
  };
  functionCall?: {
    name: string;
    args: any;
  };
  searchResults?: SearchResult[];
}

export interface ChatMessage {
  id: string;
  role: 'user' | 'model';
  parts: ChatPart[];
  isSearching?: boolean;
}

export interface ChatSession {
  id:string;
  title: string;
  messages: ChatMessage[];
  participants?: string[]; // Friend IDs
}

import React, { useState, useRef, useEffect, useCallback } from 'react';
import type { ChatMessage, ChatPart, SearchResult, UIStyle, ThemeColors, FontSize, ModelType, Friend } from '../types';
import { GoogleGenAI } from "@google/genai";
import { BotIcon, SendIcon, UserIcon, ImageIcon, SearchIcon, SparklesIcon, UsersIcon, CodeIcon, CopyIcon } from './Icons';

interface ChatViewProps {
  messages: ChatMessage[];
  setMessages: React.Dispatch<React.SetStateAction<ChatMessage[]>>;
  uiStyle: UIStyle;
  theme: ThemeColors;
  fontSize: FontSize;
  systemInstruction: string;
  model: ModelType;
  setActiveModel: (m: ModelType) => void;
  friends?: Friend[];
}

const SourceCard: React.FC<{ result: SearchResult }> = ({ result }) => (
    <a 
        href={result.uri} 
        target="_blank" 
        rel="noopener noreferrer"
        className="flex items-center gap-2 p-2 bg-white/50 dark:bg-slate-800/50 backdrop-blur-sm border border-slate-200 dark:border-slate-700 rounded-xl hover:border-blue-500 transition-all shrink-0 max-w-[160px] shadow-sm"
    >
        <div className="w-6 h-6 rounded bg-blue-100 dark:bg-blue-900/40 flex items-center justify-center shrink-0">
            <SearchIcon className="w-3 h-3 text-blue-600" />
        </div>
        <div className="flex-1 min-w-0">
            <p className="text-[10px] font-bold text-slate-900 dark:text-slate-100 truncate">{result.title}</p>
        </div>
    </a>
);

export const ChatView: React.FC<ChatViewProps> = ({ messages, setMessages, theme, systemInstruction, model, setActiveModel, friends = [] }) => {
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [selectedImage, setSelectedImage] = useState<{ data: string; mimeType: string } | null>(null);
  const [webSearchEnabled, setWebSearchEnabled] = useState(true);
  const [isModelDropdownOpen, setIsModelDropdownOpen] = useState(false);
  const [isFriendDropdownOpen, setIsFriendDropdownOpen] = useState(false);
  const [isFirstMessageSent, setIsFirstMessageSent] = useState(messages.length > 0);
  const [activeParticipants, setActiveParticipants] = useState<string[]>([]);
  const [showInviteFeedback, setShowInviteFeedback] = useState(false);

  const chatContainerRef = useRef<HTMLDivElement>(null);
  const textareaRef = useRef<HTMLTextAreaElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (chatContainerRef.current) {
      chatContainerRef.current.scrollTo({
        top: chatContainerRef.current.scrollHeight,
        behavior: 'smooth'
      });
    }
  }, [messages, isLoading]);

  useEffect(() => {
    if (messages.length > 0 && !isFirstMessageSent) {
      setIsFirstMessageSent(true);
    }
  }, [messages.length, isFirstMessageSent]);

  const handleSendMessage = useCallback(async (textOverride?: string) => {
    const textInput = (textOverride || input).trim();
    if ((!textInput && !selectedImage) || isLoading) return;

    const userMessageParts: ChatPart[] = [];
    if (selectedImage) userMessageParts.push({ inlineData: { mimeType: selectedImage.mimeType, data: selectedImage.data } });

    const participantPrefix = activeParticipants.length > 0 
        ? `[Collective Intelligence session with: ${activeParticipants.map(id => friends.find(f => f.id === id)?.name).join(', ')}] ` 
        : '';

    if (textInput) userMessageParts.push({ text: participantPrefix + textInput });

    const userMessage: ChatMessage = { id: `msg-${Date.now()}`, role: 'user', parts: userMessageParts };
    const modelPlaceholderId = `msg-${Date.now() + 1}`;
    const modelPlaceholder: ChatMessage = { id: modelPlaceholderId, role: 'model', parts: [{ text: '' }], isSearching: webSearchEnabled };

    setMessages(prev => [...prev, userMessage, modelPlaceholder]);
    setInput(''); 
    setSelectedImage(null);
    setIsLoading(true);
    if (!isFirstMessageSent) setIsFirstMessageSent(true);

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const history = messages.map(msg => ({
        role: msg.role,
        parts: msg.parts.map(p => {
            if (p.text) return { text: p.text };
            if (p.inlineData) return { inlineData: p.inlineData };
            return null;
        }).filter(Boolean) as any[]
      }));

      const realModelMapping: Record<string, string> = {
        'cognix-arc-1.0': 'gemini-3-flash-preview',
        'gemini-3-flash-preview': 'gemini-3-flash-preview',
        'gemini-3-pro-preview': 'gemini-3-pro-preview',
        'ciorea-coding': 'gemini-3-pro-preview',
        'clora-workflow': 'gemini-3-pro-preview'
      };

      const customInstructions: Record<string, string> = {
        'ciorea-coding': "You are Ciorea, an elite AI Software Architect. You write modular, scalable, and optimized code. You prioritize security, performance, and best practices.",
        'clora-workflow': "You are Clora, a high-precision workflow and technical logic engine. You analyze systems, identify bottlenecks, and provide structured optimization strategies."
      };

      const realModel = realModelMapping[model] || 'gemini-3-flash-preview';
      const effectiveInstruction = customInstructions[model] ? `${systemInstruction}\n\n${customInstructions[model]}` : systemInstruction;

      const stream = await ai.models.generateContentStream({
          model: realModel as any,
          contents: [...history, { role: 'user', parts: userMessageParts as any }],
          config: { 
              systemInstruction: effectiveInstruction, 
              tools: webSearchEnabled ? [{ googleSearch: {} }] : [],
              temperature: 0.7 
          },
      });

      let fullText = '';
      let searchResults: SearchResult[] = [];

      for await (const chunk of stream) {
        if(chunk.text) {
            fullText += chunk.text;
            setMessages(prev => prev.map(m => m.id === modelPlaceholderId ? { ...m, parts: [{ ...m.parts[0], text: fullText.replace(/\*/g, '') }], isSearching: false } : m));
        }
        const chunks = chunk.candidates?.[0]?.groundingMetadata?.groundingChunks;
        if (chunks) {
            const results = chunks.map((c: any) => c.web ? { ...c.web, type: 'web' } : null).filter(Boolean);
            searchResults = [...searchResults, ...results];
        }
      }

      if (searchResults.length > 0) {
        const unique = Array.from(new Map(searchResults.map(i => [i.uri, i])).values());
        setMessages(prev => prev.map(m => m.id === modelPlaceholderId ? { ...m, parts: [{ ...m.parts[0], searchResults: unique }] } : m));
      }
    } catch (error) {
      setMessages(prev => prev.map(m => m.id === modelPlaceholderId ? { ...m, parts: [{ text: `Interface Sync Failure: Attempting reconnection...` }], isSearching: false } : m));
    } finally {
      setIsLoading(false);
    }
  }, [input, isLoading, messages, selectedImage, systemInstruction, model, webSearchEnabled, setMessages, isFirstMessageSent, activeParticipants, friends]);

  const toggleParticipant = (friendId: string) => {
    if (activeParticipants.length >= 10 && !activeParticipants.includes(friendId)) return;
    setActiveParticipants(prev => prev.includes(friendId) ? prev.filter(id => id !== friendId) : [...prev, friendId]);
  };

  const handleShareInvite = () => {
    const inviteLink = `https://cognix.ai/session/${Date.now().toString(36)}`;
    navigator.clipboard.writeText(inviteLink);
    setShowInviteFeedback(true);
    setTimeout(() => setShowInviteFeedback(false), 2000);
  };

  const adjustTextareaHeight = () => {
    if (textareaRef.current) {
      textareaRef.current.style.height = 'auto';
      textareaRef.current.style.height = `${Math.min(textareaRef.current.scrollHeight, 180)}px`;
    }
  };

  useEffect(() => { adjustTextareaHeight(); }, [input]);

  const modelOptions = [
    { id: 'cognix-arc-1.0', label: 'CognixArc 1.0', desc: 'Standard Intelligence' },
    { id: 'gemini-3-flash-preview', label: 'Flash 3', desc: 'Ultra-fast Logic' },
    { id: 'gemini-3-pro-preview', label: 'Pro 3', desc: 'Expert Reasoning' },
    { id: 'ciorea-coding', label: 'Ciorea', desc: 'Elite Versatile Coding' },
    { id: 'clora-workflow', label: 'Clora', desc: 'High-Precision Logic' }
  ];

  const quickStarts = [
    { t: "Logic Puzzle", q: "Solve this sequence: 1, 1, 2, 3, 5, 8, ... and explain the rule.", icon: <SparklesIcon className="w-6 h-6"/> },
    { t: "Ciorea Studio", q: "Architect a robust React dashboard component with Ciorea's elite coding standards.", icon: <CodeIcon className="w-6 h-6 text-indigo-500"/> },
    { t: "Clora Analysis", q: "Perform a structured technical analysis of a microservices architecture for a FinTech app.", icon: <BotIcon className="w-6 h-6 text-emerald-500"/> },
    { t: "Global Trends", q: "Search for current breakthroughs in quantum computing and summarize the impact.", icon: <SearchIcon className="w-6 h-6 text-blue-500"/> }
  ];

  return (
    <div className="flex flex-col h-full bg-white dark:bg-slate-900 relative">
      {activeParticipants.length > 0 && (
          <div className="absolute top-4 left-1/2 -translate-x-1/2 z-20 flex items-center gap-2 px-4 py-2 bg-indigo-600 rounded-full shadow-2xl animate-fade-in border border-white/20">
              <div className="flex -space-x-2.5">
                  {activeParticipants.map(id => (
                      <div key={id} className="w-7 h-7 rounded-full bg-white border-2 border-indigo-600 flex items-center justify-center text-[9px] font-black text-indigo-600 uppercase">
                          {friends.find(f => f.id === id)?.name[0]}
                      </div>
                  ))}
              </div>
              <span className="text-[10px] font-black text-white uppercase tracking-widest">{activeParticipants.length}/10 Cognates Active</span>
          </div>
      )}

      <div ref={chatContainerRef} className="flex-1 overflow-y-auto px-4 sm:px-10 md:px-16 pb-60 pt-6 custom-scrollbar scroll-smooth">
        {!isFirstMessageSent ? (
            <div className="max-w-4xl mx-auto flex flex-col items-center justify-center min-h-[70vh] text-center px-4 animate-fade-in">
                 <div className="relative mb-8 group animate-float">
                     <div className="absolute inset-0 bg-blue-500/10 rounded-full blur-[80px] group-hover:bg-blue-500/20 transition-all duration-700"></div>
                     <BotIcon className="relative w-20 h-20 sm:w-24 sm:h-24 md:w-28 md:h-28 drop-shadow-3xl" />
                 </div>
                 <h2 className="text-4xl sm:text-5xl md:text-6xl font-black text-slate-900 dark:text-white mb-6 tracking-tight">
                   Cognix Intelligence
                 </h2>
                 <p className="text-slate-500 dark:text-slate-400 max-w-2xl mb-12 text-lg sm:text-xl font-medium opacity-90 leading-relaxed">
                    Personalized neural node for collective intelligence. Built for high-precision logic and elite software architecture.
                 </p>

                 <div className="grid grid-cols-1 sm:grid-cols-2 gap-6 w-full">
                     {quickStarts.map((item, i) => (
                        <button key={i} onClick={() => handleSendMessage(item.q)} className="text-left p-6 sm:p-8 rounded-[2.5rem] border border-slate-100 dark:border-slate-800 hover:border-blue-500 hover:bg-slate-50 dark:hover:bg-slate-800/50 transition-all group flex gap-6 items-center bg-white dark:bg-slate-900 shadow-lg shadow-slate-200/50 dark:shadow-none active:scale-[0.98]">
                            <div className="w-14 h-14 sm:w-16 sm:h-16 rounded-[1.5rem] bg-slate-100 dark:bg-slate-800 flex items-center justify-center group-hover:bg-blue-600 group-hover:text-white transition-all shadow-inner">
                                {item.icon}
                            </div>
                            <div className="min-w-0">
                                <span className="font-black text-slate-900 dark:text-white text-base sm:text-lg truncate block leading-tight">{item.t}</span>
                                <span className="text-[10px] text-slate-400 font-bold uppercase tracking-[0.2em] mt-2 block opacity-60">Neural Protocol</span>
                            </div>
                        </button>
                     ))}
                 </div>
            </div>
        ) : (
            <div className="max-w-4xl mx-auto space-y-12 animate-fade-in-up pb-20">
                {messages.map((msg) => (
                    <div key={msg.id} className={`flex gap-4 sm:gap-6 ${msg.role === 'user' ? 'flex-row-reverse' : 'flex-row'}`}>
                        <div className={`w-10 h-10 sm:w-12 sm:h-12 shrink-0 rounded-2xl flex items-center justify-center shadow-lg
                            ${msg.role === 'user' ? 'bg-slate-100 dark:bg-slate-800 text-slate-500 border border-slate-200 dark:border-slate-700' : 'bg-gradient-to-tr from-blue-600 to-indigo-600 text-white'}
                        `}>
                             {msg.role === 'user' ? <UserIcon className="w-6 h-6"/> : <BotIcon className="w-7 h-7 sm:w-8 sm:h-8"/>}
                        </div>

                        <div className={`flex flex-col gap-3 max-w-[90%] ${msg.role === 'user' ? 'items-end' : 'items-start'}`}>
                             {msg.parts.map((part, i) => (
                                 <div key={i} className={`relative leading-relaxed transition-all
                                     ${msg.role === 'user' 
                                         ? 'bg-blue-600 text-white px-5 py-3 rounded-[1.5rem] rounded-tr-sm shadow-xl font-medium text-sm sm:text-base' 
                                         : 'text-slate-800 dark:text-slate-100 text-sm sm:text-lg'}
                                 `}>
                                     {part.inlineData && <img src={`data:${part.inlineData.mimeType};base64,${part.inlineData.data}`} className="rounded-[1.5rem] mb-6 max-h-80 shadow-2xl border border-slate-200 dark:border-slate-800 object-contain" alt="Context"/>}

                                     {msg.isSearching && i === 0 && (
                                         <div className="flex items-center gap-2 text-blue-500 mb-4 bg-blue-50 dark:bg-blue-900/20 px-4 py-2 rounded-full border border-blue-500/20 w-fit">
                                             <div className="flex gap-1.5">
                                                <div className="w-2 h-2 bg-blue-500 rounded-full animate-bounce [animation-delay:-0.3s]"></div>
                                                <div className="w-2 h-2 bg-blue-500 rounded-full animate-bounce [animation-delay:-0.15s]"></div>
                                                <div className="w-2 h-2 bg-blue-500 rounded-full animate-bounce"></div>
                                             </div>
                                             <span className="text-[10px] font-black uppercase tracking-[0.2em] ml-2">Neural Search</span>
                                         </div>
                                     )}

                                     <div className="whitespace-pre-wrap prose prose-sm sm:prose-base dark:prose-invert max-w-none">{part.text}</div>

                                     {part.searchResults && part.searchResults.length > 0 && (
                                         <div className="mt-6 pt-6 border-t border-slate-100 dark:border-slate-800">
                                            <div className="flex gap-3 overflow-x-auto pb-4 no-scrollbar scroll-smooth">
                                                {part.searchResults.map((res, idx) => <SourceCard key={idx} result={res} />)}
                                            </div>
                                         </div>
                                     )}
                                 </div>
                             ))}
                        </div>
                    </div>
                ))}
                {isLoading && (
                  <div className="flex gap-4 sm:gap-6 items-center animate-fade-in">
                    <div className="w-10 h-10 sm:w-12 sm:h-12 shrink-0 rounded-2xl bg-gradient-to-tr from-blue-600 to-indigo-600 flex items-center justify-center shadow-lg">
                      <BotIcon className="w-7 h-7 animate-pulse" />
                    </div>
                    <div className="flex gap-2 p-4 bg-slate-50 dark:bg-slate-800/50 rounded-[1.2rem] shadow-inner">
                      <div className="w-2 h-2 bg-blue-500 rounded-full animate-bounce [animation-delay:-0.3s]"></div>
                      <div className="w-2 h-2 bg-blue-500 rounded-full animate-bounce [animation-delay:-0.15s]"></div>
                      <div className="w-2 h-2 bg-blue-500 rounded-full animate-bounce"></div>
                    </div>
                  </div>
                )}
            </div>
        )}
      </div>

      <div className={`absolute bottom-0 left-0 right-0 px-4 sm:px-10 md:px-20 pb-10 pt-16 transition-all duration-700 ${!isFirstMessageSent ? '' : 'bg-gradient-to-t from-white dark:from-slate-900 via-white/95 dark:via-slate-900/95 to-transparent'}`}>
          <div className="max-w-3xl mx-auto relative pointer-events-auto">
              <div className="bg-white dark:bg-slate-800/95 backdrop-blur-3xl rounded-[2.2rem] sm:rounded-[3rem] shadow-3xl border border-slate-200/60 dark:border-slate-700/60 focus-within:ring-8 ring-blue-500/5 transition-all overflow-visible">

                   <div className="flex items-center justify-between px-8 sm:px-12 pt-5 pb-2 border-b border-slate-100 dark:border-slate-700/40">
                       <div className="flex items-center gap-4 sm:gap-6 relative">
                           <div className="relative">
                                {isModelDropdownOpen && (
                                    <div className="absolute bottom-full left-0 mb-5 w-72 bg-slate-900 text-white rounded-[2rem] shadow-3xl border border-white/10 z-[100] p-2.5 animate-fade-in-up">
                                        <p className="text-[10px] font-black text-slate-500 p-4 uppercase border-b border-white/5 mb-2 tracking-widest">Select Intelligence core</p>
                                        <div className="max-h-72 overflow-y-auto custom-scrollbar">
                                            {modelOptions.map(m => (
                                                <button key={m.id} onClick={() => { setActiveModel(m.id as any); setIsModelDropdownOpen(false); }}
                                                    className={`w-full text-left px-5 py-4 hover:bg-white/10 transition-all rounded-[1.5rem] flex flex-col gap-1 ${model === m.id ? 'bg-white/10 text-blue-400' : 'text-white'}`}>
                                                    <span className="text-[12px] font-black uppercase tracking-tight">{m.label}</span>
                                                    <span className="text-[10px] opacity-40 uppercase font-bold tracking-tight">{m.desc}</span>
                                                </button>
                                            ))}
                                        </div>
                                    </div>
                                )}
                                <button onClick={() => { setIsModelDropdownOpen(!isModelDropdownOpen); setIsFriendDropdownOpen(false); }} className="flex items-center gap-2.5 px-5 py-2.5 bg-slate-900 dark:bg-slate-950 text-white rounded-full hover:bg-black transition-all border border-white/10 active:scale-95 shadow-lg">
                                    <span className="text-[11px] font-black uppercase whitespace-nowrap tracking-wider">{modelOptions.find(o => o.id === model)?.label || 'Core'}</span>
                                    <svg className={`w-4 h-4 transition-transform ${isModelDropdownOpen ? 'rotate-180' : ''}`} fill="none" stroke="currentColor" viewBox="0 0 24 24" strokeWidth="3.5"><path d="M19 9l-7 7-7-7"/></svg>
                                </button>
                           </div>

                           <button onClick={() => setWebSearchEnabled(!webSearchEnabled)} className={`flex items-center gap-2.5 px-5 py-2.5 rounded-full border transition-all ${webSearchEnabled ? 'bg-blue-600 border-blue-600 text-white shadow-lg' : 'bg-slate-50 dark:bg-slate-900 border-slate-200 dark:border-slate-700 text-slate-400'}`}>
                                <SearchIcon className="w-4.5 h-4.5" />
                                <span className="text-[10px] font-black uppercase hidden sm:inline tracking-[0.2em]">Neural Search</span>
                            </button>

                           <div className="relative">
                                <button onClick={() => { setIsFriendDropdownOpen(!isFriendDropdownOpen); setIsModelDropdownOpen(false); }} className={`flex items-center gap-2.5 px-5 py-2.5 rounded-full border transition-all ${activeParticipants.length > 0 ? 'bg-indigo-600 border-indigo-600 text-white shadow-lg' : 'bg-slate-50 dark:bg-slate-900 border-slate-200 dark:border-slate-700 text-slate-400'}`}>
                                    <UsersIcon className="w-4.5 h-4.5" />
                                    <span className="text-[10px] font-black uppercase hidden sm:inline tracking-[0.2em]">Collective</span>
