import React, { useState, useRef, useEffect, useCallback } from 'react';
import { ai } from '../services/gemini';
import { MicrophoneIcon, StopIcon, BotIcon, UserIcon, CameraIcon, FlipCameraIcon } from './Icons';
import type { LiveServerMessage, Blob } from '@google/genai';
import { Modality } from '@google/genai';
import type { ThemeColors } from '../types';

function encode(bytes: Uint8Array) {
    let binary = '';
    const len = bytes.byteLength;
    for (let i = 0; i < len; i++) { binary += String.fromCharCode(bytes[i]); }
    return btoa(binary);
}

function decode(base64: string) {
    const binaryString = atob(base64);
    const len = binaryString.length;
    const bytes = new Uint8Array(len);
    for (let i = 0; i < len; i++) { bytes[i] = binaryString.charCodeAt(i); }
    return bytes;
}

async function decodeAudioData(data: Uint8Array, ctx: AudioContext, sampleRate: number, numChannels: number): Promise<AudioBuffer> {
    const dataInt16 = new Int16Array(data.buffer);
    const frameCount = dataInt16.length / numChannels;
    const buffer = ctx.createBuffer(numChannels, frameCount, sampleRate);
    for (let channel = 0; channel < numChannels; channel++) {
        const channelData = buffer.getChannelData(channel);
        for (let i = 0; i < frameCount; i++) { channelData[i] = dataInt16[i * numChannels + channel] / 32768.0; }
    }
    return buffer;
}

export const LiveView: React.FC<{ theme?: ThemeColors }> = ({ theme }) => {
    const activeTheme = theme || { primary: 'bg-blue-600', primaryHover: 'hover:bg-blue-700', text: 'text-blue-600' };

    const [status, setStatus] = useState<'idle' | 'connecting' | 'active'>('idle');
    const [transcripts, setTranscripts] = useState<any[]>([]);
    const [isCameraOn, setIsCameraOn] = useState(false);
    const [facingMode, setFacingMode] = useState<'user' | 'environment'>('user');

    const sessionPromiseRef = useRef<any>(null);
    const streamRef = useRef<MediaStream | null>(null);
    const videoRef = useRef<HTMLVideoElement>(null);
    const inputAudioContextRef = useRef<AudioContext | null>(null);
    const outputAudioContextRef = useRef<AudioContext | null>(null);
    const outputNodeRef = useRef<GainNode | null>(null);
    const scriptProcessorRef = useRef<ScriptProcessorNode | null>(null);
    const mediaStreamSourceRef = useRef<MediaStreamAudioSourceNode | null>(null);
    const outputSourcesRef = useRef<Set<AudioBufferSourceNode>>(new Set());
    const nextStartTimeRef = useRef(0);

    const stopSession = useCallback(async () => {
        setStatus('idle');
        if (sessionPromiseRef.current) {
            try {
                const session = await sessionPromiseRef.current;
                session.close();
            } catch (e) {}
            sessionPromiseRef.current = null;
        }
        streamRef.current?.getTracks().forEach(track => track.stop());
        streamRef.current = null;
        if (videoRef.current) videoRef.current.srcObject = null;
        if (inputAudioContextRef.current?.state !== 'closed') await inputAudioContextRef.current?.close();
        if (outputAudioContextRef.current?.state !== 'closed') await outputAudioContextRef.current?.close();
        outputSourcesRef.current.forEach(source => { try { source.stop(); } catch(e) {} });
        outputSourcesRef.current.clear();
    }, []);

    const startSession = useCallback(async () => {
        setStatus('connecting');
        setTranscripts([]);
        try {
            const inputCtx = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 16000 });
            const outputCtx = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
            if (inputCtx.state === 'suspended') await inputCtx.resume();
            if (outputCtx.state === 'suspended') await outputCtx.resume();

            const outputNode = outputCtx.createGain();
            outputNode.connect(outputCtx.destination);
            inputAudioContextRef.current = inputCtx;
            outputAudioContextRef.current = outputCtx;
            outputNodeRef.current = outputNode;
            nextStartTimeRef.current = 0;

            sessionPromiseRef.current = ai.live.connect({
                model: 'gemini-2.5-flash-native-audio-preview-09-2025',
                callbacks: {
                    onopen: async () => {
                        try {
                            const constraints = { 
                                audio: true, 
                                video: isCameraOn ? { facingMode } : false 
                            };
                            streamRef.current = await navigator.mediaDevices.getUserMedia(constraints);
                            if (videoRef.current && isCameraOn) videoRef.current.srcObject = streamRef.current;

                            mediaStreamSourceRef.current = inputAudioContextRef.current!.createMediaStreamSource(streamRef.current);
                            scriptProcessorRef.current = inputAudioContextRef.current!.createScriptProcessor(4096, 1, 1);
                            scriptProcessorRef.current.onaudioprocess = (e) => {
                                const l = e.inputBuffer.getChannelData(0).length;
                                const int16 = new Int16Array(l);
                                const data = e.inputBuffer.getChannelData(0);
                                for (let i = 0; i < l; i++) { int16[i] = data[i] * 32768; }
                                sessionPromiseRef.current?.then((session: any) => {
                                    session.sendRealtimeInput({ media: { data: encode(new Uint8Array(int16.buffer)), mimeType: 'audio/pcm;rate=16000' } });
                                });
                            };
                            mediaStreamSourceRef.current.connect(scriptProcessorRef.current);
                            scriptProcessorRef.current.connect(inputAudioContextRef.current!.destination);
                            setStatus('active');
                        } catch (err) { stopSession(); }
                    },
                    onmessage: async (message: LiveServerMessage) => {
                        const base64Audio = message.serverContent?.modelTurn?.parts?.[0]?.inlineData?.data;
                        if (base64Audio && outputAudioContextRef.current) {
                            nextStartTimeRef.current = Math.max(nextStartTimeRef.current, outputAudioContextRef.current.currentTime);
                            const buffer = await decodeAudioData(decode(base64Audio), outputAudioContextRef.current, 24000, 1);
                            const source = outputAudioContextRef.current.createBufferSource();
                            source.buffer = buffer;
                            source.connect(outputNodeRef.current!);
                            source.start(nextStartTimeRef.current);
                            nextStartTimeRef.current += buffer.duration;
                            outputSourcesRef.current.add(source);
                        }
                    },
                    onerror: () => stopSession(),
                    onclose: () => setStatus('idle'),
                },
                config: {
                    responseModalities: [Modality.AUDIO],
                    systemInstruction: "You are Nexzi Live. Be concise and engage in direct voice conversation.",
                },
            });
        } catch (e) { setStatus('idle'); }
    }, [stopSession, isCameraOn, facingMode]);

    const toggleCamera = async () => {
        setIsCameraOn(!isCameraOn);
        if (status === 'active') {
            await stopSession();
            // Restarts with new camera state
            setTimeout(() => startSession(), 200);
        }
    };

    const flipCamera = async () => {
        setFacingMode(prev => prev === 'user' ? 'environment' : 'user');
        if (status === 'active') {
            await stopSession();
            setTimeout(() => startSession(), 200);
        }
    };

    return (
        <div className="flex flex-col h-full bg-slate-50 dark:bg-slate-900 p-4 relative overflow-hidden">
             {/* Camera Feed */}
            <div className={`absolute inset-0 z-0 bg-black transition-opacity duration-1000 ${isCameraOn && status === 'active' ? 'opacity-100' : 'opacity-0'}`}>
                <video ref={videoRef} autoPlay playsInline muted className="w-full h-full object-cover" />
                <div className="absolute inset-0 bg-gradient-to-b from-black/40 via-transparent to-black/60" />
            </div>

            <div className="relative z-10 h-full flex flex-col items-center justify-center">
                <div className={`p-10 text-center transition-all duration-700 ${status !== 'idle' ? 'opacity-0 scale-95 pointer-events-none' : 'opacity-100 scale-100'}`}>
                    <div className={`w-24 h-24 sm:w-28 sm:h-28 mx-auto mb-10 rounded-[2.5rem] bg-blue-600 flex items-center justify-center shadow-3xl animate-float`}>
                         <MicrophoneIcon className="w-12 h-12 text-white" />
                    </div>
                    <h2 className="text-4xl font-black text-slate-900 dark:text-white mb-4 tracking-tighter italic">Nexzi.talk</h2>
                    <p className="max-w-xs mx-auto text-slate-500 dark:text-slate-400 text-sm font-medium leading-relaxed mb-12">
                        Advanced low-latency neural uplink with optional visual grounding.
                    </p>
                </div>

                <div className="absolute bottom-12 flex flex-col items-center gap-10">
                    <div className="flex gap-4">
                        <button onClick={toggleCamera} className={`p-4 rounded-3xl transition-all shadow-xl ${isCameraOn ? 'bg-blue-600 text-white' : 'bg-white dark:bg-slate-800 text-slate-500'}`}>
                            <CameraIcon className="w-6 h-6" />
                        </button>
                        {isCameraOn && (
                            <button onClick={flipCamera} className="p-4 rounded-3xl bg-white dark:bg-slate-800 text-slate-500 shadow-xl">
                                <FlipCameraIcon className="w-6 h-6" />
                            </button>
                        )}
                    </div>

                    <button 
                        onClick={() => status === 'active' ? stopSession() : startSession()} 
                        className={`w-20 h-20 rounded-[2rem] flex items-center justify-center shadow-3xl transition-all duration-500 active:scale-90
                            ${status === 'active' ? 'bg-red-600 text-white' : 'bg-blue-600 text-white'}`}
                    >
                        {status === 'active' ? <StopIcon className="w-8 h-8" /> : <MicrophoneIcon className="w-10 h-10" />}
                    </button>
                </div>
            </div>
        </div>
    );
};

import React, { useState, useEffect } from 'react';
import type { ThemeColors, MemoryFact } from '../types';
