import React, { useState, useRef, useEffect, useCallback } from 'react';
import type { ChatMessage, ChatPart, UIStyle, ThemeColors, FontSize, ModelType, Friend } from '../types';
import { GoogleGenAI } from "@google/genai";
import { BotIcon, SendIcon, UserIcon, ImageIcon, SearchIcon, SparklesIcon, UsersIcon, CodeIcon, CopyIcon } from './Icons';

interface ChatViewProps {
  messages: ChatMessage[];
  setMessages: React.Dispatch<React.SetStateAction<ChatMessage[]>>;
  uiStyle: UIStyle;
  theme: ThemeColors;
  fontSize: FontSize;
  systemInstruction: string;
  model: ModelType;
  setActiveModel: (m: ModelType) => void;
  friends?: Friend[];
}

export const ChatView: React.FC<ChatViewProps> = ({ messages, setMessages, theme, systemInstruction, model, setActiveModel, friends = [] }) => {
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [selectedImage, setSelectedImage] = useState<{ data: string; mimeType: string } | null>(null);
  const [webSearchEnabled, setWebSearchEnabled] = useState(true);
  const [isModelDropdownOpen, setIsModelDropdownOpen] = useState(false);
  const [isFriendDropdownOpen, setIsFriendDropdownOpen] = useState(false);
  const [isFirstMessageSent, setIsFirstMessageSent] = useState(messages.length > 0);
  const [activeParticipants, setActiveParticipants] = useState<string[]>([]);
  const [showInviteFeedback, setShowInviteFeedback] = useState(false);

  const chatContainerRef = useRef<HTMLDivElement>(null);
  const textareaRef = useRef<HTMLTextAreaElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (chatContainerRef.current) {
      chatContainerRef.current.scrollTo({
        top: chatContainerRef.current.scrollHeight,
        behavior: 'smooth'
      });
    }
  }, [messages, isLoading]);

  useEffect(() => {
    if (messages.length > 0 && !isFirstMessageSent) {
      setIsFirstMessageSent(true);
    }
  }, [messages.length, isFirstMessageSent]);

  const handleSendMessage = useCallback(async (textOverride?: string) => {
    const textInput = (textOverride || input).trim();
    if ((!textInput && !selectedImage) || isLoading) return;

    const userMessageParts: ChatPart[] = [];
    if (selectedImage) userMessageParts.push({ inlineData: { mimeType: selectedImage.mimeType, data: selectedImage.data } });

    const participantPrefix = activeParticipants.length > 0 
        ? `[Collective Session: ${activeParticipants.map(id => friends.find(f => f.id === id)?.name).join(', ')}] ` 
        : '';

    if (textInput) userMessageParts.push({ text: participantPrefix + textInput });

    const userMessage: ChatMessage = { id: `msg-${Date.now()}`, role: 'user', parts: userMessageParts };
    const modelPlaceholderId = `msg-${Date.now() + 1}`;
    const modelPlaceholder: ChatMessage = { id: modelPlaceholderId, role: 'model', parts: [{ text: '' }], isSearching: webSearchEnabled };

    setMessages(prev => [...prev, userMessage, modelPlaceholder]);
    setInput(''); 
    setSelectedImage(null);
    setIsLoading(true);

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const history = messages.map(msg => ({
        role: msg.role,
        parts: msg.parts.map(p => {
            if (p.text) return { text: p.text };
            if (p.inlineData) return { inlineData: p.inlineData };
            return null;
        }).filter(Boolean) as any[]
      }));

      const realModelMapping: Record<string, string> = {
        'cognix-arc-1.0': 'gemini-3-flash-preview',
        'gemini-3-flash-preview': 'gemini-3-flash-preview',
        'gemini-3-pro-preview': 'gemini-3-pro-preview',
        'ciorea-coding': 'gemini-3-pro-preview',
        'clora-workflow': 'gemini-3-pro-preview'
      };

      const realModel = realModelMapping[model] || 'gemini-3-flash-preview';
      const stream = await ai.models.generateContentStream({
          model: realModel as any,
          contents: [...history, { role: 'user', parts: userMessageParts as any }],
          config: { systemInstruction, tools: webSearchEnabled ? [{ googleSearch: {} }] : [] },
      });

      let fullText = '';
      for await (const chunk of stream) {
        if(chunk.text) {
            fullText += chunk.text;
            setMessages(prev => prev.map(m => m.id === modelPlaceholderId ? { ...m, parts: [{ ...m.parts[0], text: fullText }], isSearching: false } : m));
        }
      }
    } catch (error) {
      setMessages(prev => prev.map(m => m.id === modelPlaceholderId ? { ...m, parts: [{ text: `Error: Session out of sync.` }], isSearching: false } : m));
    } finally {
      setIsLoading(false);
    }
  }, [input, isLoading, messages, selectedImage, systemInstruction, model, webSearchEnabled, setMessages, activeParticipants, friends]);

  const toggleParticipant = (friendId: string) => {
    if (activeParticipants.length >= 10 && !activeParticipants.includes(friendId)) return;
    setActiveParticipants(prev => prev.includes(friendId) ? prev.filter(id => id !== friendId) : [...prev, friendId]);
  };

  const shareSessionLink = () => {
    const link = `${window.location.origin}/join/${Math.random().toString(36).substring(7)}`;
    navigator.clipboard.writeText(link);
    setShowInviteFeedback(true);
    setTimeout(() => setShowInviteFeedback(false), 2000);
  };

  const modelOptions = [
    { id: 'cognix-arc-1.0', label: 'CognixArc 1.0', desc: 'Balanced Logic' },
    { id: 'gemini-3-flash-preview', label: 'Flash 3', desc: 'Fast Intelligence' },
    { id: 'ciorea-coding', label: 'Ciorea', desc: 'Architectural Coding' },
    { id: 'clora-workflow', label: 'Clora', desc: 'Technical Logic' }
  ];

  return (
    <div className="flex flex-col h-full bg-white dark:bg-slate-900 relative">
      <div ref={chatContainerRef} className="flex-1 overflow-y-auto px-4 sm:px-12 pb-56 pt-10 custom-scrollbar scroll-smooth">
        {!isFirstMessageSent ? (
            <div className="max-w-3xl mx-auto flex flex-col items-center justify-center min-h-[60vh] text-center animate-fade-in">
                 <h2 className="text-4xl sm:text-6xl font-black text-slate-900 dark:text-white mb-6 tracking-tighter italic">Nexzi.</h2>
                 <p className="text-slate-400 max-w-lg mb-12 text-sm sm:text-lg font-medium tracking-tight opacity-80">
                    A secure private node for architectural logic and collaborative intelligence.
                 </p>

                 <div className="grid grid-cols-1 sm:grid-cols-2 gap-4 w-full">
                     {[
                         { t: "Logic Deep Dive", q: "Architect a scalable microservices infrastructure for a global Fintech app.", icon: <SparklesIcon className="w-5 h-5"/> },
                         { t: "Ciorea Logic", q: "Develop a custom React engine for real-time visualization.", icon: <CodeIcon className="w-5 h-5 text-blue-500"/> }
                     ].map((item, i) => (
                        <button key={i} onClick={() => handleSendMessage(item.q)} className="text-left p-6 rounded-[2.2rem] border border-slate-100 dark:border-slate-800 hover:border-blue-500 hover:bg-slate-50 dark:hover:bg-slate-800 transition-all flex gap-5 items-center bg-white dark:bg-slate-900 shadow-sm">
                            <div className="w-12 h-12 rounded-2xl bg-slate-50 dark:bg-slate-800 flex items-center justify-center shrink-0">
                                {item.icon}
                            </div>
                            <span className="font-black text-slate-800 dark:text-white text-sm">{item.t}</span>
                        </button>
                     ))}
                 </div>
            </div>
        ) : (
            <div className="max-w-4xl mx-auto space-y-12 animate-fade-in-up pb-10">
                {messages.map((msg) => (
                    <div key={msg.id} className={`flex gap-5 ${msg.role === 'user' ? 'flex-row-reverse' : 'flex-row'}`}>
                        <div className={`w-10 h-10 shrink-0 rounded-2xl flex items-center justify-center shadow-lg
                            ${msg.role === 'user' ? 'bg-slate-100 dark:bg-slate-800 text-slate-500' : 'bg-slate-900 text-white dark:bg-white dark:text-slate-900'}
                        `}>
                             {msg.role === 'user' ? <UserIcon className="w-6 h-6"/> : <BotIcon className="w-7 h-7"/>}
                        </div>
                        <div className={`flex flex-col gap-3 max-w-[85%] ${msg.role === 'user' ? 'items-end' : 'items-start'}`}>
                             {msg.parts.map((part, i) => (
                                 <div key={i} className={`relative leading-relaxed ${msg.role === 'user' ? 'bg-blue-600 text-white px-5 py-3 rounded-[1.8rem] rounded-tr-sm text-sm' : 'text-slate-800 dark:text-slate-100 text-sm sm:text-base'}`}>
                                     <div className="whitespace-pre-wrap prose prose-sm dark:prose-invert max-w-none">{part.text}</div>
                                 </div>
                             ))}
                        </div>
                    </div>
                ))}
            </div>
        )}
      </div>

      <div className="absolute bottom-0 left-0 right-0 px-6 sm:px-12 pb-8 pt-12 bg-gradient-to-t from-white dark:from-slate-900 to-transparent">
          <div className="max-w-2xl mx-auto relative">
              <div className="bg-white dark:bg-slate-800 rounded-[2.5rem] shadow-3xl border border-slate-100 dark:border-slate-800 focus-within:ring-8 ring-blue-500/5 transition-all">
                   <div className="flex items-center justify-between px-8 pt-4 pb-2">
                       <div className="flex items-center gap-3 relative">
