                           </button>
                           {isModelDropdownOpen && (
                               <div className="absolute bottom-full left-0 mb-4 w-60 bg-white dark:bg-slate-900 rounded-[1.8rem] shadow-3xl border border-slate-100 dark:border-slate-800 z-50 p-2 animate-fade-in-up">
