                                        <button onClick={shareSessionLink} className="p-2 hover:bg-slate-50 dark:hover:bg-slate-800 rounded-xl transition-all" title="Share Session link">
                                            <CopyIcon className="w-4 h-4 text-blue-600" />
                                        </button>
                                    </div>
                                    {showInviteFeedback && <p className="text-[9px] text-green-500 font-bold mb-3 animate-pulse">Session link copied!</p>}
                                    <div className="max-h-60 overflow-y-auto custom-scrollbar space-y-2">
                                        {friends.map(f => (
                                            <button key={f.id} onClick={() => toggleParticipant(f.id)} className={`w-full flex items-center justify-between p-3 rounded-xl transition-all ${activeParticipants.includes(f.id) ? 'bg-blue-50 dark:bg-blue-900/20 text-blue-600' : 'hover:bg-slate-50'}`}>
