};

import React, { useState, useRef, useEffect } from 'react';
import type { ChatSession, Mode, ThemeColors, Friend } from '../types';
import { BotIcon, TrashIcon, PencilIcon, MicrophoneIcon, UsersIcon, CodeIcon, SparklesIcon, MenuIcon } from './Icons';

interface SidebarProps {
  chatHistory: ChatSession[];
  activeChatId: string | null;
  mode: Mode;
  onSetMode: (mode: Mode) => void;
  onSelectChat: (id: string) => void;
  onNewChat: () => void;
  onDeleteChat: (id: string) => void;
  onRenameChat: (id: string, newTitle: string) => void;
  onOpenSettings: () => void;
  isSidebarOpen: boolean;
  isDesktopSidebarOpen: boolean;
  theme: ThemeColors;
  friends: Friend[];
}

export const Sidebar: React.FC<SidebarProps> = ({
  chatHistory, activeChatId, mode, onSetMode, onSelectChat, onNewChat, onDeleteChat, onRenameChat, isSidebarOpen, isDesktopSidebarOpen, theme, friends,
}) => {
  const [editingChatId, setEditingChatId] = useState<string | null>(null);
  const [newTitle, setNewTitle] = useState('');
  const inputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (editingChatId && inputRef.current) {
        inputRef.current.focus();
        inputRef.current.select();
    }
  }, [editingChatId]);

  const handleRename = () => {
    if (editingChatId && newTitle.trim()) onRenameChat(editingChatId, newTitle.trim());
    setEditingChatId(null);
  };

  const NavItem: React.FC<{ m: Mode, icon: React.ReactNode, label: string, badge?: string }> = ({ m, icon, label, badge }) => (
    <button
        onClick={() => onSetMode(m)}
        className={`w-full flex items-center justify-between px-4 py-3 rounded-[1.4rem] transition-all duration-300
            ${mode === m 
                ? `${theme.bgSoft} ${theme.text} dark:bg-blue-900/20 dark:text-blue-400 font-black shadow-lg shadow-blue-500/5` 
                : 'text-slate-600 dark:text-slate-400 hover:bg-slate-50 dark:hover:bg-slate-900'}
        `}
    >
        <div className="flex items-center gap-3">
            <span className="shrink-0">{icon}</span>
            <span className="text-[11px] uppercase tracking-widest font-black">{label}</span>
        </div>
        {badge && <span className="text-[8px] font-black bg-blue-600 text-white px-2 py-0.5 rounded-full">{badge}</span>}
    </button>
  );

  return (
    <aside className={`fixed lg:static inset-y-0 left-0 z-50 transition-all duration-300 ease-in-out h-full shrink-0 flex flex-col bg-white dark:bg-slate-950 border-r border-slate-100 dark:border-slate-800
      ${isSidebarOpen ? 'translate-x-0 w-[300px]' : '-translate-x-full lg:translate-x-0'}
      ${isDesktopSidebarOpen ? 'lg:w-[300px]' : 'lg:w-0 overflow-hidden border-none'}
    `}>
      <div className="p-8">
        <div className="flex flex-col gap-1 mb-10">
            <h1 className="text-4xl font-black text-slate-900 dark:text-white tracking-tighter italic leading-none">Nexzi.</h1>
            <p className="text-[10px] text-blue-600 font-black uppercase tracking-[0.5em] mt-3">Neural Collective</p>
        </div>

        <button onClick={onNewChat} className="w-full flex items-center justify-center gap-3 py-4.5 bg-slate-900 dark:bg-white text-white dark:text-slate-900 rounded-[1.8rem] font-black transition-all shadow-xl hover:shadow-2xl active:scale-95 text-[11px] uppercase tracking-widest mb-2">
          New Workspace
        </button>
      </div>

      <nav className="px-5 space-y-1.5 mb-8">
        <NavItem m="chat" icon={<SparklesIcon className="w-5 h-5" />} label="Uplink" />
        <NavItem m="friends" icon={<UsersIcon className="w-5 h-5" />} label="Cognates" />
        <NavItem m="coding" icon={<CodeIcon className="w-5 h-5" />} label="DevStudio" />
        <NavItem m="live" icon={<MicrophoneIcon className="w-5 h-5" />} label="LiveTalk" />
        <NavItem m="memory" icon={<BotIcon className="w-5 h-5" />} label="Vault" />
        <NavItem m="about" icon={<svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M13 16h-1v-4h-1m1-4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z"/></svg>} label="About" />
      </nav>

      <div className="flex-1 overflow-y-auto px-5 custom-scrollbar pb-6">
            <h3 className="text-[9px] font-black text-slate-400 uppercase tracking-[0.4em] px-4 mb-4">Saved Sessions</h3>
            <div className="space-y-1">
                {chatHistory.length === 0 ? (
                  <p className="text-[10px] text-slate-400 italic px-4 py-2 opacity-50">Empty Archive</p>
                ) : (
                  chatHistory.map((chat) => (
                      <div key={chat.id} onClick={() => { if(editingChatId !== chat.id) onSelectChat(chat.id); }}
                          className={`group relative flex items-center justify-between px-4 py-3.5 cursor-pointer rounded-2xl transition-all
                          ${activeChatId === chat.id && mode === 'chat'
                              ? 'bg-slate-50 dark:bg-slate-900 text-blue-600 dark:text-blue-400 font-bold'
                              : 'text-slate-500 hover:bg-slate-50 dark:hover:bg-slate-900'}
                          `}
                      >
                          {editingChatId === chat.id ? (
                              <input ref={inputRef} type="text" value={newTitle} onChange={(e) => setNewTitle(e.target.value)} onBlur={handleRename} onKeyDown={(e) => e.key === 'Enter' && handleRename()}
                                  className="bg-transparent border-none w-full outline-none text-[11px]" />
                          ) : (
                              <>
                              <span className="truncate text-[11px] font-medium tracking-tight">{chat.title}</span>
                              <div className="hidden group-hover:flex items-center gap-1.5 absolute right-3">
                                  <button onClick={(e) => { e.stopPropagation(); setEditingChatId(chat.id); setNewTitle(chat.title); }} className="p-1 text-slate-300 hover:text-blue-500 transition-colors"><PencilIcon className="w-3.5 h-3.5"/></button>
                                  <button onClick={(e) => { e.stopPropagation(); onDeleteChat(chat.id); }} className="p-1 text-slate-300 hover:text-red-500 transition-colors"><TrashIcon className="w-3.5 h-3.5"/></button>
                              </div>
                              </>
                          )}
                      </div>
                  ))
                )}
            </div>
      </div>

      <div className="p-10 border-t border-slate-50 dark:border-slate-800 flex flex-col items-center gap-4">
          <div className="w-full flex items-center justify-between px-2">
            <div className="flex items-center gap-2">
              <div className="w-2 h-2 rounded-full bg-blue-600 animate-pulse"></div>
              <span className="text-[9px] font-black uppercase text-slate-400 tracking-widest">Active Link</span>
            </div>
            <span className="text-[9px] font-black text-slate-300 uppercase tracking-widest">v3.0</span>
          </div>
          <p className="text-[11px] font-black text-slate-400 uppercase tracking-[0.4em] italic">Created by Nexzi</p>
      </div>
    </aside>
  );
};

