  return (
    <aside className={`fixed lg:static inset-y-0 left-0 z-50 transition-all duration-300 ease-in-out h-full shrink-0 flex flex-col bg-slate-50 dark:bg-slate-900 border-r border-slate-200 dark:border-slate-800
