      ${isDesktopSidebarOpen ? 'lg:w-[280px]' : 'lg:w-0 overflow-hidden border-none'}
    `}>
      <div className="p-6">
        <div className="flex items-center gap-3 mb-8">
            <div className="w-10 h-10 bg-blue-600 rounded-xl flex items-center justify-center text-white shadow-lg">
                <BotIcon className="w-6 h-6" />
            </div>
            <h1 className="text-xl font-bold text-slate-900 dark:text-white tracking-tight">Cognix AI</h1>
        </div>

        <button onClick={onNewChat} className="w-full flex items-center justify-center gap-2 py-3 bg-white dark:bg-slate-800 text-slate-900 dark:text-white border border-slate-200 dark:border-slate-700 rounded-xl font-bold transition-all hover:bg-slate-50 dark:hover:bg-slate-700 active:scale-95 text-sm">
          + New Workspace
