        <NavItem m="friends" icon={<UsersIcon className="w-5 h-5" />} label="Network" />
        <NavItem m="coding" icon={<CodeIcon className="w-5 h-5" />} label="DevStudio" />
        <NavItem m="live" icon={<MicrophoneIcon className="w-5 h-5" />} label="LiveTalk" />
        <NavItem m="memory" icon={<BotIcon className="w-5 h-5" />} label="Vault" />
        <NavItem m="about" icon={<svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M13 16h-1v-4h-1m1-4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z"/></svg>} label="About" />
      </nav>

      <div className="flex-1 overflow-y-auto px-4 custom-scrollbar pb-6">
            <h3 className="text-[10px] font-bold text-slate-400 uppercase tracking-wider px-4 mb-3">Saved Sessions</h3>
            <div className="space-y-1">
