import { SettingsModal } from './components/SettingsModal';
import { GoogleGenAI } from "@google/genai";
import type { ChatMessage, ChatSession, Mode, UIStyle, AccentColor, ThemeColors, FontSize, Friend, ModelType } from './types';

const THEMES: Record<AccentColor, ThemeColors> = {
    blue: { primary: 'bg-blue-600', primaryHover: 'hover:bg-blue-700', text: 'text-blue-600', textDark: 'text-blue-400', bgSoft: 'bg-blue-50', darkBgSoft: 'dark:bg-blue-900/20', border: 'border-blue-600', ring: 'focus:ring-blue-600', gradient: 'bg-gradient-to-r from-blue-500 to-cyan-500' },
    violet: { primary: 'bg-violet-600', primaryHover: 'hover:bg-violet-700', text: 'text-violet-600', textDark: 'text-violet-400', bgSoft: 'bg-violet-50', darkBgSoft: 'dark:bg-violet-900/20', border: 'border-violet-600', ring: 'focus:ring-violet-600', gradient: 'bg-gradient-to-r from-violet-500 to-purple-500' },
    emerald: { primary: 'bg-emerald-600', primaryHover: 'hover:bg-emerald-700', text: 'text-emerald-600', textDark: 'text-emerald-400', bgSoft: 'bg-emerald-50', darkBgSoft: 'dark:bg-emerald-900/20', border: 'border-emerald-600', ring: 'focus:ring-emerald-600', gradient: 'bg-gradient-to-r from-emerald-500 to-teal-500' },
    rose: { primary: 'bg-rose-600', primaryHover: 'hover:bg-rose-700', text: 'text-rose-600', textDark: 'text-rose-400', bgSoft: 'bg-rose-50', darkBgSoft: 'dark:bg-violet-900/20', border: 'border-rose-600', ring: 'focus:ring-rose-600', gradient: 'bg-gradient-to-r from-rose-500 to-pink-500' },
    amber: { primary: 'bg-amber-600', primaryHover: 'hover:bg-amber-700', text: 'text-amber-600', textDark: 'text-amber-400', bgSoft: 'bg-amber-50', darkBgSoft: 'dark:bg-amber-900/20', border: 'border-amber-600', ring: 'focus:ring-amber-600', gradient: 'bg-gradient-to-r from-amber-500 to-orange-500' },
};

const App: React.FC = () => {
  const [mode, setMode] = useState<Mode>('chat');
  const [accentColor, setAccentColor] = useState<AccentColor>('blue');
  const [activeModel, setActiveModel] = useState<ModelType>('cognix-arc-1.0');
  const [systemInstruction, setSystemInstruction] = useState("You are Cognix AI, a private intelligence engine. Professional, precise, and modular.");

  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [isDesktopSidebarOpen, setIsDesktopSidebarOpen] = useState(true);
  const [isDarkMode, setIsDarkMode] = useState(false);
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);

  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [chatHistory, setChatHistory] = useState<ChatSession[]>([]);
  const [activeChatId, setActiveChatId] = useState<string | null>(null);
  const [friends, setFriends] = useState<Friend[]>([]);

  useEffect(() => {
    const savedHistory = localStorage.getItem('cognix_history');
    if (savedHistory) setChatHistory(JSON.parse(savedHistory));
    const savedFriends = localStorage.getItem('cognix_friends');
    if (savedFriends) setFriends(JSON.parse(savedFriends));
    const savedTheme = localStorage.getItem('cognix_theme');
    if (savedTheme === 'dark') { setIsDarkMode(true); document.documentElement.classList.add('dark'); }
  }, []);

  useEffect(() => localStorage.setItem('cognix_history', JSON.stringify(chatHistory)), [chatHistory]);
  useEffect(() => localStorage.setItem('cognix_friends', JSON.stringify(friends)), [friends]);
  useEffect(() => {
    if (isDarkMode) { document.documentElement.classList.add('dark'); localStorage.setItem('cognix_theme', 'dark'); }
    else { document.documentElement.classList.remove('dark'); localStorage.setItem('cognix_theme', 'light'); }
  }, [isDarkMode]);

  const currentChat = useMemo(() => chatHistory.find(c => c.id === activeChatId), [chatHistory, activeChatId]);
  const activeTheme = useMemo(() => THEMES[accentColor], [accentColor]);

  useEffect(() => { setMessages(currentChat ? currentChat.messages : []); }, [currentChat?.id]);

  const handleNewChat = () => { setActiveChatId(null); setMessages([]); setMode('chat'); if (window.innerWidth < 1024) setIsSidebarOpen(false); };

  return (
    <div className="flex h-[100dvh] overflow-hidden bg-slate-50 dark:bg-slate-950 transition-all">
      <Sidebar 
        chatHistory={chatHistory} activeChatId={activeChatId} mode={mode}
        onSetMode={(m) => { setMode(m); if(window.innerWidth < 1024) setIsSidebarOpen(false); }}
        onSelectChat={(id) => { setActiveChatId(id); setMode('chat'); if(window.innerWidth < 1024) setIsSidebarOpen(false); }}
        onNewChat={handleNewChat}
        onDeleteChat={(id) => { setChatHistory(h => h.filter(c => c.id !== id)); if (activeChatId === id) { setActiveChatId(null); setMessages([]); } }}
        onRenameChat={(id, t) => setChatHistory(h => h.map(c => c.id === id ? { ...c, title: t } : c))}
        onOpenSettings={() => setIsSettingsOpen(true)}
        isSidebarOpen={isSidebarOpen} isDesktopSidebarOpen={isDesktopSidebarOpen} theme={activeTheme} friends={friends}
      />

      <div className="flex-1 flex flex-col h-full bg-white dark:bg-slate-900 lg:rounded-l-[3rem] shadow-3xl overflow-hidden relative">
        <header className="h-20 flex items-center justify-between px-8 shrink-0 z-30 border-b border-slate-50 dark:border-slate-800">
             <div className="flex items-center gap-6">
                <button onClick={() => window.innerWidth >= 1024 ? setIsDesktopSidebarOpen(!isDesktopSidebarOpen) : setIsSidebarOpen(!isSidebarOpen)} className="p-3 -ml-2 text-slate-400 hover:bg-slate-100 dark:hover:bg-slate-800 rounded-2xl transition-all">
                    <MenuIcon className="w-6 h-6"/>
                </button>
                <div className="flex flex-col">
                  <h1 className="text-sm font-black text-slate-900 dark:text-white uppercase tracking-widest flex items-center gap-2">
                      {mode}
                      <div className="w-1.5 h-1.5 rounded-full bg-blue-600 animate-pulse"></div>
                  </h1>
                </div>
             </div>
             <div className="flex items-center gap-4">
                 <button onClick={() => setIsSettingsOpen(true)} className="p-3 bg-slate-50 dark:bg-slate-800 rounded-2xl border border-slate-100 dark:border-slate-800 text-slate-400 hover:border-blue-600 transition-all">
                    <UserIcon className="w-6 h-6"/>
                 </button>
             </div>
        </header>

        <main className="flex-1 relative overflow-hidden">
            {mode === 'chat' && (
                <ChatView messages={messages} setMessages={setMessages} uiStyle={'modern'} theme={activeTheme} fontSize={'normal'} systemInstruction={systemInstruction} model={activeModel} setActiveModel={setActiveModel} friends={friends} />
            )}
            {mode === 'live' && <LiveView theme={activeTheme} />}
            {mode === 'friends' && <FriendsView friends={friends} setFriends={setFriends} />}
            {mode === 'coding' && <CodingView theme={activeTheme} model={activeModel} />}
            {mode === 'memory' && <MemoryView theme={activeTheme} />}
            {mode === 'about' && <AboutUs />}
        </main>
      </div>

      <SettingsModal isOpen={isSettingsOpen} onClose={() => setIsSettingsOpen(false)} uiStyle={'modern'} setUiStyle={() => {}} accentColor={accentColor} setAccentColor={setAccentColor} fontSize={'normal'} setFontSize={() => {}} isDarkMode={isDarkMode} setIsDarkMode={setIsDarkMode} onClearHistory={() => { setChatHistory([]); setMessages([]); setActiveChatId(null); setIsSettingsOpen(false); }} systemInstruction={systemInstruction} setSystemInstruction={setSystemInstruction} />
    </div>
  );
}

export default App;

