  return (
    <div className="flex flex-col h-full bg-white dark:bg-slate-900 relative">
      <div ref={chatContainerRef} className="flex-1 overflow-y-auto px-4 sm:px-8 pb-40 pt-6 custom-scrollbar scroll-smooth">
