                                     {part.inlineData && (
                                       <div className="mb-3">
                                          <img src={`data:${part.inlineData.mimeType};base64,${part.inlineData.data}`} className="rounded-lg max-h-96 shadow-md border border-white/10" alt="Generated Output"/>
                                          {part.inlineData.mimeType === 'image/png' && <p className="text-[10px] mt-2 font-bold text-slate-400 uppercase">Gemini 2.5 Flash Render</p>}
                                       </div>
                                     )}
                                     <div className="whitespace-pre-wrap prose prose-sm dark:prose-invert max-w-none">{part.text}</div>
                                 </div>
                             ))}
                        </div>
                    </div>
                ))}
                {isLoading && (
                  <div className="flex gap-4 items-center animate-pulse">
                    <div className="w-10 h-10 rounded-xl bg-blue-600 flex items-center justify-center text-white shadow-md"><BotIcon className="w-7 h-7"/></div>
                    <div className="bg-slate-50 dark:bg-slate-800 px-4 py-2 rounded-xl text-xs font-bold text-slate-400 uppercase tracking-widest">Thinking</div>
                  </div>
                )}
            </div>
        )}
      </div>

      <div className="absolute bottom-0 left-0 right-0 px-4 pb-8 pt-10 bg-gradient-to-t from-white dark:from-slate-900 to-transparent">
          <div className="max-w-3xl mx-auto">
              <div className="bg-white dark:bg-slate-800 rounded-3xl shadow-2xl border border-slate-200 dark:border-slate-700 overflow-hidden">
                   <div className="flex items-center gap-2 px-6 py-2 border-b border-slate-100 dark:border-slate-700 bg-slate-50 dark:bg-slate-900/50">
                       <button onClick={() => setIsModelDropdownOpen(!isModelDropdownOpen)} className="text-[10px] font-black uppercase tracking-widest text-slate-400 hover:text-blue-600 flex items-center gap-1">
                           {modelOptions.find(o => o.id === model)?.label}
                           <svg className="w-3 h-3" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path d="M19 9l-7 7-7-7"/></svg>
                       </button>
                       <div className="h-3 w-px bg-slate-300 dark:bg-slate-600 mx-2"></div>
                       <button onClick={() => setWebSearchEnabled(!webSearchEnabled)} className={`text-[10px] font-black uppercase tracking-widest flex items-center gap-1.5 transition-colors ${webSearchEnabled ? 'text-blue-600' : 'text-slate-400'}`}>
                           <SearchIcon className="w-3 h-3" /> Web Grounding
                       </button>
                       {isModelDropdownOpen && (
                            <div className="absolute bottom-full left-6 mb-3 w-48 bg-white dark:bg-slate-800 rounded-2xl shadow-2xl border border-slate-200 dark:border-slate-700 z-50 p-2 animate-fade-in-up">
                                {modelOptions.map(m => (
                                    <button key={m.id} onClick={() => { setActiveModel(m.id as any); setIsModelDropdownOpen(false); }} className="w-full text-left px-3 py-2.5 hover:bg-slate-50 dark:hover:bg-slate-700 rounded-xl text-xs font-bold text-slate-700 dark:text-slate-300">
                                        {m.label}
                                    </button>
                                ))}
                            </div>
                       )}
                   </div>

                   <div className="p-4 flex items-end gap-4">
                        <button onClick={() => fileInputRef.current?.click()} className="p-3 rounded-2xl bg-slate-50 dark:bg-slate-900 text-slate-500 hover:text-blue-600 transition-colors shadow-inner">
                            <ImageIcon className="w-6 h-6"/>
                            <input type="file" ref={fileInputRef} onChange={(e) => {
                                const file = e.target.files?.[0];
                                if (file) {
                                    const reader = new FileReader();
                                    reader.onloadend = () => setSelectedImage({ data: (reader.result as string).split(',')[1], mimeType: file.type });
                                    reader.readAsDataURL(file);
                                }
                            }} accept="image/*" className="hidden" />
                        </button>
                        <textarea ref={textareaRef} value={input} onChange={e => setInput(e.target.value)}
                            onKeyDown={e => e.key === 'Enter' && !e.shiftKey && (e.preventDefault(), handleSendMessage())}
                            placeholder="Type your message..."
                            className="flex-1 bg-transparent border-none outline-none resize-none py-3 text-sm text-slate-900 dark:text-white max-h-40 min-h-[44px]"
                            rows={1} />
                        <button onClick={() => handleSendMessage()} disabled={isLoading || (!input && !selectedImage)} className="w-14 h-14 bg-blue-600 text-white rounded-2xl shadow-lg disabled:opacity-50 active:scale-90 transition-all flex items-center justify-center shrink-0">
                             <SendIcon className="w-7 h-7"/>
                        </button>
                   </div>
              </div>
          </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect, useMemo } from 'react';
