  const chatContainerRef = useRef<HTMLDivElement>(null);
  const textareaRef = useRef<HTMLTextAreaElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (chatContainerRef.current) {
      chatContainerRef.current.scrollTo({
        top: chatContainerRef.current.scrollHeight,
        behavior: 'smooth'
      });
    }
  }, [messages, isLoading]);

  const handleSendMessage = useCallback(async (textOverride?: string) => {
    const textInput = (textOverride || input).trim();
    if ((!textInput && !selectedImage) || isLoading) return;

    const userMessageParts: ChatPart[] = [];
    if (selectedImage) userMessageParts.push({ inlineData: { mimeType: selectedImage.mimeType, data: selectedImage.data } });

    const participantPrefix = activeParticipants.length > 0 
        ? `[Group: ${activeParticipants.map(id => friends.find(f => f.id === id)?.name).join(', ')}] ` 
        : '';

    if (textInput) userMessageParts.push({ text: participantPrefix + textInput });

    const userMessage: ChatMessage = { id: `msg-${Date.now()}`, role: 'user', parts: userMessageParts };
    const modelPlaceholderId = `msg-${Date.now() + 1}`;
    const modelPlaceholder: ChatMessage = { id: modelPlaceholderId, role: 'model', parts: [{ text: '' }], isSearching: webSearchEnabled };

    setMessages(prev => [...prev, userMessage, modelPlaceholder]);
    setInput(''); 
    setSelectedImage(null);
    setIsLoading(true);

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

      const isImageRequest = /generate (an )?image|create (an )?image|draw|paint/i.test(textInput);
      const targetModel = isImageRequest ? 'gemini-2.5-flash-image' : (
        model === 'ciorea-coding' || model === 'clora-workflow' || model === 'gemini-3-pro-preview' 
        ? 'gemini-3-pro-preview' 
        : 'gemini-3-flash-preview'
      );

      const history = messages.map(msg => ({
        role: msg.role,
        parts: msg.parts.map(p => {
            if (p.text) return { text: p.text };
            if (p.inlineData) return { inlineData: p.inlineData };
            return null;
        }).filter(Boolean) as any[]
      }));

      const response = await ai.models.generateContent({
          model: targetModel,
          contents: [...history, { role: 'user', parts: userMessageParts as any }],
          config: { 
            systemInstruction: systemInstruction,
            tools: !isImageRequest && webSearchEnabled ? [{ googleSearch: {} }] : [] 
          },
      });

      let responseParts: ChatPart[] = [];
      for (const part of response.candidates[0].content.parts) {
        if (part.text) {
          responseParts.push({ text: part.text });
        } else if (part.inlineData) {
          responseParts.push({ inlineData: { mimeType: part.inlineData.mimeType, data: part.inlineData.data } });
        }
      }

      setMessages(prev => prev.map(m => m.id === modelPlaceholderId ? { 
        ...m, 
        parts: responseParts, 
        isSearching: false 
      } : m));

    } catch (error) {
      setMessages(prev => prev.map(m => m.id === modelPlaceholderId ? { ...m, parts: [{ text: `Interface Alert: Data uplink interrupted. Please retry.` }], isSearching: false } : m));
    } finally {
      setIsLoading(false);
    }
  }, [input, isLoading, messages, selectedImage, systemInstruction, model, webSearchEnabled, setMessages, activeParticipants, friends]);

  const modelOptions = [
    { id: 'cognix-arc-1.0', label: 'Cognix Arc 1.0', desc: 'Standard Logic' },
    { id: 'gemini-3-flash-preview', label: 'Flash 3.0', desc: 'High Velocity' },
    { id: 'ciorea-coding', label: 'Ciorea Dev', desc: 'Code Architect' },
    { id: 'clora-workflow', label: 'Clora Logic', desc: 'Process Engine' }
  ];

  return (
    <div className="flex flex-col h-full bg-white dark:bg-slate-900 relative">
      <div ref={chatContainerRef} className="flex-1 overflow-y-auto px-4 sm:px-12 pb-44 pt-8 custom-scrollbar scroll-smooth">
        {messages.length === 0 ? (
            <div className="max-w-2xl mx-auto flex flex-col items-center justify-center min-h-[70vh] text-center animate-fade-in">
                 <div className="w-24 h-24 bg-blue-600 rounded-[2.5rem] flex items-center justify-center text-white shadow-[0_20px_50px_rgba(37,99,235,0.3)] mb-10 group transition-all hover:scale-105 duration-500">
                     <BotIcon className="w-14 h-14" />
                 </div>
                 <h2 className="text-4xl font-extrabold text-slate-900 dark:text-white mb-4 tracking-tight">Cognix AI</h2>
                 <p className="text-slate-500 dark:text-slate-400 mb-12 max-w-md font-medium">
                    Initializing private neural node. Your request for technical or creative intelligence is ready for processing.
                 </p>

                 <div className="grid grid-cols-1 sm:grid-cols-2 gap-4 w-full px-4">
                     {[
                        { t: "Logic Problem", q: "Solve the Fibonacci sequence up to 10 terms with a custom algorithm." },
                        { t: "Architecture", q: "Design a high-availability cloud infrastructure for a fintech app." },
                        { t: "Image Studio", q: "Generate a professional 3D render of a futuristic office workspace." },
                        { t: "Live Search", q: "Analyze the current trends in global semiconductor manufacturing." }
                     ].map((item, i) => (
                        <button key={i} onClick={() => handleSendMessage(item.q)} className="text-left p-5 rounded-[1.8rem] border border-slate-100 dark:border-slate-800 hover:border-blue-500 hover:bg-blue-50/50 dark:hover:bg-blue-900/10 transition-all bg-white dark:bg-slate-900 shadow-sm group">
                            <span className="font-bold text-slate-900 dark:text-white text-sm block mb-1 group-hover:text-blue-600 transition-colors">{item.t}</span>
                            <span className="text-xs text-slate-400 line-clamp-1 font-medium italic">{item.q}</span>
                        </button>
                     ))}
                 </div>
            </div>
        ) : (
            <div className="max-w-4xl mx-auto space-y-10 pb-12">
                {messages.map((msg) => (
                    <div key={msg.id} className={`flex gap-5 ${msg.role === 'user' ? 'flex-row-reverse' : 'flex-row'} animate-fade-in-up`}>
                        <div className={`w-11 h-11 shrink-0 rounded-2xl flex items-center justify-center shadow-lg transition-transform hover:scale-105
                            ${msg.role === 'user' ? 'bg-slate-100 dark:bg-slate-800 text-slate-500' : 'bg-blue-600 text-white shadow-[0_10px_20px_rgba(37,99,235,0.2)]'}
                        `}>
                             {msg.role === 'user' ? <UserIcon className="w-6 h-6"/> : <BotIcon className="w-7 h-7"/>}
                        </div>
                        <div className={`flex flex-col gap-3 max-w-[82%] ${msg.role === 'user' ? 'items-end' : 'items-start'}`}>
                             {msg.parts.map((part, i) => (
                                 <div key={i} className={`p-5 rounded-[1.8rem] text-sm leading-relaxed shadow-sm transition-all duration-300 ${msg.role === 'user' ? 'bg-blue-600 text-white rounded-tr-none font-medium' : 'bg-slate-50 dark:bg-slate-800 text-slate-800 dark:text-slate-100 rounded-tl-none border border-slate-100 dark:border-slate-700/50'}`}>
                                     {part.inlineData && (
                                       <div className="mb-4 group relative overflow-hidden rounded-2xl shadow-md">
                                          <img src={`data:${part.inlineData.mimeType};base64,${part.inlineData.data}`} className="max-h-96 w-full object-cover transition-transform duration-700 group-hover:scale-110" alt="Generated Output"/>
                                          <div className="absolute top-3 left-3 px-3 py-1 bg-black/40 backdrop-blur-md rounded-lg text-[9px] font-black uppercase text-white tracking-widest">Render v2.5</div>
                                       </div>
                                     )}
                                     <div className="whitespace-pre-wrap prose prose-sm dark:prose-invert max-w-none font-medium text-slate-700 dark:text-slate-200">{part.text}</div>
                                 </div>
                             ))}
                        </div>
                    </div>
                ))}
                {isLoading && (
                  <div className="flex gap-5 items-center animate-pulse">
                    <div className="w-11 h-11 rounded-2xl bg-blue-600 flex items-center justify-center text-white shadow-lg"><BotIcon className="w-7 h-7"/></div>
                    <div className="bg-slate-50 dark:bg-slate-800 px-6 py-3 rounded-2xl text-[10px] font-black text-blue-600 uppercase tracking-[0.3em] shadow-sm flex items-center gap-3">
                       Thinking
                       <div className="flex gap-1">
                          <span className="w-1 h-1 bg-blue-600 rounded-full animate-bounce"></span>
                          <span className="w-1 h-1 bg-blue-600 rounded-full animate-bounce [animation-delay:0.2s]"></span>
                          <span className="w-1 h-1 bg-blue-600 rounded-full animate-bounce [animation-delay:0.4s]"></span>
                       </div>
                    </div>
                  </div>
                )}
            </div>
        )}
      </div>

      <div className="absolute bottom-0 left-0 right-0 px-6 pb-10 pt-16 bg-gradient-to-t from-white dark:from-slate-900 via-white/95 dark:via-slate-900/95 to-transparent pointer-events-none">
          <div className="max-w-3xl mx-auto pointer-events-auto">
              <div className="bg-white dark:bg-slate-800/95 backdrop-blur-xl rounded-[2.5rem] shadow-[0_20px_60px_rgba(0,0,0,0.15)] border border-slate-200 dark:border-slate-700/50 overflow-hidden transition-all duration-500 focus-within:shadow-[0_25px_70px_rgba(37,99,235,0.15)]">
                   <div className="flex items-center gap-2 px-8 py-3 border-b border-slate-100 dark:border-slate-700 bg-slate-50/50 dark:bg-slate-900/30">
                       <button onClick={() => setIsModelDropdownOpen(!isModelDropdownOpen)} className="text-[10px] font-black uppercase tracking-widest text-slate-400 hover:text-blue-600 flex items-center gap-1.5 transition-colors">
                           {modelOptions.find(o => o.id === model)?.label}
                           <svg className="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24" strokeWidth="3"><path d="M19 9l-7 7-7-7"/></svg>
                       </button>
                       <div className="h-3 w-px bg-slate-200 dark:bg-slate-700 mx-3"></div>
                       <button onClick={() => setWebSearchEnabled(!webSearchEnabled)} className={`text-[10px] font-black uppercase tracking-widest flex items-center gap-2 transition-all ${webSearchEnabled ? 'text-blue-600' : 'text-slate-400'}`}>
                           <div className={`w-1.5 h-1.5 rounded-full ${webSearchEnabled ? 'bg-blue-600 shadow-[0_0_8px_#2563EB]' : 'bg-slate-400'}`}></div>
                           Web Grounding
                       </button>
                       {isModelDropdownOpen && (
                            <div className="absolute bottom-full left-8 mb-4 w-52 bg-white dark:bg-slate-800 rounded-3xl shadow-2xl border border-slate-100 dark:border-slate-700 z-50 p-2 animate-fade-in-up overflow-hidden">
                                {modelOptions.map(m => (
                                    <button key={m.id} onClick={() => { setActiveModel(m.id as any); setIsModelDropdownOpen(false); }} className={`w-full text-left px-4 py-3 hover:bg-blue-50 dark:hover:bg-blue-900/20 rounded-2xl text-[11px] font-bold transition-all ${model === m.id ? 'text-blue-600 bg-blue-50 dark:bg-blue-900/20' : 'text-slate-600 dark:text-slate-300'}`}>
                                        <div className="flex flex-col">
                                          <span>{m.label}</span>
                                          <span className="text-[9px] opacity-40 uppercase tracking-widest">{m.desc}</span>
                                        </div>
                                    </button>
                                ))}
                            </div>
                       )}
                   </div>

                   <div className="p-4 flex items-end gap-4 px-6 pb-6">
                        <button onClick={() => fileInputRef.current?.click()} className="p-3.5 rounded-2xl bg-slate-50 dark:bg-slate-900 text-slate-400 hover:text-blue-600 hover:bg-blue-50 dark:hover:bg-blue-900 transition-all shadow-inner active:scale-95 shrink-0">
                            <ImageIcon className="w-6 h-6"/>
                            <input type="file" ref={fileInputRef} onChange={(e) => {
                                const file = e.target.files?.[0];
                                if (file) {
                                    const reader = new FileReader();
                                    reader.onloadend = () => setSelectedImage({ data: (reader.result as string).split(',')[1], mimeType: file.type });
                                    reader.readAsDataURL(file);
                                }
                            }} accept="image/*" className="hidden" />
                        </button>
                        <textarea ref={textareaRef} value={input} onChange={e => setInput(e.target.value)}
                            onKeyDown={e => e.key === 'Enter' && !e.shiftKey && (e.preventDefault(), handleSendMessage())}
                            placeholder="Initialize neural request..."
                            className="flex-1 bg-transparent border-none outline-none resize-none py-3.5 text-sm sm:text-base text-slate-900 dark:text-white placeholder-slate-400 max-h-44 min-h-[48px] font-medium"
                            rows={1} />
                        <button onClick={() => handleSendMessage()} disabled={isLoading || (!input && !selectedImage)} className="w-16 h-16 bg-blue-600 text-white rounded-[1.6rem] shadow-[0_10px_25px_rgba(37,99,235,0.4)] disabled:opacity-30 disabled:shadow-none active:scale-90 transition-all flex items-center justify-center shrink-0 hover:bg-blue-700">
                             <SendIcon className="w-8 h-8"/>
                        </button>
                   </div>
                   {selectedImage && (
                      <div className="px-8 pb-4 flex items-center gap-3 animate-fade-in">
                          <div className="relative w-12 h-12 rounded-xl overflow-hidden shadow-md border-2 border-blue-600 animate-pulse">
                              <img src={`data:${selectedImage.mimeType};base64,${selectedImage.data}`} className="w-full h-full object-cover" alt="Selected"/>
                              <button onClick={() => setSelectedImage(null)} className="absolute inset-0 bg-black/40 flex items-center justify-center text-white font-black text-xs">&times;</button>
                          </div>
                          <span className="text-[10px] font-black uppercase tracking-widest text-blue-600">Attachment Synced</span>
                      </div>
                   )}
              </div>
          </div>
      </div>
    </div>
  );
};

