                                          <img src={`data:${part.inlineData.mimeType};base64,${part.inlineData.data}`} className="max-h-96 w-full object-cover transition-transform duration-700 group-hover:scale-110" alt="Generated Output"/>
                                          <div className="absolute top-3 left-3 px-3 py-1 bg-black/40 backdrop-blur-md rounded-lg text-[9px] font-black uppercase text-white tracking-widest">Render v2.5</div>
                                       </div>
                                     )}
                                     <div className="whitespace-pre-wrap prose prose-sm dark:prose-invert max-w-none font-medium text-slate-700 dark:text-slate-200">{part.text}</div>
                                 </div>
                             ))}
