                    <div className="bg-slate-50 dark:bg-slate-800 px-6 py-3 rounded-2xl text-[10px] font-black text-blue-600 uppercase tracking-[0.3em] shadow-sm flex items-center gap-3">
                       Processing
                       <div className="flex gap-1">
                          <span className="w-1 h-1 bg-blue-600 rounded-full animate-bounce"></span>
                          <span className="w-1 h-1 bg-blue-600 rounded-full animate-bounce [animation-delay:0.2s]"></span>
                          <span className="w-1 h-1 bg-blue-600 rounded-full animate-bounce [animation-delay:0.4s]"></span>
                       </div>
                    </div>
                  </div>
                )}
            </div>
        )}
      </div>

      <div className="absolute bottom-0 left-0 right-0 px-6 pb-10 pt-16 bg-gradient-to-t from-white dark:from-slate-900 via-white/95 dark:via-slate-900/95 to-transparent pointer-events-none">
