import React, { useState, useRef, useEffect, useCallback } from 'react';
import type { ChatMessage, ChatPart, UIStyle, ThemeColors, FontSize, ModelType, Friend } from '../types';
import { GoogleGenAI } from "@google/genai";
import { BotIcon, SendIcon, UserIcon, ImageIcon, SearchIcon, SparklesIcon, UsersIcon, CodeIcon, CopyIcon } from './Icons';

interface ChatViewProps {
  messages: ChatMessage[];
  setMessages: React.Dispatch<React.SetStateAction<ChatMessage[]>>;
  uiStyle: UIStyle;
  theme: ThemeColors;
  fontSize: FontSize;
  systemInstruction: string;
  model: ModelType;
  setActiveModel: (m: ModelType) => void;
  friends?: Friend[];
}

export const ChatView: React.FC<ChatViewProps> = ({ messages, setMessages, theme, systemInstruction, model, setActiveModel, friends = [] }) => {
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [selectedImage, setSelectedImage] = useState<{ data: string; mimeType: string } | null>(null);
  const [webSearchEnabled, setWebSearchEnabled] = useState(true);
  const [isModelDropdownOpen, setIsModelDropdownOpen] = useState(false);
  const [isCognateDropdownOpen, setIsCognateDropdownOpen] = useState(false);
  const [activeParticipants, setActiveParticipants] = useState<string[]>([]);
  const [showInviteFeedback, setShowInviteFeedback] = useState(false);

  const chatContainerRef = useRef<HTMLDivElement>(null);
  const textareaRef = useRef<HTMLTextAreaElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (chatContainerRef.current) {
      chatContainerRef.current.scrollTo({
        top: chatContainerRef.current.scrollHeight,
        behavior: 'smooth'
      });
    }
  }, [messages, isLoading]);

  const handleSendMessage = useCallback(async (textOverride?: string) => {
    const textInput = (textOverride || input).trim();
    if ((!textInput && !selectedImage) || isLoading) return;

    const userMessageParts: ChatPart[] = [];
    if (selectedImage) userMessageParts.push({ inlineData: { mimeType: selectedImage.mimeType, data: selectedImage.data } });

    const participantPrefix = activeParticipants.length > 0 
        ? `[Collective Node: ${activeParticipants.map(id => friends.find(f => f.id === id)?.name).join(', ')}] ` 
        : '';

    if (textInput) userMessageParts.push({ text: participantPrefix + textInput });

    const userMessage: ChatMessage = { id: `msg-${Date.now()}`, role: 'user', parts: userMessageParts };
    const modelPlaceholderId = `msg-${Date.now() + 1}`;
    const modelPlaceholder: ChatMessage = { id: modelPlaceholderId, role: 'model', parts: [{ text: '' }], isSearching: webSearchEnabled };

    setMessages(prev => [...prev, userMessage, modelPlaceholder]);
    setInput(''); 
    setSelectedImage(null);
    setIsLoading(true);

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

      const isImageRequest = /generate (an )?image|create (an )?image|draw|paint/i.test(textInput);
      const targetModel = isImageRequest ? 'gemini-2.5-flash-image' : (
        model === 'ciorea-coding' || model === 'clora-workflow' || model === 'gemini-3-pro-preview' 
        ? 'gemini-3-pro-preview' 
        : 'gemini-3-flash-preview'
      );

      const history = messages.map(msg => ({
        role: msg.role,
        parts: msg.parts.map(p => {
            if (p.text) return { text: p.text };
            if (p.inlineData) return { inlineData: p.inlineData };
            return null;
        }).filter(Boolean) as any[]
      }));

      const response = await ai.models.generateContent({
          model: targetModel,
          contents: [...history, { role: 'user', parts: userMessageParts as any }],
          config: { 
            systemInstruction: systemInstruction,
            tools: !isImageRequest && webSearchEnabled ? [{ googleSearch: {} }] : [] 
          },
      });

      let responseParts: ChatPart[] = [];
      for (const part of response.candidates[0].content.parts) {
        if (part.text) {
          responseParts.push({ text: part.text });
        } else if (part.inlineData) {
          responseParts.push({ inlineData: { mimeType: part.inlineData.mimeType, data: part.inlineData.data } });
        }
      }

      setMessages(prev => prev.map(m => m.id === modelPlaceholderId ? { 
        ...m, 
        parts: responseParts, 
        isSearching: false 
      } : m));

    } catch (error) {
      setMessages(prev => prev.map(m => m.id === modelPlaceholderId ? { ...m, parts: [{ text: `Neural Link Failure: Interface interrupted. Secure re-syncing required.` }], isSearching: false } : m));
    } finally {
      setIsLoading(false);
    }
  }, [input, isLoading, messages, selectedImage, systemInstruction, model, webSearchEnabled, setMessages, activeParticipants, friends]);

  const toggleParticipant = (friendId: string) => {
    if (activeParticipants.length >= 10 && !activeParticipants.includes(friendId)) return;
    setActiveParticipants(prev => prev.includes(friendId) ? prev.filter(id => id !== friendId) : [...prev, friendId]);
  };

  const shareSessionLink = () => {
    const link = `${window.location.origin}/nexus/node/${Math.random().toString(36).substring(7)}`;
    navigator.clipboard.writeText(link);
    setShowInviteFeedback(true);
    setTimeout(() => setShowInviteFeedback(false), 2000);
  };

  const modelOptions = [
    { id: 'gemini-3-pro-preview', label: 'Gemini 3.0 Pro', desc: 'SOTA Reasoning' },
    { id: 'cognix-arc-1.0', label: 'Cognix Arc 1.0', desc: 'Fast Logic' },
    { id: 'gemini-3-flash-preview', label: 'Flash 3.0', desc: 'High Velocity' },
    { id: 'ciorea-coding', label: 'Ciorea Dev', desc: 'Code Architect' }
  ];

  return (
    <div className="flex flex-col h-full bg-white dark:bg-slate-900 relative">
      {activeParticipants.length > 0 && (
          <div className="absolute top-4 left-1/2 -translate-x-1/2 z-20 flex items-center gap-2 px-3 py-1.5 bg-blue-600 rounded-full shadow-lg animate-fade-in border border-white/20">
              <div className="flex -space-x-2">
                  {activeParticipants.map(id => (
                      <div key={id} className="w-6 h-6 rounded-full bg-white border-2 border-blue-600 flex items-center justify-center text-[8px] font-black text-blue-600 uppercase">
                          {friends.find(f => f.id === id)?.name[0]}
                      </div>
                  ))}
              </div>
              <span className="text-[9px] font-bold text-white uppercase tracking-wider">{activeParticipants.length}/10 Active Nodes</span>
          </div>
      )}

      <div ref={chatContainerRef} className="flex-1 overflow-y-auto px-4 sm:px-12 pb-48 pt-8 custom-scrollbar scroll-smooth">
        {messages.length === 0 ? (
            <div className="max-w-2xl mx-auto flex flex-col items-center justify-center min-h-[70vh] text-center animate-fade-in">
                 <div className="w-24 h-24 bg-gradient-to-br from-blue-400 to-blue-600 rounded-[2.5rem] flex items-center justify-center text-white shadow-[0_20px_60px_rgba(37,99,235,0.4)] mb-12 group transition-all hover:scale-110 duration-500 relative">
                     <BotIcon className="w-14 h-14" />
                     <div className="absolute -inset-2 bg-blue-400/20 blur-xl rounded-full animate-pulse-soft"></div>
                 </div>
                 <h2 className="text-4xl font-black text-slate-900 dark:text-white mb-4 tracking-tighter">CognixAI V3.0 Pro</h2>
                 <p className="text-slate-400 dark:text-slate-500 mb-14 max-w-md font-medium leading-relaxed">
                    The next evolution of neural intelligence. Private. Persistent. Professional.
                 </p>

                 <div className="grid grid-cols-1 sm:grid-cols-2 gap-5 w-full px-4">
                     {[
                        { t: "Logic Problem", q: "Architect a complex logic flow for a fintech gateway." },
                        { t: "Neural Rendering", q: "Generate a hyper-realistic 3D render of a futuristic server farm." },
                        { t: "Data Analysis", q: "Analyze the current global shift in artificial intelligence policy." },
                        { t: "Code Synthesis", q: "Refactor this TypeScript interface for maximum extensibility." }
                     ].map((item, i) => (
                        <button key={i} onClick={() => handleSendMessage(item.q)} className="text-left p-6 rounded-[2rem] border border-slate-100 dark:border-slate-800 hover:border-blue-500 hover:bg-blue-50/40 dark:hover:bg-blue-900/10 transition-all bg-white dark:bg-slate-900 shadow-sm group">
                            <span className="font-black text-slate-800 dark:text-white text-sm block mb-1 group-hover:text-blue-600 transition-colors uppercase tracking-tight">{item.t}</span>
                            <span className="text-xs text-slate-400 font-medium italic line-clamp-1 opacity-70">{item.q}</span>
                        </button>
                     ))}
                 </div>
            </div>
        ) : (
            <div className="max-w-4xl mx-auto space-y-12 pb-16">
                {messages.map((msg) => (
                    <div key={msg.id} className={`flex gap-6 ${msg.role === 'user' ? 'flex-row-reverse' : 'flex-row'} animate-fade-in-up`}>
                        <div className={`w-12 h-12 shrink-0 rounded-2xl flex items-center justify-center shadow-md transition-all duration-300
                            ${msg.role === 'user' ? 'bg-slate-50 dark:bg-slate-800 text-slate-400' : 'bg-blue-600 text-white shadow-[0_12px_24px_rgba(37,99,235,0.25)]'}
                        `}>
