                        </div>
                        <div className={`flex flex-col gap-4 max-w-[85%] ${msg.role === 'user' ? 'items-end' : 'items-start'}`}>
                             {msg.parts.map((part, i) => (
                                 <div key={i} className={`p-6 rounded-[2.2rem] text-sm sm:text-base leading-relaxed shadow-sm border transition-all duration-500 ${msg.role === 'user' ? 'bg-blue-600 text-white border-blue-600 rounded-tr-none font-medium' : 'bg-white dark:bg-slate-800 text-slate-800 dark:text-slate-100 border-slate-100 dark:border-slate-700 rounded-tl-none shadow-blue-500/5'}`}>
                                     {part.inlineData && (
                                       <div className="mb-5 group relative overflow-hidden rounded-2xl shadow-xl border border-white/10">
                                          <img src={`data:${part.inlineData.mimeType};base64,${part.inlineData.data}`} className="max-h-[500px] w-full object-contain transition-transform duration-700 group-hover:scale-105 bg-slate-100 dark:bg-slate-900" alt="Engine Pulse"/>
                                          <div className="absolute bottom-4 right-4 px-3 py-1 bg-black/60 backdrop-blur-md rounded-lg text-[9px] font-black uppercase text-white tracking-widest">Cognix V3.0 RENDER</div>
                                       </div>
                                     )}
                                     <div className="whitespace-pre-wrap prose prose-sm sm:prose-base dark:prose-invert max-w-none font-medium tracking-tight">{part.text}</div>
                                 </div>
                             ))}
                        </div>
                    </div>
                ))}
                {isLoading && (
                  <div className="flex gap-6 items-center animate-pulse">
                    <div className="w-12 h-12 rounded-2xl bg-blue-600 flex items-center justify-center text-white shadow-lg"><BotIcon className="w-8 h-8"/></div>
                    <div className="bg-slate-50 dark:bg-slate-800 px-7 py-3.5 rounded-2xl text-[10px] font-black text-blue-600 uppercase tracking-[0.4em] shadow-sm flex items-center gap-3">
                       Thinking
                       <div className="flex gap-1.5">
                          <span className="w-1.5 h-1.5 bg-blue-600 rounded-full animate-bounce shadow-blue-500"></span>
                          <span className="w-1.5 h-1.5 bg-blue-600 rounded-full animate-bounce [animation-delay:0.2s] shadow-blue-500"></span>
                          <span className="w-1.5 h-1.5 bg-blue-600 rounded-full animate-bounce [animation-delay:0.4s] shadow-blue-500"></span>
                       </div>
                    </div>
                  </div>
                )}
            </div>
        )}
      </div>

      <div className="absolute bottom-0 left-0 right-0 px-6 pb-12 pt-16 bg-gradient-to-t from-white dark:from-slate-900 via-white/95 dark:via-slate-900/95 to-transparent pointer-events-none">
          <div className="max-w-3xl mx-auto pointer-events-auto">
              <div className="bg-white/80 dark:bg-slate-800/80 backdrop-blur-2xl rounded-[2.8rem] shadow-[0_30px_70px_rgba(0,0,0,0.18)] border border-slate-200/60 dark:border-slate-700/50 overflow-visible transition-all duration-500 focus-within:shadow-[0_40px_100px_rgba(37,99,235,0.2)] focus-within:border-blue-500/50 group">
                   <div className="flex items-center gap-2 px-10 py-3.5 border-b border-slate-100 dark:border-slate-700/50 bg-slate-50/40 dark:bg-slate-900/30">
                       <div className="relative">
                            <button onClick={() => setIsModelDropdownOpen(!isModelDropdownOpen)} className="text-[10px] font-black uppercase tracking-widest text-slate-400 hover:text-blue-600 flex items-center gap-2 transition-all group-focus-within:text-blue-500">
                                {modelOptions.find(o => o.id === model)?.label}
                                <svg className="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24" strokeWidth="3.5"><path d="M19 9l-7 7-7-7"/></svg>
                            </button>
                            {isModelDropdownOpen && (
                                <div className="absolute bottom-full left-0 mb-5 w-56 bg-white dark:bg-slate-800 rounded-[2rem] shadow-2xl border border-slate-100 dark:border-slate-700 z-50 p-2.5 animate-fade-in-up">
                                    {modelOptions.map(m => (
                                        <button key={m.id} onClick={() => { setActiveModel(m.id as any); setIsModelDropdownOpen(false); }} className={`w-full text-left px-4 py-3.5 hover:bg-blue-50 dark:hover:bg-blue-900/20 rounded-2xl text-[11px] font-black transition-all ${model === m.id ? 'text-blue-600 bg-blue-50 dark:bg-blue-900/20' : 'text-slate-500 dark:text-slate-400'}`}>
                                            <div className="flex flex-col">
                                              <span>{m.label}</span>
                                              <span className="text-[8px] opacity-50 uppercase tracking-[0.2em] font-bold mt-0.5">{m.desc}</span>
                                            </div>
                                        </button>
                                    ))}
                                </div>
                            )}
                       </div>

                       <div className="h-4 w-px bg-slate-200 dark:bg-slate-700 mx-4 opacity-50"></div>

                       <button onClick={() => setWebSearchEnabled(!webSearchEnabled)} className={`text-[10px] font-black uppercase tracking-widest flex items-center gap-2.5 transition-all ${webSearchEnabled ? 'text-blue-600' : 'text-slate-400'}`}>
                           <div className={`w-2 h-2 rounded-full ${webSearchEnabled ? 'bg-blue-600 shadow-[0_0_12px_#2563EB]' : 'bg-slate-300 dark:bg-slate-600'}`}></div>
                           Neural Search
                       </button>

                       <div className="h-4 w-px bg-slate-200 dark:bg-slate-700 mx-4 opacity-50"></div>

                       <div className="relative">
                           <button onClick={() => setIsCognateDropdownOpen(!isCognateDropdownOpen)} className={`text-[10px] font-black uppercase tracking-widest flex items-center gap-2.5 transition-all ${activeParticipants.length > 0 ? 'text-blue-600' : 'text-slate-400'}`}>
                               <UsersIcon className="w-4 h-4" />
                               {activeParticipants.length > 0 ? `${activeParticipants.length} Linked Nodes` : 'Invite Cognates'}
                           </button>
                           {isCognateDropdownOpen && (
                               <div className="absolute bottom-full left-0 mb-5 w-60 bg-white dark:bg-slate-800 rounded-[2rem] shadow-2xl border border-slate-100 dark:border-slate-700 z-50 p-3 animate-fade-in-up">
                                   <div className="flex items-center justify-between px-4 py-3 border-b border-slate-50 dark:border-slate-700 mb-3">
                                       <span className="text-[10px] font-black uppercase tracking-widest text-slate-500">Linked Network</span>
                                       <button onClick={shareSessionLink} className="p-2 hover:bg-blue-50 rounded-xl transition-all"><CopyIcon className="w-4 h-4 text-blue-600"/></button>
                                   </div>
                                   {showInviteFeedback && <p className="text-[9px] text-green-500 font-black px-4 mb-3 uppercase tracking-widest">Protocol Sync OK</p>}
                                   <div className="max-h-60 overflow-y-auto custom-scrollbar px-1 space-y-1">
                                       {friends.map(f => (
                                           <button key={f.id} onClick={() => toggleParticipant(f.id)} className={`w-full flex items-center justify-between px-4 py-3 rounded-2xl text-[11px] font-black transition-all ${activeParticipants.includes(f.id) ? 'bg-blue-50 dark:bg-blue-900/20 text-blue-600 shadow-sm' : 'text-slate-500 dark:text-slate-400 hover:bg-slate-50'}`}>
                                               <span>{f.name}</span>
                                               {activeParticipants.includes(f.id) && <div className="w-2 h-2 rounded-full bg-blue-600 animate-pulse"></div>}
                                           </button>
                                       ))}
                                       {friends.length === 0 && <p className="text-[10px] text-slate-400 italic px-4 py-3">No nodes identified.</p>}
                                   </div>
                               </div>
                           )}
                       </div>
                   </div>

                   <div className="p-5 flex items-end gap-5 px-8 pb-8">
                        <button onClick={() => fileInputRef.current?.click()} className="p-4 rounded-3xl bg-slate-50 dark:bg-slate-900 text-slate-400 hover:text-blue-600 hover:bg-blue-50 dark:hover:bg-blue-900 transition-all shadow-inner active:scale-90 shrink-0 border border-transparent hover:border-blue-100">
                            <ImageIcon className="w-7 h-7"/>
                            <input type="file" ref={fileInputRef} onChange={(e) => {
                                const file = e.target.files?.[0];
                                if (file) {
                                    const reader = new FileReader();
                                    reader.onloadend = () => setSelectedImage({ data: (reader.result as string).split(',')[1], mimeType: file.type });
                                    reader.readAsDataURL(file);
                                }
                            }} accept="image/*" className="hidden" />
                        </button>
                        <textarea ref={textareaRef} value={input} onChange={e => setInput(e.target.value)}
                            onKeyDown={e => e.key === 'Enter' && !e.shiftKey && (e.preventDefault(), handleSendMessage())}
                            placeholder="Ask Cognix anything..."
                            className="flex-1 bg-transparent border-none outline-none resize-none py-4 text-base sm:text-lg text-slate-900 dark:text-white placeholder-slate-400 max-h-48 min-h-[56px] font-semibold tracking-tight"
                            rows={1} />
                        <button onClick={() => handleSendMessage()} disabled={isLoading || (!input && !selectedImage)} className="w-16 h-16 bg-blue-600 text-white rounded-[1.8rem] shadow-[0_15px_30px_rgba(37,99,235,0.45)] disabled:opacity-20 disabled:shadow-none active:scale-90 transition-all flex items-center justify-center shrink-0 hover:bg-blue-700 hover:-translate-y-1">
                             <SendIcon className="w-9 h-9"/>
                        </button>
                   </div>
                   {selectedImage && (
                      <div className="px-10 pb-6 flex items-center gap-4 animate-fade-in-up">
                          <div className="relative w-14 h-14 rounded-2xl overflow-hidden shadow-xl border-2 border-blue-600 group/img">
                              <img src={`data:${selectedImage.mimeType};base64,${selectedImage.data}`} className="w-full h-full object-cover" alt="Selected Node"/>
                              <button onClick={() => setSelectedImage(null)} className="absolute inset-0 bg-black/50 flex items-center justify-center text-white font-black text-sm opacity-0 group-hover/img:opacity-100 transition-all">✕</button>
                          </div>
                          <div className="flex flex-col">
                            <span className="text-[10px] font-black uppercase tracking-[0.2em] text-blue-600">Attachment Synced</span>
                            <span className="text-[8px] font-bold text-slate-400 uppercase tracking-widest">{selectedImage.mimeType.split('/')[1]} stream</span>
                          </div>
                      </div>
                   )}
              </div>
          </div>
      </div>
    </div>
  );
};

