        onSelectChat={(id) => { setActiveChatId(id); setMode('chat'); if(window.innerWidth < 1024) setIsSidebarOpen(false); }}
        onNewChat={handleNewChat}
        onDeleteChat={(id) => { setChatHistory(h => h.filter(c => c.id !== id)); if (activeChatId === id) { setActiveChatId(null); setMessages([]); } }}
        onRenameChat={(id, t) => setChatHistory(h => h.map(c => c.id === id ? { ...c, title: t } : c))}
        onOpenSettings={() => setIsSettingsOpen(true)}
        isSidebarOpen={isSidebarOpen} isDesktopSidebarOpen={isDesktopSidebarOpen} theme={activeTheme} friends={friends}
      />

      <div className={`flex-1 flex flex-col h-full bg-white dark:bg-slate-900 transition-all duration-300 relative overflow-hidden ${isDesktopSidebarOpen && window.innerWidth >= 1024 ? 'lg:border-l border-slate-200 dark:border-slate-800' : ''}`}>
        <header className="h-14 sm:h-16 flex items-center justify-between px-4 sm:px-6 shrink-0 z-30 border-b border-slate-100 dark:border-slate-800 bg-white/80 dark:bg-slate-900/80 backdrop-blur-xl">
             <div className="flex items-center gap-3">
                <button 
                  onClick={() => window.innerWidth >= 1024 ? setIsDesktopSidebarOpen(!isDesktopSidebarOpen) : setIsSidebarOpen(!isSidebarOpen)} 
                  className="p-2 text-slate-500 hover:text-brand-600 hover:bg-brand-50 dark:hover:bg-brand-900/20 rounded-lg transition-all"
                  aria-label="Toggle Sidebar"
                >
                    <MenuIcon className="w-5 h-5"/>
                </button>
                <div className="flex flex-col">
                  <h1 className="text-[10px] font-bold text-slate-400 uppercase tracking-[0.2em]">
                      {mode} / cognix.v3.pro
                  </h1>
                  {activeChatId && currentChat && mode === 'chat' && (
                    <span className="text-xs font-semibold text-slate-700 dark:text-slate-200 truncate max-w-[150px] sm:max-w-xs">{currentChat.title}</span>
                  )}
                </div>
             </div>
             <div className="flex items-center gap-2 sm:gap-3">
                 <button 
                  onClick={() => setIsSettingsOpen(true)} 
                  className="p-2 sm:p-2.5 bg-slate-50 dark:bg-slate-800 rounded-lg border border-slate-200 dark:border-slate-700 text-slate-500 hover:text-brand-600 transition-all shadow-sm"
                  aria-label="Settings"
                 >
                    <UserIcon className="w-5 h-5"/>
                 </button>
             </div>
        </header>

        {joinNotification && (
          <div className="absolute top-20 left-1/2 -translate-x-1/2 z-50 px-6 py-3 bg-brand-600 text-white rounded-xl shadow-2xl text-xs font-bold uppercase tracking-widest animate-slide-up">
            {joinNotification}
          </div>
        )}

        <main className="flex-1 relative overflow-hidden">
            {mode === 'chat' && (
                <ChatView messages={messages} setMessages={setMessages} uiStyle={'modern'} theme={activeTheme} fontSize={'normal'} systemInstruction={systemInstruction} model={activeModel} setActiveModel={setActiveModel} friends={friends} />
            )}
            {mode === 'live' && <LiveView theme={activeTheme} />}
            {mode === 'friends' && <FriendsView friends={friends} setFriends={setFriends} />}
            {mode === 'community' && <CommunityView theme={activeTheme} model={activeModel} />}
            {mode === 'coding' && <CodingView theme={activeTheme} model={activeModel} />}
            {mode === 'memory' && <MemoryView theme={activeTheme} />}
            {mode === 'about' && <AboutUs />}
        </main>
      </div>

      <SettingsModal 
        isOpen={isSettingsOpen} 
        onClose={() => setIsSettingsOpen(false)} 
        uiStyle={'modern'} setUiStyle={() => {}} 
        accentColor={accentColor} setAccentColor={setAccentColor} 
        fontSize={'normal'} setFontSize={() => {}} 
        isDarkMode={isDarkMode} setIsDarkMode={setIsDarkMode} 
        onClearHistory={() => { setChatHistory([]); setMessages([]); setActiveChatId(null); setIsSettingsOpen(false); }} 
        systemInstruction={systemInstruction} setSystemInstruction={setSystemInstruction} 
      />
    </div>
  );
}

