import React, { useState, useRef, useEffect, useCallback } from 'react';
import type { ChatMessage, ChatPart, UIStyle, ThemeColors, FontSize, ModelType, Friend } from '../types';
import { GoogleGenAI } from "@google/genai";
import { BotIcon, SendIcon, UserIcon, ImageIcon, SearchIcon, SparklesIcon, UsersIcon, CodeIcon, CopyIcon } from './Icons';

interface ChatViewProps {
  messages: ChatMessage[];
  setMessages: React.Dispatch<React.SetStateAction<ChatMessage[]>>;
  uiStyle: UIStyle;
  theme: ThemeColors;
  fontSize: FontSize;
  systemInstruction: string;
  model: ModelType;
  setActiveModel: (m: ModelType) => void;
  friends?: Friend[];
}

export const ChatView: React.FC<ChatViewProps> = ({ messages, setMessages, theme, systemInstruction, model, setActiveModel, friends = [] }) => {
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [selectedImage, setSelectedImage] = useState<{ data: string; mimeType: string } | null>(null);
  const [webSearchEnabled, setWebSearchEnabled] = useState(true);
  const [isModelDropdownOpen, setIsModelDropdownOpen] = useState(false);
  const [activeParticipants, setActiveParticipants] = useState<string[]>([]);
  const [showInviteToast, setShowInviteToast] = useState(false);

  const chatContainerRef = useRef<HTMLDivElement>(null);
  const textareaRef = useRef<HTMLTextAreaElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (chatContainerRef.current) {
      chatContainerRef.current.scrollTo({
        top: chatContainerRef.current.scrollHeight,
        behavior: 'smooth'
      });
    }
  }, [messages, isLoading]);

  const handleSendMessage = useCallback(async (textOverride?: string) => {
    const textInput = (textOverride || input).trim();
    if ((!textInput && !selectedImage) || isLoading) return;

    const userMessageParts: ChatPart[] = [];
    if (selectedImage) userMessageParts.push({ inlineData: { mimeType: selectedImage.mimeType, data: selectedImage.data } });

    const participantPrefix = activeParticipants.length > 0 
        ? `[Cluster Sync: ${activeParticipants.map(id => friends.find(f => f.id === id)?.name).join(', ')}] ` 
        : '';

    if (textInput) userMessageParts.push({ text: participantPrefix + textInput });

    const userMessage: ChatMessage = { id: `msg-${Date.now()}`, role: 'user', parts: userMessageParts };
    const modelPlaceholderId = `msg-${Date.now() + 1}`;
    const modelPlaceholder: ChatMessage = { id: modelPlaceholderId, role: 'model', parts: [{ text: '' }], isSearching: webSearchEnabled };

    setMessages(prev => [...prev, userMessage, modelPlaceholder]);
    setInput(''); 
    setSelectedImage(null);
    setIsLoading(true);

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const isImageRequest = /generate (an )?image|create (an )?image|draw|paint/i.test(textInput);

      let targetModel: string = 'gemini-3-pro-preview';
      if (isImageRequest) targetModel = 'gemini-2.5-flash-image';
      else if (model === 'gemini-3-flash-preview') targetModel = 'gemini-3-flash-preview';
      else if (model === 'gemini-3-pro-preview') targetModel = 'gemini-3-pro-preview';
      else if (model === 'cognix-v2' || model === 'gemini-flash-lite-latest') targetModel = 'gemini-flash-lite-latest';
      else if (model === 'clora-n1' || model === 'corea-rv1') targetModel = 'gemini-3-pro-preview';

      const history = messages.map(msg => ({
        role: msg.role,
        parts: msg.parts.map(p => {
            if (p.text) return { text: p.text };
            if (p.inlineData) return { inlineData: p.inlineData };
            return null;
        }).filter(Boolean) as any[]
      }));

      const response = await ai.models.generateContent({
          model: targetModel,
          contents: [...history, { role: 'user', parts: userMessageParts as any }],
          config: { 
            systemInstruction: systemInstruction,
            tools: !isImageRequest && webSearchEnabled ? [{ googleSearch: {} }] : [] 
          },
      });

      let responseParts: ChatPart[] = [];
      for (const part of response.candidates[0].content.parts) {
        if (part.text) responseParts.push({ text: part.text });
        else if (part.inlineData) responseParts.push({ inlineData: { mimeType: part.inlineData.mimeType, data: part.inlineData.data } });
      }

      setMessages(prev => prev.map(m => m.id === modelPlaceholderId ? { ...m, parts: responseParts, isSearching: false } : m));
    } catch (error) {
      setMessages(prev => prev.map(m => m.id === modelPlaceholderId ? { ...m, parts: [{ text: `Neural Link Failure: Handshake timed out. Ensure connectivity and retry.` }], isSearching: false } : m));
    } finally {
      setIsLoading(false);
    }
  }, [input, isLoading, messages, selectedImage, systemInstruction, model, webSearchEnabled, setMessages, activeParticipants, friends]);

  const handleShareInvite = () => {
    // Generate a unique join ID
    const joinId = Math.random().toString(36).substring(2, 7);
    const joinUrl = `${window.location.origin}/join/${joinId}`;
    navigator.clipboard.writeText(joinUrl);
    setShowInviteToast(true);
    setTimeout(() => setShowInviteToast(false), 3000);

    // Simulating someone joining for UI feedback
    if (friends.length > 0 && activeParticipants.length < 5) {
        setTimeout(() => {
            const potentialFriends = friends.filter(f => !activeParticipants.includes(f.id));
            if (potentialFriends.length > 0) {
                const nextFriend = potentialFriends[Math.floor(Math.random() * potentialFriends.length)];
                setActiveParticipants(prev => [...prev, nextFriend.id]);
            }
        }, 2000);
    }
  };

  const modelOptions: {id: ModelType, label: string, desc: string}[] = [
    { id: 'gemini-3-pro-preview', label: 'Pro 3.0', desc: 'Superior SOTA Reasoning' },
    { id: 'gemini-3-flash-preview', label: 'Flash 3.0', desc: 'Real-time High Velocity' },
    { id: 'cognix-v2', label: 'CognixV2', desc: 'Optimized Workflow Engine' },
    { id: 'clora-n1', label: 'CloraN1', desc: 'Technical Operations' },
    { id: 'corea-rv1', label: 'CoreaRv1', desc: 'Creative Vision Synthesis' },
    { id: 'gemini-flash-lite-latest', label: 'Flash Lite', desc: 'High Efficiency Core' },
    { id: 'gemini-2.5-flash-image', label: 'Neural Visualizer', desc: 'Generative Image Engine' }
  ];

  return (
    <div className="flex flex-col h-full bg-white dark:bg-slate-900 transition-colors duration-300 relative">
      {/* Invite Toast */}
      {showInviteToast && (
        <div className="absolute top-6 left-1/2 -translate-x-1/2 z-50 px-6 py-2.5 bg-brand-600 text-white rounded-full text-[10px] font-black uppercase tracking-widest shadow-2xl animate-slide-up border border-white/20">
          Sync link copied. Node active.
        </div>
      )}

      {/* Messages Viewport */}
      <div ref={chatContainerRef} className="flex-1 overflow-y-auto px-4 sm:px-6 md:px-12 lg:px-24 xl:px-48 pb-48 pt-10 custom-scrollbar scroll-smooth">
        {messages.length === 0 ? (
            <div className="max-w-2xl mx-auto flex flex-col items-center justify-center min-h-[60vh] text-center animate-fade-in py-12">
                 <div className="w-16 h-16 bg-brand-600 rounded-2xl flex items-center justify-center text-white shadow-xl mb-8 transition-transform hover:scale-105 duration-500">
                     <BotIcon className="w-10 h-10" />
                 </div>
                 <h2 className="text-3xl font-black text-slate-900 dark:text-white mb-3 tracking-tighter">
                   CognixAI <span className="text-brand-600">V3.0 Pro</span>
                 </h2>
                 <p className="text-slate-400 dark:text-slate-500 mb-12 max-w-sm font-medium leading-relaxed text-sm">
                   A professional intelligence engine for complex logic, creative synthesis, and node collaboration.
                 </p>

                 <div className="grid grid-cols-1 sm:grid-cols-2 gap-3 w-full max-w-xl px-4">
                     {[
                        { t: "Logic Architecture", q: "Architect a scalable microservices structure for fintech." },
                        { t: "Neural Rendering", q: "Generate a hyper-minimalist 3D office space design." },
                        { t: "System Sync", q: "How do I optimize cluster synchronization in low latency?" },
                        { t: "Code Analysis", q: "Refactor this TypeScript interface for better extensibility." }
                     ].map((item, i) => (
                        <button key={i} onClick={() => handleSendMessage(item.q)} className="text-left p-5 rounded-2xl border border-slate-100 dark:border-slate-800 hover:border-brand-500/50 hover:bg-slate-50 dark:hover:bg-slate-800/50 transition-all bg-white dark:bg-slate-900 shadow-sm group">
                            <span className="font-bold text-slate-900 dark:text-white text-[11px] block mb-1 uppercase tracking-tight group-hover:text-brand-600 transition-colors">{item.t}</span>
                            <span className="text-[10px] text-slate-400 font-medium italic opacity-60 line-clamp-1">{item.q}</span>
                        </button>
                     ))}
                 </div>
            </div>
        ) : (
            <div className="max-w-3xl mx-auto space-y-10 pb-12">
                {messages.map((msg) => (
                    <div key={msg.id} className={`flex gap-4 sm:gap-6 ${msg.role === 'user' ? 'flex-row-reverse' : 'flex-row'} animate-slide-up`}>
                        <div className={`w-9 h-9 shrink-0 rounded-xl flex items-center justify-center shadow-sm transition-all duration-300
                            ${msg.role === 'user' ? 'bg-slate-50 dark:bg-slate-800 text-slate-400' : 'bg-brand-600 text-white shadow-brand-500/10'}
                        `}>
                             {msg.role === 'user' ? <UserIcon className="w-5 h-5"/> : <BotIcon className="w-5 h-5"/>}
                        </div>
                        <div className={`flex flex-col gap-3 max-w-[85%] ${msg.role === 'user' ? 'items-end' : 'items-start'}`}>
                             {msg.parts.map((part, i) => (
                                 <div key={i} className={`px-5 py-4 rounded-2xl sm:rounded-[1.4rem] text-sm sm:text-base leading-relaxed border transition-all duration-500 ${msg.role === 'user' ? 'message-bubble-user rounded-tr-none font-medium' : 'message-bubble-bot rounded-tl-none text-slate-700 dark:text-slate-200 shadow-sm'}`}>
                                     {part.inlineData && (
                                       <div className="mb-4 group relative overflow-hidden rounded-xl shadow-lg">
                                          <img src={`data:${part.inlineData.mimeType};base64,${part.inlineData.data}`} className="max-h-[500px] w-full object-contain transition-transform duration-700 group-hover:scale-105 bg-slate-900" alt="Output"/>
                                          <div className="absolute top-3 left-3 px-3 py-1 bg-black/50 backdrop-blur-md rounded-lg text-[8px] font-black uppercase text-white tracking-widest border border-white/10">Cognix Render</div>
                                       </div>
                                     )}
                                     <div className="whitespace-pre-wrap prose prose-sm sm:prose-base dark:prose-invert max-w-none font-medium tracking-tight">{part.text}</div>
                                 </div>
                             ))}
                        </div>
                    </div>
                ))}
                {isLoading && (
                  <div className="flex gap-4 sm:gap-6 items-center animate-pulse">
                    <div className="w-9 h-9 rounded-xl bg-brand-600 flex items-center justify-center text-white"><BotIcon className="w-5 h-5"/></div>
                    <div className="bg-slate-50 dark:bg-slate-800 px-5 py-2.5 rounded-2xl text-[10px] font-black text-brand-600 uppercase tracking-widest flex items-center gap-3">
                       Thinking
                       <div className="flex gap-1">
                          <span className="w-1 h-1 bg-brand-600 rounded-full animate-bounce"></span>
                          <span className="w-1 h-1 bg-brand-600 rounded-full animate-bounce [animation-delay:0.2s]"></span>
                          <span className="w-1 h-1 bg-brand-600 rounded-full animate-bounce [animation-delay:0.4s]"></span>
                       </div>
                    </div>
                  </div>
                )}
            </div>
        )}
      </div>

      {/* Input Console */}
      <div className="absolute bottom-0 left-0 right-0 px-4 sm:px-6 pb-6 sm:pb-8 pt-12 bg-gradient-to-t from-white dark:from-slate-900 via-white/95 dark:via-slate-900/95 to-transparent pointer-events-none z-40">
          <div className="max-w-4xl mx-auto pointer-events-auto">
              <div className="bg-white/90 dark:bg-slate-800/90 backdrop-blur-xl rounded-[2rem] shadow-[0_20px_50px_rgba(0,0,0,0.08)] border border-slate-200/50 dark:border-slate-700/50 overflow-visible transition-all duration-500 focus-within:shadow-[0_20px_60px_rgba(37,99,235,0.12)] focus-within:border-brand-500/40 group/input">
                   {/* Contextual Top Bar */}
                   <div className="flex items-center gap-3 px-6 sm:px-8 py-3 border-b border-slate-100/50 dark:border-slate-700/30 bg-slate-50/20 dark:bg-slate-900/20 overflow-x-auto no-scrollbar whitespace-nowrap">
                       <div className="relative shrink-0">
                            <button onClick={() => setIsModelDropdownOpen(!isModelDropdownOpen)} className="text-[9px] font-black uppercase tracking-widest text-slate-400 hover:text-brand-600 flex items-center gap-1.5 transition-all">
                                {modelOptions.find(o => o.id === model)?.label || 'Model'}
                                <svg className="w-2.5 h-2.5" fill="none" stroke="currentColor" viewBox="0 0 24 24" strokeWidth="4"><path d="M19 9l-7 7-7-7"/></svg>
                            </button>
                            {isModelDropdownOpen && (
                                <div className="absolute bottom-full left-0 mb-4 w-52 bg-white dark:bg-slate-800 rounded-2xl shadow-2xl border border-slate-100 dark:border-slate-700 z-50 p-2 animate-slide-up">
                                    {modelOptions.map(m => (
                                        <button key={m.id} onClick={() => { setActiveModel(m.id); setIsModelDropdownOpen(false); }} className={`w-full text-left px-4 py-2.5 hover:bg-brand-50 dark:hover:bg-brand-900/20 rounded-xl text-[10px] font-black transition-all ${model === m.id ? 'text-brand-600 bg-brand-50 dark:bg-brand-900/30' : 'text-slate-500 dark:text-slate-400'}`}>
                                            <div className="flex flex-col">
                                              <span>{m.label}</span>
                                              <span className="text-[8px] opacity-40 uppercase tracking-widest mt-0.5">{m.desc}</span>
                                            </div>
                                        </button>
                                    ))}
                                </div>
                            )}
                       </div>

                       <div className="h-3 w-px bg-slate-200 dark:bg-slate-800 opacity-50 shrink-0"></div>

                       <button onClick={() => setWebSearchEnabled(!webSearchEnabled)} className={`text-[9px] font-black uppercase tracking-widest flex items-center gap-2 transition-all shrink-0 ${webSearchEnabled ? 'text-brand-600' : 'text-slate-400'}`}>
                           <div className={`w-1.5 h-1.5 rounded-full ${webSearchEnabled ? 'bg-brand-600 shadow-[0_0_8px_#2563EB]' : 'bg-slate-300 dark:bg-slate-700'}`}></div>
                           Neural Search
                       </button>

                       <div className="h-3 w-px bg-slate-200 dark:bg-slate-800 opacity-50 shrink-0"></div>

                       <div className="flex items-center gap-3">
                           <button onClick={handleShareInvite} className="text-[9px] font-black uppercase tracking-widest text-slate-400 hover:text-brand-600 flex items-center gap-2 transition-all shrink-0">
                               <CopyIcon className="w-3.5 h-3.5" />
                               Invite Node
                           </button>

                           {activeParticipants.length > 0 && (
                               <div className="flex -space-x-1.5 transition-all animate-fade-in">
                                   {activeParticipants.map(id => {
                                       const f = friends.find(friend => friend.id === id);
                                       return (
                                           <div key={id} className="w-5 h-5 rounded-full border border-white dark:border-slate-800 bg-brand-600 flex items-center justify-center text-[7px] font-black text-white uppercase shadow-sm" title={f?.name}>
                                               {f?.name?.[0]}
                                           </div>
                                       );
                                   })}
                               </div>
                           )}
                       </div>
                   </div>

                   {/* TextArea Console */}
                   <div className="p-4 sm:p-5 flex items-end gap-3 sm:gap-4 px-6 sm:px-10 pb-5 sm:pb-7">
                        <button onClick={() => fileInputRef.current?.click()} className="p-3.5 rounded-xl bg-slate-50 dark:bg-slate-900 text-slate-400 hover:text-brand-600 hover:bg-brand-50 dark:hover:bg-brand-900 transition-all shadow-inner shrink-0 group/clip">
                            <ImageIcon className="w-5 h-5 transition-transform group-hover/clip:-translate-y-0.5"/>
                            <input type="file" ref={fileInputRef} onChange={(e) => {
                                const file = e.target.files?.[0];
                                if (file) {
                                    const reader = new FileReader();
                                    reader.onloadend = () => setSelectedImage({ data: (reader.result as string).split(',')[1], mimeType: file.type });
                                    reader.readAsDataURL(file);
                                }
                            }} accept="image/*" className="hidden" />
                        </button>

                        <textarea ref={textareaRef} value={input} onChange={e => setInput(e.target.value)}
                            onKeyDown={e => e.key === 'Enter' && !e.shiftKey && (e.preventDefault(), handleSendMessage())}
                            placeholder="Initialize query..."
                            className="flex-1 bg-transparent border-none outline-none resize-none py-3 text-sm sm:text-base text-slate-800 dark:text-white placeholder-slate-300 dark:placeholder-slate-600 font-semibold tracking-tight max-h-40 min-h-[44px]"
                            rows={1} />

                        <button onClick={() => handleSendMessage()} disabled={isLoading || (!input && !selectedImage)} className="w-12 h-12 sm:w-14 sm:h-14 bg-brand-600 text-white rounded-xl shadow-lg disabled:opacity-20 active:scale-95 transition-all flex items-center justify-center shrink-0 hover:bg-brand-700 relative group/send">
                             <SendIcon className="w-6 h-6 relative z-10 transition-transform group-hover/send:translate-x-0.5 group-hover/send:-translate-y-0.5"/>
                        </button>
                   </div>

                   {/* Inline Attachment Preview */}
                   {selectedImage && (
                      <div className="px-10 pb-5 flex items-center gap-4 animate-slide-up">
                          <div className="relative w-10 h-10 rounded-xl overflow-hidden shadow-lg border-2 border-brand-600 group/img">
                              <img src={`data:${selectedImage.mimeType};base64,${selectedImage.data}`} className="w-full h-full object-cover" alt="Selected Media"/>
                              <button onClick={() => setSelectedImage(null)} className="absolute inset-0 bg-black/60 flex items-center justify-center text-white font-black text-xs opacity-0 group-hover/img:opacity-100 transition-all">✕</button>
                          </div>
                          <div className="flex flex-col">
                            <span className="text-[9px] font-black uppercase tracking-widest text-brand-600">Attachment Ready</span>
                            <span className="text-[8px] font-bold text-slate-400 uppercase tracking-[0.2em]">{selectedImage.mimeType.split('/')[1]} buffer</span>
                          </div>
                      </div>
                   )}
              </div>
          </div>
      </div>
    </div>
  );
};

import React, { useState, useRef, useEffect } from 'react';
import type { ChatSession, Mode, ThemeColors, Friend } from '../types';
import { BotIcon, TrashIcon, PencilIcon, MicrophoneIcon, UsersIcon, CodeIcon, SparklesIcon } from './Icons';

interface SidebarProps {
  chatHistory: ChatSession[];
  activeChatId: string | null;
  mode: Mode;
  onSetMode: (mode: Mode) => void;
  onSelectChat: (id: string) => void;
  onNewChat: () => void;
  onDeleteChat: (id: string) => void;
  onRenameChat: (id: string, newTitle: string) => void;
  onOpenSettings: () => void;
  isSidebarOpen: boolean;
  isDesktopSidebarOpen: boolean;
  theme: ThemeColors;
  friends: Friend[];
}

export const Sidebar: React.FC<SidebarProps> = ({
  chatHistory, activeChatId, mode, onSetMode, onSelectChat, onNewChat, onDeleteChat, onRenameChat, isSidebarOpen, isDesktopSidebarOpen, theme, friends,
}) => {
  const [editingChatId, setEditingChatId] = useState<string | null>(null);
  const [newTitle, setNewTitle] = useState('');
  const inputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (editingChatId && inputRef.current) {
        inputRef.current.focus();
        inputRef.current.select();
    }
  }, [editingChatId]);

  const handleRename = () => {
    if (editingChatId && newTitle.trim()) onRenameChat(editingChatId, newTitle.trim());
    setEditingChatId(null);
  };

  const NavItem: React.FC<{ m: Mode, icon: React.ReactNode, label: string }> = ({ m, icon, label }) => (
    <button
        onClick={() => onSetMode(m)}
        className={`w-full flex items-center gap-3.5 px-4 py-3 rounded-xl transition-all duration-300
            ${mode === m 
                ? 'bg-brand-600 text-white shadow-lg shadow-brand-500/20' 
                : 'text-slate-500 dark:text-slate-400 hover:bg-white dark:hover:bg-slate-800/50 hover:text-brand-600'}
        `}
    >
        <span className="shrink-0">{icon}</span>
        <span className="text-xs font-bold tracking-widest uppercase">{label}</span>
    </button>
  );

  return (
    <aside className={`fixed lg:static inset-y-0 left-0 z-50 transition-all duration-500 cubic-bezier(0.16, 1, 0.3, 1) h-full shrink-0 flex flex-col bg-slate-50 dark:bg-slate-950 border-r border-slate-200 dark:border-slate-800/50
      ${isSidebarOpen ? 'translate-x-0 w-[280px]' : '-translate-x-full lg:translate-x-0'}
      ${isDesktopSidebarOpen ? 'lg:w-[280px]' : 'lg:w-0 overflow-hidden border-none opacity-0'}
    `}>
      <div className="p-6">
        <div className="flex items-center gap-3.5 mb-10 group cursor-pointer px-2" onClick={() => onSetMode('chat')}>
            <div className="w-10 h-10 bg-brand-600 rounded-xl flex items-center justify-center text-white shadow-xl transition-transform duration-500 group-hover:scale-110">
                <BotIcon className="w-6 h-6" />
            </div>
            <div className="flex flex-col">
              <h1 className="text-lg font-black text-slate-900 dark:text-white tracking-tighter">CognixAI</h1>
              <span className="text-[8px] font-black uppercase tracking-[0.3em] text-brand-600">V3.0 PRO</span>
            </div>
        </div>

        <button onClick={onNewChat} className="w-full flex items-center justify-center gap-2.5 py-3.5 bg-white dark:bg-slate-800 text-slate-900 dark:text-white border border-slate-200 dark:border-slate-700 rounded-xl font-black text-[10px] uppercase tracking-[0.2em] shadow-sm hover:border-brand-500 hover:text-brand-600 transition-all active:scale-95">
          + New Terminal
        </button>
      </div>

      <nav className="px-4 space-y-1 mb-8">
        <NavItem m="chat" icon={<SparklesIcon className="w-4 h-4" />} label="Neural Hub" />
        <NavItem m="community" icon={<UsersIcon className="w-4 h-4" />} label="Collective" />
        <NavItem m="friends" icon={<UsersIcon className="w-4 h-4" />} label="Clusters" />
        <NavItem m="coding" icon={<CodeIcon className="w-4 h-4" />} label="Studio" />
        <NavItem m="live" icon={<MicrophoneIcon className="w-4 h-4" />} label="Voice" />
        <NavItem m="memory" icon={<BotIcon className="w-4 h-4" />} label="Vault" />
      </nav>

      <div className="flex-1 overflow-y-auto px-4 custom-scrollbar pb-8">
            <h3 className="text-[9px] font-black text-slate-400 uppercase tracking-[0.25em] px-4 mb-4 flex items-center gap-2">
              <div className="w-1 h-1 rounded-full bg-brand-600"></div> Archive
            </h3>
            <div className="space-y-1">
                {chatHistory.length === 0 && (
                  <p className="text-[9px] text-slate-400 italic px-4 py-2 uppercase tracking-widest opacity-50">Null Archive</p>
                )}
                {chatHistory.map((chat) => (
                    <div key={chat.id} onClick={() => { if(editingChatId !== chat.id) onSelectChat(chat.id); }}
                        className={`group relative flex items-center justify-between px-4 py-3 cursor-pointer rounded-xl transition-all
                        ${activeChatId === chat.id && mode === 'chat'
                            ? 'bg-brand-50 dark:bg-brand-900/20 text-brand-600 dark:text-brand-400 font-bold border-l-4 border-brand-600'
                            : 'text-slate-500 hover:bg-white dark:hover:bg-slate-800 hover:text-slate-900'}
                        `}
                    >
                        {editingChatId === chat.id ? (
                            <input ref={inputRef} type="text" value={newTitle} onChange={(e) => setNewTitle(e.target.value)} onBlur={handleRename} onKeyDown={(e) => e.key === 'Enter' && handleRename()}
                                className="bg-transparent border-none w-full outline-none text-[11px] font-bold" />
                        ) : (
                            <>
                            <span className="truncate text-[11px] font-bold tracking-tight">{chat.title}</span>
                            <div className="hidden group-hover:flex items-center gap-1.5 absolute right-2 bg-white/95 dark:bg-slate-800/95 backdrop-blur-sm p-1 rounded-lg shadow-sm border border-slate-100 dark:border-slate-700">
                                <button onClick={(e) => { e.stopPropagation(); setEditingChatId(chat.id); setNewTitle(chat.title); }} className="p-1 text-slate-400 hover:text-brand-500 transition-colors"><PencilIcon className="w-3 h-3"/></button>
                                <button onClick={(e) => { e.stopPropagation(); onDeleteChat(chat.id); }} className="p-1 text-slate-400 hover:text-red-500 transition-colors"><TrashIcon className="w-3 h-3"/></button>
                            </div>
                            </>
                        )}
                    </div>
                ))}
            </div>
      </div>

      <div className="p-8 border-t border-slate-100 dark:border-slate-800/50">
          <p className="text-[9px] font-black text-slate-300 text-center uppercase tracking-[0.3em] leading-loose">
            Engineering by <br/> <span className="text-brand-600">Shashwat Ranjan Jha</span>
          </p>
      </div>
    </aside>
  );
};
